// 🍪 БРОНЕБОЙНАЯ АВТОРИЗАЦИЯ ДЛЯ ВСЕХ СУБДОМЕНОВ (*.sotka.one)
    (function syncCrossSubdomainAuth() {
    const hostname = window.location.hostname.toLowerCase();
    const isSotka = hostname.endsWith('sotka.one');
    const cookieDomain = isSotka ? 'sotka.one' : undefined;

    const killAllAuthCookies = () => {
        const domains = ['sotka.one', '.sotka.one', hostname, ''];
        ['pb_auth', 'pb_rider'].forEach(name => {
            domains.forEach(d => {
                const domStr = d ? `; domain=${d}` : '';
                document.cookie = `${name}=; path=/${domStr}; max-age=0; expires=Thu, 01 Jan 1970 00:00:00 GMT; SameSite=Lax; Secure`;
                document.cookie = `${name}=; path=/${domStr}; max-age=0; expires=Thu, 01 Jan 1970 00:00:00 GMT`;
            });
        });
    };

    // Проверяем, есть ли непустая кука pb_auth
    const authCookieMatch = document.cookie.match(/(?:^|;\s*)pb_auth=([^;]+)/);
    const hasAuthCookie = Boolean(authCookieMatch && authCookieMatch[1] && authCookieMatch[1].trim() !== '');

    if (hasAuthCookie) {
        try {
            pb.authStore.loadFromCookie(document.cookie, 'pb_auth');
        } catch(e) {}
    } else if (isSotka) {
        // 🔒 Если куки pb_auth нет (пользователь вышел на любом субдомене) — жестко гасим локальную сессию!
        pb.authStore.clear();
        localStorage.removeItem('pocketbase_auth');
        localStorage.removeItem('vilka_cached_rider');
        localStorage.removeItem('vilka_nav_state');
        killAllAuthCookies();
    }

    // Восстанавливаем кэш профиля ТОЛЬКО если токен реально валиден!
    if (pb.authStore.isValid && pb.authStore.token) {
        const rMatch = document.cookie.match(/(?:^|;\s*)pb_rider=([^;]+)/);
        if (rMatch && !localStorage.getItem('vilka_cached_rider')) {
            try {
                const rawRider = decodeURIComponent(rMatch[1]);
                if (rawRider && rawRider.startsWith('{')) {
                    localStorage.setItem('vilka_cached_rider', rawRider);
                }
            } catch(e) {}
        }
    } else {
        localStorage.removeItem('vilka_cached_rider');
    }

    const saveCrossDomainAuth = () => {
        if (pb.authStore.isValid && pb.authStore.token) {
            document.cookie = pb.authStore.exportToCookie({
                httpOnly: false,
                secure: window.location.protocol === 'https:',
                sameSite: 'Lax',
                domain: cookieDomain,
                path: '/'
            }, 'pb_auth');

            const cachedRider = localStorage.getItem('vilka_cached_rider');
            if (cachedRider && isSotka) {
                document.cookie = `pb_rider=${encodeURIComponent(cachedRider)}; path=/; domain=sotka.one; max-age=31536000; SameSite=Lax; Secure`;
            }
        } else {
            killAllAuthCookies();
            localStorage.removeItem('vilka_cached_rider');
        }
    };

    pb.authStore.onChange(saveCrossDomainAuth);
    if (pb.authStore.isValid) saveCrossDomainAuth();
})();
	
