class PelotonCRM {
    constructor(app) {
        this.app = app; 
        this.currentView = 'calendar';
        this.dataCalendar = []; this.dataTeam = { m: [], f: [] }; 
        this.dataMarket = { m: [], f: [] }; this.dataRatings = [];
        
        this.currentTab = 'm'; 
        this.sort = { field: 'points', dir: 'desc' };
        this.searchQuery = "";
        
        this.viewedTeamId = null; 
        this.editIndex = null;    
        
        this.openedEventId = null;
        this.openedEventName = "";
        this.openedEventType = "";
        this.raceRosterList = [];

        // 🔥 ДОБАВЛЯЕМ КЭШ ДЛЯ ПОРЯДКА КАТЕГОРИЙ
        this.localCategoryOrder = {}; 

        // 🔥 ВОТ ОНО! Инициализируем наш новый независимый сервис трансляций:
        this.liveService = new LiveBoardService(this); 
    }
	
	async handleGpxUpload(inputEl) {
        const file = inputEl.files?.[0];
        if (!file) return;
        try {
            const parsed = await parseAndAnalyzeGpx(file);
            const curDist = this.constructorState.activeDistances[this.constructorState.selectedDistIndex];
            if (!curDist) return;

            curDist.trackData = parsed;
            if (Number(curDist.laps) === 0) curDist.laps = 1;
            
            // 💡 Длина трека — это 1 круг. Умножаем на число кругов:
            const laps = Number(curDist.laps) || 1;
            curDist.dist = parseFloat((parsed.summary.distance * laps).toFixed(2));

            this.renderNeoConstructorModal();
            alert(`✅ GPX трек загружен:\n• Длина круга: ${parsed.summary.distance} км\n• Всего (${laps} кр.): ${curDist.dist} км\n• Набор: +${parsed.summary.gain} м / -${parsed.summary.loss} м\n• Макс. уклон: ${parsed.summary.maxSlope}%`);
        } catch (err) {
            alert("❌ Ошибка GPX: " + err.message);
        } finally {
            inputEl.value = '';
        }
    }

    removeNeoTrackData() {
        const curDist = this.constructorState.activeDistances[this.constructorState.selectedDistIndex];
        if (curDist) {
            curDist.trackData = null;
            this.renderNeoConstructorModal();
        }
    }
	
// ==========================================
    // 📱 QR-ПУЛЬТ СУДЕЙСТВА (PERO.SOTKA.ONE НА CANVAS)
    // ==========================================
    openRaceQrModal(raceId, raceName) {
        if (!raceId) return;

        const safeRaceName = this.app.escapeHTML(raceName || this.openedEventName || 'ГОНКА');
        const pultUrl = `https://pero.sotka.one/?race_id=${raceId}`;

        let modal = document.getElementById('qrModal');
        if (!modal) {
            modal = document.createElement('div');
            modal.id = 'qrModal';
            modal.className = 'modal-overlay';
            modal.style.cssText = 'position:fixed; inset:0; background:rgba(0,0,0,0.85); z-index:10000050; display:flex; align-items:center; justify-content:center; backdrop-filter:blur(10px); padding:16px; box-sizing:border-box;';
            document.body.appendChild(modal);
        }

        // Монохромные SVG-иконки
        const svgJudge = `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m16 16 3-8 3 8c-.87.65-1.92 1-3 1s-2.13-.35-3-1Z"/><path d="m2 16 3-8 3 8c-.87.65-1.92 1-3 1s-2.13-.35-3-1Z"/><path d="M7 21h10"/><path d="M12 3v18"/><path d="M3 7h2c2 0 5-1 7-2 2 1 5 2 7 2h2"/></svg>`;
        const svgClose = `<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg>`;
        const svgLink = `<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M10 13a5 5 0 0 0 7.54.54l3-3a5 5 0 0 0-7.07-7.07l-1.72 1.71"></path><path d="M14 11a5 5 0 0 0-7.54-.54l-3 3a5 5 0 0 0 7.07 7.07l1.71-1.71"></path></svg>`;
        const svgExternal = `<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6"></path><polyline points="15 3 21 3 21 9"></polyline><line x1="10" y1="14" x2="21" y2="3"></line></svg>`;

        modal.innerHTML = `
            <div class="modal-box" style="max-width:380px; width:92vw; background:var(--bg-surface); border:1px solid var(--border); border-radius:24px; padding:24px 20px; font-family:'Manrope', sans-serif; box-sizing:border-box; box-shadow:0 25px 60px rgba(0,0,0,0.5); display:flex; flex-direction:column; align-items:center; text-align:center;">
                
                <!-- Шапка окна -->
                <div style="display:flex; justify-content:space-between; align-items:center; width:100%; margin-bottom:12px; border-bottom:1px solid var(--border); padding-bottom:10px;">
                    <div style="font-family:'Unbounded', sans-serif; font-size:10px; font-weight:800; color:var(--primary); text-transform:uppercase; letter-spacing:0.5px; display:flex; align-items:center; gap:6px;">
                        ${svgJudge}
                        <span>ПУЛЬТ СУДЕЙСТВА</span>
                    </div>
                    <button type="button" onclick="document.getElementById('qrModal').style.display='none'" 
                            style="background:var(--bg-body); border:1px solid var(--border); color:var(--text-muted); width:28px; height:28px; border-radius:50%; cursor:pointer; display:flex; align-items:center; justify-content:center; padding:0; transition:0.15s ease;"
                            onmouseover="this.style.color='var(--text-main)'; this.style.borderColor='var(--text-main)';"
                            onmouseout="this.style.color='var(--text-muted)'; this.style.borderColor='var(--border)';"
                            title="Закрыть">
                        ${svgClose}
                    </button>
                </div>

                <div style="font-family:'Unbounded', sans-serif; font-size:13px; font-weight:900; color:var(--text-main); text-transform:uppercase; margin-bottom:16px; line-height:1.3;">
                    ${safeRaceName}
                </div>

                <!-- Контрастная подложка под локальный Canvas QR-код -->
                <div style="background:#ffffff; padding:14px; border-radius:18px; box-shadow:0 8px 24px rgba(0,0,0,0.15); margin-bottom:16px; display:flex; align-items:center; justify-content:center; width:216px; height:216px; box-sizing:border-box;">
                    <div id="raceQrCanvasBox"></div>
                </div>

                <!-- Поясняющий текст -->
                <div style="font-size:11px; color:var(--text-muted); line-height:1.45; margin-bottom:18px;">
                    Наведите камеру смартфона для входа в судейский пульт хронометража и финиша.
                </div>

                <!-- Кнопки действий -->
                <div style="display:flex; flex-direction:column; gap:8px; width:100%;">
                    <button id="qrCopyBtn" type="button" onclick="window.app.crm.copyQrPultLink()" 
                            style="background:var(--bg-surface-hover); color:var(--text-main); border:1px solid var(--border); padding:11px; border-radius:10px; font-family:'Unbounded', sans-serif; font-size:9.5px; font-weight:800; cursor:pointer; display:flex; align-items:center; justify-content:center; gap:7px; transition:0.2s;"
                            onmouseover="this.style.borderColor='var(--primary)';"
                            onmouseout="this.style.borderColor='var(--border)';">
                        ${svgLink}
                        <span>СКОПИРОВАТЬ ССЫЛКУ</span>
                    </button>
                    
                    <a id="qrDirectOpenBtn" href="${pultUrl}" target="_blank" 
                       style="background:transparent; color:var(--text-muted); border:1px dashed var(--border); padding:10px; border-radius:10px; font-family:'Unbounded', sans-serif; font-size:9px; font-weight:800; text-decoration:none; display:flex; align-items:center; justify-content:center; gap:6px; transition:0.2s;"
                       onmouseover="this.style.color='var(--primary)'; this.style.borderColor='var(--primary)';"
                       onmouseout="this.style.color='var(--text-muted)'; this.style.borderColor='var(--border)';">
                        ${svgExternal}
                        <span>ОТКРЫТЬ В НОВОЙ ВКЛАДКЕ</span>
                    </a>
                </div>

            </div>
        `;

        this.currentQrRaceId = raceId;
        modal.style.display = 'flex';

        // Локальная генерация QR-кода через Canvas (как в IDUCK)
        setTimeout(async () => {
            const box = document.getElementById('raceQrCanvasBox');
            if (!box) return;
            box.innerHTML = '';

            try {
                if (typeof QRCode !== 'undefined' && QRCode.toCanvas) {
                    const canvas = await QRCode.toCanvas(pultUrl, {
                        width: 188,
                        margin: 1,
                        color: {
                            dark: "#000000",
                            light: "#ffffff"
                        },
                        errorCorrectionLevel: 'M'
                    });
                    canvas.style.borderRadius = '8px';
                    canvas.style.display = 'block';
                    box.appendChild(canvas);
                } else if (typeof QRCode !== 'undefined') {
                    new QRCode(box, {
                        text: unescape(encodeURIComponent(pultUrl)),
                        width: 188,
                        height: 188,
                        colorDark: "#000000",
                        colorLight: "#ffffff",
                        correctLevel: QRCode.CorrectLevel.M
                    });
                } else {
                    box.innerHTML = '<span style="color:var(--danger); font-size:11px;">Библиотека QR недоступна</span>';
                }
            } catch (err) {
                console.error("Ошибка формирования QR:", err);
                box.innerHTML = '<span style="color:var(--danger); font-size:11px;">Ошибка генерации кода</span>';
            }
        }, 40);
    }

    // 📋 Копирование ссылки с монохромной индикацией успеха
    copyQrPultLink() {
        const targetRaceId = this.currentQrRaceId || this.openedEventId;
        const urlToCopy = `https://pero.sotka.one/?race_id=${targetRaceId}`;

        navigator.clipboard.writeText(urlToCopy).then(() => {
            const btn = document.getElementById('qrCopyBtn');
            if (btn) {
                const originalHtml = btn.innerHTML;
                btn.innerHTML = `
                    <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"></polyline></svg>
                    <span>ССЫЛКА СКОПИРОВАНА</span>
                `;
                btn.style.borderColor = 'var(--primary)';
                btn.style.color = 'var(--primary)';
                setTimeout(() => {
                    btn.innerHTML = originalHtml;
                    btn.style.borderColor = 'var(--border)';
                    btn.style.color = 'var(--text-main)';
                }, 1800);
            }
        }).catch(() => {
            prompt("Скопируйте ссылку вручную:", urlToCopy);
        });
    }

 // =========================================================
    // 🔥 МЕТОДЫ УПРАВЛЕНИЯ ПОРЯДКОМ КАТЕГОРИЙ
    // =========================================================
    async updateGroupOrder(raceId, catsJson, newIndex) {
        let catsArray = [];
        // Используем стандартный JSON.parse (без decodeURIComponent)
        try { catsArray = JSON.parse(catsJson); } catch(e) { return; }
        
        const idx = parseInt(newIndex);
        
        catsArray.forEach(catName => {
            if (isNaN(idx)) {
                delete this.localCategoryOrder[catName];
            } else {
                this.localCategoryOrder[catName] = idx;
            }
        });

        await this.saveCategoryOrderToDb(raceId);
    }

    async unmergeCategories(raceId, catsJson) {
        if (!confirm("Разделить эту объединенную группу обратно на исходные категории?")) return;

        let catsArray = [];
        try { catsArray = JSON.parse(catsJson); } catch(e) { return; }
        
        catsArray.forEach(catName => {
            delete this.localCategoryOrder[catName];
        });

        await this.saveCategoryOrderToDb(raceId);
    }

    async saveCategoryOrderToDb(raceId) {
        try {
            await pb.collection('races').update(raceId, { category_order: this.localCategoryOrder }, { requestKey: 'cat_order_update' });
            
            // 1. Перерисовка таблицы в CRM
            if (typeof this.renderFilteredRaceRosterTable === 'function') {
                this.renderFilteredRaceRosterTable();
            }

            // 🔥 2. Мгновенная пересортировка категорий в открытом старт-листе
            if (this.liveService && typeof this.liveService.renderLiveBoard === 'function') {
                this.liveService.renderLiveBoard();
            }
        } catch(e) {
            console.error("Ошибка сохранения порядка категорий:", e);
        }
    }

    // 🔥 УМНАЯ СОРТИРОВКА СИЛЫ КАТЕГОРИИ
    getCatRank(cat) {
        if (!cat) return 9999;
        let rank = 0; let c = cat.toString().toUpperCase();
        
        // Чем меньше число, тем слабее гонщик (стартует раньше)
        if (c.includes('V')) rank += 100; else if (c.includes('U')) rank += 200; else if (c.includes('O')) rank += 300;
        else if (c.includes('E')) rank += 400; else if (c.includes('D')) rank += 500; else if (c.includes('C')) rank += 600;
        else if (c.includes('B')) rank += 700; else if (c.includes('A+')) rank += 900; else if (c.includes('A')) rank += 800;
        else rank += 1000;

        if (c.includes('F') || c.includes('Ж') || c.includes('W')) rank += 10; else rank += 20;

        const matchU = c.match(/U(\d+)/);
        if (matchU) rank += parseInt(matchU[1]); 
        else {
            const matchAge = c.match(/\d/);
            if (matchAge) rank += (9 - parseInt(matchAge[0])); else rank += 5;
        }
        return rank;
    }
	
	
	
	// ==========================================
    // 🔥 СЛОВАРИ ПОКРЫТИЙ И ФОРМАТОВ ГОНОК
    // ==========================================
    
    // 1. ТИП ПОКРЫТИЯ (Где проходит гонка)
    get RACE_SURFACES() {
        return {
            'road': 'ШОССЕ',
            'offroad': 'ГРУНТ',
            'track': 'ТРЕК',
            'indoor': 'ИНДОР'
        };
    }

    // 2. ФОРМАТ ГОНКИ (Как определяем победителя)
    get RACE_FORMATS() {
        return {
            'mass': 'ГРУППА',
            'itt': 'РАЗДЕЛКА',
            'ttt': 'КОМАНДА',
            'crit': 'ПО ОЧКАМ',
            'relay': 'ЭСТАФЕТА'
        };
    }
		
		// ==========================================
    // 🔥 ДЕФОЛТНЫЕ ПРАВИЛА РЕЙТИНГА И КЛАСТЕРОВ 
    // ==========================================
    get DEFAULT_RATING_RULES() {
        return {
            speed_thresholds: {
                road: { M: { "A+": 40.0, "A": 37.0, "B": 34.0, "C": 30.0, "D": 26.0 }, F: { "A+": 36.0, "A": 33.0, "B": 30.0, "C": 26.0, "D": 22.0 } },
                offroad: { M: { "A+": 25.0, "A": 22.0, "B": 19.0, "C": 16.0, "D": 13.0 }, F: { "A+": 22.0, "A": 19.0, "B": 16.0, "C": 13.0, "D": 10.0 } },
                track: { M: { "A+": 48.0, "A": 45.0, "B": 42.0, "C": 38.0, "D": 34.0 }, F: { "A+": 43.0, "A": 40.0, "B": 37.0, "C": 34.0, "D": 30.0 } },
                indoor: { M: { "A+": 42.0, "A": 39.0, "B": 36.0, "C": 32.0, "D": 28.0 }, F: { "A+": 38.0, "A": 35.0, "B": 32.0, "C": 28.0, "D": 24.0 } }
            },
            mass_start_banks: { "A+": 1000, "A": 800, "B": 600, "C": 400, "D": 200, "O": 200, "V": 400 }
        };
    }

        // ==========================================
        // 🔥 УПРАВЛЕНИЕ МУЛЬТИ-ДИСТАНЦИЯМИ (В ОДНОЙ ГОНКЕ)
        // ==========================================
        initDistancesUI() {
        const container = document.getElementById('dynamicDistancesContainer');
        if (!container) return;
        
        const oldInputWrap = document.getElementById('evDist')?.parentElement;
        const oldLapsWrap = document.getElementById('evLaps')?.parentElement;
        
        if (oldInputWrap) oldInputWrap.style.display = 'none';
        if (oldLapsWrap) oldLapsWrap.style.display = 'none';

        this.activeDistances = []; 

        const evCatLogic = document.getElementById('evCatLogic');
        if (evCatLogic) {
            evCatLogic.style.display = 'none';
            if (evCatLogic.previousElementSibling) evCatLogic.previousElementSibling.style.display = 'none';
        }

        container.innerHTML = `
            <div style="margin-bottom: 15px; background: rgba(255,193,7,0.05); padding: 15px; border-radius: 8px; border: 1px dashed var(--primary);">
                <div style="font-size:10px; color:var(--text-muted); text-transform:uppercase; margin-bottom:5px; font-weight:bold;">Длина одного круга (км) *</div>
                <input type="number" id="evLapLength" class="auth-input" style="width:100%; border-radius:8px; border: 1px solid var(--border); background: var(--bg-body); color: var(--text-main); padding: 10px 14px; outline:none;" placeholder="Можно 0, если не важно" step="0.01" min="0">
            </div>

            <div style="font-size:10px; color:var(--text-muted); text-transform:uppercase; margin-bottom:5px; font-weight:bold;">Доступные дистанции / Заезды *</div>
            <div id="distancesTagsList" style="display:flex; flex-direction:column; gap:8px; margin-bottom:10px;"></div>
            
            <div style="display:flex; flex-wrap:wrap; gap:10px; align-items: flex-end; background: var(--bg-surface-hover); padding: 15px; border-radius: 8px; border: 1px solid var(--border);">
                <div style="flex: 2; min-width: 150px;">
                    <div style="font-size:9px; color:var(--text-muted); margin-bottom:4px; text-transform:uppercase;">Название (напр. PRO)</div>
                    <input type="text" id="newDistNameInput" class="auth-input" style="width:100%; margin:0; border-radius:8px; padding: 10px; font-size:12px; outline:none;" placeholder="Напр. Лайт">
                </div>
                <div style="flex: 1; min-width: 80px;">
                    <div style="font-size:9px; color:var(--text-muted); margin-bottom:4px; text-transform:uppercase;">Кругов</div>
                    <input type="number" id="newDistLapsInput" class="auth-input" style="width:100%; margin:0; border-radius:8px; padding: 10px; font-size:12px; outline:none;" placeholder="1" step="1" min="1">
                </div>
				<div style="flex: 1; min-width: 100px;">
                    <div style="font-size:9px; color:var(--text-muted); margin-bottom:4px; text-transform:uppercase;">В экипаже</div>
                    <input type="number" id="newDistSquadInput" class="auth-input" style="width:100%; margin:0; border-radius:8px; padding: 10px; font-size:12px; outline:none;" placeholder="1" value="1" step="1" min="1" title="Количество человек в экипаже (1 = соло)">
                </div>

                <div style="flex: 2; min-width: 150px;">
                    <div style="font-size:9px; color:var(--text-muted); margin-bottom:4px; text-transform:uppercase;">Деление на группы</div>
                    <select id="newDistCatLogicInput" class="auth-input" style="width:100%; margin:0; border-radius:8px; padding: 10px; font-size:12px; outline:none;">
                        <option value="clusters" selected>Кластеры (A+, A, B...)</option>
                        <option value="age">Возрастные (18-22...)</option>
                        <option value="mixed">Смешанные (AM, CF4...)</option>
						<option value="teams">Командные (М / Ж / Микст)</option>
                        <option value="absolute">Абсолют (без групп)</option>
                    </select>
                </div>

                <div style="flex: 3; min-width: 200px;">
                    <div style="font-size:9px; color:var(--text-muted); margin-bottom:4px; text-transform:uppercase;">Правило рейтинга</div>
                    <select id="newDistRuleInput" class="auth-input" style="width:100%; margin:0; border-radius:8px; padding: 10px; font-size:12px; outline:none;">
                        <option value="">По умолчанию (Как у события)</option>
                    </select>
                </div>
                
                <button type="button" class="btn-black" onclick="window.app.crm.addDistanceObjTag(event)" style="padding:10px 15px; border-radius:8px; font-size:11px; height: 38px; flex-shrink: 0; width: 100%; background:var(--primary); color:#000; font-weight:bold; cursor:pointer; transition:0.2s;">+ ДОБАВИТЬ ДИСТАНЦИЮ</button>
            </div>
        `;
    }
	
        addDistanceObjTag(event) {
        if (event) event.preventDefault(); 

        const nameInput = document.getElementById('newDistNameInput');
        const lapsInput = document.getElementById('newDistLapsInput');
        const ruleInput = document.getElementById('newDistRuleInput');
        const catLogicInput = document.getElementById('newDistCatLogicInput');
        const squadInput = document.getElementById('newDistSquadInput');
        
        const name = nameInput.value.trim();
        const laps = parseInt(lapsInput.value);
        const ruleId = ruleInput.value;
        const catLogic = catLogicInput ? catLogicInput.value : 'clusters';
        const squadMax = squadInput && squadInput.value ? parseInt(squadInput.value) : 1;
        
        if (!name || !laps || laps < 1) return alert("Введите название и количество кругов!");
        
        let ruleName = "По умолчанию";
        if (ruleId && ruleInput.options[ruleInput.selectedIndex]) {
            ruleName = ruleInput.options[ruleInput.selectedIndex].text.replace(/\[.*?\] /, '');
        }
        
        let catName = "Кластеры";
        if (catLogicInput && catLogicInput.options[catLogicInput.selectedIndex]) {
            catName = catLogicInput.options[catLogicInput.selectedIndex].text.split(' ')[1]; 
        }
        
        const distId = 'd_' + Date.now().toString(36) + Math.random().toString(36).substr(2, 5);
        
        this.activeDistances.push({ 
            id: distId, 
            name: name, 
            laps: laps, 
            rule_id: ruleId, 
            rule_name: ruleName,
            cat_logic: catLogic,
            cat_name: catName,
			squad_max: squadMax
        });
        
        nameInput.value = '';
        lapsInput.value = '';
        ruleInput.value = ''; 
        if (catLogicInput) catLogicInput.value = 'clusters';
        
        this.renderDistanceObjTags();
    }

        removeDistanceObjTag(distId) {
        this.activeDistances = this.activeDistances.filter(d => d.id !== distId);
        this.renderDistanceObjTags();
    }

    renderDistanceObjTags() {
        const list = document.getElementById('distancesTagsList');
        if (!list) return;
        const lapLength = parseFloat(document.getElementById('evLapLength').value) || 0;
        
        list.innerHTML = this.activeDistances.map(d => {
            const totalKm = lapLength > 0 ? (lapLength * d.laps).toFixed(2) + ' км' : `${d.laps} кр.`;
            const ruleBadge = d.rule_id 
                ? `<span style="background:rgba(0,0,0,0.2); padding:2px 6px; border-radius:4px; font-size:9px;">⚖️ ${this.app.escapeHTML(d.rule_name)}</span>` 
                : `<span style="background:rgba(0,0,0,0.1); padding:2px 6px; border-radius:4px; font-size:9px; opacity:0.7;">⚖️ Баз. правило</span>`;
            
            const catBadge = d.cat_name 
                ? `<span style="background:rgba(255,255,255,0.2); padding:2px 6px; border-radius:4px; font-size:9px; margin-left:4px;">${this.app.escapeHTML(d.cat_name)}</span>`
                : '';

            return `
            <div style="background:var(--primary); color:#000; padding:10px 12px; border-radius:8px; font-size:12px; font-weight:bold; display:flex; justify-content:space-between; align-items:center; gap:10px; width: 100%; margin-bottom: 8px;">
                <div style="display:flex; align-items:center; gap:8px; flex-wrap:wrap;">
                    <span style="font-family:'Unbounded';">${this.app.escapeHTML(d.name)}</span> 
                    <span style="font-family:'Roboto Mono';">(${totalKm})</span>
                    ${catBadge}
                    ${ruleBadge}
                </div>
                <span style="cursor:pointer; background:rgba(0,0,0,0.1); width:24px; height:24px; border-radius:50%; display:flex; justify-content:center; align-items:center; transition:0.2s;" onmouseover="this.style.background='rgba(0,0,0,0.3)'" onmouseout="this.style.background='rgba(0,0,0,0.1)'" onclick="window.app.crm.removeDistanceObjTag('${d.id}')">✕</span>
            </div>
            `;
        }).join('');
    }
	
		async loadCups(pelotonId, preselectedCupId = null) {
        const cupSelectEl = document.getElementById('evCup');
        if (!cupSelectEl) return;
        
        if (!pelotonId) {
            cupSelectEl.innerHTML = '<option value="">-- Вне кубка --</option>';
            cupSelectEl.disabled = true;
            return;
        }
        
        cupSelectEl.disabled = true;
        cupSelectEl.innerHTML = '<option value="">Загрузка кубков...</option>';
        
        try {
            const cups = await pb.collection('cups').getFullList({
                filter: `peloton_id = "${pelotonId}"`,
                sort: '-created',
                requestKey: null
            });
            
            let opts = '<option value="">-- Одиночная гонка (Без кубка) --</option>';
            cups.forEach(c => {
                const isSelected = (preselectedCupId === c.id) ? 'selected' : '';
                opts += `<option value="${c.id}" ${isSelected}>${c.name}</option>`;
            });
            
            cupSelectEl.innerHTML = opts;
            cupSelectEl.disabled = false;
        } catch (e) {
            console.error("Ошибка загрузки кубков:", e);
            cupSelectEl.innerHTML = '<option value="">Ошибка загрузки</option>';
        }
    }

        // 🔥 УНИВЕРСАЛЬНЫЙ СПИСОК ФОРМАТОВ (Больше не зависит от покрытия)
        updateDisciplineList(selectedFormat = '') {
            // В твоем коде select может называться evDiscipline или evFormat, страхуемся:
            const discSelect = document.getElementById('evDiscipline') || document.getElementById('evFormat');
            if (!discSelect) return;
            
            discSelect.innerHTML = '<option value="" disabled selected>Формат...</option>';
            
            for (const [key, name] of Object.entries(this.RACE_FORMATS)) {
                const sel = key === selectedFormat ? 'selected' : '';
                discSelect.innerHTML += `<option value="${key}" ${sel}>${name}</option>`;
            }
        }
	
		// 🔥 ЗАГРУЗЧИК ПРАВИЛ ИЗ БАЗЫ В ВЫПАДАЮЩИЙ СПИСОК
        // 🔥 ЗАГРУЗЧИК ПРАВИЛ ИЗ БАЗЫ (ОПТИМИЗИРОВАННЫЙ)
        async loadRatingRulesUI(selectedRuleId = '') {
            try {
                const rules = await pb.collection('rating_rules').getFullList({ sort: 'type,name', requestKey: null });
                
                let html = '<option value="">🌟 Правила рейтинга: По умолчанию (Базовые)</option>';
                
                rules.forEach(r => {
                    const sel = r.id === selectedRuleId ? 'selected' : '';
                    const typeName = r.type === 'ind' ? 'Разделка' : 'Масс-старт';
                    const surfaceName = this.RACE_SURFACES[r.surface] || r.surface;
                    html += `<option value="${r.id}" ${sel}>[${surfaceName} | ${typeName}] ${this.app.escapeHTML(r.name)}</option>`;
                });
                
                const distRuleSelect = document.getElementById('newDistRuleInput');
                if (distRuleSelect) {
                    distRuleSelect.innerHTML = html; 
                }
                
            } catch (e) {
                console.error('Ошибка загрузки правил рейтинга', e);
            }
        }
		
    // ==========================================
    // ⚡ ФАСАД ДЛЯ ТРАНСЛЯЦИЙ (Здесь больше нет дубликатов!)
    // ==========================================
    cleanupLiveBoard() { this.liveService.cleanupLiveBoard(); }
    closeLiveBoard() { this.liveService.closeLiveBoard(); }
    openLiveBoard(raceId, event) { this.liveService.openLiveBoard(raceId, event); }
    switchLiveTab(t) { this.liveService.switchLiveTab(t); }
    switchLiveSort(s) { this.liveService.switchLiveSort(s); }
    
    // ==========================================
    // БАЗОВЫЕ МЕТОДЫ CRM
    // ==========================================
    getSortedList(sourceData) {
        if (!sourceData) return [];
        let list = [...(sourceData[this.currentTab] || [])];
        if (this.searchQuery) { 
            const q = this.searchQuery.toLowerCase(); 
            list = list.filter(p => ((p.name || '').toLowerCase().includes(q)) || ((p.surname || '').toLowerCase().includes(q)) || ((p.team || '').toLowerCase().includes(q))); 
        }
        return list.sort((a, b) => { 
            let vA = a[this.sort.field], vB = b[this.sort.field]; 
            if (typeof vA === 'string') vA = vA.toLowerCase(); 
            if (typeof vB === 'string') vB = vB.toLowerCase(); 
            if (this.sort.field === 'points' || this.sort.field === 'year') { vA = Number(vA)||0; vB = Number(vB)||0; } 
            return vA < vB ? (this.sort.dir === 'asc' ? -1 : 1) : (vA > vB ? (this.sort.dir === 'asc' ? 1 : -1) : 0); 
        });
    }

    setTab(tab) { this.currentTab = tab; this.renderUI(); }
    setSearch(query) { 
        this.searchQuery = query; 
        this.renderUI(); 
        const input = document.getElementById('pelotonSearchInput');
        if (input) {
            input.focus();
            const len = input.value.length;
            input.setSelectionRange(len, len);
        }
    }
    setSort(field) { 
        if (this.sort.field === field) this.sort.dir = this.sort.dir === 'asc' ? 'desc' : 'asc'; 
        else { this.sort.field = field; this.sort.dir = (field === 'points') ? 'desc' : 'asc'; } 
        this.renderUI(); 
    }
    setCalendarFilter(type) { this.calendarFilter = type; this.renderUI(); }
	setSurfaceFilter(type) { this.surfaceFilter = type; this.formatFilter = 'all'; this.renderUI(); }
    setFormatFilter(type) { this.formatFilter = type; this.renderUI(); }
    setTeamGenderFilter(gender) { this.teamGenderFilter = gender; this.renderUI(); }
    setTeamSearch(query) { this.teamSearchQuery = query.toLowerCase(); }
	setRosterSearch(query) { this.rosterSearchQuery = query; }
	setArchiveYear(year) { this.archiveYear = parseInt(year); this.renderUI(); }
	setRosterTeamFilter(mode) {
        this.rosterTeamFilter = mode;
        const btnAll = document.getElementById('btn-roster-all');
        const btnMyTeam = document.getElementById('btn-roster-myteam');
        
        if (btnAll && btnMyTeam) {
            const activeBg = 'var(--text-main)', activeColor = 'var(--bg-body)';
            const inactiveBg = 'transparent', inactiveColor = 'var(--text-muted)';
            
            btnAll.style.background = mode === 'all' ? activeBg : inactiveBg;
            btnAll.style.color = mode === 'all' ? activeColor : inactiveColor;
            
            btnMyTeam.style.background = mode === 'myteam' ? activeBg : inactiveBg;
            btnMyTeam.style.color = mode === 'myteam' ? activeColor : inactiveColor;
        }
        
        if (typeof this.renderFilteredRaceRosterTable === 'function') {
            this.renderFilteredRaceRosterTable();
        }
    }
	// 🔥 ФУНКЦИЯ: ДОБАВИТЬ/УБРАТЬ ИЗ ИЗБРАННОГО
    async toggleBookmark(raceId, event) {
        if (event) event.stopPropagation(); // Чтобы клик по звездочке не открывал саму гонку
        if (!this.app.currentRider) return;

        // Достаем массив закладок
        let bookmarks = this.app.currentRider.bookmarks || [];
        if (typeof bookmarks === 'string') { try { bookmarks = JSON.parse(bookmarks); } catch(e) { bookmarks = []; } }
        if (!Array.isArray(bookmarks)) bookmarks = [];

        // Добавляем или удаляем
        if (bookmarks.includes(raceId)) {
            bookmarks = bookmarks.filter(id => id !== raceId);
        } else {
            bookmarks.push(raceId);
        }

        // Оптимистично обновляем интерфейс
        this.app.currentRider.bookmarks = bookmarks;
        this.renderUI();

        // Отправляем в базу
        try {
            await pb.collection('riders').update(this.app.currentRider.id, { bookmarks: bookmarks }, { requestKey: null });
        } catch(e) {
            console.error("Ошибка сохранения закладки:", e);
        }
    }

    switchView(view) {
        if (typeof this.cleanupLiveBoard === 'function') {
            this.cleanupLiveBoard();
        }
        const liveModal = document.getElementById('liveBoardModal');
        if (liveModal && liveModal.style.display === 'flex') {
            liveModal.style.display = 'none';
        }
        
        this.currentView = view;
        
        // 🔥 ДИНАМИЧЕСКОЕ ИМЯ КОМАНДЫ ДЛЯ ЗАГОЛОВКА (Поддержка мульти-клубов)
        let dynamicTeamName = 'Моя команда';
        if (view === 'team') {
            let tId = this.viewedTeamId;
            if (!tId && this.app.currentRider?.team_id) {
                const myTeams = Array.isArray(this.app.currentRider.team_id) ? this.app.currentRider.team_id : [this.app.currentRider.team_id];
                tId = myTeams.find(id => this.app.teamsMap[id]?.peloton_id === this.app.currentPelotonFilter) || myTeams[0];
            }
            if (tId && this.app.teamsMap[tId]) {
                dynamicTeamName = this.app.teamsMap[tId].name;
            }
        }

        const headerData = {
            'calendar': { icon: '📅', title: 'Календарь', sub: 'Гонки и тренировки' },
            'team': { icon: '👥', title: dynamicTeamName, sub: 'Управление составом' }, // 👈 Теперь тут будет реальное имя!
            'market': { icon: '🔄', title: 'Трансферы', sub: 'Свободные агенты' },
            'rating': { icon: '🏆', title: 'Рейтинг', sub: 'Командный зачет' },
            'rules': { icon: '⚙️', title: 'Библиотека правил', sub: 'Настройка начисления очков' }
        };

        const hd = headerData[view];
        if (hd) {
            const hIcon = document.getElementById('crmHeaderAvatar');
            const hTitle = document.getElementById('crmHeaderTitle');
            const hSub = document.getElementById('crmHeaderSub');
            if (hIcon) hIcon.innerText = hd.icon;
            if (hTitle) hTitle.innerText = hd.title.toUpperCase();
            if (hSub) hSub.innerText = hd.sub;
        }

        // Перерисовываем левое меню, чтобы активная желтая полоска перепрыгнула на нужный пункт
        if (this.app && typeof this.app.renderPelotonsTab === 'function') {
            this.app.renderPelotonsTab();
        }

        // Грузим сам контент раздела
        this.loadData();
        
        // 🔥 Умное поведение для мобилок: открываем правую панель
        const ws = document.getElementById('pelotonWorkspace');
        if (ws && window.innerWidth <= 768) {
            ws.classList.add('mobile-open');
        }
    }

  async loadData() {
        const contentArea = document.getElementById('crmContentArea');
        if(!contentArea) return;
        contentArea.innerHTML = `<div style="display:flex; flex-direction:column; align-items:center; justify-content:center; height:100%;"><div class="spinner" style="width:40px; height:40px; border-width:4px; display:inline-block; border-color: var(--primary) transparent transparent transparent;"></div><div style="margin-top:15px; font-family:'Unbounded'; font-size:12px; color:var(--text-muted); font-weight:800;">СИНХРОНИЗАЦИЯ...</div></div>`;
        
        const currentFilterId = this.app.currentPelotonFilter || 'all';

        try {
            if (this.currentView === 'calendar') {
                let records = await pb.collection('races').getFullList({ sort: 'date', expand: 'race_type_id, creator_id, team_id, cup_id, peloton_id, judge_id', requestKey: null });
                let allRosters = [];
                try { allRosters = await pb.collection('race_rosters').getFullList({ fields: 'race_id,rider_id,status', requestKey: null }); } catch(e) {}
                
                // 🔥 ПРАВИЛЬНЫЙ ПОИСК СУДЕЙ (КАК У ОРГАНИЗАТОРОВ)
                let judgeQueryIds = [];
                let judgeQueryEmails = [];
                
                records.forEach(r => {
                    let jObj = r.expand?.judge_id;
                    if (Array.isArray(jObj)) jObj = jObj[0];
                    if (jObj) {
                        judgeQueryIds.push(jObj.id);
                        if (jObj.email) judgeQueryEmails.push(jObj.email);
                    }
                });
                
                judgeQueryIds = [...new Set(judgeQueryIds)];
                judgeQueryEmails = [...new Set(judgeQueryEmails)];

                let judgesRiders = [];
                if (judgeQueryIds.length > 0 || judgeQueryEmails.length > 0) {
                    try {
                        let filters = [];
                        if (judgeQueryIds.length > 0) filters.push( ...judgeQueryIds.map(id => `user_id="${id}"`) );
                        if (judgeQueryEmails.length > 0) filters.push( ...judgeQueryEmails.map(email => `email="${email}"`) );
                        
                        const jFilters = filters.join(' || ');
                        judgesRiders = await pb.collection('riders').getFullList({ filter: jFilters, requestKey: null });
                    } catch(e) { console.warn("Не удалось подгрузить профили судей", e); }
                }

                const myId = this.app.currentRider?.id;
                const roles = this.app.usersMap[this.app.currentRider?.email] || [];
                const isSuper = JSON.stringify(roles).includes('superadmin');
                const myTeams = Array.isArray(this.app.currentRider?.team_id) ? this.app.currentRider.team_id : (this.app.currentRider?.team_id ? [this.app.currentRider.team_id] : []);

                // 🛡️ ПЕРВИЧНЫЙ ФИЛЬТР
                records = records.filter(r => {
                    if (isSuper) return true; 
                    const amIRegistered = allRosters.some(roster => roster.race_id === r.id && roster.rider_id === myId && roster.status !== 'canceled');
                    if (amIRegistered) return true; 
                    
                    if (r.level === 'team') {
                        if (r.is_public) return true;
                        return myTeams.includes(r.team_id);
                    }
                    if (r.level === 'personal') return r.creator_id === myId;
                    
                    if (r.level === 'peloton') {
                        let pId = r.peloton_id; 
                        if (Array.isArray(pId)) pId = pId[0]; 
                        if (pId && !this.app.pelotonsMap[pId]) return false; 
                    }
                    return true;
                });

                // 🗂️ ВТОРИЧНЫЙ ФИЛЬТР
                if (currentFilterId !== 'all') {
                    records = records.filter(r => {
                        let pId = r.peloton_id; 
                        if (!pId) return false; 
                        if (Array.isArray(pId)) return pId.includes(currentFilterId); 
                        return pId === currentFilterId;
                    });
                } else {
                    records = records.filter(r => {
                        if (r.level === 'peloton') {
                            let pId = r.peloton_id; 
                            if (Array.isArray(pId)) pId = pId[0];
                            const peloton = pId ? this.app.pelotonsMap[pId] : null;
                            
                            if (peloton && peloton.is_private === true) {
                                if (isSuper) return true; 
                                const amIRegistered = allRosters.some(roster => roster.race_id === r.id && roster.rider_id === myId && roster.status !== 'canceled');
                                if (!amIRegistered) return false; 
                            }
                        }
                        return true;
                    });
                }

                const rosterCounts = {};
                allRosters.forEach(r => { if (r.status !== 'canceled') rosterCounts[r.race_id] = (rosterCounts[r.race_id] || 0) + 1; });

                this.dataCalendar = records.map(r => {
                    let typeName = r.expand?.race_type_id?.name || 'ЗАЕЗД';
                    if (r.format && this.RACE_FORMATS[r.format]) {typeName = this.RACE_FORMATS[r.format];}
                    if (r.surface && this.RACE_SURFACES[r.surface]) {typeName = `${this.RACE_SURFACES[r.surface]} • ${typeName}`;}

                    let badgeBg = "var(--warning)"; 
                    let badgeColor = "#000";
                    let badgeText = typeName.toUpperCase();

                    if (r.level === 'peloton') {
                        badgeBg = "var(--primary)"; 
                        badgeColor = "#000";
                    } else if (r.level === 'team') {
                        badgeBg = "var(--info)"; 
                        badgeColor = "#fff";
                    }
                    
                    let orgName = 'Организатор';
                    if (r.level === 'peloton' && r.expand?.peloton_id) {
                        orgName = r.expand.peloton_id.name; 
                    } else if (r.expand?.creator_id) {
                        const creator = r.expand.creator_id;
                        if (creator.name) {
                            orgName = creator.name;
                        } else if (creator.first_name || creator.last_name) {
                            orgName = `${creator.first_name || ''} ${creator.last_name || ''}`.trim();
                        }
                    }
                    
                    let finalJudgeName = 'Не назначен';
                    let finalJudgeRiderId = null;
                    
                    let jObj = r.expand?.judge_id;
                    if (Array.isArray(jObj)) jObj = jObj[0];

                    if (jObj) {
                        finalJudgeName = jObj.name || jObj.username || jObj.email || 'Судья';
                        const jRider = judgesRiders.find(jr => jr.user_id === jObj.id || jr.email === jObj.email);
                        if (jRider) {
                            finalJudgeName = `${jRider.first_name} ${jRider.last_name}`;
                            finalJudgeRiderId = jRider.id; 
                        }
                    }

                    return { 
                        id: r.id, 
                        name: r.name, 
                        rawDate: r.date, 
                        date: r.date, // 👈 Сохраняем исходную ISO-дату для расчетов и фильтров
                        formattedDate: new Date(r.date).toLocaleString('ru-RU', {day:'numeric', month:'short', hour:'2-digit', minute:'2-digit'}),
                        level: r.level || 'personal', 
                        is_public: r.is_public || false, 
                        distance: r.distance || 0, 
                        type: typeName, 
                        status: r.status, 
                        org: orgName, 
                        creator_id: r.creator_id,  
                        judge_id: r.judge_id,
                        judgeName: finalJudgeName,
                        judgeRiderId: finalJudgeRiderId,
                        expand: r.expand, 
                        rosterCount: rosterCounts[r.id] || 0,
                        isRegistered: allRosters.some(roster => roster.race_id === r.id && roster.rider_id === myId && roster.status !== 'canceled'),
                        myRosterStatus: allRosters.find(roster => roster.race_id === r.id && roster.rider_id === myId)?.status || null,
                        surface: r.surface,
                        format: r.format,
                        cat_logic: r.cat_logic,
                        max_riders: r.max_riders || 0,
                        category_order: r.category_order,
                        peloton_id: r.peloton_id, // 👈 Возвращаем привязку к лиге
                        verification_status: r.verification_status, // 👈 Сохраняем признак официальной гонки
                        cupId: Array.isArray(r.cup_id) ? r.cup_id[0] : r.cup_id,
                        cupName: r.expand?.cup_id ? (Array.isArray(r.expand.cup_id) ? r.expand.cup_id[0].name : r.expand.cup_id.name) : null,
                        badgeBg: badgeBg,
                        badgeColor: badgeColor,
                        badgeText: badgeText
                    };
                });
            } 
            else if (this.currentView === 'team') {
                let targetTeamId = this.viewedTeamId;
                // 🔥 ЗАЩИТА: Добавлен `?` после this.app.currentRider
                if (!targetTeamId && this.app.currentRider?.team_id) {
                    const myTeams = Array.isArray(this.app.currentRider.team_id) ? this.app.currentRider.team_id : [this.app.currentRider.team_id];
                    targetTeamId = myTeams.find(id => this.app.teamsMap[id]?.peloton_id === currentFilterId) || myTeams[0];
                }

                if (targetTeamId) {
                    const records = await pb.collection('riders').getFullList({ filter: `team_id ~ "${targetTeamId}"`, sort: '-rating', requestKey: null }); 
                    let m = [], f = [];
                    records.forEach(r => { 
                        const gStr = String(r.gender || 'M').toUpperCase().trim(); 
const p = { id: r.id, name: r.first_name, surname: r.last_name, year: r.yob, gender: gStr, group: r.base_cluster || 'B', points: r.rating || 0, team: this.getRiderTeamNames(r) }; 
                        if (gStr === 'F' || gStr === 'Ж') f.push(p); else m.push(p); 
                    }); 
                    this.dataTeam = { m, f };
                } else { this.dataTeam = { m: [], f: [] }; }
            }
            else if (this.currentView === 'market') { 
                const oneTeam = Object.values(this.app.teamsMap).find(t => t.name && t.name.toUpperCase().includes('ONE TEAM'));
                const oneTeamId = oneTeam ? oneTeam.id : null;
                if (oneTeamId) {
                    const records = await pb.collection('riders').getFullList({ filter: `team_id ~ "${oneTeamId}"`, sort: '-rating', requestKey: null }); 
                    let m = [], f = [];
                    records.forEach(r => { 
                        const gStr = String(r.gender || 'M').toUpperCase().trim(); 
                        const p = { id: r.id, name: r.first_name, surname: r.last_name, year: r.yob, gender: gStr, group: r.base_cluster || 'B', points: r.rating || 0, team: this.getRiderTeamNames(r) };
                        if (gStr === 'F' || gStr === 'Ж') f.push(p); else m.push(p); 
                    }); 
                    this.dataMarket = { m, f };
                }
            }
            else if (this.currentView === 'rating') {
                let teams = await pb.collection('teams').getFullList({ requestKey: null }); 
                
                // 1. 🔥 ФИЛЬТР ПО РОДНОМУ (ПЕРВОМУ) ПЕЛОТОНУ КОМАНДЫ
                if (currentFilterId !== 'all') {
                    teams = teams.filter(t => {
                        let pId = t.peloton_id; if (!pId) return false;
                        let homeP = Array.isArray(pId) ? pId[0] : pId;
                        if (typeof homeP === 'object' && homeP !== null) homeP = homeP.id;
                        return String(homeP) === String(currentFilterId);
                    });
                }

                // 2. 🔥 ДИНАМИЧЕСКИЙ РАСЧЕТ ТОП-3 И ОБЩИХ ОЧКОВ
                const ridersList = Object.values(this.app.ridersMap || {});
                
                let calculatedTeams = teams.map(t => {
                    const isOneTeam = t.name && t.name.toUpperCase().includes('ONE TEAM');
                    
                    // Находим гонщиков этой команды (исключая системного бота)
                    let teamRiders = ridersList.filter(r => {
                        if (r.email === 'bot@sotka.one') return false;
                        const rTeams = Array.isArray(r.team_id) ? r.team_id : (r.team_id ? [r.team_id] : []);
                        return rTeams.includes(t.id);
                    });

                    // Сортируем гонщиков команды по личному рейтингу (от сильных к слабым)
                    teamRiders.sort((a, b) => (b.rating || 0) - (a.rating || 0));

                    // Берем 3 лучших результата
                    const top3Riders = teamRiders.slice(0, 3);
                    const top3Points = top3Riders.reduce((sum, r) => sum + (r.rating || 0), 0);
                    
                    // Сумма всех участников
                    const totalPoints = teamRiders.reduce((sum, r) => sum + (r.rating || 0), 0);

                    return {
                        id: t.id,
                        name: t.name,
                        top3Points: top3Points,
                        totalPoints: totalPoints,
                        isOneTeam: isOneTeam
                    };
                });

                // 3. 🔥 РАЗДЕЛЕНИЕ: Зачётные команды отдельно, ONE TEAM отдельно
                let regularTeams = calculatedTeams.filter(t => !t.isOneTeam);
                let oneTeams = calculatedTeams.filter(t => t.isOneTeam);

                // Сортируем регулярные команды по Топ-3 очкам (при равенстве — по общей сумме)
                regularTeams.sort((a, b) => {
                    if (b.top3Points !== a.top3Points) return b.top3Points - a.top3Points;
                    return b.totalPoints - a.totalPoints;
                });

                // ONE TEAM отправляется в самый подвал
                this.dataRatings = [...regularTeams, ...oneTeams];
            }
            else if (this.currentView === 'rules') {
                const rulesList = await pb.collection('rating_rules').getFullList({ sort: 'type,name', requestKey: null });
                this.dataRules = rulesList;
            }
            this.renderUI();
        } catch(e) { 
            // 🔥 ВЫВОДИМ ОШИБКУ В КОНСОЛЬ ДЛЯ ДЕБАГА
            console.error("🔥 ОШИБКА СЕТИ В loadData:", e);
            contentArea.innerHTML = `<div style="text-align:center; padding: 40px; color: var(--danger); font-family:'Unbounded';">ОШИБКА СЕТИ<div style="font-size:10px; font-family:'Manrope'; color:var(--text-muted); margin-top:10px;">${e.message || ''}</div></div>`; 
        }
    }
    renderUI() {
        const contentArea = document.getElementById('crmContentArea');
        let html = '';

        if (this.currentView === 'calendar') {
            const roles = this.app.usersMap[this.app.currentRider?.email] || [];
            const rStr = JSON.stringify(roles);
            const isAdmin = rStr.includes('admin') || rStr.includes('superadmin');
            const isCaptain = rStr.includes('captain');

            this.calendarFilter = this.calendarFilter && this.calendarFilter !== 'all' ? this.calendarFilter : 'races';

            let subMenuHtml = `<div style="display:flex; gap:8px; margin-bottom: 20px; overflow-x:auto; scrollbar-width:none; padding-bottom:4px; -webkit-overflow-scrolling:touch;">`;
            if (isAdmin || isCaptain) {
                subMenuHtml += `<button style="background:var(--primary); color:#000; border:none; padding:8px 16px; border-radius:50px; font-family:'Unbounded'; font-weight:800; font-size:10px; cursor:pointer; flex-shrink:0; transition:0.2s; box-shadow: 0 4px 10px rgba(255,193,7,0.3);" onclick="window.app.crm.openCreateEventModal()">+ СОЗДАТЬ</button>`;
                subMenuHtml += `<div style="width:1px; background:var(--border); margin:0 4px; flex-shrink:0;"></div>`;
            }

            const filters = [
                { id: 'fav', name: '⭐ МОИ' },
                { id: 'races', name: 'ГОНКИ' },
                { id: 'team', name: 'КОМАНДНЫЕ' },
                { id: 'archive', name: 'РЕЗУЛЬТАТЫ' }
            ];
			// 🔥 ВКЛАДКА МОДЕРАЦИИ ДЛЯ ОРГАНИЗАТОРА
            if (isAdmin) {
                const pendingCount = this.dataCalendar.filter(r => r.verification_status === 'pending').length;
                filters.push({ 
                    id: 'moderation', 
                    name: `МОДЕРАЦИЯ ${pendingCount > 0 ? `(${pendingCount})` : ''}` 
                });
            }

            filters.forEach(f => {
                const isActive = this.calendarFilter === f.id;
                const bg = isActive ? 'var(--text-main)' : 'transparent';
                const color = isActive ? 'var(--bg-body)' : 'var(--text-muted)';
                const border = isActive ? 'var(--text-main)' : 'var(--border)';
                subMenuHtml += `<button style="background:${bg}; color:${color}; border:1px solid ${border}; padding:8px 16px; border-radius:50px; font-family:'Unbounded'; font-weight:800; font-size:10px; cursor:pointer; flex-shrink:0; transition:0.2s;" onclick="window.app.crm.setCalendarFilter('${f.id}')">${f.name}</button>`;
            });
            subMenuHtml += `</div>`;
            html += subMenuHtml;

            const archiveEvents = this.dataCalendar.filter(ev => ev.status === 'Finished');
            let availableYears = [...new Set(archiveEvents.map(ev => new Date(ev.rawDate || ev.date).getFullYear()))].sort((a,b) => b - a);
            const currentRealYear = new Date().getFullYear();
            if (availableYears.length === 0) availableYears = [currentRealYear];
            if (!this.archiveYear) this.archiveYear = availableYears.includes(currentRealYear) ? currentRealYear : availableYears[0];

            if (this.calendarFilter === 'archive') {
                html += `
                <div style="margin-bottom: 25px;">
                    <select class="auth-input" style="width: auto; padding: 10px 20px; border-radius: 50px; background: var(--bg-surface-hover); border: 1px solid var(--primary); color: var(--primary); font-family: 'Unbounded'; font-size: 11px; font-weight: 800; cursor: pointer; outline: none; transition: 0.2s;" onchange="window.app.crm.setArchiveYear(this.value)">
                        ${availableYears.map(y => `<option value="${y}" ${this.archiveYear === y ? 'selected' : ''} style="background:var(--bg-body); color:var(--text-main);">СЕЗОН ${y}</option>`).join('')}
                    </select>
                </div>`;
            }

            let baseEvents = this.dataCalendar.filter(r => {
                const isFinished = r.status === 'Finished';
                
                if (this.calendarFilter === 'moderation') {
                    return r.verification_status === 'pending';
                }
                if (this.calendarFilter === 'archive') {
                    if (!isFinished) return false;
                    return new Date(r.rawDate || r.date).getFullYear() === this.archiveYear;
                }
                if (isFinished) return false;
                if (this.calendarFilter === 'races') return (r.level === 'peloton' && r.verification_status !== 'pending');
                if (this.calendarFilter === 'team') return r.level === 'team';
                if (this.calendarFilter === 'fav') {
                    let bookmarks = this.app.currentRider?.bookmarks || [];
                    if (typeof bookmarks === 'string') { try { bookmarks = JSON.parse(bookmarks); } catch(e) { bookmarks = []; } }
                    if (!Array.isArray(bookmarks)) bookmarks = [];

                    // 🔥 Считываем подписки на спортсменов и команды
                    let subs = this.app.currentRider?.subscriptions || { riders: [], teams: [] };
                    if (typeof subs === 'string') { try { subs = JSON.parse(subs); } catch(e) { subs = { riders: [], teams: [] }; } }
                    const subRiders = Array.isArray(subs.riders) ? subs.riders : [];
                    const subTeams = Array.isArray(subs.teams) ? subs.teams : [];

                    const isBookmarked = bookmarks.includes(r.id);
                    const isMyRegistration = r.isRegistered;
                    const isCreator = r.creator_id === this.app.currentRider?.id;
                    const isSubscribedCreator = r.creator_id && subRiders.includes(r.creator_id);
                    const isSubscribedTeam = r.team_id && subTeams.includes(r.team_id);

                    return isBookmarked || isMyRegistration || isCreator || isSubscribedCreator || isSubscribedTeam;
                }
                return true;
            });

            // 💡 ЭТАП 2: УМНЫЕ КНОПКИ ПОКРЫТИЙ И ФОРМАТОВ
            const availableSurfaceIds = [...new Set(baseEvents.map(ev => ev.surface).filter(Boolean))];
            const availableFormatIds = [...new Set(baseEvents.map(ev => ev.format).filter(Boolean))];

            this.surfaceFilter = this.surfaceFilter || 'all';
            this.formatFilter = this.formatFilter || 'all';
            
            if (this.surfaceFilter !== 'all' && !availableSurfaceIds.includes(this.surfaceFilter)) this.surfaceFilter = 'all';
            if (this.formatFilter !== 'all' && !availableFormatIds.includes(this.formatFilter)) this.formatFilter = 'all';

            if (availableSurfaceIds.length > 0 || availableFormatIds.length > 0) {
                let filtersHtml = `<div style="display:flex; gap:8px; margin-bottom: 20px; overflow-x:auto; scrollbar-width:none; padding-bottom:4px; -webkit-overflow-scrolling:touch; align-items:center;">`;
                
                if (availableSurfaceIds.length > 0) {
                    const allSurfActive = this.surfaceFilter === 'all';
                    filtersHtml += `<button style="background:${allSurfActive ? 'rgba(255, 193, 7, 0.15)' : 'transparent'}; color:${allSurfActive ? 'var(--primary)' : 'var(--text-muted)'}; border:1px solid ${allSurfActive ? 'var(--primary)' : 'var(--border)'}; padding:6px 12px; border-radius:8px; font-family:'Unbounded'; font-weight:800; font-size:9px; cursor:pointer; flex-shrink:0; transition:0.2s;" onclick="window.app.crm.setSurfaceFilter('all')">ВСЕ ПОКРЫТИЯ</button>`;
                    
                    availableSurfaceIds.forEach(sId => {
                        const isActive = this.surfaceFilter === sId;
                        const bg = isActive ? 'rgba(255, 193, 7, 0.15)' : 'transparent';
                        const color = isActive ? 'var(--primary)' : 'var(--text-muted)';
                        const border = isActive ? 'var(--primary)' : 'var(--border)';
                        const sName = this.RACE_SURFACES[sId] || sId.toUpperCase(); 
                        
                        filtersHtml += `<button style="background:${bg}; color:${color}; border:1px solid ${border}; padding:6px 12px; border-radius:8px; font-family:'Unbounded'; font-weight:800; font-size:9px; cursor:pointer; flex-shrink:0; transition:0.2s;" onclick="window.app.crm.setSurfaceFilter('${sId}')">${sName}</button>`;
                    });
                }

                if (availableSurfaceIds.length > 0 && availableFormatIds.length > 0) {
                    filtersHtml += `<div style="width:1px; height:16px; background:var(--border); margin:0 4px; flex-shrink:0;"></div>`;
                }

                if (availableFormatIds.length > 0) {
                    availableFormatIds.forEach(fId => {
                        const isActive = this.formatFilter === fId;
                        const bg = isActive ? 'rgba(59, 130, 246, 0.15)' : 'transparent';
                        const color = isActive ? 'var(--info)' : 'var(--text-muted)';
                        const border = isActive ? 'var(--info)' : 'var(--border)';
                        const fName = this.RACE_FORMATS[fId] || fId.toUpperCase(); 
                        
                        const action = isActive ? 'all' : fId; 
                        filtersHtml += `<button style="background:${bg}; color:${color}; border:1px solid ${border}; padding:6px 12px; border-radius:8px; font-family:'Unbounded'; font-weight:800; font-size:9px; cursor:pointer; flex-shrink:0; transition:0.2s;" onclick="window.app.crm.setFormatFilter('${action}')">${fName}</button>`;
                    });
                }

                filtersHtml += `</div>`;
                html += filtersHtml;
            }

            // 💡 ЭТАП 3: ФИНАЛЬНАЯ ФИЛЬТРАЦИЯ
            let eventsToRender = baseEvents.filter(r => {
                if (this.surfaceFilter !== 'all' && r.surface !== this.surfaceFilter) return false;
                if (this.formatFilter !== 'all' && r.format !== this.formatFilter) return false;
                return true;
            });
			
			// 🔥 Скрываем чужие тренировки без подписки из общего списка
                if (this.calendarFilter === 'all' || this.calendarFilter === 'races') {
                    eventsToRender = eventsToRender.filter(r => this.app.canUserSeeEvent(r));
                }

            if (this.calendarFilter === 'archive') {
                eventsToRender.sort((a, b) => new Date(b.rawDate || b.date) - new Date(a.rawDate || a.date)); 
            } else {
                eventsToRender.sort((a, b) => new Date(a.rawDate || a.date) - new Date(b.rawDate || b.date)); 
            }

            if (eventsToRender.length === 0) { 
                html += '<div style="text-align:center; padding:60px; color:var(--text-muted); font-family:\'Unbounded\'; border: 1px dashed var(--border); border-radius: 20px;">СОБЫТИЙ НЕ НАЙДЕНО</div>'; 
            } else {
                let currentMonth = '';
                let gridOpen = false;

                eventsToRender.forEach(r => {
                    let dObj = new Date(r.rawDate || r.date);
                    let monthName = dObj.toLocaleDateString('ru-RU', { month: 'long', year: 'numeric' }).toUpperCase();
                    
                    if (monthName !== currentMonth) {
                        if (gridOpen) { html += '</div>'; gridOpen = false; } 
                        html += `<div style="font-family:'Unbounded'; font-weight:800; font-size:14px; color:var(--text-main); margin: 30px 0 15px 0; display:flex; align-items:center; gap:10px; opacity: 0.9;"><span style="display:inline-block; width:8px; height:8px; background:var(--primary); border-radius:50%; box-shadow: 0 0 10px var(--primary);"></span>${monthName}</div>`;
                        currentMonth = monthName;
                    }

                    if (!gridOpen) { html += '<div style="display:flex; flex-direction:column; gap:8px;">'; gridOpen = true; }

                    let day = dObj.getDate();
                    let monthNum = (dObj.getMonth() + 1).toString().padStart(2, '0');
                    let year = dObj.getFullYear();
                    let time = dObj.toLocaleTimeString('ru-RU', { hour: '2-digit', minute: '2-digit' });

                    let org = r.org; if (r.level === 'team' && r.expand?.team_id) org = `<b style="color:var(--info);">${r.expand.team_id.name}</b>`;
                    
                    let cupHtml = '';
                    if (r.cupId && r.cupName) {
                        cupHtml = `<div onclick="window.app.crm.openCupStandings('${r.cupId}')" style="display:inline-flex; align-items:center; gap:5px; background:rgba(255,193,7,0.1); color:var(--primary); border:1px solid rgba(255,193,7,0.3); padding:4px 8px; border-radius:6px; font-size:9px; font-family:'Unbounded'; font-weight:800; cursor:pointer; margin-bottom:8px; transition:0.2s;" onmouseover="this.style.background='var(--primary)'; this.style.color='#000';" onmouseout="this.style.background='rgba(255,193,7,0.1)'; this.style.color='var(--primary)';">🏆 ${r.cupName.toUpperCase()} <span>→</span></div>`;
                    }
                    
                    // 🔥 ОПРЕДЕЛЯЕМ ПРАВА НА УПРАВЛЕНИЕ ЗАЯВКАМИ
                    const isCreator = r.creator_id === this.app.currentRider?.id;
                    const isAssignedJudge = r.judgeRiderId === this.app.currentRider?.id;
                    const isManagerOrJudge = JSON.stringify(roles).includes('admin') || JSON.stringify(roles).includes('superadmin') || JSON.stringify(roles).includes('judge');
                    const canManageRoster = isManagerOrJudge || isCreator || isAssignedJudge;

                    let primaryHtml = '';
                    if (r.status === 'LIVE') {
                        primaryHtml = `<button class="p-btn-black btn-live" onclick="window.app.openLiveBoard('${r.id}', event)" style="width:100%; margin:0;"><div style="width:6px; height:6px; background:currentColor; border-radius:50%; animation: dot-pulse 1s infinite; display:inline-block; vertical-align:middle; margin-right:5px;"></div>LIVE ПРОТОКОЛ</button>`; 
                    } else if (r.status === 'Finished') {
                        primaryHtml = `<button class="p-btn-black btn-res" onclick="window.app.openLiveBoard('${r.id}', event)" style="width:100%; margin:0;">РЕЗУЛЬТАТЫ</button>`; 
                    } else if (r.status === 'Registration') {
                        const isFull = r.max_riders > 0 && r.rosterCount >= r.max_riders;
                        
                        // 🔥 ФИКС: Админы и судьи игнорируют блокировку SOLD OUT
                        if (isFull && !r.isRegistered && !canManageRoster) {
                            primaryHtml = `<button class="p-btn-black" style="width:100%; margin:0; background: var(--bg-surface-hover); color: var(--text-muted); border: 1px solid var(--border); cursor: not-allowed;">МЕСТ НЕТ (SOLD OUT)</button>`; 
                        } else {
                            primaryHtml = `<button class="p-btn-black btn-reg" onclick="window.app.crm.openRaceRoster('${r.id}', '${this.app.escapeHTML(r.name)}', '${r.type}')" style="width:100%; margin:0;">УЧАСТНИКИ / ЗАЯВКА</button>`; 
                        }
                    } else {
                        primaryHtml = `<div style="text-align:center; width:100%; font-size:10px; font-family:'Unbounded'; color:var(--text-muted); font-weight:800; padding:12px 0;">${r.status}</div>`; 
                    }

                    const baseBtnStyle = "height:32px; border-radius:8px; font-family:'Unbounded', sans-serif; font-size:10px; font-weight:800; display:flex; align-items:center; justify-content:center; cursor:pointer; transition:0.2s; box-sizing:border-box;";
                    const iconBtnStyle = baseBtnStyle + " width:32px; padding:0;";
                    const textBtnStyle = baseBtnStyle + " padding:0 12px; gap:6px;";

                    let judgeBtn = '';
                    if (isManagerOrJudge && (r.status === 'LIVE' || r.status === 'Finished')) {
                        judgeBtn = `<button style="${textBtnStyle} background:rgba(255,193,7,0.1); color:var(--warning); border:1px solid rgba(255,193,7,0.3);" onclick="window.open('https://sotka.one/repult?race_id=${r.id}', '_blank')">⚖️ СУДИТЬ</button>`;
                    }

                    // 🔥 НОВАЯ КНОПКА: Управление заявками для Лайва, Анонсов и Завершенных гонок
                    let manageRosterBtn = '';
                    if (canManageRoster && r.status !== 'Registration') {
                        manageRosterBtn = `<button style="${textBtnStyle} background:rgba(40,167,69,0.1); color:var(--success); border:1px solid rgba(40,167,69,0.3);" title="Управление заявками" onclick="window.app.crm.openRaceRoster('${r.id}', '${this.app.escapeHTML(r.name)}', '${r.type}')">ЗАЯВКИ</button>`;
                    }

                    let chatBtn = '';
                    const raceChat = window.app.chats.find(c => c.race_id === r.id);
                    if (raceChat) {
                        chatBtn = `<button style="${textBtnStyle} background:rgba(59,130,246,0.1); color:var(--info); border:1px solid rgba(59,130,246,0.3);" onclick="window.app.switchTab('chats'); window.app.openChat('${raceChat.id}')">💬 ЧАТ</button>`;
                    }

                    let deleteBtn = ''; let editBtn = '';
                    if ((isAdmin || isCreator) && (r.status === 'Registration' || r.status === 'Скоро')) {
                        editBtn = `<button style="${iconBtnStyle} background:rgba(255,193,7,0.1); color:var(--warning); border:1px solid rgba(255,193,7,0.3); font-size:14px;" title="Редактировать гонку" onclick="window.app.crm.openEditEventModal('${r.id}')">✏️</button>`;
                        deleteBtn = `<button style="${iconBtnStyle} background:rgba(255,51,102,0.1); color:var(--danger); border:1px solid rgba(255,51,102,0.3); font-size:14px;" title="Удалить гонку" onclick="window.app.crm.deleteRace('${r.id}')">🗑️</button>`;
                    }
					
					let startPultBtn = '';
if (isManagerOrJudge || isAssignedJudge) {
    startPultBtn = `<button style="${textBtnStyle} background:rgba(255,193,7,0.1); color:var(--primary); border:1px solid rgba(255,193,7,0.3);" title="QR-код для Стартового пульта" onclick="window.app.crm.openRaceQrModal('${r.id}', '${this.app.escapeHTML(r.name)}')">📱 СТАРТОВЫЙ ПУЛЬТ</button>`;
}
                    let inviteBtn = '';
                    const myTeamsForInvite = Array.isArray(this.app.currentRider?.team_id) ? this.app.currentRider.team_id : (this.app.currentRider?.team_id ? [this.app.currentRider.team_id] : []);
                    const rTeams = Array.isArray(r.team_id) ? r.team_id : (r.team_id ? [r.team_id] : []);
                    const isMyTeamEvent = r.level === 'team' && myTeamsForInvite.some(id => rTeams.includes(id));
                    
                    if ((r.level === 'personal' && isCreator) || (r.level === 'team' && (isCreator || isAdmin || (isCaptain && isMyTeamEvent)))) {
                        const inviteTextRaw = `Привет! Приглашаю на тренировку «${r.name}» (${r.date}). Жми кнопку, чтобы добавиться в старт-лист:\n\n[ACTION:REGISTER:${r.id}]`;
                        const safeInviteText = encodeURIComponent(inviteTextRaw);
                        inviteBtn = `<button style="${textBtnStyle} background:rgba(168,85,247,0.1); color:#a855f7; border:1px solid rgba(168,85,247,0.3);" title="Скопировать инвайт" onclick="window.app.copyText(decodeURIComponent('${safeInviteText}'), 'Ссылка скопирована! Отправьте её в любой чат VILKA.')">🔗 ПРИГЛАСИТЬ</button>`;
                    }

                    let posterBtn = '';
                    if (r.isRegistered) {
                        const pText = (r.status === 'Finished' || r.myRosterStatus === 'finished') ? '📸 РЕЗУЛЬТАТ' : '📸 Я В ДЕЛЕ';
                        posterBtn = `<button style="${textBtnStyle} background:var(--primary); color:#000; border:none; box-shadow:0 4px 10px rgba(255,193,7,0.3);" title="Создать постер для соцсетей" onclick="window.app.crm.generateRacePoster('${r.id}', '${this.app.currentRider?.id}')">${pText}</button>`;
                    }

                    // 🔥 КНОПКИ БЫСТРОГО РЕШЕНИЯ ДЛЯ АДМИНИСТРАТОРА (МОДЕРАЦИЯ)
                    let moderationActionsHtml = '';
                    if (isAdmin && r.verification_status === 'pending') {
                        moderationActionsHtml = `
                            <button style="${textBtnStyle} background:rgba(0,230,118,0.15); color:var(--success); border:1px solid var(--success);" title="Утвердить старт как официальную гонку Лиги" onclick="window.app.crm.approveRaceAsOfficial('${r.id}')">🏆 УТВЕРДИТЬ КАК ГОНКУ</button>
                            <button style="${textBtnStyle} background:rgba(59,130,246,0.15); color:var(--info); border:1px solid var(--info);" title="Оставить заезд как тренировку" onclick="window.app.crm.setRaceAsTraining('${r.id}')">🚴 ОСТАВИТЬ ТРЕНИРОВКОЙ</button>
                        `;
                    }

                    let secondaryHtml = '';
                    if (moderationActionsHtml || posterBtn || inviteBtn || chatBtn || judgeBtn || manageRosterBtn || startPultBtn || editBtn || deleteBtn) {
                        secondaryHtml = `<div style="display:flex; gap:8px; flex-wrap:wrap; margin-top:10px;">${moderationActionsHtml}${posterBtn}${inviteBtn}${chatBtn}${judgeBtn}${manageRosterBtn}${startPultBtn}${editBtn}${deleteBtn}</div>`;
                    }

                    let bookmarks = this.app.currentRider?.bookmarks || [];
                    if (typeof bookmarks === 'string') { try { bookmarks = JSON.parse(bookmarks); } catch(e) { bookmarks = []; } }
                    const isBookmarked = Array.isArray(bookmarks) && bookmarks.includes(r.id);

                    const starIcon = isBookmarked 
                        ? `<svg width="16" height="16" viewBox="0 0 24 24" fill="var(--primary)" stroke="var(--primary)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2"></polygon></svg>` 
                        : `<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2"></polygon></svg>`;
                    
                    const starBtn = `<button onclick="window.app.crm.toggleBookmark('${r.id}', event)" style="background:none; border:none; cursor:pointer; color:var(--text-muted); padding:0; display:inline-flex; align-items:center; transition:0.2s;" onmouseover="this.style.transform='scale(1.2)'" onmouseout="this.style.transform='scale(1)'" title="В избранное">${starIcon}</button>`;

                    const displayState = (window.app.expandedRaceId === r.id) ? 'block' : 'none';
                    const activeBg = (window.app.expandedRaceId === r.id) ? 'var(--bg-surface-hover)' : 'var(--bg-surface)';
                    const chevron = (window.app.expandedRaceId === r.id) ? '▲' : '▼';

                    // 🔥 ОТОБРАЖАЕМ СУДЬЮ (ИЛИ КАК ТЕКСТ, ИЛИ КАК КЛИКАБЕЛЬНЫЙ ЧАТ)
                    let judgeHtml = '<span style="color:var(--text-muted);">Не назначен</span>';
                    if (r.judgeRiderId) {
                        judgeHtml = `<span style="color:var(--info); cursor:pointer; font-weight:bold; transition:0.2s;" onmouseover="this.style.textDecoration='underline'" onmouseout="this.style.textDecoration='none'" onclick="event.stopPropagation(); window.app.startDirectChat('${r.judgeRiderId}'); window.app.switchTab('chats');" title="Написать судье">${r.judgeName}</span>`;
                    } else if (r.judgeName !== 'Не назначен') {
                        judgeHtml = `<span style="color:var(--text-main); font-weight:bold;">${r.judgeName}</span>`;
                    }

                    if (!document.getElementById('calendar-mobile-fix')) {
                        document.head.insertAdjacentHTML('beforeend', `<style id="calendar-mobile-fix">@media(max-width: 600px) { .cal-hide-mob { display:none !important; } .cal-name-text { font-size:14px !important; } }</style>`);
                    }

                    html += `
                    <div class="calendar-accordion-item" style="background:${activeBg}; border:1px solid var(--border); border-radius:12px; overflow:hidden; transition:0.2s; margin-bottom:8px;">
                        
                        <div class="calendar-accordion-header" style="display:flex; align-items:center; padding:12px 16px; cursor:pointer;" onclick="
                            const body = this.nextElementSibling;
                            const isOpen = body.style.display === 'block';
                            document.querySelectorAll('.calendar-accordion-body').forEach(b => { b.style.display = 'none'; b.parentElement.style.background = 'var(--bg-surface)'; b.parentElement.querySelector('.chevron').innerText = '▼'; });
                            if (isOpen) {
                                body.style.display = 'none';
                                this.parentElement.style.background = 'var(--bg-surface)';
                                this.querySelector('.chevron').innerText = '▼';
                                window.app.expandedRaceId = null;
                            } else {
                                body.style.display = 'block';
                                this.parentElement.style.background = 'var(--bg-surface-hover)';
                                this.querySelector('.chevron').innerText = '▲';
                                window.app.expandedRaceId = '${r.id}';
                            }
                        ">
                            <div style="display:flex; align-items:center; gap:10px; flex-shrink:0; padding-right:15px;">
                                ${starBtn}
                                <div style="display:flex; align-items:baseline; gap:1px;">
    <b style="color:var(--text-main); font-family:'Roboto Mono'; font-size:28px; line-height:1; letter-spacing:-1px;">${day}</b>
    <span style="color:var(--text-muted); font-size:14px; font-family:'Roboto Mono'; font-weight:bold;">.${monthNum}</span>
</div>
                            </div>
                            
                            <div style="flex:1; min-width:0; display:flex; flex-direction:column; justify-content:center; border-left: 1px solid rgba(255,255,255,0.05); padding-left:15px;">
                                <div class="cal-name-text" style="font-family:'Unbounded'; font-weight:800; font-size:16px; color:var(--text-main); white-space:nowrap; overflow:hidden; text-overflow:ellipsis; margin-bottom:4px;">${r.name}</div>
                                <div style="font-family:'Unbounded'; font-size:10px; font-weight:800; color:var(--primary); text-transform:uppercase;">${r.type} ${cupHtml}</div>
                            </div>
                            
                            <div style="display:flex; align-items:center; gap:15px; flex-shrink:0; text-align:right;">
                                <div class="cal-hide-mob">
                                    <div style="font-family:'Roboto Mono'; font-weight:bold; font-size:14px; color:var(--text-main);">${r.distance} км</div>
                                    <div style="font-size:10px; color:var(--text-muted); font-family:'Unbounded'; margin-top:2px;">${r.rosterCount} заявки</div>
                                </div>
                                <span class="chevron" style="color:var(--text-muted); font-size:12px; margin-left:5px;">${chevron}</span>
                            </div>
                        </div>
                        
                        <div class="calendar-accordion-body" style="display:${displayState}; padding:0 16px 16px 16px; border-top:1px dashed var(--border); cursor:default;">
                            <div style="display:flex; justify-content:space-between; align-items:center; margin-top:16px; margin-bottom:15px;">
                                <div style="font-family:'Roboto Mono'; font-weight:bold; font-size:12px; color:var(--text-main);">
                                    СТАРТ: ${time}
                                </div>
								<div style="font-size:11px; color:var(--text-muted); z-index:2; position:relative;">
                                    <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="var(--info)" stroke-width="2" style="vertical-align:middle; margin-right:4px;"><circle cx="12" cy="12" r="10"></circle><line x1="12" y1="8" x2="12" y2="12"></line><line x1="12" y1="16" x2="12.01" y2="16"></line></svg>
                                    Судья: ${judgeHtml}
                                </div>
                            </div>
                            
                            <div style="display:flex; flex-direction:column; gap:8px;">
                                ${primaryHtml}
                                ${secondaryHtml}
                            </div>
                        </div>
                    </div>`;
                });
                if (gridOpen) html += '</div>';
            }
        }
        else if (this.currentView === 'team') {
            let targetTeamId = this.viewedTeamId;
            
            // 🔥 ФИКС: Создаем переменную в правильной области видимости!
            const currentFilterId = this.app.currentPelotonFilter || 'all';

            // ЗАЩИТА: Добавлен знак вопроса для безопасного чтения
            if (!targetTeamId && this.app.currentRider?.team_id) {
                const myTeams = Array.isArray(this.app.currentRider.team_id) ? this.app.currentRider.team_id : [this.app.currentRider.team_id];
                
                // УМНЫЙ ПОИСК: Безопасно извлекаем peloton_id, даже если это массив
                targetTeamId = myTeams.find(id => {
                    const t = this.app.teamsMap[id];
                    if (!t) return false;
                    const pId = Array.isArray(t.peloton_id) ? t.peloton_id[0] : t.peloton_id;
                    return pId === currentFilterId;
                }) || myTeams[0];
            }

            if (targetTeamId) {
                let adminBarHtml = '';
                const roles = this.app.usersMap[this.app.currentRider?.email] || [];
                const rStr = JSON.stringify(roles);
                const isAdmin = rStr.includes('admin') || rStr.includes('superadmin');
                const isJudge = rStr.includes('judge');
                
                const myTeams = Array.isArray(this.app.currentRider?.team_id) ? this.app.currentRider.team_id : (this.app.currentRider?.team_id ? [this.app.currentRider.team_id] : []);
                const isCaptain = rStr.includes('captain') && myTeams.includes(targetTeamId);
                const isManager = isAdmin || isJudge || isCaptain;
                
                if (isAdmin || isJudge) {
                    let tOpts = '<option value="" disabled selected>-- Выберите команду --</option>';
                    Object.values(this.app.teamsMap).sort((a,b)=>a.name.localeCompare(b.name)).forEach(t => { const sel = (t.id === targetTeamId) ? 'selected' : ''; tOpts += `<option value="${t.id}" ${sel}>${t.name}</option>`; });
                    let delBtn = isAdmin ? `<button onclick="window.app.deleteCurrentTeam()" class="admin-btn admin-btn-danger">Удалить</button>` : '';
                    let capBtn = isAdmin ? `<button onclick="document.getElementById('captainModal').style.display='flex'" class="admin-btn admin-btn-secondary">Капитан</button>` : '';
                    let createBtn = isAdmin ? `<button onclick="document.getElementById('createTeamModal').style.display='flex'" class="admin-btn admin-btn-primary">+ Команда</button>` : '';
                    adminBarHtml = `<div class="admin-bar open"><div class="admin-bar-header" onclick="this.parentElement.classList.toggle('open')"><h3>УПРАВЛЕНИЕ КОМАНДАМИ</h3><span style="color:var(--primary);">▼</span></div><div class="admin-bar-content"><div class="admin-controls-row"><select class="admin-select" onchange="window.app.crm.adminSwitchTeam(this.value)">${tOpts}</select>${createBtn} ${capBtn} ${delBtn}</div></div></div>`;
                }

                const totalPoints = [...this.dataTeam.m, ...this.dataTeam.f].reduce((sum, r) => sum + r.points, 0);
                let teamChat = this.app.chats.find(c => {
                    const cTeams = Array.isArray(c.team_id) ? c.team_id : (c.team_id ? [c.team_id] : []);
                    return cTeams.includes(targetTeamId) && c.type === 'team_channel';
                }) || this.app.chats.find(c => {
                    const cTeams = Array.isArray(c.team_id) ? c.team_id : (c.team_id ? [c.team_id] : []);
                    return cTeams.includes(targetTeamId) && c.type === 'team';
                });

                let chatBtn = teamChat ? `<button class="p-btn" style="background:rgba(255,193,7,0.1); color:var(--primary); border:1px dashed var(--primary); height:100%;" onclick="window.app.switchTab('chats'); window.app.openChat('${teamChat.id}')"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"></path></svg> КАНАЛ КОМАНДЫ</button>` : '';            
                html += adminBarHtml;

                const myTeamObj = this.app.teamsMap[targetTeamId];
                const myTeamName = myTeamObj ? myTeamObj.name : "МОЯ КОМАНДА";

                const canRename = isAdmin || isCaptain;
                let renameBtnHtml = canRename ? `
                    <button onclick="window.app.crm.renameTeam('${targetTeamId}', '${myTeamName}')" style="background: transparent; border: none; cursor: pointer; color: var(--text-muted); font-size: 16px; transition: 0.2s;" onmouseover="this.style.color='var(--primary)'" onmouseout="this.style.color='var(--text-muted)'" title="Изменить название">
                        ✏️
                    </button>` : '';

                html += `
                <div style="display: flex; align-items: center; gap: 12px; margin-bottom: 25px;">
                    <h2 style="margin: 0; font-size: 22px; color: var(--text-main); font-family: 'Unbounded', sans-serif; text-transform: uppercase;">${myTeamName}</h2>
                    ${renameBtnHtml}
                </div>`;
                
                html += `<div class="p-team-dashboard active"><div class="p-stat-card"><div class="p-stat-title">Рейтинг команды</div><div class="p-stat-value highlight">${totalPoints} pts</div></div><div class="p-stat-card"><div class="p-stat-title">Состав (М/Ж)</div><div class="p-stat-value">${this.dataTeam.m.length} / ${this.dataTeam.f.length}</div></div><div class="p-stat-card" style="background:transparent; border:none; padding:0; box-shadow:none;">${chatBtn}</div></div>`;

                this.teamGenderFilter = this.teamGenderFilter || 'all';
                this.teamSearchQuery = this.teamSearchQuery || '';

                let rosterControlsHtml = `<div style="display:flex; gap:8px; margin-bottom: 20px; overflow-x:auto; scrollbar-width:none; padding-bottom:4px; -webkit-overflow-scrolling:touch; align-items:center;">`;
                
                if (isManager) {
                    rosterControlsHtml += `<button style="background:var(--primary); color:#000; border:none; padding:8px 16px; border-radius:50px; font-family:'Unbounded'; font-weight:800; font-size:10px; cursor:pointer; flex-shrink:0; transition:0.2s; box-shadow: 0 4px 10px rgba(255,193,7,0.3);" onclick="document.getElementById('inlineAddRow').style.display='table-row'">+ ДОБАВИТЬ ГОНЩИКА</button>`;
                    rosterControlsHtml += `<div style="width:1px; background:var(--border); margin:0 4px; flex-shrink:0; height:20px;"></div>`;
                }

                const filters = [
                    { id: 'all', name: 'ВСЕ' },
                    { id: 'M', name: 'МУЖЧИНЫ' },
                    { id: 'F', name: 'ЖЕНЩИНЫ' }
                ];

                filters.forEach(f => {
                    const isActive = this.teamGenderFilter === f.id;
                    const bg = isActive ? 'var(--text-main)' : 'transparent';
                    const color = isActive ? 'var(--bg-body)' : 'var(--text-muted)';
                    const border = isActive ? 'var(--text-main)' : 'var(--border)';
                    rosterControlsHtml += `<button style="background:${bg}; color:${color}; border:1px solid ${border}; padding:8px 16px; border-radius:50px; font-family:'Unbounded'; font-weight:800; font-size:10px; cursor:pointer; flex-shrink:0; transition:0.2s;" onclick="window.app.crm.setTeamGenderFilter('${f.id}')">${f.name}</button>`;
                });

                rosterControlsHtml += `<div style="margin-left:auto; flex-shrink:0;"><input type="text" placeholder="Поиск гонщика..." value="${this.teamSearchQuery}" style="background:var(--bg-surface-hover); border:1px solid var(--border); color:var(--text-main); padding:8px 16px; border-radius:50px; font-family:'Manrope'; font-size:11px; outline:none; transition:0.2s; min-width:180px;" oninput="window.app.crm.setTeamSearch(this.value); window.app.crm.renderFilteredRosterTable();"></div>`;
                rosterControlsHtml += `</div>`;
                
                html += rosterControlsHtml;
                html += '<div id="teamRosterTableContainer"></div>';

                this.renderFilteredRosterTable = () => {
                    const tableContainer = document.getElementById('teamRosterTableContainer');
                    if (!tableContainer) return;

                    let filteredRoster = [...this.dataTeam.m, ...this.dataTeam.f];
                    
                    if (this.teamGenderFilter === 'M') {
                        filteredRoster = this.dataTeam.m;
                    } else if (this.teamGenderFilter === 'F') {
                        filteredRoster = this.dataTeam.f;
                    }
                    
                    if (this.teamSearchQuery) {
                        const q = this.teamSearchQuery.toLowerCase();
                        filteredRoster = filteredRoster.filter(r => ((r.name || '').toLowerCase().includes(q)) || ((r.surname || '').toLowerCase().includes(q)) || ((r.team || '').toLowerCase().includes(q)));
                    }

                    filteredRoster.sort((a, b) => { 
                        let vA = a[this.sort.field], vB = b[this.sort.field]; 
                        if (typeof vA === 'string') vA = vA.toLowerCase(); 
                        if (typeof vB === 'string') vB = vB.toLowerCase(); 
                        if (this.sort.field === 'points' || this.sort.field === 'year') { vA = Number(vA)||0; vB = Number(vB)||0; } 
                        return vA < vB ? (this.sort.dir === 'asc' ? -1 : 1) : (vA > vB ? (this.sort.dir === 'asc' ? 1 : -1) : 0); 
                    });

                    tableContainer.innerHTML = this.buildRosterTable(filteredRoster, false);
                };

                setTimeout(() => { if(typeof this.renderFilteredRosterTable === 'function') this.renderFilteredRosterTable(); }, 10);
            }
        }
        else if (this.currentView === 'market') { 
            html += this.buildControlsRow();
            html += this.buildRosterTable(this.getSortedList(this.dataMarket), true); 
        }
        else if (this.currentView === 'rating') {
            html += `<div class="p-table-container"><table class="p-roster-table"><thead><tr><th style="width:40px; text-align:center;">#</th><th>Команда</th><th style="width:80px; text-align:right;">Топ-3</th><th style="width:80px; text-align:right;">Всего</th></tr></thead><tbody>`;
            
            const myTeams = Array.isArray(this.app.currentRider?.team_id) ? this.app.currentRider.team_id : (this.app.currentRider?.team_id ? [this.app.currentRider.team_id] : []);

            let rank = 1;

            this.dataRatings.forEach((t) => { 
                const isMine = myTeams.includes(t.id); 
                const bg = isMine ? 'background:var(--bg-surface-hover);' : ''; 
                
                // 🔥 Порядковый номер только для боевых команд
                let rankDisplay = '';
                if (t.isOneTeam) {
                    rankDisplay = `<span style="color:var(--text-muted); font-size:11px; font-family:'Roboto Mono'; font-weight:bold;">—</span>`;
                } else {
                    rankDisplay = `<b style="color:var(--text-muted); font-family:'Roboto Mono';">${rank}</b>`;
                    rank++;
                }
                
                let oneTeamBadge = t.isOneTeam ? `<span style="background:rgba(255,255,255,0.08); color:var(--text-muted); padding:2px 6px; border-radius:4px; font-size:8px; font-family:'Unbounded'; font-weight:800; border:1px solid var(--border);">ВНЕ ЗАЧЁТА</span>` : '';

                html += `<tr style="${bg} cursor:pointer; transition:0.2s;" onclick="window.app.crm.toggleTeamRoster('${t.id}')" onmouseover="this.style.backgroundColor='var(--bg-surface-hover)'" onmouseout="this.style.backgroundColor='${isMine ? 'var(--bg-surface-hover)' : 'transparent'}'" title="Нажмите, чтобы увидеть состав">
                    <td style="text-align:center;">${rankDisplay}</td>
                    <td style="max-width: 140px; width: 100%; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">
                        <div style="display:flex; align-items:center; gap:8px; overflow:hidden;">
                            <b style="color:var(--text-main); font-family:'Unbounded'; font-size:13px; text-transform:uppercase; overflow:hidden; text-overflow:ellipsis;">${this.app.escapeHTML(t.name)}</b> 
                            ${oneTeamBadge}
                            <span id="icon-roster-${t.id}" style="color:var(--text-muted); font-size:10px; flex-shrink:0;">▼</span>
                        </div>
                    </td>
                    <td style="text-align:right;"><b style="color:var(--primary); font-size:15px; font-family:'Roboto Mono';">${t.top3Points}</b></td>
                    <td style="text-align:right;"><span style="color:var(--text-muted); font-size:13px; font-family:'Roboto Mono'; font-weight:bold;">${t.totalPoints}</span></td>
                </tr>`; 

                // Раскрывающийся состав команды
                let teamRiders = Object.values(this.app.ridersMap).filter(r => {
                    if (r.email === 'bot@sotka.one') return false;
                    const rTeams = Array.isArray(r.team_id) ? r.team_id : (r.team_id ? [r.team_id] : []);
                    return rTeams.includes(t.id);
                });
                teamRiders.sort((a,b) => (b.rating || 0) - (a.rating || 0));

                let ridersHtml = '';
                if (teamRiders.length === 0) {
                    ridersHtml = `<div style="padding:15px; text-align:center; color:var(--text-muted); font-size:12px; font-family:'Unbounded';">СОСТАВ ПУСТ</div>`;
                } else {
                    ridersHtml = `<div style="padding: 10px; display:grid; grid-template-columns: repeat(auto-fill, minmax(240px, 1fr)); gap: 8px;">`;
                    teamRiders.forEach((r, idx) => {
                        // Подсвечиваем участников, входящих в Топ-3
                        const isTop3 = idx < 3;
                        const top3Badge = isTop3 ? `<span style="background:rgba(255,193,7,0.15); color:var(--primary); padding:1px 5px; border-radius:4px; font-size:8px; font-family:'Unbounded'; font-weight:bold; margin-left:4px; border:1px solid rgba(255,193,7,0.3);">ТОП-3</span>` : '';

                        ridersHtml += `<div style="display:flex; justify-content:space-between; align-items:center; background:var(--bg-body); padding:8px 10px; border-radius:8px; border:1px solid var(--border);">
                            <div style="display:flex; align-items:center; gap:8px; min-width:0; flex:1;">
                                <span style="color:var(--text-muted); font-size:10px; font-family:'Roboto Mono'; font-weight:bold; flex-shrink:0;">${idx+1}.</span>
                                <span style="font-size:12px; font-weight:600; color:var(--text-main); cursor:pointer; transition:0.2s; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; display:block;" onmouseover="this.style.color='var(--primary)'" onmouseout="this.style.color='var(--text-main)'" onclick="event.stopPropagation(); window.app.openProfile('${r.id}', event)">${this.app.escapeHTML(r.first_name)} ${this.app.escapeHTML(r.last_name)}</span>
                                ${top3Badge}
                            </div>
                            <b style="color:var(--primary); font-size:13px; font-family:'Roboto Mono'; flex-shrink:0; margin-left:10px;">${r.rating || 0}</b>
                        </div>`;
                    });
                    ridersHtml += `</div>`;
                }

                html += `<tr id="row-roster-${t.id}" style="display:none; background:rgba(0,0,0,0.1);"><td colspan="4" style="padding:0; border-bottom:2px solid var(--primary);">${ridersHtml}</td></tr>`;
            });
            html += '</tbody></table></div>';
        }
       
        else if (this.currentView === 'rules') {
            html += `<div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:20px;">
                <h2 style="font-family:'Unbounded'; font-size:18px; color:var(--text-main); margin:0; display:flex; align-items:center; gap:10px;"><span style="color:var(--primary);">⚙️</span> ПРАВИЛА РЕЙТИНГОВ</h2>
                <button class="p-btn-black" onclick="window.app.crm.openRuleModal()" style="width:auto; padding:10px 20px; margin:0;">+ СОЗДАТЬ ПРАВИЛО</button>
            </div>`;

            html += `<div class="dash-table-wrapper"><table class="dash-table"><thead><tr><th>Название</th><th>Покрытие / Формат</th><th>Описание</th><th style="width:80px; text-align:center;">Действия</th></tr></thead><tbody>`;
            
            if (!this.dataRules || this.dataRules.length === 0) {
                html += `<tr><td colspan="4" style="text-align:center; padding:40px; color:var(--text-muted); font-family:'Unbounded'; font-size:12px;">Библиотека правил пуста</td></tr>`;
            } else {
                this.dataRules.forEach(r => {
                    const sName = this.RACE_SURFACES[r.surface] || r.surface;
                    const tName = r.type === 'ind' ? 'РАЗДЕЛКА' : 'Группа';
                    html += `<tr style="transition:0.2s;" onmouseover="this.style.background='var(--bg-surface-hover)'" onmouseout="this.style.background='transparent'">
                        <td><b style="color:var(--text-main); font-size:13px;">${this.app.escapeHTML(r.name)}</b></td>
                        <td><span style="background:var(--bg-body); padding:4px 8px; border-radius:6px; border:1px solid var(--border); font-size:10px; font-weight:bold; color:var(--primary);">${sName} • ${tName}</span></td>
                        <td style="font-size:11px; color:var(--text-muted);">${this.app.escapeHTML(r.description)}</td>
                        <td style="text-align:center;">
                            <button onclick="window.app.crm.openRuleModal('${r.id}')" style="background:rgba(255,193,7,0.1); border:1px solid rgba(255,193,7,0.3); color:var(--warning); cursor:pointer; padding:6px; border-radius:6px; margin-right:4px; transition:0.2s;" title="Редактировать">✏️</button>
                            <button onclick="window.app.crm.deleteRule('${r.id}')" style="background:rgba(255,51,102,0.1); border:1px solid rgba(255,51,102,0.3); color:var(--danger); cursor:pointer; padding:6px; border-radius:6px; transition:0.2s;" title="Удалить">✕</button>
                        </td>
                    </tr>`;
                });
            }
            html += `</tbody></table></div>`;

            if (!document.getElementById('ruleEditModal')) {
                const m = document.createElement('div');
                m.id = 'ruleEditModal';
                m.className = 'modal-overlay';
                m.innerHTML = `
                <div class="modal-box" style="max-width:600px; max-height:90vh; display:flex; flex-direction:column;">
                    <h3 id="ruleModalTitle" style="color:var(--primary); margin-bottom:20px; font-family:'Unbounded';">ПРАВИЛО РЕЙТИНГА</h3>
                    <div style="overflow-y:auto; flex:1; padding-right:10px;">
                        <input type="hidden" id="ruleId">
                        
                        <label style="font-size:10px; color:var(--text-muted); font-family:'Unbounded';">НАЗВАНИЕ (ВИДЯТ ОРГАНИЗАТОРЫ)</label>
                        <input type="text" id="ruleName" class="auth-input" style="width:100%; margin-bottom:15px;" placeholder="Например: Шоссе ПРО (Масс-старт)">
                        
                        <label style="font-size:10px; color:var(--text-muted); font-family:'Unbounded';">КРАТКОЕ ОПИСАНИЕ</label>
                        <input type="text" id="ruleDesc" class="auth-input" style="width:100%; margin-bottom:15px;" placeholder="Как начисляются очки?">
                        
                        <div style="display:flex; gap:10px; margin-bottom:15px;">
    <div style="flex:1;">
        <label style="font-size:10px; color:var(--text-muted); font-family:'Unbounded';">МАТЕМАТИКА (БАЗА)</label>
        <select id="ruleType" class="auth-input" style="width:100%;" onchange="window.app.crm.fillRuleTemplate(true)">
            <option value="mass">Группа / Критериум (Банк очков)</option>
            <option value="ind">Индивидуальная / ITT (Множитель скорости)</option>
        </select>
    </div>
    <div style="flex:1;">
        <label style="font-size:10px; color:var(--text-muted); font-family:'Unbounded';">ПОКРЫТИЕ</label>
        <select id="ruleSurface" class="auth-input" style="width:100%;">
            <option value="road">Шоссе</option>
            <option value="offroad">Грунт</option>
            <option value="track">Трек</option>
            <option value="indoor">Индор</option>
        </select>
    </div>
</div>

                        <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:5px;">
                            <label style="font-size:10px; color:var(--text-muted); font-family:'Unbounded';">КОНФИГУРАЦИЯ (JSON)</label>
                            <span style="font-size:10px; color:var(--info); cursor:pointer; font-weight:bold; font-family:'Unbounded';" onclick="window.app.crm.fillRuleTemplate()">[ ВСТАВИТЬ ШАБЛОН ]</span>
                        </div>
                        <textarea id="ruleConfig" class="auth-input" style="width:100%; height:250px; font-family:'Roboto Mono', monospace; font-size:12px; line-height:1.4; resize:vertical; background:var(--bg-body);"></textarea>
                    </div>
                    
                    <div style="display:flex; gap:10px; margin-top:20px;">
                        <button class="btn-black" style="flex:1; background:var(--success); color:#000;" onclick="window.app.crm.saveRule()">💾 СОХРАНИТЬ</button>
                        <button class="btn-black" style="flex:1; background:var(--bg-body); color:var(--text-main); border:1px solid var(--border);" onclick="document.getElementById('ruleEditModal').style.display='none'">ОТМЕНА</button>
                    </div>
                </div>`;
                document.body.appendChild(m);
            }
        }
        contentArea.innerHTML = html;
    }
	
    // ==========================================
    // УПРАВЛЕНИЕ КОМАНДОЙ (ОСТАЛЬНОЕ)
    // ==========================================
    toggleTeamRoster(teamId) {
        const row = document.getElementById(`row-roster-${teamId}`);
        const icon = document.getElementById(`icon-roster-${teamId}`);
        if (row) {
            if (row.style.display === 'none') {
                row.style.display = 'table-row';
                if (icon) icon.innerText = '▲';
            } else {
                row.style.display = 'none';
                if (icon) icon.innerText = '▼';
            }
        }
    }

    buildControlsRow(extraBtn = '') {
        const mClass = this.currentTab === 'm' ? 'active' : ''; const fClass = this.currentTab === 'f' ? 'active' : '';
        return `<div style="display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:16px; margin-bottom:16px;"><div style="display:flex; gap:10px; flex-wrap:wrap;"><div style="display:flex; gap:10px; background:var(--bg-surface); padding:4px; border-radius:50px; border:1px solid var(--border);"><button class="crm-tab-btn ${mClass}" style="padding:8px 16px; border:none;" onclick="window.app.crm.setTab('m')">Мужчины (M)</button><button class="crm-tab-btn ${fClass}" style="padding:8px 16px; border:none;" onclick="window.app.crm.setTab('f')">Женщины (F)</button></div>${extraBtn}</div><div style="flex:1; display:flex; justify-content:flex-end;"><input type="text" id="pelotonSearchInput" class="auth-input" style="width:100%; max-width:300px; margin:0; padding:10px 16px; border-radius:50px;" placeholder="Поиск гонщика..." value="${this.searchQuery}" oninput="window.app.crm.setSearch(this.value)"></div></div>`;
    }

   buildRosterTable(list, isMarket = false) {
        const roles = this.app.usersMap[this.app.currentRider?.email] || [];
        const rStr = JSON.stringify(roles);
        
        // 🔥 ФИКС: Умная проверка Капитанства
        const myTeams = Array.isArray(this.app.currentRider?.team_id) ? this.app.currentRider.team_id : (this.app.currentRider?.team_id ? [this.app.currentRider.team_id] : []);
        const targetTeamId = this.viewedTeamId || (myTeams.length > 0 ? myTeams.find(id => this.app.teamsMap[id]?.peloton_id === this.app.currentPelotonFilter) || myTeams[0] : null);
        
        const isManager = rStr.includes('admin') || rStr.includes('superadmin') || rStr.includes('judge') || (rStr.includes('captain') && myTeams.includes(targetTeamId));
        const isMyCaptain = rStr.includes('captain') && myTeams.length > 0;

        const sortIcon = (field) => this.sort.field === field ? (this.sort.dir === 'asc' ? '<span style="color:var(--primary)">▲</span>' : '<span style="color:var(--primary)">▼</span>') : '';
        let html = `<div class="p-table-container"><table class="p-roster-table"><thead><tr><th style="width: 100px;">Действие</th><th style="cursor:pointer;" onclick="window.app.crm.setSort('name')">Спортсмен ${sortIcon('name')}</th><th style="cursor:pointer;" onclick="window.app.crm.setSort('year')">Г.Р. ${sortIcon('year')}</th><th style="cursor:pointer;" onclick="window.app.crm.setSort('group')">Кластер ${sortIcon('group')}</th><th style="cursor:pointer;" onclick="window.app.crm.setSort('points')">Рейт. ${sortIcon('points')}</th></tr></thead><tbody>`;

        if (isManager && !isMarket) {
            let clusterOpts = `<option value="B">B</option><option value="A+">A+</option><option value="A">A</option><option value="C">C</option><option value="D">D</option><option value="E">E</option><option value="V">V</option><option value="O">O</option>`;
            html += `<tr class="inline-add-row" id="inlineAddRow" style="display:none;"><td colspan="5" style="padding: 16px;"><div class="inline-form-grid"><div style="display:flex; gap:8px;"><button id="submitBtn" class="p-btn-black" style="padding:8px; width:100%; margin:0;" onclick="window.app.crm.submitForm()">СОХРАНИТЬ</button></div><div style="display:flex; gap:8px;"><input type="text" id="newName" class="inline-input" placeholder="Имя *"><input type="text" id="newSurname" class="inline-input" placeholder="Фамилия *"></div><input type="number" id="newYear" class="inline-input" placeholder="Год *"><div style="display:flex; gap:8px;"><select id="newGender" class="inline-input"><option value="M" ${this.currentTab === 'm' ? 'selected' : ''}>М</option><option value="F" ${this.currentTab === 'f' ? 'selected' : ''}>Ж</option></select><select id="newCluster" class="inline-input">${clusterOpts}</select></div><div style="font-family:'Roboto Mono'; font-weight:bold; color:var(--text-muted); text-align:center;">- pts</div></div></td></tr>`;
        }

        if (list.length === 0) {
            html += `<tr><td colspan="5" style="text-align:center; padding:40px; color:var(--text-muted); font-family:'Unbounded'; font-size:12px;">СПИСОК ПУСТ</td></tr>`;
        } else {
            list.forEach(p => {
                const isMe = this.app.currentRider?.id === p.id;
                const meBadge = isMe ? `<span style="background:var(--primary); color:#000; font-size:9px; padding:2px 6px; border-radius:4px; font-family:'Unbounded'; font-weight:bold; margin-left:6px;">Я</span>` : '';
                const msgBtn = (!isMe) ? `<div class="msg-icon-btn" title="Написать" onclick="window.app.startDirectChat('${p.id}'); window.app.switchTab('chats');"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"></path></svg></div>` : '';
                
                let act = '<span style="color:var(--text-muted); font-size:10px;">-</span>';
                
                if (isMarket) {
                    if ((isMyCaptain || isManager) && !isMe) {
                        act = `<button class="p-btn-black" style="padding: 6px 12px; width: auto; font-size: 9px; background: rgba(0, 230, 118, 0.1); color: var(--success); border: 1px dashed var(--success);" onclick="window.app.inviteToTeam('${p.id}')">ПРИГЛАСИТЬ</button>`;
                    } else { act = '<span style="color:var(--success); font-size:10px; font-weight:bold;">СВОБОДЕН</span>'; }
                } else if (isManager) {
                    act = `<div style="display:flex; gap:8px;"><button class="btn-edit" onclick="window.app.crm.openEditModal('${p.id}')">✎</button><button class="btn-del" onclick="window.app.crm.removePlayer('${p.id}')">✕</button></div>`;
                }

                html += `<tr><td>${act}</td><td><div style="display:flex; align-items:center;"><div style="font-weight:600; font-size:14px; cursor:pointer; transition:0.2s;" onmouseover="this.style.color='var(--primary)'" onmouseout="this.style.color='var(--text-main)'" onclick="window.app.openProfile('${p.id}')">${p.name} ${p.surname}</div>${meBadge}${msgBtn}</div></td><td><span style="color:var(--text-muted); font-family:'Roboto Mono';">${p.year}</span></td><td><span style="background:var(--bg-body); border:1px solid var(--border); padding:4px 8px; border-radius:6px; font-size:11px; font-weight:600; font-family:'Roboto Mono';">${p.gender} • ${p.group}</span></td><td><b style="color:var(--primary); font-size:14px; font-family:'Roboto Mono';">${p.points}</b></td></tr>`;
            });
        }
        html += '</tbody></table></div>';
        return html;
    }

    adminSwitchTeam(teamId) { this.viewedTeamId = teamId; this.switchView('team'); }
    
    async submitForm() {
        const btn = document.getElementById('submitBtn'), 
              name = document.getElementById('newName').value.trim(), 
              surname = document.getElementById('newSurname').value.trim(), 
              yearStr = document.getElementById('newYear').value.trim(), 
              gender = document.getElementById('newGender').value, 
              cluster = document.getElementById('newCluster').value;
              
        if (!name || !surname || !yearStr || !gender) return alert("Заполните: Имя, Фамилия, Год рождения и Пол");
        if (yearStr.length !== 4 || isNaN(Number(yearStr))) return alert("Введите корректный год рождения (4 цифры)");
        
        const year = Number(yearStr);
        
        btn.disabled = true; btn.innerText = "⌛"; 
        
        try {
            // 🔥 ФИКС 1: Вытаскиваем правильный ID команды (строку)
            const targetTeamId = this.viewedTeamId || (Array.isArray(this.app.currentRider?.team_id) ? this.app.currentRider?.team_id[0] : this.app.currentRider?.team_id);
            
            // ==========================================
            // 🔥 АБСОЛЮТНАЯ ЗАЩИТА ОТ ДУБЛИКАТОВ (ГЛОБАЛЬНАЯ ПРОВЕРКА)
            // ==========================================
            if (!this.editIndex) { // Проверяем на дубли ТОЛЬКО при создании нового гонщика
                try {
                    const existingRider = await pb.collection('riders').getFirstListItem(
                        `first_name="${name}" && last_name="${surname}" && yob=${year}`, 
                        { requestKey: null }
                    );

                    alert(`❌ ОШИБКА: Спортсмен уже существует!\n\nГонщик ${name} ${surname} (${year} г.р.) уже зарегистрирован в системе.\n\nСоздание дубликатов запрещено. Найдите его через поиск и отправьте запрос на ТРАНСФЕР.`);
                    
                    btn.disabled = false; btn.innerText = "СОХРАНИТЬ";
                    return; 
                } catch (searchErr) {
                    // Ошибка 404 (не найдено) означает, что дублей нет. Всё отлично!
                }
            }
            // ==========================================

            // 🔥 ФИКС 2: Отправляем team_id строго в виде МАССИВА
            const data = { first_name: name, last_name: surname, yob: year, gender: gender, base_cluster: cluster, team_id: [targetTeamId], rating: 0 };
            
            if (this.editIndex) { 
                // 🔥 ФИКС 3: ПРИ РЕДАКТИРОВАНИИ НЕ ТРОГАЕМ team_id ВООБЩЕ, чтобы не удалить гонщика из других клубов!
                delete data.team_id;
                await pb.collection('riders').update(this.editIndex, data, { requestKey: null }); 
            } else { 
                await pb.collection('riders').create(data, { requestKey: null }); 
            }
            
            this.cancelInlineEdit(); 
            this.loadData(); 
            
        } catch(e) { 
            console.error(e);
            alert("Ошибка сохранения"); 
        } finally { 
            btn.disabled = false; 
            btn.innerText = "СОХРАНИТЬ"; 
        }
    }

    openEditModal(id) { 
        if (this.editIndex === id) { this.cancelInlineEdit(); return; }
        const p = this.getSortedList(this.dataTeam).find(x => x.id === id); if(!p) return; 
        
        const row = document.getElementById('inlineAddRow');
        if (row) row.style.display = 'table-row';

        this.editIndex = p.id; 
        document.getElementById('newName').value = p.name; document.getElementById('newSurname').value = p.surname; 
        document.getElementById('newYear').value = p.year; document.getElementById('newGender').value = p.gender === 'Ж' || p.gender === 'F' ? 'F' : 'M';
        document.getElementById('newCluster').value = p.group.replace(/[^A-Z+]/g, '') || 'B';
        
        const btn = document.getElementById('submitBtn');
        btn.style.background = "var(--text-main)"; btn.style.color = "var(--bg-body)"; btn.innerText = "ОБНОВИТЬ";
    }

    cancelInlineEdit() {
        this.editIndex = null; 
        document.getElementById('newName').value = ''; document.getElementById('newSurname').value = ''; document.getElementById('newYear').value = '';
        
        const btn = document.getElementById('submitBtn');
        btn.style.background = "var(--primary)"; btn.style.color = "#000"; btn.innerText = "СОХРАНИТЬ";

        const row = document.getElementById('inlineAddRow');
        if (row) row.style.display = 'none';
    }

    async removePlayer(riderId) { 
        if(!confirm("Исключить спортсмена из этой команды?")) return; 
        
        // Узнаем, из какой команды мы его кикаем
        const targetTeamId = this.viewedTeamId || (Array.isArray(this.app.currentRider?.team_id) ? this.app.currentRider?.team_id[0] : this.app.currentRider?.team_id);
        const oneTeam = Object.values(this.app.teamsMap).find(t => t.name && t.name.toUpperCase().includes('ONE TEAM'));
        const oneTeamId = oneTeam ? oneTeam.id : null;
        
        if(!oneTeamId) return alert("Не найдена системная база ONE TEAM"); 
        
        try { 
            const rider = this.app.ridersMap[riderId];
            if (!rider) return;
            
            // Удаляем только текущую открытую команду
            let currentTeams = Array.isArray(rider.team_id) ? [...rider.team_id] : (rider.team_id ? [rider.team_id] : []);
            currentTeams = currentTeams.filter(id => id !== targetTeamId);
            
            // Если выгнали отовсюду - даем статус Свободного Агента (ONE TEAM)
            if (currentTeams.length === 0) currentTeams.push(oneTeamId);

            await pb.collection('riders').update(riderId, { team_id: currentTeams, transfer_request: "" }, { requestKey: null }); 
            this.loadData(); 
        } catch(e) { alert("Ошибка удаления"); } 
    }
    
    async renameTeam(teamId, currentName) {
        const roles = this.app.usersMap[this.app.currentRider?.email] || [];
        const rStr = JSON.stringify(roles);
        const isAdmin = rStr.includes('admin') || rStr.includes('superadmin');
        
        // 🔥 ФИКС: Проверка капитанства через массив
        const myTeams = Array.isArray(this.app.currentRider?.team_id) ? this.app.currentRider.team_id : (this.app.currentRider?.team_id ? [this.app.currentRider.team_id] : []);
        const isCaptain = rStr.includes('captain') && myTeams.includes(teamId);
        
        if (!isAdmin && !isCaptain) {
            return alert("❌ Только капитан или администратор может менять название команды!");
        }

        const newName = prompt("Введите новое название команды:", currentName);
        if (!newName || newName.trim() === "" || newName === currentName) return;
        
        try {
            await pb.collection('teams').update(teamId, { name: newName.trim() }, { requestKey: null });
            
            const teamChats = this.app.chats.filter(c => c.team_id === teamId && (c.type === 'team_channel' || c.type === 'team'));
            for (let chat of teamChats) {
                await pb.collection('chats').update(chat.id, { name: newName.trim() }, { requestKey: null });
            }

            alert("✅ Название команды и канала успешно изменено!");
            location.reload(); 
        } catch(e) {
            console.error(e);
            alert("❌ Ошибка при переименовании.");
        }
    }

// ==========================================
    // ГОНКИ И КАЛЕНДАРЬ
    // ==========================================
  async openRaceRoster(raceId, raceName, raceType) {
        if (!raceName || raceName.trim() === '') {
            const cached = this.dataCalendar.find(r => r.id === raceId);
            if (cached) {
                raceName = cached.name;
            } else {
                try { 
                    const r = await pb.collection('races').getOne(raceId, { requestKey: null }); 
                    raceName = r.name; 
                } catch(e) { raceName = 'СОРЕВНОВАНИЕ'; }
            }
        }

        // 🔥 ФИКС: Принудительно создаем скрытую рабочую область, если мы туда еще не заходили
        if (typeof this.app.ensureWorkspaceExists === 'function') {
            this.app.ensureWorkspaceExists();
        }

        // 🔥 Выводим рабочую область на передний план и прячем чат
        const ws = document.getElementById('pelotonWorkspace');
        const mainChat = document.getElementById('mainChatArea');
        if (ws) {
            ws.style.display = 'flex';
            ws.classList.add('mobile-open');
        }
        if (mainChat) {
            mainChat.style.display = 'none';
        }

        this.openedEventId = raceId; 
        this.openedEventName = raceName; 
        this.openedEventType = raceType || "";
        
        const contentArea = document.getElementById('crmContentArea');
        contentArea.innerHTML = `<div style="display:flex; flex-direction:column; align-items:center; justify-content:center; height:100%;"><div class="spinner" style="width:40px; height:40px; border-width:4px; display:inline-block; border-color: var(--primary) transparent transparent transparent;"></div></div>`;
        
        const roles = this.app.usersMap[this.app.currentRider?.email] || []; 
        const rStr = JSON.stringify(roles);
        const currentRace = this.dataCalendar.find(r => r.id === raceId);
        
        this.localCategoryOrder = {};
        let freshRaceObj = null; 
        try {
            freshRaceObj = await pb.collection('races').getOne(raceId, { requestKey: null, fetchOptions: { cache: 'no-store' } });
            if (freshRaceObj && freshRaceObj.category_order) {
                let parsedOrder = typeof freshRaceObj.category_order === 'string' ? JSON.parse(freshRaceObj.category_order) : freshRaceObj.category_order;
                this.localCategoryOrder = Array.isArray(parsedOrder) ? {} : (parsedOrder || {});
            }
        } catch(e) { console.error("Ошибка скачивания индексов категорий", e); }

        let isOrganizer = false;
        if (rStr.includes('superadmin')) isOrganizer = true;
        if (currentRace) {
            let userPelotons = Array.isArray(this.app.currentRider.peloton_id) ? this.app.currentRider.peloton_id : [this.app.currentRider.peloton_id];
            if (rStr.includes('admin') && (userPelotons.includes(currentRace.peloton_id) || this.app.currentRider.id === currentRace.creator_id)) isOrganizer = true;
            if (currentRace.judge_id === this.app.currentRider.id || rStr.includes('judge')) isOrganizer = true; 
        }

        try {
            const rosters = await pb.collection('race_rosters').getFullList({ 
                filter: `race_id = "${raceId}"`, 
                expand: 'rider_id,rider_id.team_id,gruppetto_id', 
                requestKey: null 
            });
            let combinedList = [];
            
            // ВЕТКА 1: ОРГАНИЗАТОР / СУДЬЯ
            if (isOrganizer) {
                rosters.forEach(r => {
                    let rider = r.expand?.rider_id; 
                    if (!rider) return;
                    let tName = this.getRiderTeamNames(rider); 
                    if (r.expand?.gruppetto_id) tName = `${tName} <span style="color:#a855f7; font-weight:800; font-size:10px;">[G: ${r.expand.gruppetto_id.name}]</span>`;
                    
                    let gender = String(rider.gender || 'M').toUpperCase().trim(); 
                    let catCode = r.final_cluster || rider.base_cluster || 'B';
                    
                    combinedList.push({ 
                        id: rider.id, 
                        name: rider.first_name, 
                        surname: rider.last_name, 
                        year: rider.yob, 
                        gender: gender, 
                        group: catCode, 
                        final_cluster: r.final_cluster || catCode,
                        base_cluster: rider.base_cluster || 'B',
                        computedCat: catCode,
                        points: rider.rating || 0, 
                        team: tName, 
                        teamId: rider.team_id, 
                        isRegistered: true, 
                        recordId: r.id, 
                        plannedStart: r.planned_start, 
                        bib: r.bib || "", 
                        is_paid: r.is_paid || false, 
                        squad_name: r.squad_name || "", 
                        squad_id: r.squad_id || null, 
                        distance_id: r.distance_id || null 
                    });
                });
                
                let racePelotonId = null;
                try {
                    const dbRace = await pb.collection('races').getOne(raceId, { requestKey: null });
                    racePelotonId = dbRace.peloton_id;
                } catch(e) { racePelotonId = currentRace ? currentRace.peloton_id : null; }
                if (Array.isArray(racePelotonId)) racePelotonId = racePelotonId[0];

                Object.values(this.app.ridersMap).forEach(rider => {
    // Оставляем только скрытие бота:
    if (rider.email === 'bot@sotka.one') return;
    if (rider.first_name === 'Гость') return;

                    const rTeams = Array.isArray(rider.team_id) ? rider.team_id : (rider.team_id ? [rider.team_id] : []);
                    let hasMatchingPeloton = rTeams.length === 0; 
                    for (let tId of rTeams) {
                        let tObj = this.app.teamsMap[tId];
                        if (tObj) {
                            let teamPelotons = Array.isArray(tObj.peloton_id) ? tObj.peloton_id : (tObj.peloton_id ? [tObj.peloton_id] : []);
                            if (!racePelotonId || teamPelotons.includes(racePelotonId)) { hasMatchingPeloton = true; break; }
                        }
                    }
                    if (racePelotonId && rTeams.length > 0 && !hasMatchingPeloton) return;

                    if (!combinedList.find(x => x.id === rider.id)) {
                        let gender = String(rider.gender || 'M').toUpperCase().trim(); 
                        let catCode = rider.base_cluster || 'B';
                        let tName = this.getRiderTeamNames(rider); 
                        combinedList.push({ 
                            id: rider.id, 
                            name: rider.first_name, 
                            surname: rider.last_name, 
                            year: rider.yob, 
                            gender: gender, 
                            group: catCode, 
                            final_cluster: '',
                            base_cluster: rider.base_cluster || 'B',
                            computedCat: catCode,
                            points: rider.rating || 0, 
                            team: tName, 
                            teamId: rider.team_id, 
                            isRegistered: false, 
                            recordId: null, 
                            plannedStart: null, 
                            bib: "", 
                            squad_name: "", 
                            squad_id: null, 
                            distance_id: null 
                        });
                    }
                });
            // ВЕТКА 2: КАПИТАН
            } else if (rStr.includes('captain') && this.app.currentRider?.team_id) {
                const myTeams = Array.isArray(this.app.currentRider.team_id) ? this.app.currentRider.team_id : [this.app.currentRider.team_id];
                const activeTeamId = myTeams.find(id => this.app.teamsMap[id]?.peloton_id === this.app.currentPelotonFilter) || myTeams[0];

                let teamRiders = [];
                if (activeTeamId) { 
                    teamRiders = await pb.collection('riders').getFullList({ filter: `team_id ~ "${activeTeamId}"`, sort: '-rating', requestKey: null }); 
                }

                teamRiders.forEach(rider => {
                    let gender = String(rider.gender || 'M').toUpperCase().trim(); 
                    let reg = rosters.find(x => x.rider_id === rider.id);
                    let catCode = (reg && reg.final_cluster) || rider.base_cluster || 'B';
                    let tName = this.getRiderTeamNames(rider); 
                    if (reg && reg.expand?.gruppetto_id) tName = `${tName} <span style="color:#a855f7; font-weight:800; font-size:10px;">[G: ${reg.expand.gruppetto_id.name}]</span>`;
                    
                    combinedList.push({ 
                        id: rider.id, 
                        name: rider.first_name, 
                        surname: rider.last_name, 
                        year: rider.yob, 
                        gender: gender, 
                        group: catCode, 
                        final_cluster: reg ? (reg.final_cluster || catCode) : '',
                        base_cluster: rider.base_cluster || 'B',
                        computedCat: catCode,
                        points: rider.rating || 0, 
                        team: tName, 
                        teamId: rider.team_id, 
                        isRegistered: !!reg, 
                        recordId: reg ? reg.id : null, 
                        plannedStart: reg ? reg.planned_start : null, 
                        bib: reg ? reg.bib : "", 
                        is_paid: reg ? reg.is_paid : false, 
                        squad_name: reg ? (reg.squad_name || "") : "", 
                        squad_id: reg ? (reg.squad_id || null) : null, 
                        distance_id: reg ? (reg.distance_id || null) : null 
                    });
                });
                
                rosters.forEach(r => {
                    if (combinedList.find(x => x.id === r.rider_id)) return; 
                    let rider = r.expand?.rider_id; 
                    if (!rider) return;
                    let rTeamName = this.getRiderTeamNames(rider); 
                    if (r.expand?.gruppetto_id) rTeamName = `${rTeamName} <span style="color:#a855f7; font-weight:800; font-size:10px;">[G: ${r.expand.gruppetto_id.name}]</span>`;
                    
                    let catCode = r.final_cluster || rider.base_cluster || 'B';
                    combinedList.push({ 
                        id: rider.id, 
                        name: rider.first_name, 
                        surname: rider.last_name, 
                        year: rider.yob, 
                        gender: String(rider.gender || 'M').toUpperCase().trim(), 
                        group: catCode, 
                        final_cluster: r.final_cluster || catCode,
                        base_cluster: rider.base_cluster || 'B',
                        computedCat: catCode,
                        points: rider.rating || 0, 
                        team: rTeamName, 
                        teamId: rider.team_id, 
                        isRegistered: true, 
                        recordId: r.id, 
                        plannedStart: r.planned_start, 
                        bib: r.bib || "", 
                        is_paid: r.is_paid || false, 
                        squad_name: r.squad_name || "", 
                        squad_id: r.squad_id || null, 
                        distance_id: r.distance_id || null 
                    });
                });
            // ВЕТКА 3: ГОНЩИК / ПО УМОЛЧАНИЮ
            } else if (this.app.currentRider) {
                const mp = this.app.currentRider; 
                let reg = rosters.find(x => x.rider_id === mp.id);
                let gender = String(mp.gender || 'M').toUpperCase().trim(); 
                let catCode = (reg && reg.final_cluster) || mp.base_cluster || 'B';
                let tName = this.getRiderTeamNames(mp); 
                if (reg && reg.expand?.gruppetto_id) tName = `${tName} <span style="color:#a855f7; font-weight:800; font-size:10px;">[G: ${reg.expand.gruppetto_id.name}]</span>`;
                
                combinedList = [{ 
                    id: mp.id, 
                    name: mp.first_name, 
                    surname: mp.last_name, 
                    year: mp.yob, 
                    gender: gender, 
                    group: catCode, 
                    final_cluster: reg ? (reg.final_cluster || catCode) : '',
                    base_cluster: mp.base_cluster || 'B',
                    computedCat: catCode,
                    points: mp.rating || 0, 
                    team: tName, 
                    teamId: mp.team_id, 
                    isRegistered: !!reg, 
                    recordId: reg ? reg.id : null, 
                    plannedStart: reg ? reg.planned_start : null, 
                    bib: reg ? reg.bib : "", 
                    is_paid: reg ? reg.is_paid : false, 
                    squad_name: reg ? (reg.squad_name || "") : "", 
                    squad_id: reg ? (reg.squad_id || null) : null, 
                    distance_id: reg ? (reg.distance_id || null) : null 
                }];
                
                rosters.forEach(r => {
                    if (r.rider_id === mp.id) return;
                    let rider = r.expand?.rider_id; 
                    if (!rider) return;
                    let rTeamName = this.getRiderTeamNames(rider); 
                    if (r.expand?.gruppetto_id) rTeamName = `${rTeamName} <span style="color:#a855f7; font-weight:800; font-size:10px;">[G: ${r.expand.gruppetto_id.name}]</span>`;
                    
                    let catCode = r.final_cluster || rider.base_cluster || 'B';
                    combinedList.push({ 
                        id: rider.id, 
                        name: rider.first_name, 
                        surname: rider.last_name, 
                        year: rider.yob, 
                        gender: String(rider.gender || 'M').toUpperCase().trim(), 
                        group: catCode, 
                        final_cluster: r.final_cluster || catCode,
                        base_cluster: rider.base_cluster || 'B',
                        computedCat: catCode,
                        points: rider.rating || 0, 
                        team: rTeamName, 
                        teamId: rider.team_id, 
                        isRegistered: true, 
                        recordId: r.id, 
                        plannedStart: r.planned_start, 
                        bib: r.bib || "", 
                        is_paid: r.is_paid || false, 
                        squad_name: r.squad_name || "", 
                        squad_id: r.squad_id || null, 
                        distance_id: r.distance_id || null 
                    });
                });
            }
          
            combinedList.sort((a, b) => {
                if (a.isRegistered && !b.isRegistered) return -1;
                if (!a.isRegistered && b.isRegistered) return 1;
                if (a.isRegistered && b.isRegistered) {
                    const clusterWeights = { 'A+': 7, 'A': 6, 'B': 5, 'C': 4, 'D': 3, 'E': 2, 'O': 1, 'V': 0 };
                    let valA = clusterWeights[a.base_cluster || a.group] || 0;
                    let valB = clusterWeights[b.base_cluster || b.group] || 0;
                    if (valA !== valB) return valA - valB; 
                    if (a.gender !== b.gender) return a.gender.localeCompare(b.gender);
                }
                let surnameA = a.surname || ''; 
                let surnameB = b.surname || '';
                if (surnameA !== surnameB) return surnameA.localeCompare(surnameB);
                let nameA = a.name || ''; 
                let nameB = b.name || '';
                return nameA.localeCompare(nameB);
            });

            this.raceRosterList = combinedList;

            let html = `<div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:16px;">
                <h2 style="font-family:'Unbounded'; font-weight:800; font-size:18px; color:var(--text-main); margin:0;">ЗАЯВКА: ${raceName.toUpperCase()}</h2>
                <button style="background:var(--bg-body); color:var(--text-main); border:1px solid var(--border); padding:8px 16px; border-radius:50px; font-family:'Unbounded'; font-weight:800; font-size:10px; cursor:pointer; transition:0.2s;" onmouseover="this.style.borderColor='var(--text-main)'" onmouseout="this.style.borderColor='var(--border)'" onclick="window.app.crm.switchView('calendar')">← НАЗАД</button>
            </div>`;
            
            html += `<div style="display:flex; gap:8px; margin-bottom: 20px; overflow-x:auto; scrollbar-width:none; padding-bottom:4px; -webkit-overflow-scrolling:touch;">`;
            if (isOrganizer) { 
                const btnStyle = "background:transparent; color:var(--text-muted); border:1px solid var(--border); padding:8px 16px; border-radius:50px; font-family:'Unbounded'; font-weight:800; font-size:10px; cursor:pointer; flex-shrink:0; transition:0.2s;";
                html += `<button style="${btnStyle}" onmouseover="this.style.color='var(--text-main)'; this.style.borderColor='var(--text-main)';" onmouseout="this.style.color='var(--text-muted)'; this.style.borderColor='var(--border)';" onclick="window.app.crm.generateBibs()">BIB-НОМЕРА</button>`;
                html += `<button style="${btnStyle}" onmouseover="this.style.color='var(--text-main)'; this.style.borderColor='var(--text-main)';" onmouseout="this.style.color='var(--text-muted)'; this.style.borderColor='var(--border)';" onclick="window.app.crm.openWaveStartModal()">ВОЛНЫ (МАСС-СТАРТ)</button>`;
                html += `<button style="${btnStyle}" onmouseover="this.style.color='var(--text-main)'; this.style.borderColor='var(--text-main)';" onmouseout="this.style.color='var(--text-muted)'; this.style.borderColor='var(--border)';" onclick="window.app.crm.generateITTStarts()">ITT-СТАРТЫ</button>`;
                html += `<button style="${btnStyle}" onmouseover="this.style.color='var(--text-main)'; this.style.borderColor='var(--text-main)';" onmouseout="this.style.color='var(--text-muted)'; this.style.borderColor='var(--border)';" onclick="window.app.crm.triggerCsvImport('${raceId}')">ИМПОРТ CSV</button>`;
                
                if (currentRace && currentRace.status !== 'Finished' && currentRace.status !== 'LIVE') {
                    html += `<button style="background:rgba(255,51,102,0.1); color:var(--danger); border:1px solid rgba(255,51,102,0.3); padding:8px 16px; border-radius:50px; font-family:'Unbounded'; font-weight:800; font-size:10px; cursor:pointer; flex-shrink:0; transition:0.2s; margin-left:10px;" onmouseover="this.style.background='var(--danger)'; this.style.color='#fff';" onmouseout="this.style.background='rgba(255,51,102,0.1)'; this.style.color='var(--danger)';" onclick="window.app.crm.startManualLiveRace('${raceId}')">🔴 СТАРТ ГОНКИ (LIVE)</button>`;
                }
                if (currentRace && currentRace.status === 'LIVE') {
                    html += `<button style="background:rgba(0,230,118,0.1); color:var(--success); border:1px solid rgba(0,230,118,0.3); padding:8px 16px; border-radius:50px; font-family:'Unbounded'; font-weight:800; font-size:10px; cursor:pointer; flex-shrink:0; transition:0.2s; margin-left:10px;" onmouseover="this.style.background='var(--success)'; this.style.color='#fff';" onmouseout="this.style.background='rgba(0,230,118,0.1)'; this.style.color='var(--success)';" onclick="window.app.crm.finalizeRaceProcess('${raceId}')">🏁 ЗАКРЫТЬ И РАСПРЕДЕЛИТЬ ОЧКИ</button>`;
                }
            }                
            html += `</div>`;

            this.rosterSearchQuery = ''; 
            this.rosterTeamFilter = 'all'; 

            html += `<div style="display:flex; justify-content:space-between; align-items:center; margin-bottom: 15px; flex-wrap:wrap; gap:10px;">
                <div style="display:flex; background:var(--bg-surface-hover); border-radius:50px; padding:4px; border:1px solid var(--border);">
                    <button id="btn-roster-all" onclick="window.app.crm.setRosterTeamFilter('all')" style="background:var(--text-main); color:var(--bg-body); border:none; padding:6px 16px; border-radius:50px; font-family:'Unbounded', sans-serif; font-size:10px; font-weight:800; cursor:pointer; transition:0.2s;">ВСЕ</button>
                    <button id="btn-roster-myteam" onclick="window.app.crm.setRosterTeamFilter('myteam')" style="background:transparent; color:var(--text-muted); border:none; padding:6px 16px; border-radius:50px; font-family:'Unbounded', sans-serif; font-size:10px; font-weight:800; cursor:pointer; transition:0.2s;">МОЯ КОМАНДА</button>
                </div>
                <input type="text" placeholder="Поиск гонщика..." value="${this.rosterSearchQuery}" style="background:var(--bg-surface-hover); border:1px solid var(--border); color:var(--text-main); padding:8px 16px; border-radius:50px; font-family:'Manrope'; font-size:11px; outline:none; transition:0.2s; min-width:200px;" oninput="window.app.crm.setRosterSearch(this.value); window.app.crm.renderFilteredRaceRosterTable();">
            </div>`;

            html += `<div id="raceRosterTableContainer"></div>`;
            contentArea.innerHTML = html;

            this.renderFilteredRaceRosterTable = () => {
                const tableContainer = document.getElementById('raceRosterTableContainer');
                if (!tableContainer) return;

                const raceObj = freshRaceObj || (typeof currentRace !== 'undefined' ? currentRace : null);
                const isTeamRace = raceObj && (raceObj.format === 'ttt' || raceObj.format === 'relay');

                const crmSquadGenders = {};
                combinedList.forEach(item => {
                    if (item.isRegistered && item.squad_id) {
                        if (!crmSquadGenders[item.squad_id]) crmSquadGenders[item.squad_id] = [];
                        crmSquadGenders[item.squad_id].push(String(item.gender || 'M').toUpperCase().trim());
                    }
                });

                let filteredList = [...combinedList];
                const myId = this.app.currentRider?.id;

                // 1. Фильтр «Моя команда»
                if (this.rosterTeamFilter === 'myteam') {
                    const myTeams = Array.isArray(this.app.currentRider?.team_id)
                        ? this.app.currentRider.team_id
                        : (this.app.currentRider?.team_id ? [this.app.currentRider.team_id] : []);

                    filteredList = filteredList.filter(p => {
                        if (p.id === myId || p.rider_id === myId) return true;
                        const rawTeams = p.teamId || p.team_id;
                        const pTeams = Array.isArray(rawTeams) ? rawTeams : (rawTeams ? [rawTeams] : []);
                        return myTeams.some(id => pTeams.includes(id));
                    });
                }

                // 2. Умный поиск (по ФИО, BIB, клубу)
                if (this.rosterSearchQuery) {
                    const q = this.rosterSearchQuery.toLowerCase().trim();
                    filteredList = filteredList.filter(p => {
                        const str = `${p.surname || ''} ${p.name || ''} ${p.name || ''} ${p.surname || ''} ${p.bib || ''} ${p.team || ''} ${p.group || ''}`.toLowerCase();
                        return str.includes(q);
                    });
                }

                // 3. Расчет категорий с защитой от перезаписи судейских правок
                filteredList.forEach(p => {
                    const existingCat = p.final_cluster || p.group;
                    if (p.isRegistered && existingCat && (existingCat.includes('[') || existingCat.includes('•'))) {
                        p.computedCat = existingCat;
                        return;
                    }

                    p.computedCat = existingCat || 'B';
                    if (raceObj && typeof this.getRaceCategory === 'function') {
                        try {
                            p.computedCat = this.getRaceCategory({
                                gender: p.gender,
                                yob: p.year,
                                base_cluster: p.base_cluster || p.group || 'B',
                                id: p.id,
                                squad_id: p.squad_id,
                                squad_genders: crmSquadGenders[p.squad_id] || []
                            }, raceObj);
                        } catch (e) {}
                    }
                });

                const registeredRiders = filteredList.filter(r => r.isRegistered);
                const unregisteredRiders = filteredList.filter(r => !r.isRegistered);

                const squadCounts = {};
                registeredRiders.forEach(p => {
                    if (p.squad_id) squadCounts[p.squad_id] = (squadCounts[p.squad_id] || 0) + 1;
                });

                let groupedRosters = {};
                registeredRiders.forEach(p => {
                    let orderIndex = this.localCategoryOrder[p.computedCat];
                    if (orderIndex !== undefined && orderIndex !== null && orderIndex !== "") {
                        if (!groupedRosters[orderIndex]) groupedRosters[orderIndex] = { index: parseInt(orderIndex), originalCats: new Set(), riders: [] };
                        groupedRosters[orderIndex].originalCats.add(p.computedCat);
                        groupedRosters[orderIndex].riders.push(p);
                    } else {
                        if (!groupedRosters[p.computedCat]) groupedRosters[p.computedCat] = { index: 99999, originalCats: new Set([p.computedCat]), riders: [] };
                        groupedRosters[p.computedCat].riders.push(p);
                    }
                });

                let groupsArray = Object.values(groupedRosters);
                groupsArray.sort((a, b) => {
                    if (a.index !== b.index) return a.index - b.index;
                    const catA = Array.from(a.originalCats)[0];
                    const catB = Array.from(b.originalCats)[0];
                    return window.app.crm.getCatRank(catA) - window.app.crm.getCatRank(catB);
                });

                groupsArray.forEach(group => {
                    group.riders.sort((a, b) => {
                        let timeA = a.plannedStart || "23:59:59";
                        let timeB = b.plannedStart || "23:59:59";
                        if (timeA !== timeB) return timeA.localeCompare(timeB);
                        
                        if (isTeamRace) {
                            let squadA = a.squad_id || '';
                            let squadB = b.squad_id || '';
                            if (squadA !== squadB) {
                                if (!squadA) return 1;  
                                if (!squadB) return -1;
                                return squadA.localeCompare(squadB);
                            }
                        }

                        let ptsA = a.points || 0; 
                        let ptsB = b.points || 0;
                        if (ptsA !== ptsB) return ptsA - ptsB; 
                        
                        return (a.surname + a.name).localeCompare(b.surname + b.name);
                    });
                });

                unregisteredRiders.sort((a, b) => {
                    if (a.computedCat !== b.computedCat) return window.app.crm.getCatRank(a.computedCat) - window.app.crm.getCatRank(b.computedCat);
                    let ptsA = a.points || 0; 
                    let ptsB = b.points || 0;
                    if (ptsA !== ptsB) return ptsA - ptsB;
                    return (a.surname + a.name).localeCompare(b.surname + b.name);
                });

                let tableHtml = `<div class="p-table-container"><table class="p-roster-table"><thead><tr><th style="width:100px;">Действие</th><th style="width:60px;">BIB</th><th>Имя</th><th style="max-width: 140px;">Команда</th><th style="width:80px;">ГР</th><th>Категория</th><th>Старт</th><th>Рейт.</th></tr></thead><tbody>`;
                
                if (filteredList.length === 0) { 
                    tableHtml += `<tr><td colspan="8" style="text-align:center; padding:40px; color:var(--text-muted); font-family:'Unbounded';">Гонщики не найдены</td></tr>`; 
                } else {
                    const generateRowHtml = (p) => {
                        let bg = p.isRegistered ? 'background:var(--success-light);' : ''; 
                        let act = "";
                        let canEditRow = (isOrganizer || p.id === (this.app.currentRider ? this.app.currentRider.id : null));
                        if (!canEditRow && typeof rStr !== 'undefined' && rStr.includes('captain')) {
                            const myTeams = Array.isArray(this.app.currentRider?.team_id) ? this.app.currentRider.team_id : [this.app.currentRider?.team_id];
                            const pTeams = Array.isArray(p.teamId) ? p.teamId : [p.teamId];
                            if (myTeams.some(id => pTeams.filter(Boolean).includes(id))) canEditRow = true;
                        }

                        if (canEditRow) {
                            act = p.isRegistered 
                                ? `<button class="btn-action" style="background:rgba(255,51,102,0.1); border:1px solid var(--danger); color:var(--danger); width:auto; padding:6px 12px; font-size:9px; border-radius:6px; font-family:'Unbounded'; font-weight:800; cursor:pointer; transition:0.2s;" onclick="window.app.crm.revokeRaceReg('${p.recordId}')">ОТОЗВАТЬ</button>` 
                                : `<button class="btn-action" style="background:var(--primary); border:1px solid var(--primary); color:#000; width:auto; padding:6px 12px; font-size:9px; border-radius:6px; font-family:'Unbounded'; font-weight:800; cursor:pointer; transition:0.2s;" onclick="window.app.crm.registerSingleRider('${p.id}', this, event)">ЗАЯВИТЬ</button>`;
                        } else {
                            act = p.isRegistered ? `<span style="color:var(--success); font-weight:800; font-size:10px;">ЗАЯВЛЕН</span>` : `<span style="color:var(--text-muted); font-size:10px;">-</span>`;
                        }

                        let genderBadge = "";
                        const catStr = String(p.computedCat || "");
                        if (!catStr.includes('[') && !catStr.includes('U')) {
                            genderBadge = p.gender === 'F' ? '<span style="font-family:\'Unbounded\'; font-size:9px; font-weight:800; padding:2px 6px; border-radius:4px; background:var(--bg-body); border:1px solid var(--border); margin-right:6px; color:var(--danger);">Ж</span>' : '<span style="font-family:\'Unbounded\'; font-size:9px; font-weight:800; padding:2px 6px; border-radius:4px; background:var(--bg-body); border:1px solid var(--border); margin-right:6px;">М</span>';
                        }

                        let bibHtml = "-"; 
                        if (p.isRegistered) { 
                            let inputDisabled = isOrganizer ? "" : "disabled";
                            bibHtml = `<input type="text" style="width:40px; height:30px; text-align:center; background:transparent; border:1px solid var(--border); color:var(--primary); font-family:'Roboto Mono'; font-weight:bold; border-radius:4px;" value="${p.bib || ''}" onchange="window.app.crm.updateBib('${p.recordId}', this.value, this)" ${inputDisabled}>`; 
                        }
                        
                        let paidBadge = "";
                        if (p.isRegistered) {
                            let paidAction = isOrganizer ? `onclick="window.app.crm.togglePaymentStatus('${p.recordId}', ${p.is_paid})"` : '';
                            let cursorStyle = isOrganizer ? 'cursor:pointer;' : 'cursor:default;';
                            paidBadge = p.is_paid 
                                ? `<span ${paidAction} style="background:#e6f4ea; color:#28a745; padding:2px 6px; border-radius:4px; font-size:9px; font-weight:800; ${cursorStyle} margin-left:8px; border:1px solid #c3e6cb; transition:0.2s; white-space:nowrap;" title="Нажмите, чтобы отменить оплату">₽ ОПЛ</span>`
                                : `<span ${paidAction} style="background:#f8d7da; color:#dc3545; padding:2px 6px; border-radius:4px; font-size:9px; font-weight:800; ${cursorStyle} margin-left:8px; border:1px solid #f5c6cb; transition:0.2s; white-space:nowrap;" title="Нажмите, чтобы подтвердить оплату">₽ НЕ ОПЛ</span>`;
                        }
                        
                        let timeHtml = "-"; 
                        if (p.isRegistered) { 
                            let inputDisabled = isOrganizer ? "" : "disabled";
                            timeHtml = `<input type="text" style="width:70px; height:30px; text-align:center; background:transparent; border:1px solid var(--border); color:var(--text-main); font-family:'Roboto Mono'; font-weight:bold; border-radius:4px;" value="${p.plannedStart || ''}" placeholder="--:--" onchange="window.app.crm.updateStartTime('${p.recordId}', this.value, this)" ${inputDisabled}>`; 
                        }

                        let catHtml = `<span style="font-size:11px; font-weight:600; font-family:'Roboto Mono';">${p.computedCat}</span>`;
                        if (p.isRegistered) {
                            let inputDisabled = isOrganizer ? "" : "disabled";
                            catHtml = `<input type="text" style="width:70px; height:30px; text-align:center; background:transparent; border:1px solid var(--border); color:var(--text-main); font-family:'Roboto Mono'; font-weight:bold; border-radius:4px;" value="${p.computedCat}" onchange="window.app.crm.updateCategory('${p.recordId}', this.value, this)" ${inputDisabled}>`;
                        }

                        let squadBadge = '';
                        if (isTeamRace && p.squad_id) {
                            const currentSqCount = squadCounts[p.squad_id] || 1;
                            const sMax = raceObj ? (raceObj.squad_max > 1 ? raceObj.squad_max : ((raceObj.format==='ttt'||raceObj.format==='relay') ? 4 : 1)) : 1;
                            
                            let joinBtn = '';
                            const myRiderId = this.app.currentRider ? this.app.currentRider.id : null;
                            const myRow = myRiderId ? filteredList.find(r => r.id === myRiderId && r.isRegistered) : null;
                            const isAlreadyInThisSquad = myRow && myRow.squad_id === p.squad_id;
                            const isMySquadAlreadyFull = myRow && myRow.squad_id && (squadCounts[myRow.squad_id] || 1) >= sMax;

                            if (currentSqCount < sMax && !isAlreadyInThisSquad && !isMySquadAlreadyFull) {
                                joinBtn = `<button onclick="window.app.joinSquadDirectly('${raceObj.id}', '${p.squad_id}', '${this.app.escapeHTML(p.squad_name || '')}', '${p.distance_id || ''}')" style="background:#000000; color:var(--primary, #ffc107); border:1px solid var(--primary, #ffc107); padding:2px 8px; border-radius:4px; font-size:8px; font-family:'Unbounded'; font-weight:800; cursor:pointer; margin-left:6px; box-shadow: 0 2px 5px rgba(255,193,7,0.2); transition:0.2s;" onmouseover="this.style.transform='scale(1.05)'" onmouseout="this.style.transform='none'">🤝 ВСТУПИТЬ</button>`;
                            }
                            
                            squadBadge = `<br><span style="background:rgba(168,85,247,0.15); color:#a855f7; padding:2px 4px; border-radius:4px; font-size:9px; font-family:'Unbounded'; font-weight:800; border:1px solid rgba(168,85,247,0.3); margin-top: 4px; display: inline-flex; align-items: center;">ЭКИПАЖ: ${(p.squad_name || '').toUpperCase()} (${currentSqCount}/${sMax})${joinBtn}</span>`;
                        }

                        return `<tr style="${bg}"><td>${act}</td><td>${bibHtml}</td> <td><div style="display:flex; align-items:center; flex-wrap:nowrap;"><b style="font-size:13px; cursor:pointer; transition:0.2s; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;" onmouseover="this.style.color='var(--primary)'" onmouseout="this.style.color=''" onclick="window.app.openProfile('${p.id}')" title="Открыть профиль">${p.name} ${p.surname}</b> ${paidBadge}</div>${squadBadge}</td><td style="max-width: 140px; white-space: normal; line-height: 1.3; word-wrap: break-word;"><span style="color:var(--text-muted); font-size:11px;">${p.team}</span></td><td><span style="color:var(--text-muted); font-family:'Roboto Mono'; font-size:12px;">${p.year}</span></td><td><div style="display:flex; align-items:center;">${genderBadge}${catHtml}</div></td><td>${timeHtml}</td><td><b style="color:var(--primary); font-size:13px; font-family:'Roboto Mono';">${p.points}</b></td></tr>`;
                    };

                    groupsArray.forEach(group => {
                        const originalCatsArray = Array.from(group.originalCats).sort((a,b) => window.app.crm.getCatRank(a) - window.app.crm.getCatRank(b));
                        const groupName = originalCatsArray.join(' <span style="color:var(--text-muted);">+</span> ');
                        const currentInputValue = group.index === 99999 ? '' : group.index;
                        const isMergedGroup = originalCatsArray.length > 1;

                        let orderInputHtml = '';
                        if (isOrganizer) {
                            let unmergeBtnHtml = '';
                            const catsJsonForUpdate = this.app.escapeHTML(JSON.stringify(originalCatsArray));
                            
                            if (isMergedGroup) {
                                unmergeBtnHtml = `<button onclick="window.app.crm.unmergeCategories('${raceObj.id}', '${catsJsonForUpdate}')" style="background:rgba(255,51,102,0.1); border:1px solid rgba(255,51,102,0.3); color:var(--danger); padding:4px 8px; border-radius:4px; font-size:9px; font-family:'Unbounded'; font-weight:800; cursor:pointer; margin-right: 10px;" title="Разделить на отдельные категории">✂️️ РАЗДЕЛИТЬ</button>`;
                            }
                            
                            orderInputHtml = `
                                <div style="display:flex; align-items:center;">
                                    ${unmergeBtnHtml}
                                    <span style="font-size:10px; color:var(--text-muted); margin-right: 8px;">Очередь:</span>
                                    <input type="number" value="${currentInputValue}" placeholder="-" onchange="window.app.crm.updateGroupOrder('${raceObj.id}', '${catsJsonForUpdate}', this.value)" style="width:40px; height:24px; text-align:center; background:var(--bg-body); border:1px solid var(--border); color:var(--primary); font-family:'Roboto Mono'; font-weight:bold; border-radius:4px; outline:none;">
                                </div>`;
                        }

                        tableHtml += `<tr><td colspan="8" style="padding:0; background:var(--bg-surface-hover); border-top: 2px solid var(--primary); border-bottom: 1px solid var(--border);">
                            <div style="display:flex; justify-content:space-between; align-items:center; padding:14px 10px;">
                                <div style="color:var(--text-main); font-family:'Unbounded'; font-weight:800; font-size:13px; text-transform:uppercase;">КАТЕГОРИЯ: <span style="color:var(--primary);">${groupName}</span></div>
                                ${orderInputHtml}
                            </div>
                        </td></tr>`;

                        group.riders.forEach(p => { tableHtml += generateRowHtml(p); });
                    });

                    if (unregisteredRiders.length > 0) {
                        tableHtml += `<tr><td colspan="8" style="padding: 30px 10px 10px; border-bottom: 1px solid var(--border); color: var(--text-muted); font-family: 'Unbounded'; font-weight: 800; font-size: 11px; text-transform: uppercase; text-align: center;">🔻 ДОСТУПНЫ ДЛЯ ЗАЯВКИ 🔻</td></tr>`;
                        unregisteredRiders.forEach(p => { tableHtml += generateRowHtml(p); });
                    }
                }
                tableHtml += `</tbody></table></div>`; 
                tableContainer.innerHTML = tableHtml;
            };
            
            setTimeout(() => { 
                if (typeof this.renderFilteredRaceRosterTable === 'function') {
                    this.renderFilteredRaceRosterTable(); 
                }
            }, 10);

        } catch(e) { 
            console.error(e); 
            contentArea.innerHTML = '<div style="text-align:center; color:var(--danger); padding:40px;">Ошибка загрузки состава</div>'; 
        }
    }
async updateBib(recordId, newBib, inputEl) {
    if (!recordId) return;

    let targetRider = (this.liveService?.currentLiveStartList || []).find(r => (r.recordId || r.id) === recordId)
                   || (this.raceRosterList || []).find(r => (r.recordId || r.id) === recordId);

    const cleanBib = (newBib || '').trim();

    // 🛑 1. ЗАЩИТА: мусорные данные, сканер паспортов и кириллица
    if (cleanBib.startsWith('V1') || cleanBib.startsWith('v1') || 
        cleanBib.startsWith('М1') || cleanBib.startsWith('м1') || 
        cleanBib.includes('|') || cleanBib.includes('/') || 
        /[а-яА-ЯёЁ]/.test(cleanBib) || cleanBib.length > 7) {

        if (inputEl) {
            inputEl.value = (targetRider?.bib && !targetRider.bib.startsWith('V1') && !targetRider.bib.startsWith('М1')) ? targetRider.bib : '';
        }
        return;
    }

    // 🏁 2. Определение формата заезда (соло против командной гонки)
    const raceId = targetRider?.race_id || this.openedEventId || this.liveService?.expandedRaceId;
    const raceObj = (this.dataCalendar?.find(r => r.id === raceId))
             || (this.app?.racesMap?.[raceId])
             || (this.liveService?.currentEventRaces?.find(r => r.id === raceId));

    const squadMax = parseInt(raceObj?.squad_max || targetRider?.squad_max || 1);
    const isTeamRace = raceObj?.format === 'ttt' || raceObj?.format === 'relay' || squadMax > 1;

    // 🛑 3. ПРОВЕРКА НА ДУБЛИКАТ НОМЕРА
    if (cleanBib !== "") {
        const currentList = this.liveService?.currentLiveStartList || this.raceRosterList || [];

        const duplicate = currentList.find(r => {
            const rRecId = r.recordId || r.id;
            if (rRecId === recordId) return false; // Сам редактируемый участник
            if (!r.isRegistered) return false;
            return String(r.bib || '').trim() === cleanBib;
        });

        if (duplicate) {
            const isSameSquad = Boolean(
                targetRider?.squad_id && 
                duplicate.squad_id && 
                targetRider.squad_id === duplicate.squad_id
            );

            // А. В индивидуальной гонке совпадение номеров запрещено категорически
            if (!isTeamRace) {
                const dupName = duplicate.fullName || `${duplicate.name || ''} ${duplicate.surname || ''}`.trim() || `№${cleanBib}`;
                alert(`❌ В индивидуальной гонке номер №${cleanBib} уже выдан спортсмену:\n«${dupName}»!\n\nОдинаковые номера разрешены только в командных заездах.`);
                if (inputEl) inputEl.value = targetRider?.bib || '';
                return;
            }

            // Б. В командной гонке: совпадение допустимо только внутри одного экипажа
            if (isTeamRace && !isSameSquad) {
                const dupSquad = duplicate.squad_name || `Экипаж №${cleanBib}`;
                alert(`❌ Номер №${cleanBib} уже занят другим составом:\n«${dupSquad}»!\n\nДля добавления спортсмена в этот экипаж используйте кнопку «Управление экипажем».`);
                if (inputEl) inputEl.value = targetRider?.bib || '';
                return;
            }
        }
    }

    // 👥 4. Если гонка командная и спортсмен в экипаже — обновляем номер сразу всей команде
    if (isTeamRace && targetRider?.squad_id && typeof this.updateSquadBib === 'function') {
        await this.updateSquadBib(raceId, targetRider.squad_id, cleanBib, inputEl);
        return;
    }

    // 💾 5. Сохранение одиночного номера в PocketBase
    if (inputEl) inputEl.style.backgroundColor = 'var(--success-light)';

    try {
        await pb.collection('race_rosters').update(recordId, { bib: cleanBib }, { requestKey: null });

        if (targetRider) targetRider.bib = cleanBib;

        if (this.liveService?.currentLiveStartList) {
            const lr = this.liveService.currentLiveStartList.find(r => (r.recordId || r.id) === recordId);
            if (lr) lr.bib = cleanBib;
        }
        if (this.raceRosterList) {
            const cr = this.raceRosterList.find(r => (r.recordId || r.id) === recordId);
            if (cr) cr.bib = cleanBib;
        }

        if (inputEl) {
            inputEl.value = cleanBib;
            setTimeout(() => { inputEl.style.backgroundColor = ''; }, 800);
        }
    } catch(e) {
        console.error("Ошибка сохранения BIB:", e);
        if (inputEl) {
            inputEl.style.backgroundColor = 'var(--danger-light)';
            inputEl.value = targetRider?.bib || ''; // Откатываем значение в поле на актуальное
        }
        alert("Ошибка сохранения номера: " + e.message);
    }
}
// =========================================================
    // 🔢 СОХРАНЕНИЕ BIB НОМЕРА ДЛЯ ВСЕГО ЭКИПАЖА / КОМАНДЫ
    // =========================================================
    async updateSquadBib(raceId, squadId, newBib, inputEl) {
        if (!squadId) return;
        const cleanBib = (newBib || '').trim();
        if (inputEl) inputEl.style.backgroundColor = 'rgba(255, 193, 7, 0.2)';

        try {
            // 1. Напрямую из базы достаем всех участников экипажа
            const dbRosters = await pb.collection('race_rosters').getFullList({
                filter: `race_id="${raceId}" && squad_id="${squadId}" && status!="canceled"`,
                requestKey: null
            });

            // 2. Гарантированно обновляем поле bib у каждого участника по его roster.id
            await Promise.all(dbRosters.map(m => 
                pb.collection('race_rosters').update(m.id, { bib: cleanBib }, { requestKey: null })
            ));

            // 3. Синхронизируем локальные списки в памяти
            const liveList = this.liveService?.currentLiveStartList || [];
            const crmList = this.raceRosterList || [];

            liveList.forEach(r => {
                if (r.squad_id === squadId) r.bib = cleanBib;
            });
            crmList.forEach(r => {
                if (r.squad_id === squadId) r.bib = cleanBib;
            });

            if (inputEl) {
                inputEl.value = cleanBib;
                inputEl.style.backgroundColor = 'rgba(16, 185, 129, 0.2)';
                setTimeout(() => { inputEl.style.backgroundColor = ''; }, 800);
            }
        } catch(e) {
            console.error("Ошибка сохранения BIB номера экипажа:", e);
            if (inputEl) inputEl.style.backgroundColor = 'rgba(239, 68, 68, 0.2)';
            alert("Ошибка сохранения номера: " + e.message);
        }
    }

    // =========================================================
    // ⏱️ СОХРАНЕНИЕ ВРЕМЕНИ СТАРТА ДЛЯ ВСЕГО ЭКИПАЖА
    // =========================================================
    async updateSquadStartTime(raceId, squadId, newTime, inputEl) {
        if (!squadId) return;
        let formattedTime = (newTime || '').trim();
        if (formattedTime.length === 5 && formattedTime.includes(':')) {
            formattedTime += ':00';
        }
        if (inputEl) inputEl.style.backgroundColor = 'rgba(255, 193, 7, 0.2)';

        try {
            // 1. Напрямую из базы достаем всех участников экипажа
            const dbRosters = await pb.collection('race_rosters').getFullList({
                filter: `race_id="${raceId}" && squad_id="${squadId}" && status!="canceled"`,
                requestKey: null
            });

            // 2. Гарантированно обновляем время старта каждому участнику по его roster.id
            await Promise.all(dbRosters.map(m => 
                pb.collection('race_rosters').update(m.id, { planned_start: formattedTime }, { requestKey: null })
            ));

            // 3. Синхронизируем локальные списки в памяти
            const liveList = this.liveService?.currentLiveStartList || [];
            const crmList = this.raceRosterList || [];

            liveList.forEach(r => {
                if (r.squad_id === squadId) r.plannedStart = formattedTime;
            });
            crmList.forEach(r => {
                if (r.squad_id === squadId) r.plannedStart = formattedTime;
            });

            if (inputEl) {
                inputEl.value = formattedTime;
                inputEl.style.backgroundColor = 'rgba(16, 185, 129, 0.2)';
                setTimeout(() => { inputEl.style.backgroundColor = ''; }, 800);
            }
        } catch(e) {
            console.error("Ошибка сохранения времени старта экипажа:", e);
            if (inputEl) inputEl.style.backgroundColor = 'rgba(239, 68, 68, 0.2)';
            alert("Ошибка сохранения времени: " + e.message);
        }
    }
	// ==========================================
    // 🔥 РУЧНОЕ УПРАВЛЕНИЕ СТАТУСОМ ОПЛАТЫ
    // ==========================================
async togglePaymentStatus(recordId, currentStatus) {
    if (!recordId) return;

    const appRef = this.app || window.app;
    const curRider = appRef?.currentRider;

    // 1. Проверка авторизации: гости не могут проводить операции со счётом
    if (!curRider || curRider.id === 'anonymous_guest' || (curRider.email && curRider.email.startsWith('guest_'))) {
        alert("Для проведения оплаты или подтверждения взноса необходимо войти в аккаунт.");
        if (typeof appRef?.openLoginScreen === 'function') appRef.openLoginScreen();
        return;
    }

    // 2. Находим спортсмена и гарантированный ID гонки
    const targetRosterItem = (this.liveService?.currentLiveStartList || this.raceRosterList || []).find(r => (r.recordId || r.id) === recordId);
    const targetName = targetRosterItem ? (targetRosterItem.fullName || `${targetRosterItem.name || ''} ${targetRosterItem.surname || ''}`.trim()) : 'участника';

    const targetRaceId = this.openedEventId || this.liveService?.expandedRaceId || targetRosterItem?.race_id;

    let race = (this.dataCalendar ? this.dataCalendar.find(r => r.id === targetRaceId) : null)
            || (appRef?.racesMap ? appRef.racesMap[targetRaceId] : null);

    if (!race && targetRaceId) {
        try {
            race = await pb.collection('races').getOne(targetRaceId, { requestKey: null });
        } catch(e) {}
    }

    const raceCost = parseInt(race?.price ?? race?.cost ?? 0) || 0;
    const raceTitle = race?.name || 'Гонка';

    // 3. Проверка прав организатора (только Суперадмин, Админ и Создатель заезда)
    const myRole = appRef?.getUserMaxRole ? appRef.getUserMaxRole() : 'rider';
    const roleWeights = appRef?.ROLE_WEIGHTS || { superadmin: 100, admin: 80, judge: 60, captain: 40, rider: 20 };
    const isSuperOrAdmin = (roleWeights[myRole] || 20) >= (roleWeights['admin'] || 80);
    const myRiderId = curRider.id;
    const myUserId = pb.authStore.model?.id;
    const isRaceCreator = Boolean(race && (race.creator_id === myRiderId || race.creator_id === myUserId));
    const isPrivilegedOrganizer = isSuperOrAdmin || isRaceCreator;

    // Вспомогательная функция обновления интерфейса (CRM, LiveBoard и чат)
    const syncUiState = async (newPaidStatus) => {
        let freshRoster = null;
        try {
            freshRoster = await pb.collection('race_rosters').getOne(recordId, { requestKey: null });
        } catch (err) {
            console.warn("Не удалось подтянуть свежий ростер из базы:", err);
        }

        // Обновляем запись в списке CRM
        let p = this.raceRosterList?.find(r => (r.recordId || r.id) === recordId);
        if (p) {
            p.is_paid = newPaidStatus;
            if (freshRoster) {
                p.bib = freshRoster.bib || p.bib || '';
                p.plannedStart = freshRoster.planned_start || p.plannedStart || '';
                p.actualStart = freshRoster.actual_start || p.actualStart || '';
            }
        }

        // Обновляем запись в открытом табло LiveBoard
        if (this.liveService && Array.isArray(this.liveService.currentLiveStartList)) {
            let lp = this.liveService.currentLiveStartList.find(r => (r.recordId || r.id) === recordId);
            if (lp) {
                lp.is_paid = newPaidStatus;
                if (freshRoster) {
                    lp.bib = freshRoster.bib || lp.bib || '';
                    lp.plannedStart = freshRoster.planned_start || lp.plannedStart || '';
                    lp.actualStart = freshRoster.actual_start || lp.actualStart || '';
                }
            }
        }

        if (typeof this.renderFilteredRaceRosterTable === 'function') {
            this.renderFilteredRaceRosterTable();
        }
        if (this.liveService && typeof this.liveService.renderLiveBoard === 'function') {
            this.liveService.renderLiveBoard();
        }
        if (appRef && typeof appRef.syncRaceButtonsState === 'function') {
            appRef.syncRaceButtonsState();
        }
    };

    // -----------------------------------------------------------------
    // СЦЕНАРИЙ 1: СЛОТ УЖЕ ОПЛАЧЕН (Отмена статуса оплаты)
    // -----------------------------------------------------------------
    if (currentStatus === true) {
        if (!isPrivilegedOrganizer) {
            alert("Участие уже оплачено и зафиксировано в протоколе. Отменить взнос может только организатор гонки.");
            return;
        }

        if (!confirm(`Вы организатор гонки.\n\nОТМЕНИТЬ оплату участия для ${targetName}?`)) return;

        try {
            await pb.collection('race_rosters').update(recordId, { is_paid: false }, { requestKey: null });
            await syncUiState(false);
        } catch (e) {
            alert("Ошибка изменения статуса: " + e.message);
        }
        return;
    }

    // -----------------------------------------------------------------
    // СЦЕНАРИЙ 2: БЕСПЛАТНАЯ ГОНКА / ОПЛАТА НА МЕСТЕ (Цена = 0 W)
    // -----------------------------------------------------------------
    if (raceCost === 0) {
        if (!isPrivilegedOrganizer) {
            alert("Взнос за эту гонку не установлен (участие бесплатное или оплачивается наличными на месте). Допуск подтверждает организатор или судья на старте.");
            return;
        }

        if (!confirm(`Подтвердить допуск/оплату на месте для ${targetName}?`)) return;

        try {
            await pb.collection('race_rosters').update(recordId, { is_paid: true }, { requestKey: null });
            await syncUiState(true);
        } catch (e) {
            alert("Ошибка подтверждения: " + e.message);
        }
        return;
    }

    // -----------------------------------------------------------------
    // СЦЕНАРИЙ 3: ДЕЙСТВИЕ ОРГАНИЗАТОРА (Выбор: бесплатный чек-ин или Ватты)
    // -----------------------------------------------------------------
    if (isPrivilegedOrganizer) {
        const manualConfirm = confirm(
            `Вы организатор гонки «${raceTitle}».\n\n` +
            `• Нажмите «OK», чтобы подтвердить оплату БЕСПЛАТНО (ручной чек-ин наличных на месте).\n` +
            `• Нажмите «Отмена», чтобы оплатить слот за ${targetName} со своего счёта Драфт (${raceCost} Ватт).`
        );

        if (manualConfirm) {
            try {
                await pb.collection('race_rosters').update(recordId, { is_paid: true }, { requestKey: null });
                await syncUiState(true);
            } catch (e) {
                alert("Ошибка подтверждения: " + e.message);
            }
            return;
        }
    }

    // -----------------------------------------------------------------
    // СЦЕНАРИЙ 4: СПИСАНИЕ ВАТТ СО СЧЁТА ДРАФТ (Любой атлет за любого атлета)
    // -----------------------------------------------------------------
    const confirmBuy = confirm(
        `Оплатить участие за ${targetName}?\n\n` +
        `Гонка: «${raceTitle}»\n` +
        `С вашего счёта Драфт будет списано: ${raceCost} Ватт.`
    );
    if (!confirmBuy) return;

    try {
        // ✅ Добавили [RACE_FEE], race_id и roster_id
        const payResponse = await pb.send('/api/draft/pay', {
            method: 'POST',
            body: {
                amount: raceCost,
                purpose: `[RACE_FEE] Взнос за ${targetName}: ${raceTitle}`,
                race_id: targetRaceId,
                roster_id: recordId
            }
        });

        if (payResponse && payResponse.success) {
            await pb.collection('race_rosters').update(recordId, { is_paid: true }, { requestKey: null });

            alert(`💳 Успешно! Списано ${raceCost} Ватт за ${targetName}. Участие подтверждено!`);
            await syncUiState(true);

            if (typeof appRef?.loadDraftWallet === 'function') appRef.loadDraftWallet(true);
            if (typeof appRef?.loadDraftHistory === 'function') appRef.loadDraftHistory();
        }
    } catch (err) {
        console.error("Ошибка при оплате слота:", err);
        const errMsg = err.data?.message || err.message || "";
        const errCode = err.data?.error || "";

        if (errCode === "INSUFFICIENT_FUNDS" || errMsg.includes("Недостаточно Ватт") || errMsg.includes("недостаточно")) {
            if (confirm(`❌ На вашем балансе недостаточно Ватт (стоимость слота: ${raceCost} W).\n\nПополнить баланс через Т-Банк прямо сейчас?`)) {
                if (typeof appRef?.promptTopup === 'function') {
                    appRef.promptTopup();
                }
            }
        } else {
            alert("Ошибка проведения оплаты: " + (errMsg || "Сбой связи с платёжным шлюзом"));
        }
    }
}
	async updateStartTime(recordId, newTime, inputEl) {
        if (!recordId) return;
        if (inputEl) inputEl.style.backgroundColor = 'var(--success-light)';
        try {
            let formattedTime = newTime.trim();
            if (formattedTime.length === 5 && formattedTime.includes(':')) {
                formattedTime += ':00';
            }
            
            // Находим целевого гонщика в ростерах
            const curRider = (this.liveService?.currentLiveStartList || []).find(r => r.recordId === recordId || r.id === recordId)
                          || (this.raceRosterList || []).find(r => r.recordId === recordId || r.id === recordId);
            
            const squadId = curRider?.squad_id;

            // 🔥 ЕСЛИ УЧАСТНИК В ЭКИПАЖЕ — СИНХРОНИЗИРУЕМ ВСЕХ НАПАРНИКОВ
            if (squadId) {
                const targetList = this.liveService?.currentLiveStartList || this.raceRosterList || [];
                const squadMembers = targetList.filter(r => r.squad_id === squadId && (r.recordId || r.id));

                // Обновляем всех участников связки в базе PocketBase
                await Promise.all(squadMembers.map(m => {
                    const targetRecId = m.recordId || m.id;
                    return pb.collection('race_rosters').update(targetRecId, { planned_start: formattedTime }, { requestKey: null });
                }));

                // Синхронизируем время в CRM
                (this.raceRosterList || []).forEach(r => {
                    if (r.squad_id === squadId) r.plannedStart = formattedTime;
                });

                // Синхронизируем время в открытом табло LiveBoard
                if (this.liveService && Array.isArray(this.liveService.currentLiveStartList)) {
                    this.liveService.currentLiveStartList.forEach(r => {
                        if (r.squad_id === squadId) r.plannedStart = formattedTime;
                    });
                }
            } else {
                // Одиночный участник
                await pb.collection('race_rosters').update(recordId, { planned_start: formattedTime }, { requestKey: null });
                
                let p = (this.raceRosterList || []).find(r => r.recordId === recordId || r.id === recordId);
                if (p) p.plannedStart = formattedTime;

                if (this.liveService && Array.isArray(this.liveService.currentLiveStartList)) {
                    let lp = this.liveService.currentLiveStartList.find(r => r.recordId === recordId || r.id === recordId);
                    if (lp) lp.plannedStart = formattedTime;
                }
            }
            
            if (inputEl) inputEl.value = formattedTime;
            
            setTimeout(() => { 
                if (inputEl) inputEl.style.backgroundColor = ''; 
                if (typeof this.renderFilteredRaceRosterTable === 'function') {
                    this.renderFilteredRaceRosterTable();
                }
                // Мгновенная перерисовка табло со всеми напарниками
                if (this.liveService && typeof this.liveService.renderLiveBoard === 'function') {
                    this.liveService.renderLiveBoard();
                }
            }, 300);
            
        } catch(e) { 
            console.error("Ошибка сохранения времени старта:", e);
            if (inputEl) inputEl.style.backgroundColor = 'var(--danger-light)'; 
            alert("Ошибка сохранения времени старта"); 
        }
    }

async updateCategory(recordId, newCat, inputEl) {
        if (!recordId) return;
        if (inputEl) inputEl.style.backgroundColor = 'var(--success-light)';
        
        try {
            // 🎯 1. Сохраняем категорию ЦЕЛИКОМ (НЕ срезаем [М] / [Ж], чтобы не ломать зачёт по полу в пульте)
            let formattedCat = (newCat || '').trim();
            if (!formattedCat) return;
            
            // 2. Сохраняем отредактированную категорию в базу данных
            await pb.collection('race_rosters').update(recordId, { final_cluster: formattedCat }, { requestKey: null });
            
            // 3. Обновляем локальный кэш таблицы CRM
            let p = this.raceRosterList?.find(r => (r.recordId || r.id) === recordId);
            if (p) {
                p.group = formattedCat;
                p.computedCat = formattedCat;
                p.final_cluster = formattedCat;
            }

            // 4. Синхронизируем с открытым Live-бордом хронометража
            if (this.liveService?.currentLiveStartList) {
                let lp = this.liveService.currentLiveStartList.find(r => (r.recordId || r.id) === recordId);
                if (lp) {
                    lp.group = formattedCat;
                    lp.computedCat = formattedCat;
                    lp.final_cluster = formattedCat;
                }
            }
            
            // 5. Мягко снимаем подсветку и перерисовываем таблицы
            setTimeout(() => { 
                if (inputEl) inputEl.style.backgroundColor = ''; 
                if (typeof this.renderFilteredRaceRosterTable === 'function') {
                    this.renderFilteredRaceRosterTable();
                }
                if (this.liveService && typeof this.liveService.renderLiveBoard === 'function') {
                    this.liveService.renderLiveBoard();
                }
            }, 400);
            
        } catch(e) { 
            console.error("Ошибка сохранения категории:", e);
            if (inputEl) inputEl.style.backgroundColor = 'var(--danger-light)'; 
            alert("Ошибка сохранения категории: " + e.message); 
        }
    }
    // ==========================================
    // 🔥 ОДИНОЧНАЯ ЗАЯВКА ИЗ ТАБЛИЦЫ РОСТЕРА (БЕЗ ПЕРЕЗАГРУЗКИ)
    // ==========================================
async registerSingleRider(riderId, btn, event, targetRaceId = null, gear = null) {
        if (event) event.stopPropagation();
        
        if (this.app.currentRider && this.app.currentRider.email && this.app.currentRider.email.startsWith('guest_')) {
            alert('Регистрация на гонку доступна только авторизованным спортсменам. Пожалуйста, войдите в свой аккаунт Сотка.');
            return; 
        }

        // 1. Получаем список всех заездов/дистанций текущего события
        const eventRaces = (this.liveService?.currentEventRaces && this.liveService.currentEventRaces.length > 0)
            ? this.liveService.currentEventRaces
            : (typeof this.app?.getSisterRaces === 'function' && this.openedEventId ? this.app.getSisterRaces(this.openedEventId) : []);

        // 2. Если заездов несколько и конкретный заезд ещё не выбран:
        if (!targetRaceId && eventRaces.length > 1) {
            const activeFilter = this.liveService?.liveDistanceFilter;

            // Если открыта конкретная вкладка дистанции (например, «30 КМ») — заявляем именно в неё
            if (activeFilter && activeFilter !== 'all') {
                const matched = eventRaces.find(r => r.distance == activeFilter || r.id === activeFilter);
                if (matched) targetRaceId = matched.id;
            }

            // Если активен просмотр «ВСЕ ДИСТАНЦИИ» — открываем окно выбора заезда
            if (!targetRaceId) {
                this.openAssignDistanceModal(riderId, eventRaces, btn);
                return;
            }
        }

        const finalRaceId = targetRaceId || this.openedEventId || this.liveService?.expandedRaceId;
        let currentRace = (this.dataCalendar ? this.dataCalendar.find(r => r.id === finalRaceId) : null)
                       || (this.app.racesMap ? this.app.racesMap[finalRaceId] : null)
                       || (eventRaces.find(r => r.id === finalRaceId));

        if (currentRace && currentRace.level === 'peloton') {
            const targetRider = (this.raceRosterList ? this.raceRosterList.find(r => r.id === riderId) : null)
                             || (this.app.ridersMap ? this.app.ridersMap[riderId] : null);
            if (targetRider && (targetRider.group === 'O' || targetRider.base_cluster === 'O')) {
                alert(`❌ Официальные гонки недоступны для любителей (Кластер O).`);
                return;
            }
        }

        const oldText = btn?.innerText || '';
        if (btn) {
            btn.innerText = '⌛...';
            btn.disabled = true;
            btn.style.opacity = '0.7';
        }

        try { 
            const targetRider = (this.raceRosterList ? this.raceRosterList.find(r => r.id === riderId) : null)
                             || (this.app?.ridersMap ? this.app.ridersMap[riderId] : null);

            let calculatedCategory = gear || "";
            if (currentRace && typeof this.getRaceCategory === 'function' && targetRider) {
                try {
                    calculatedCategory = this.getRaceCategory({
                        gender: targetRider.gender || 'M',
                        yob: targetRider.yob || targetRider.year || 1990,
                        base_cluster: targetRider.base_cluster || targetRider.group || 'B',
                        id: targetRider.id,
                        gear: gear
                    }, currentRace);
                } catch(e) {}
            }

            const finalCat = calculatedCategory || gear || targetRider?.base_cluster || "B";

            // ⏱️ РАЗДЕЛЕНИЕ: Только для группового старта (mass, crit). Для разделок (ITT, TTT, Relay, DTT) — строго пусто!
            const isTimeTrial = currentRace?.format === 'itt' || currentRace?.format === 'ttt' || currentRace?.format === 'relay' || (currentRace?.name || '').toUpperCase().includes('DTT');
            let autoPlannedStart = "";
            if (!isTimeTrial && (currentRace?.date || currentRace?.rawDate)) {
                const rDate = new Date(currentRace.date || currentRace.rawDate);
                if (!isNaN(rDate.getTime())) {
                    const hh = String(rDate.getHours()).padStart(2, '0');
                    const mm = String(rDate.getMinutes()).padStart(2, '0');
                    const ss = String(rDate.getSeconds()).padStart(2, '0');
                    autoPlannedStart = `${hh}:${mm}:${ss}`;
                }
            }

            const newRecord = await pb.collection('race_rosters').create({ 
                race_id: finalRaceId, 
                rider_id: riderId, 
                status: 'registered',
                is_paid: false,
                planned_start: autoPlannedStart,
                final_cluster: finalCat
            }, { requestKey: null });
            
            // 🎯 1. Обновляем статус, категорию и время старта в списке CRM
            let p = this.raceRosterList?.find(r => r.id === riderId);
            if (p) {
                p.isRegistered = true;
                p.recordId = newRecord.id;
                p.race_id = finalRaceId;
                p.is_paid = false;
                p.plannedStart = autoPlannedStart;
                p.group = finalCat;
                p.computedCat = finalCat;
                p.final_cluster = finalCat;
            }

            // 🎯 2. Обновляем статус, категорию и время старта в открытом табло LiveBoard
            if (this.liveService && Array.isArray(this.liveService.currentLiveStartList)) {
                let lp = this.liveService.currentLiveStartList.find(r => r.id === riderId);
                if (lp) {
                    lp.isRegistered = true;
                    lp.recordId = newRecord.id;
                    lp.race_id = finalRaceId;
                    lp.is_paid = false;
                    lp.plannedStart = autoPlannedStart;
                    lp.group = finalCat;
                    lp.computedCat = finalCat;
                    lp.final_cluster = finalCat;
                    const assignedRace = eventRaces.find(r => r.id === finalRaceId);
                    if (assignedRace) {
                        lp.distance = assignedRace.distance;
                        lp.distance_tag = assignedRace.name?.includes('[') 
                            ? assignedRace.name.split('[')[1].replace(']', '').trim() 
                            : `${assignedRace.distance} КМ`;
                    }
                }
            }

            // 🎯 3. Если заявляется текущий спортсмен — обновляем личный кэш заявок
            if (riderId === this.app.currentRider?.id) {
                if (!this.app.myRosters) this.app.myRosters = {};
                this.app.myRosters[finalRaceId] = newRecord;
            }

            // 🎯 4. Возвращаем кнопку в активное состояние
            if (btn) {
                btn.innerText = oldText;
                btn.disabled = false;
                btn.style.opacity = '1';
            }

            if (typeof this.renderFilteredRaceRosterTable === 'function') {
                this.renderFilteredRaceRosterTable();
            }
            if (this.liveService && typeof this.liveService.renderLiveBoard === 'function') {
                this.liveService.renderLiveBoard();
            }
            if (this.app && typeof this.app.syncRaceButtonsState === 'function') {
                this.app.syncRaceButtonsState();
            }
            
        } catch(e) { 
            console.error("Детали ошибки PB:", e);
            alert(`❌ Ошибка заявки: ${e.message}`); 
            if (btn) {
                btn.innerText = oldText;
                btn.disabled = false;
                btn.style.opacity = '1';
            }
        }
    }
	openAssignDistanceModal(riderId, racesList, triggerBtn) {
        // Вызываем обновленное красивое окно с типами велосипедов
        window.app.openDistanceSelectorModal(racesList, riderId);
    }
	
    async revokeRaceReg(recordId) { 
        if (!confirm("Отозвать заявку этого гонщика?")) return; 
        try { 
            await pb.collection('race_rosters').delete(recordId, { requestKey: null }); 
            
            // 1. Снимаем статус локально в списке CRM
            let p = this.raceRosterList.find(r => r.recordId === recordId);
            if (p) {
                p.isRegistered = false;
                p.recordId = null;
                p.bib = "";
                p.plannedStart = null;
            }

            // 2. Снимаем статус в списке LiveBoardService (если открыт старт-лист)
            if (this.liveService && Array.isArray(this.liveService.currentLiveStartList)) {
                let lp = this.liveService.currentLiveStartList.find(r => r.recordId === recordId);
                if (lp) {
                    lp.isRegistered = false;
                    lp.recordId = null;
                    lp.bib = "";
                    lp.plannedStart = null;
                }
            }

            // 3. Мгновенно перерисовываем таблицу CRM (если открыта вкладка CRM)
            if (typeof this.renderFilteredRaceRosterTable === 'function') {
                this.renderFilteredRaceRosterTable();
            }

            // 🔥 4. Мгновенно перерисовываем открытое табло старт-листа
            if (this.liveService && typeof this.liveService.renderLiveBoard === 'function') {
                this.liveService.renderLiveBoard();
            }

            // 🔥 5. Синхронизируем кнопки в чате (чтобы кнопка снова стала желтой "ЗАЯВИТЬСЯ")
            if (this.app && typeof this.app.syncRaceButtonsState === 'function') {
                this.app.syncRaceButtonsState();
            }
        } catch(e) { 
            console.error("Ошибка при отмене заявки:", e);
            alert("Ошибка при отмене"); 
        } 
    }
  async generateBibs() {
        if (!this.openedEventId) return;
        let sortedRiders = [...this.raceRosterList].filter(p => p.isRegistered);
        if (sortedRiders.length === 0) return alert("Нет подтвержденных заявок!");
        if (!confirm("Автоматически присвоить номера ВСЕМ заявленным гонщикам строго по ВРЕМЕНИ СТАРТА с объединением экипажей TTT?")) return;

        // 🔥 ПРЕДРАСЧЕТ ПОЛОВ ДЛЯ АВТОГЕНЕРАТОРА НОМЕРОВ
        const crmSquadGenders = {};
        sortedRiders.forEach(item => {
            if (item.squad_id) {
                if (!crmSquadGenders[item.squad_id]) crmSquadGenders[item.squad_id] = [];
                crmSquadGenders[item.squad_id].push(String(item.gender || 'M').toUpperCase().trim());
            }
        });

        // 🔥 ШАГ 1: Подготавливаем категории с защитой от перезаписи судейских правок
        const raceObj = (this.dataCalendar ? this.dataCalendar.find(r => r.id === this.openedEventId) : null)
                     || (this.app?.racesMap ? this.app.racesMap[this.openedEventId] : null);
        const isTeamRace = raceObj && (raceObj.format === 'ttt' || raceObj.format === 'relay' || (raceObj.squad_max > 1));

        sortedRiders.forEach(p => {
            const existingCat = p.final_cluster || p.computedCat || p.group;
            if (existingCat && (existingCat.includes('[') || existingCat.includes('•'))) {
                p.computedCat = existingCat;
            } else {
                p.computedCat = existingCat || 'B';
                if (raceObj && typeof this.getRaceCategory === 'function') {
                    try { 
                        p.computedCat = this.getRaceCategory({ 
                            gender: p.gender, 
                            yob: p.year || p.yob, 
                            base_cluster: p.base_cluster || p.group || 'B',
                            id: p.id,
                            squad_id: p.squad_id,
                            squad_genders: crmSquadGenders[p.squad_id] || []
                        }, raceObj); 
                    } catch(e) {}
                }
            }

            // Определяем индекс группы для сортировки при равном времени
            let orderIndex = this.localCategoryOrder ? this.localCategoryOrder[p.computedCat] : undefined;
            p.groupIndex = (orderIndex !== undefined && orderIndex !== null && orderIndex !== "") ? parseInt(orderIndex, 10) : 99999;
        });

        // 🔥 ШАГ 2: ГЛОБАЛЬНАЯ СОРТИРОВКА (Интегрирован замок для TTT)
        sortedRiders.sort((a, b) => {
            let timeA = a.plannedStart || "23:59:59";
            let timeB = b.plannedStart || "23:59:59";
            
            // 1. Сначала строго по времени! Кто раньше едет, у того меньше BIB
            if (timeA !== timeB) return timeA.localeCompare(timeB); 
            
            // 2. Группируем напарников по экипажу внутри одной минуты старта
            if (isTeamRace) {
                let squadA = a.squad_id || '';
                let squadB = b.squad_id || '';
                if (squadA !== squadB) {
                    if (!squadA) return 1;  
                    if (!squadB) return -1;
                    return squadA.localeCompare(squadB);
                }
            }
            
            // 3. Если время старта и экипаж совпадают (или оба соло) — смотрим на приоритет группы
            if (a.groupIndex !== b.groupIndex) return a.groupIndex - b.groupIndex;
            
            // 4. Если время и группа совпадают — по очкам (новички раньше)
            let ptsA = a.points || 0; 
            let ptsB = b.points || 0;
            if (ptsA !== ptsB) return ptsA - ptsB; 
            
            // 5. В самом конце — по алфавиту
            return (a.surname + a.name).localeCompare(b.surname + b.name);
        });

        // 🔥 ШАГ 3: Раздаем номера и сохраняем параллельно
        try {
            const squadBibMap = {}; // Карта выданных номеров для экипажей: { squad_id: "номер" }
            let bibCounter = 1;
            const updateTasks = [];

            for (let i = 0; i < sortedRiders.length; i++) {
                const rider = sortedRiders[i];
                let assignedBib = "";

                // Если гонщик едет в экипаже
                if (isTeamRace && rider.squad_id) {
                    if (!squadBibMap[rider.squad_id]) {
                        squadBibMap[rider.squad_id] = bibCounter.toString();
                        bibCounter++;
                    }
                    assignedBib = squadBibMap[rider.squad_id];
                } 
                // Если едет одиночка
                else {
                    assignedBib = bibCounter.toString();
                    bibCounter++;
                }

                rider.bib = assignedBib;

                if (rider.recordId) {
                    updateTasks.push(
                        pb.collection('race_rosters').update(rider.recordId, { bib: assignedBib }, { requestKey: null })
                    );
                }
            }

            // Быстрое параллельное сохранение всех номеров в PocketBase
            await Promise.all(updateTasks);

            // Локальная синхронизация с открытым Live-бордом
            if (this.liveService?.currentLiveStartList) {
                this.liveService.currentLiveStartList.forEach(lr => {
                    const matched = sortedRiders.find(sr => sr.id === lr.id || (sr.recordId && sr.recordId === lr.recordId));
                    if (matched) lr.bib = matched.bib;
                });
            }

            alert("✅ Стартовые номера успешно присвоены! Экипажи TTT получили одинаковые BIB.");
            
            // 🎯 Мгновенная перерисовка открытого Live-борда или таблицы CRM
            if (this.liveService && document.getElementById('liveBoardModal')?.style.display === 'flex') {
                await this.liveService.openLiveBoard(this.liveService.expandedRaceId || this.openedEventId);
            } else if (typeof this.renderFilteredRaceRosterTable === 'function') {
                this.renderFilteredRaceRosterTable();
            } else if (typeof this.openRaceRoster === 'function') {
                this.openRaceRoster(this.openedEventId, this.openedEventName, this.openedEventType);
            }
            
        } catch(e) { 
            console.error("Ошибка автоматического присвоения:", e);
            alert("❌ Ошибка при генерации номеров: " + (e.message || "Сетевой сбой")); 
        } 
    }
// ==========================================
    // ⏱️ ГЕНЕРАТОР ITT / DTT СТАРТОВ С УЧЁТОМ ОЧЕРЕДИ ГРУПП
    // ==========================================
    async generateITTStarts() {
        const raceObj = (this.dataCalendar ? this.dataCalendar.find(r => r.id === this.openedEventId) : null)
                     || (this.app?.racesMap ? this.app.racesMap[this.openedEventId] : null);

        const isTeamRace = raceObj && (raceObj.format === 'ttt' || raceObj.format === 'relay' || (raceObj.name || '').toUpperCase().includes('DTT'));

        // 1. Запрашиваем время первого старта
        const startTimeInput = prompt("Введите время старта ПЕРВОЙ категории (ЧЧ:ММ или ЧЧ:ММ:СС):", "11:01:00");
        if (!startTimeInput) return;

        let parts = startTimeInput.trim().split(':').map(Number);
        if (parts.some(isNaN) || parts.length < 2) {
            return alert("❌ Неверный формат времени. Введите в формате 10:00 или 10:00:00");
        }
        let startHours = parts[0];
        let startMinutes = parts[1];
        let startSeconds = parts[2] || 0;

        // 2. Запрашиваем интервал между стартами
        const defaultInterval = isTeamRace ? "120" : "60";
        const intervalInput = prompt(
            isTeamRace 
                ? "Интервал между стартами ЭКИПАЖЕЙ в секундах (например, 60 или 120):" 
                : "Интервал между стартами участников в секундах (например, 30 или 60):", 
            defaultInterval
        );
        if (!intervalInput) return;

        const intervalSec = parseInt(intervalInput, 10);
        if (isNaN(intervalSec) || intervalSec <= 0) {
            return alert("❌ Интервал должен быть положительным числом секунд.");
        }

        // 3. Получаем зарегистрированных участников
        let targetList = (this.liveService?.currentLiveStartList || this.raceRosterList || []).filter(r => r.isRegistered);
        if (targetList.length === 0) {
            return alert("❌ В старт-листе нет зарегистрированных участников.");
        }

        // 4. Считываем сохраненный порядок категорий (ОЧЕРЕДЬ: 1, 2, 3...)
        let localCatOrder = this.localCategoryOrder || {};
        if (raceObj?.category_order) {
            let parsed = typeof raceObj.category_order === 'string' ? JSON.parse(raceObj.category_order) : raceObj.category_order;
            if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
                localCatOrder = { ...localCatOrder, ...parsed };
            }
        }

        // Предрасчет состава экипажей для точной категории
        const crmSquadGenders = {};
        targetList.forEach(item => {
            if (item.isRegistered && item.squad_id) {
                if (!crmSquadGenders[item.squad_id]) crmSquadGenders[item.squad_id] = [];
                crmSquadGenders[item.squad_id].push(String(item.gender || 'M').toUpperCase().trim());
            }
        });

        // Присваиваем каждому участнику категорию гонки (ЖЕНЩИНЫ / МИКСТ / МУЖЧИНЫ)
        targetList.forEach(p => {
            if (typeof this.getRaceCategory === 'function' && raceObj) {
                try {
                    p.computedCat = this.getRaceCategory({
                        gender: p.gender,
                        yob: p.year || p.yob,
                        base_cluster: p.group,
                        id: p.id,
                        squad_id: p.squad_id,
                        squad_genders: crmSquadGenders[p.squad_id] || []
                    }, raceObj);
                } catch(e) {
                    p.computedCat = p.group || 'B';
                }
            } else {
                p.computedCat = p.computedCat || p.group || 'B';
            }
        });

        const getCategoryRank = (catName) => {
            if (!catName) return 99999;
            const clean = String(catName).trim();
            if (localCatOrder[clean] !== undefined && localCatOrder[clean] !== null && localCatOrder[clean] !== "") {
                return parseInt(localCatOrder[clean], 10);
            }
            for (let key in localCatOrder) {
                if (clean.includes(key) || key.includes(clean)) {
                    return parseInt(localCatOrder[key], 10);
                }
            }
            if (typeof this.getCatRank === 'function') {
                return 1000 + this.getCatRank(clean);
            }
            return 99999;
        };

        // 5. Объединяем участников в стартовые слоты (напарники экипажа идут строго вместе)
        let slots = [];
        let squadSlotMap = {};

        targetList.forEach(rider => {
            const sId = rider.squad_id;
            if (sId) {
                if (squadSlotMap[sId] !== undefined) {
                    slots[squadSlotMap[sId]].riders.push(rider);
                } else {
                    squadSlotMap[sId] = slots.length;
                    slots.push({
                        isSquad: true,
                        squadId: sId,
                        category: rider.computedCat || rider.group || 'B',
                        riders: [rider]
                    });
                }
            } else {
                slots.push({
                    isSquad: false,
                    squadId: null,
                    category: rider.computedCat || rider.group || 'B',
                    riders: [rider]
                });
            }
        });

        // 6. 🔥 СТРОГАЯ СОРТИРОВКА: СНАЧАЛА ОЧЕРЕДЬ ГРУПП (1 -> 2 -> 3), ВНУТРИ — ПО РЕЙТИНГУ/BIB
        slots.sort((slotA, slotB) => {
            // 1. Очередь категорий (1: Женщины -> 2: Микст -> 3: Мужчины)
            let orderA = getCategoryRank(slotA.category);
            let orderB = getCategoryRank(slotB.category);
            if (orderA !== orderB) return orderA - orderB;

            // 2. Внутри одной группы — если уже есть номера BIB, сортируем по ним
            let bibsA = slotA.riders.map(r => parseInt(r.bib, 10)).filter(n => !isNaN(n) && n > 0);
            let bibsB = slotB.riders.map(r => parseInt(r.bib, 10)).filter(n => !isNaN(n) && n > 0);
            let bibA = bibsA.length ? Math.min(...bibsA) : 999999;
            let bibB = bibsB.length ? Math.min(...bibsB) : 999999;

            if (bibA !== 999999 && bibB !== 999999 && bibA !== bibB) {
                return bibA - bibB;
            }

            // 3. Внутри группы — от меньшего рейтинга к лидерам
            let ptsA = slotA.riders.reduce((acc, r) => acc + (Number(r.points) || 0), 0) / slotA.riders.length;
            let ptsB = slotB.riders.reduce((acc, r) => acc + (Number(r.points) || 0), 0) / slotB.riders.length;
            if (ptsA !== ptsB) return ptsA - ptsB;

            let nameA = slotA.riders[0]?.surname || slotA.riders[0]?.name || '';
            let nameB = slotB.riders[0]?.surname || slotB.riders[0]?.name || '';
            return nameA.localeCompare(nameB);
        });

        // 7. Присваиваем время старта последовательно
        let currentTotalSec = startHours * 3600 + startMinutes * 60 + startSeconds;
        const updatePromises = [];

        slots.forEach(slot => {
            let h = Math.floor(currentTotalSec / 3600) % 24;
            let m = Math.floor((currentTotalSec % 3600) / 60);
            let s = currentTotalSec % 60;

            let timeStr = `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;

            slot.riders.forEach(rider => {
                rider.plannedStart = timeStr;
                const recId = rider.recordId || rider.roster_id;
if (recId) {
    updatePromises.push(
        pb.collection('race_rosters').update(recId, { planned_start: timeStr }, { requestKey: null })
    );
}
            });

            currentTotalSec += intervalSec;
        });

        try {
            await Promise.all(updatePromises);

            if (this.liveService) {
                this.liveService.currentLiveStartList = targetList;
                if (typeof this.liveService.renderLiveBoard === 'function') {
                    this.liveService.renderLiveBoard();
                }
            }
            if (typeof this.renderFilteredRaceRosterTable === 'function') {
                this.renderFilteredRaceRosterTable();
            }

            alert(`✅ Время успешно распределено строго по порядку категорий (1 ➔ 2 ➔ 3)!`);
        } catch(err) {
            console.error("Ошибка генерации ITT-стартов:", err);
            alert("❌ Ошибка сохранения времени: " + err.message);
        }
    }	
async openWaveStartModal() {
    // 1. Берём актуальный список участников из LiveBoard или CRM
    const sourceList = this.liveService?.currentLiveStartList?.length 
        ? this.liveService.currentLiveStartList 
        : (this.raceRosterList || []);
    let riders = [...sourceList].filter(p => p.isRegistered);
    if (riders.length === 0) return alert("В заявке нет участников!");

    const btn = document.activeElement;
    let originalText = "";
    if (btn && btn.tagName === 'BUTTON') {
        originalText = btn.innerText;
        btn.innerText = "ЗАГРУЗКА...";
        btn.disabled = true;
    }

    try {
        let raceObj = null;
        try { 
            raceObj = await pb.collection('races').getOne(this.openedEventId, { requestKey: null }); 
        } catch (err) {}

        const distancesMap = {};
        const sisterRaces = typeof this.app?.getSisterRaces === 'function' && raceObj
            ? this.app.getSisterRaces(raceObj)
            : (this.liveService?.currentEventRaces || (raceObj ? [raceObj] : []));

        sisterRaces.forEach(sr => {
            const tag = sr.name.includes('[') 
                ? sr.name.split('[')[1].replace(']', '').trim() 
                : (sr.distance ? `${sr.distance} КМ` : sr.name);
            distancesMap[sr.id] = tag;
        });

        const crmSquadGenders = {};
        riders.forEach(item => {
            if (item.squad_id) {
                if (!crmSquadGenders[item.squad_id]) crmSquadGenders[item.squad_id] = [];
                crmSquadGenders[item.squad_id].push(String(item.gender || 'M').toUpperCase().trim());
            }
        });

        const catCalculator = (typeof this.getRaceCategory === 'function') ? this.getRaceCategory.bind(this) : 
                              (window.app && typeof window.app.getRaceCategory === 'function' ? window.app.getRaceCategory.bind(window.app) : null);

        riders.forEach(r => {
            r.tempCat = r.computedCat;
            if (!r.tempCat) {
                r.tempCat = r.group || 'B';
                if (raceObj && catCalculator) {
                    try { 
                        r.tempCat = catCalculator({ 
                            gender: r.gender, 
                            yob: r.year, 
                            base_cluster: r.group,
                            id: r.id,
                            squad_id: r.squad_id,
                            squad_genders: crmSquadGenders[r.squad_id] || [],
                            distance_id: r.distance_id || r.race_id || null
                        }, raceObj); 
                    } catch (e) {}
                }
            }
        });

        let groupedByDistance = {};
        const orderMap = this.localCategoryOrder || {};

        riders.forEach(r => {
            const distId = r.distance_id || r.race_id || 'main';
            const distName = distancesMap[distId] 
                          || r.distance_tag 
                          || (r.distance ? `${r.distance} КМ` : '') 
                          || r.race_name 
                          || (raceObj?.name || 'Основной старт');

            if (!groupedByDistance[distId]) {
                groupedByDistance[distId] = {
                    name: distName,
                    waves: {}
                };
            }

            let orderIndex = orderMap[`${distId}_${r.tempCat}`] !== undefined ? orderMap[`${distId}_${r.tempCat}`] : orderMap[r.tempCat];
            let groupKey;

            if (orderIndex !== undefined && orderIndex !== null && orderIndex !== "") {
                groupKey = `wave_${orderIndex}`;
            } else {
                groupKey = `cat_${r.tempCat}`;
            }

            // 2. Подтягиваем присвоенное время из полей plannedStart / planned_start
            const riderTime = r.plannedStart || r.planned_start || '';

            if (!groupedByDistance[distId].waves[groupKey]) {
                groupedByDistance[distId].waves[groupKey] = {
                    cats: new Set(),
                    count: 0,
                    sampleTime: riderTime, // Сохраняем время первого участника волны
                    isMerged: orderIndex !== undefined && orderIndex !== null && orderIndex !== "",
                    index: orderIndex !== undefined && orderIndex !== null && orderIndex !== "" ? parseInt(orderIndex) : 99999
                };
            } else if (!groupedByDistance[distId].waves[groupKey].sampleTime && riderTime) {
                groupedByDistance[distId].waves[groupKey].sampleTime = riderTime;
            }

            groupedByDistance[distId].waves[groupKey].cats.add(r.tempCat);
            groupedByDistance[distId].waves[groupKey].count++;
        });

        let container = document.getElementById('waveStartGroups'); 
        container.innerHTML = '';

        Object.entries(groupedByDistance).forEach(([distId, distData]) => {
            let distHeaderHtml = `
                <div style="background: var(--bg-surface); padding: 10px 14px; border-radius: 8px; margin: 16px 0 8px 0; border-left: 4px solid var(--primary); display: flex; justify-content: space-between; align-items: center;">
                    <div style="font-weight: 800; font-family: 'Unbounded'; font-size: 13px; color: var(--text-main);">
                        🏁 ${distData.name.toUpperCase()}
                    </div>
                    <button type="button" class="btn-quick-fill" data-dist="${distId}" style="background: transparent; border: 1px dashed var(--border); color: var(--primary); font-size: 10px; padding: 4px 8px; border-radius: 4px; cursor: pointer;">
                        Заполнить все одинаково
                    </button>
                </div>
            `;
            container.insertAdjacentHTML('beforeend', distHeaderHtml);

            let sortedKeys = Object.keys(distData.waves).sort((a, b) => {
                let gwA = distData.waves[a];
                let gwB = distData.waves[b];
                if (gwA.index !== gwB.index) return gwA.index - gwB.index;
                return Array.from(gwA.cats)[0].localeCompare(Array.from(gwB.cats)[0]);
            });

            sortedKeys.forEach(key => {
                const g = distData.waves[key];
                const catsArray = Array.from(g.cats).sort(); 
                const groupName = catsArray.join(' <span style="color:var(--text-muted);">+</span> ');
                const badge = g.isMerged ? `<span style="background:rgba(255,51,102,0.1); color:var(--danger); padding:2px 6px; border-radius:4px; font-size:9px; margin-right:6px; font-weight:800;">ВОЛНА ${g.index}</span>` : '';
                const color = g.isMerged ? 'var(--text-main)' : 'var(--primary)';
                const encodedCats = encodeURIComponent(JSON.stringify(catsArray));

                // 3. Подставляем реальное значение в value="${...}"
                const assignedValue = g.sampleTime || '';

                container.insertAdjacentHTML('beforeend', `
                    <div style="display: flex; justify-content: space-between; align-items: center; background: var(--bg-surface-hover); border: 1px solid var(--border); border-radius: 12px; padding: 10px 16px; margin-bottom: 6px;">
                        <div style="display: flex; flex-direction: column; gap: 4px; text-align: left;">
                            <div style="font-size: 13px; font-weight: 800; font-family: 'Unbounded'; color: var(--text-main); white-space: normal; line-height: 1.4;">
                                ${badge}<span style="color:${color};">${groupName}</span>
                            </div>
                            <div style="font-size: 11px; color: var(--text-muted); font-family: 'Manrope', sans-serif;">
                                Участников: ${g.count}
                            </div>
                        </div>
                        <input type="text" 
                               id="wave-time-${distId}-${key}" 
                               data-dist-id="${distId}" 
                               data-cats="${encodedCats}" 
                               class="auth-input wave-dist-input-${distId}" 
                               style="width: 100px; margin: 0; background: var(--bg-body); border: 1px solid var(--border); color: var(--text-main); border-radius: 8px; padding: 8px 12px; font-family: 'Roboto Mono', monospace; font-size: 13px; text-align: center; font-weight: bold; outline: none; flex-shrink: 0;" 
                               value="${assignedValue}"
                               placeholder="10:00:00">
                    </div>
                `);
            });
        });

        // 4. Кнопка «Заполнить все одинаково» берет уже установленное время (12:00:00), а не 10:00:00
        container.querySelectorAll('.btn-quick-fill').forEach(btn => {
            btn.onclick = () => {
                const dId = btn.getAttribute('data-dist');
                const inputs = container.querySelectorAll(`.wave-dist-input-${dId}`);
                let firstVal = "";
                for (const inp of inputs) {
                    if (inp.value && inp.value.trim()) {
                        firstVal = inp.value.trim();
                        break;
                    }
                }
                if (!firstVal) firstVal = "10:00:00";
                const newVal = prompt("Укажите время старта для всей дистанции (ЧЧ:ММ:СС):", firstVal);
                if (newVal) inputs.forEach(inp => inp.value = newVal.trim());
            };
        });

        document.getElementById('waveStartModal').style.display = 'flex';
    } catch (err) {
        console.error(err);
        alert("Ошибка формирования волн");
    } finally {
        if (btn && btn.tagName === 'BUTTON') {
            btn.innerText = originalText;
            btn.disabled = false;
        }
    }
}
async applyWaveStarts() {
    const sourceList = this.liveService?.currentLiveStartList?.length 
        ? this.liveService.currentLiveStartList 
        : (this.raceRosterList || []);
    let riders = [...sourceList].filter(p => p.isRegistered);
    if (riders.length === 0) return alert("В заявке нет участников!");

    let timeAssignments = [];
    let hasTimes = false;

    const inputs = document.querySelectorAll('[id^="wave-time-"]');
    inputs.forEach(input => {
        let val = input.value.trim();
        if (val) {
            if (val.length === 5) val += ":00";
            
            const distId = input.getAttribute('data-dist-id') || 'main';
            let catsArr = [];
            try {
                catsArr = JSON.parse(decodeURIComponent(input.getAttribute('data-cats')));
            } catch(e) { 
                console.error("Ошибка чтения категорий", e); 
            }

            if (catsArr.length > 0) {
                timeAssignments.push({ distId: distId, cats: catsArr, time: val });
                hasTimes = true;
            }
        }
    });

    if (!hasTimes) return alert("Не указано ни одного времени!");

    const btn = document.getElementById('btn-save-waves') || document.activeElement; 
    let originalBtnText = "";
    if (btn && btn.tagName === 'BUTTON') {
        originalBtnText = btn.innerText;
        btn.disabled = true; 
        btn.innerText = "СОХРАНЕНИЕ...";
    }

    const crmSquadGenders = {};
    riders.forEach(item => {
        if (item.squad_id) {
            if (!crmSquadGenders[item.squad_id]) crmSquadGenders[item.squad_id] = [];
            crmSquadGenders[item.squad_id].push(String(item.gender || 'M').toUpperCase().trim());
        }
    });

    let raceObj = null;
    try { 
        raceObj = await pb.collection('races').getOne(this.openedEventId, { requestKey: null }); 
    } catch(e) {}

    const catCalculator = (typeof this.getRaceCategory === 'function') ? this.getRaceCategory.bind(this) : 
                          (window.app && typeof window.app.getRaceCategory === 'function' ? window.app.getRaceCategory.bind(window.app) : null);

    try {
        const updatePromises = [];

        for (let rider of riders) {
            const riderDistId = rider.distance_id || rider.race_id || 'main';

            let computedCat = rider.computedCat;
            if (!computedCat) {
                computedCat = rider.group || 'B';
                if (raceObj && catCalculator) {
                    try { 
                        computedCat = catCalculator({ 
                            gender: rider.gender, 
                            yob: rider.year, 
                            base_cluster: rider.group,
                            id: rider.id,
                            squad_id: rider.squad_id,
                            squad_genders: crmSquadGenders[rider.squad_id] || [],
                            distance_id: riderDistId
                        }, raceObj); 
                    } catch (e) {}
                }
            }

            let assignedTime = null;
            for (let assignment of timeAssignments) {
                const isMatchingDist = (assignment.distId === riderDistId) || 
                                       (assignment.distId === 'main' && !rider.distance_id && !rider.race_id);

                if (isMatchingDist && assignment.cats.includes(computedCat)) {
                    assignedTime = assignment.time;
                    break;
                }
            }

            if (assignedTime && rider.recordId) {
                rider.plannedStart = assignedTime;
                rider.planned_start = assignedTime;
                updatePromises.push(
                    pb.collection('race_rosters').update(rider.recordId, { planned_start: assignedTime }, { requestKey: null })
                );
            }
        }

        if (updatePromises.length > 0) {
            await Promise.all(updatePromises);
        }
        
        alert("✅ Волновые старты успешно сохранены с учетом дистанций!");
        const modal = document.getElementById('waveStartModal');
        if (modal) modal.style.display = 'none';
        
        if (this.liveService && document.getElementById('liveBoardModal')?.style.display === 'flex') {
            await this.liveService.openLiveBoard(this.liveService.expandedRaceId || this.openedEventId);
        } else if (typeof this.openRaceRoster === 'function') {
            this.openRaceRoster(this.openedEventId, this.openedEventName, this.openedEventType);
        }
    } catch(e) { 
        console.error("Ошибка сохранения волн:", e);
        alert("❌ Ошибка сохранения волн: " + (e.message || "Сбой соединения")); 
    } finally { 
        if (btn && btn.tagName === 'BUTTON') {
            btn.disabled = false; 
            btn.innerText = originalBtnText || "Назначить"; 
        }
    }
}
	// 🔥 РУЧНОЙ ЗАПУСК ГОНКИ В РЕЖИМ LIVE
    async startManualLiveRace(raceId) {
        if (!confirm("🚀 Внимание! Перевести гонку в режим LIVE и закрыть регистрацию?\n\nВ чат гонки будет отправлено системное оповещение.")) return;

        try {
            // Меняем статус гонки на LIVE
            await pb.collection('races').update(raceId, { status: 'LIVE' }, { requestKey: null });

            try {
                const raceChat = this.app.chats.find(c => c.race_id === raceId);
                const botRider = Object.values(this.app.ridersMap).find(r => r.email === 'bot@sotka.one');
                if (raceChat && botRider) {
                    await pb.collection('messages').create({
                        chat_id: raceChat.id,
                        sender_id: botRider.id,
                        text: `ГОНКА ЗАПУЩЕНА!\n\nСтартовый протокол зафиксирован. Участники уходят на дистанцию согласно расписанию.\n\n[ACTION:LIVE:${raceId}]`
                    }, { requestKey: null });
                }
            } catch(botErr) { console.error("Ошибка отправки ботом", botErr); }

            alert("✅ Гонка успешно переведена в статус LIVE!");
            this.openRaceRoster(this.openedEventId, this.openedEventName, this.openedEventType);
            
            // Обновляем чаты, чтобы красные кнопки синхронизировались
            if (this.app && typeof this.app.loadChats === 'function') {
                this.app.loadChats();
            }
        } catch(e) {
            console.error("Ошибка старта:", e);
            alert("❌ Ошибка при запуске гонки.");
        }
    }

async finalizeRaceProcess(raceId) {
        if (!confirm("⚠️ ВНИМАНИЕ: Это действие перенесет результаты из Лайв-борда в профили спортсменов, начислит очки и подведет итоги Драфта. Продолжить?")) return;

        if (typeof showVilkaSplash === 'function') showVilkaSplash(); 

        try {
            // 1. Получаем гонку и её лайв-борд
            const race = await pb.collection('races').getOne(raceId, { expand: 'rating_rule_id', requestKey: null });
            let liveBoard = race.live_board;

            if (typeof liveBoard === 'string') {
                try { liveBoard = JSON.parse(liveBoard); } catch(e) { liveBoard = []; }
            }

            if (!liveBoard || !Array.isArray(liveBoard) || liveBoard.length === 0) {
                throw new Error("Лайв-борд пуст. Данных для переноса нет.");
            }

            // Достаем правила начисления очков
            let pSys = {};
            if (race.expand?.rating_rule_id && race.expand.rating_rule_id.config) {
                let cfg = race.expand.rating_rule_id.config;
                pSys = typeof cfg === 'string' ? JSON.parse(cfg) : cfg;
            } else {
                pSys = this.app.DEFAULT_RATING_RULES || {
                    mass_start_banks: { 'A+': 1000, 'A': 800, 'B': 600, 'C': 400, 'D': 200, 'E': 200, 'O': 200, 'V': 400 },
                    decay_factor: 0.85
                };
            }

            const isMassStart = race.format === 'mass' || race.format === 'crit';
            const raceDistance = parseFloat(race.distance) || 0;
            const multiplier = pSys.multiplier !== undefined ? parseFloat(pSys.multiplier) : 1.0;
            const isPerformance = (!pSys.calc_type || pSys.calc_type === 'performance');

            // 2. Получаем все заявки на эту гонку
            const rosters = await pb.collection('race_rosters').getFullList({
                filter: `race_id="${raceId}"`, expand: 'rider_id', requestKey: null
            });

            let updatedCount = 0;
            let clusterPositions = {};

            // 3. Распаковываем результаты и переносим в базу
            for (let result of liveBoard) {
                let rosterEntry = rosters.find(r => r.bib && String(r.bib) === String(result.bib));
                
                if (!rosterEntry && result.name) {
                    rosterEntry = rosters.find(r => {
                        if (!r.expand?.rider_id) return false;
                        const dbName = `${r.expand.rider_id.last_name} ${r.expand.rider_id.first_name}`.trim().toLowerCase();
                        const dbNameRev = `${r.expand.rider_id.first_name} ${r.expand.rider_id.last_name}`.trim().toLowerCase();
                        const resName = result.name.trim().toLowerCase();
                        return dbName === resName || dbNameRev === resName;
                    });
                }

                if (rosterEntry) {
                    // Суммируем все круги
                    let lapsArr = result.lapTimes;
                    if (typeof lapsArr === 'string') {
                        try { lapsArr = JSON.parse(lapsArr); } catch(e) { lapsArr = []; }
                    }

                    let timeMs = 0;
                    if (Array.isArray(lapsArr) && lapsArr.length > 0) {
                        timeMs = lapsArr.reduce((sum, lap) => sum + (parseInt(lap) || 0), 0);
                    }
                    if (!timeMs && result.timeStr) {
                        timeMs = this.parseTimeToMs ? this.parseTimeToMs(result.timeStr) : 0;
                    }

                    const status = (result.timeStr === 'DNF' || result.timeStr === 'DSQ') ? 'dnf' : 'finished';
                    
                    // Автоматический расчет скорости, если она отсутствует
                    let speed = parseFloat(result.speed) || 0;
                    if (speed <= 0 && timeMs > 0 && raceDistance > 0 && status === 'finished') {
                        speed = parseFloat((raceDistance / (timeMs / 3600000)).toFixed(2));
                        result.speed = speed.toString();
                    }

                    const baseCluster = result.baseCluster || rosterEntry.expand?.rider_id?.base_cluster || 'B';
                    let points = parseInt(result.points) || 0;

                    // Если очков не было в JSON — считаем
                    if (status === 'finished' && points === 0) {
                        if (isMassStart) {
                            if (!clusterPositions[baseCluster]) clusterPositions[baseCluster] = 1;
                            const position = clusterPositions[baseCluster]++;

                            let customBanks = pSys.banks || pSys.mass_start_banks || pSys.cluster_banks || { 'A+': 1000, 'A': 800, 'B': 600, 'C': 400, 'D': 200, 'E': 200, 'O': 200, 'V': 400 };
                            let baseBank = customBanks[baseCluster] || customBanks['C'] || 400;
                            let decay = pSys.decay_factor !== undefined ? parseFloat(pSys.decay_factor) : 0.85;
                            
                            points = Math.max(1, Math.round(baseBank * Math.pow(decay, position - 1)));
                        } else {
                            if (isPerformance && speed > 0) {
                                points = Math.round(raceDistance * speed * multiplier);
                            }
                        }
                    }

                    result.points = points; 

                    // 🎯 Сохраняем категорию ЦЕЛИКОМ, не срезая префиксы пола [М] / [Ж]
                    const finalCategory = (result.category || rosterEntry.final_cluster || '').trim();
                    result.category = finalCategory;

                    // А) Обновляем заявку
                    await pb.collection('race_rosters').update(rosterEntry.id, {
                        status: status,
                        time_ms: timeMs,
                        laps: result.laps || (Array.isArray(lapsArr) && lapsArr.length > 0 ? lapsArr.length : 1),
                        earned_points: points,
                        final_cluster: finalCategory,
                        speed: speed
                    }, { requestKey: null });

                    // Б) Обновляем рейтинг гонщика
                    if (status === 'finished' && rosterEntry.expand?.rider_id) {
                        const rider = rosterEntry.expand.rider_id;
                        let updatePayload = { rating: (rider.rating || 0) + points };
                        
                        if (result.recCluster && result.recCluster !== '-') {
                            const clusterRanks = { 'O':0, 'E':1, 'D':2, 'C':3, 'B':4, 'A':5, 'A+':6, 'V':7 };
                            if (clusterRanks[result.recCluster] > (clusterRanks[rider.base_cluster] || 0)) {
                                updatePayload.base_cluster = result.recCluster;
                            }
                        }
                        
                        const surfKey = `rating_${race.surface || 'road'}`;
                        if (rider[surfKey] !== undefined) {
                            updatePayload[surfKey] = (rider[surfKey] || 0) + points;
                        }

                        await pb.collection('riders').update(rider.id, updatePayload, { requestKey: null });
                    }
                    updatedCount++;
                }
            }

            // Обновление рейтинга команд
            try {
                const teamIdsToUpdate = [...new Set(rosters.map(r => r.expand?.rider_id?.team_id).flat().filter(Boolean))];
                for (let tId of teamIdsToUpdate) {
                    const teamRiders = await pb.collection('riders').getFullList({ filter: `team_id ~ "${tId}"`, requestKey: null });
                    const teamTotal = teamRiders.reduce((sum, r) => sum + (r.rating || 0), 0);
                    await pb.collection('teams').update(tId, { points: teamTotal }, { requestKey: null });
                }
            } catch(e) { console.warn("Командные очки не обновлены:", e); }

            // Подведение итогов Драфта
            try {
                const draftConfigs = await pb.collection('draft_configs').getFullList({ filter: `race_id="${raceId}"`, requestKey: null });
                if (draftConfigs.length > 0) {
                    const draftRosters = await pb.collection('draft_rosters').getFullList({ filter: `race_id="${raceId}"`, requestKey: null });
                    const updatedRaceRosters = await pb.collection('race_rosters').getFullList({ filter: `race_id="${raceId}"`, requestKey: null });

                    for (const dr of draftRosters) {
                        const teamRiders = [dr.rider_1, dr.rider_2, dr.rider_3].filter(Boolean);
                        let totalLaps = 0; let totalTime = 0;

                        for (const tId of teamRiders) {
                            const rRes = updatedRaceRosters.find(x => x.rider_id === tId);
                            if (rRes) {
                                totalLaps += (rRes.laps || 0);
                                totalTime += (rRes.time_ms || 0);
                            }
                        }
                        await pb.collection('draft_rosters').update(dr.id, { laps_sum: totalLaps, time_sum: totalTime }, { requestKey: null });
                    }
                    
                    await pb.collection('draft_configs').update(draftConfigs[0].id, { is_active: false }, { requestKey: null });
                }
            } catch (draftErr) { console.warn("Драфт не обработан:", draftErr); }

            // Меняем статус гонки и сохраняем обновленный live_board с валидной скоростью и полной категорией
            await pb.collection('races').update(raceId, { status: 'Finished', live_board: liveBoard }, { requestKey: null });

            alert(`✅ Финализация завершена!\n\nПеренесено результатов: ${updatedCount}.\nОчки, зачетные группы и скорости сохранены корректно.`);
            window.location.reload(); 

        } catch (err) {
            console.error("Ошибка финализации:", err);
            alert("❌ Ошибка: " + err.message);
        } finally {
            if (typeof hideVilkaSplash === 'function') hideVilkaSplash();
        }
    }
// =========================================================================
    // 1. ХЕЛПЕР: СТАНДАРТНЫЙ РЕГЛАМЕНТ ДИСТАНЦИИ (ПО УМОЛЧАНИЮ ТОЛЬКО АБСОЛЮТ)
    // =========================================================================
    createDefaultDistanceScoring() {
        const curSurface = this.constructorState?.surface || 'road';
        const defaultGearsBySurface = {
            road: ['ROAD'],
            offroad: ['GRAVEL', 'MTB'],
            track: ['FIX'],
            indoor: ['ROAD']
        };

        return {
            hasAbsolute: true,
            hasPro: false,
            hasAge: false,
            agePreset: 'gf10',
            ageBands: null,
            hasClusters: false,
            useGear: false,
            activeGears: [...(defaultGearsBySurface[curSurface] || ['ROAD'])],
            customCategories: [],
            quorum: 3
        };
    }


parseDistanceScoring(catLogic, surface = 'road') {
        const sc = this.createDefaultDistanceScoring();
        if (surface) {
            const defaultGearsBySurface = {
                road: ['ROAD'],
                offroad: ['GRAVEL', 'MTB'],
                track: ['FIX'],
                indoor: ['ROAD']
            };
            sc.activeGears = [...(defaultGearsBySurface[surface] || ['ROAD'])];
        }

        if (!catLogic) return sc;

        try {
            const parsed = (typeof catLogic === 'string') ? JSON.parse(catLogic) : catLogic;
            if (parsed.has_absolute !== undefined) sc.hasAbsolute = Boolean(parsed.has_absolute);
            if (parsed.has_pro !== undefined) sc.hasPro = Boolean(parsed.has_pro);
            if (parsed.has_age !== undefined) sc.hasAge = Boolean(parsed.has_age);
            if (parsed.age_bands) sc.ageBands = parsed.age_bands;
            if (parsed.has_clusters !== undefined) sc.hasClusters = Boolean(parsed.has_clusters);
            if (parsed.has_team_genders !== undefined) sc.hasTeamGenders = Boolean(parsed.has_team_genders);
            if (parsed.has_team_age !== undefined) sc.hasTeamAge = Boolean(parsed.has_team_age);
            if (parsed.team_age_mode) sc.teamAgeMode = parsed.team_age_mode;
            if (parsed.use_gear !== undefined) sc.useGear = Boolean(parsed.use_gear);
            if (Array.isArray(parsed.active_gears) && parsed.active_gears.length > 0) {
                sc.activeGears = [...parsed.active_gears];
            }
            if (Array.isArray(parsed.custom_categories)) sc.customCategories = [...parsed.custom_categories];
            if (parsed.quorum) sc.quorum = parsed.quorum;

            if (parsed.model) {
                if (parsed.model === 'absolute') { sc.hasAbsolute = true; sc.hasAge = false; }
                if (parsed.model === 'pure_age') { sc.hasAge = true; sc.hasAbsolute = false; }
                if (parsed.model === 'sport_age') { sc.hasPro = true; sc.hasAge = true; }
                if (parsed.model === 'clusters') { sc.hasClusters = true; sc.hasAbsolute = false; }
            }
        } catch(e) {
            console.warn("Ошибка парсинга cat_logic:", e);
        }
        return sc;
    }

    // =========================================================================
    // 2. ИНИЦИАЛИЗАЦИЯ СОЗДАНИЯ СОБЫТИЯ
    // =========================================================================
async openCreateEventModal(dateStr = null, defaultEventType = null) {
        // 1. Надежная проверка на гостя
        const rider = this.app.currentRider;
        const isGuest = (typeof this.app.isUserGuest === 'function')
            ? this.app.isUserGuest()
            : (!pb.authStore.isValid || this.app.isGuest || !rider || rider.id === 'anonymous_guest' || (rider.email && (rider.email.startsWith('guest_') || rider.email.startsWith('guest@'))));

        if (isGuest) {
            this.showGuestAuthModal();
            return;
        }

        this.editEventId = null;

        const myRole = typeof this.getUserMaxRole === 'function' ? this.getUserMaxRole() : 'rider';
        const roles = (this.app.usersMap && this.app.currentRider?.email) ? (this.app.usersMap[this.app.currentRider.email] || []) : [];
        const rStr = JSON.stringify(roles);
        const isAdmin = rStr.includes('superadmin') || rStr.includes('admin');
        const isJudge = rStr.includes('judge');
        const amISuper = rStr.includes('superadmin');

        let defaultDate = new Date().toISOString().slice(0, 10);
        if (dateStr) {
            try {
                const d = new Date(dateStr);
                const offset = d.getTimezoneOffset() * 60000;
                defaultDate = (new Date(d - offset)).toISOString().slice(0, 10);
            } catch(e) {}
        }

        const myId = this.app.currentRider?.id;
        const myUserId = pb.authStore.model?.id;
        const myTeams = Array.isArray(this.app.currentRider?.team_id) ? this.app.currentRider.team_id : (this.app.currentRider?.team_id ? [this.app.currentRider.team_id] : []);
        
        let subPelotonIds = [];
        let rawSubs = this.app.currentRider?.subscriptions;
        if (typeof rawSubs === 'string' && rawSubs.trim()) {
            try { rawSubs = JSON.parse(rawSubs); } catch(e) {}
        }
        if (rawSubs && typeof rawSubs === 'object') {
            subPelotonIds = Array.isArray(rawSubs.pelotons) ? rawSubs.pelotons : [];
        }

        const myAdminPelotons = [];
        const mySubscribedPelotons = [];
        const otherPelotonsList = [];

        Object.values(this.app.pelotonsMap || {}).forEach(p => {
            const adminIds = (Array.isArray(p.admin_id) ? p.admin_id : [p.admin_id]).map(a => (typeof a === 'object' && a !== null) ? a.id : String(a).trim());
            const isMyAdmin = adminIds.includes(myId) || adminIds.includes(myUserId);
            const isTeamHome = myTeams.some(tId => {
                const t = this.app.teamsMap?.[tId];
                const pId = t && t.peloton_id ? (Array.isArray(t.peloton_id) ? t.peloton_id[0] : t.peloton_id) : null;
                return pId === p.id;
            });
            const isSubscribed = subPelotonIds.includes(p.id);

            if (isMyAdmin) {
                myAdminPelotons.push(p);
            } else if (isTeamHome || isSubscribed) {
                mySubscribedPelotons.push(p);
            } else if (!p.is_private || amISuper) {
                otherPelotonsList.push(p);
            }
        });

        const myPelotonsList = [...myAdminPelotons, ...mySubscribedPelotons];

        let primaryPelotonId = "";
        if (myAdminPelotons.length > 0) {
            primaryPelotonId = myAdminPelotons[0].id;
        } else if (myPelotonsList.length > 0) {
            primaryPelotonId = myPelotonsList[0].id;
        } else if (otherPelotonsList.length > 0) {
            primaryPelotonId = otherPelotonsList[0].id;
        }

        // 🔥 СТРОГОЕ ПРАВИЛО: гонка пелотона доступна по умолчанию ТОЛЬКО реальным админам пелотонов
        const isPelotonAdmin = amISuper || isAdmin || (myAdminPelotons && myAdminPelotons.length > 0);
        
        let initialEventType = 'personal';
        if (isPelotonAdmin) {
            const activeTabBtn = document.querySelector('.cal-tab-btn.active, .crm-tab.active, .tab-btn.active, .calendar-tab.active');
            const isTrainingsTab = (this.activeCalendarTab === 'trainings' || this.currentCalendarTab === 'trainings') 
                || (activeTabBtn && activeTabBtn.innerText && activeTabBtn.innerText.toUpperCase().includes('ТРЕНИРОВК'));

            if (!isTrainingsTab && (defaultEventType === 'peloton' || defaultEventType === 'races' || !defaultEventType)) {
                initialEventType = 'peloton';
            }
        }

        this.constructorState = {
            name: "",
            date: defaultDate,
			time: "11:00",
            eventType: initialEventType,
            isPublic: true,
            pelotonId: (initialEventType === 'peloton') ? primaryPelotonId : "",
            myPelotonsList: myPelotonsList,
            myAdminPelotons: myAdminPelotons,
            otherPelotonsList: otherPelotonsList,
            judgeId: "",
            judgesList: [],
            surface: 'road',
            format: 'mass',
            price: "",
            activeDistances: [
                { id: 'd_1', name: 'Основная', dist: "", laps: 1, time: "11:00", scoring: this.createDefaultDistanceScoring() }
            ],
            selectedDistIndex: 0
        };

        if (isAdmin || isJudge) {
            pb.collection('users').getFullList({ filter: 'role ~ "judge"', requestKey: null }).then(judges => {
                this.constructorState.judgesList = judges;
                const judgeSelect = document.getElementById('ncJudgeSelect');
                if (judgeSelect) {
                    let jHtml = '<option value="">-- Без назначения судьи --</option>';
                    judges.forEach(j => {
                        const jn = j.name || j.username || 'Судья';
                        const safe = (this.app && typeof this.app.escapeHTML === 'function') ? this.app.escapeHTML(jn) : jn;
                        jHtml += '<option value="' + j.id + '">' + safe + '</option>';
                    });
                    judgeSelect.innerHTML = jHtml;
                }
            }).catch(() => {});
        }

        this.renderNeoConstructorModal();
    }

showGuestAuthModal() {
        let modal = document.getElementById('guestAuthModal');
        if (!modal) {
            modal = document.createElement('div');
            modal.id = 'guestAuthModal';
            document.body.appendChild(modal);
        }
        modal.className = 'nc-modal-overlay';
        modal.style.setProperty('display', 'flex', 'important');

        modal.innerHTML = `
            <div class="nc-window" style="width:100% !important; max-width:380px !important; height:auto !important; max-height:none !important; text-align:center; padding:28px 24px; box-sizing:border-box;" onclick="event.stopPropagation()">
                <div style="display:flex; justify-content:center; margin-bottom:14px; color:var(--nc-text);">
                    <svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
                        <rect x="3" y="11" width="18" height="11" rx="2" ry="2"></rect>
                        <path d="M7 11V7a5 5 0 0 1 10 0v4"></path>
                    </svg>
                </div>
                <div style="font-family:Unbounded, sans-serif; font-size:13px; font-weight:900; letter-spacing:0.3px; text-transform:uppercase; margin-bottom:8px; color:var(--nc-text);">
                    ДОСТУП ОГРАНИЧЕН
                </div>
                <div style="font-size:11px; line-height:1.5; color:var(--nc-text-muted); margin-bottom:20px;">
                    Создание заездов и добавление событий в календарь доступно только зарегистрированным участникам.
                </div>
                <div style="display:flex; flex-direction:column; gap:8px;">
                    <button type="button" class="nc-pill-btn active" style="height:38px; width:100%; font-family:Unbounded, sans-serif; font-size:10px; font-weight:900;" onclick="document.getElementById('guestAuthModal').remove(); if(typeof window.app.openLoginScreen === 'function') window.app.openLoginScreen();">
                        ВОЙТИ В ПРОФИЛЬ
                    </button>
                    <button type="button" class="nc-pill-btn" style="height:36px; width:100%; font-size:10.5px;" onclick="document.getElementById('guestAuthModal').remove();">
                        ЗАКРЫТЬ
                    </button>
                </div>
            </div>
        `;

        modal.onclick = (e) => {
            if (e.target === modal) modal.remove();
        };
    }
    // =========================================================================
    // 3. ЗАКРЫТИЕ ОКНА КОНСТРУКТОРА
    // =========================================================================
    closeNeoConstructorModal() {
        const modal = document.getElementById('createEventModal');
        if (modal) {
            modal.classList.add('hidden');
            modal.style.setProperty('display', 'none', 'important');
        }
        this.editEventId = null;
    }

    // =========================================================================
    // 4. ВЁРСТКА МОДАЛЬНОГО ОКНА КОНСТРУКТОРА
    // =========================================================================
renderNeoConstructorModal() {
        let modal = document.getElementById('createEventModal');
        
        let prevScroll = 0;
        if (modal) {
            const pane = modal.querySelector('.nc-left-pane');
            if (pane) prevScroll = pane.scrollTop;
        }

        if (!modal) {
            modal = document.createElement('div');
            modal.id = 'createEventModal';
            document.body.appendChild(modal);
        }
        modal.className = 'nc-modal-overlay';
        modal.classList.remove('hidden');
        modal.style.setProperty('display', 'flex', 'important');

        modal.onclick = (e) => {
            if (e.target === modal) window.app.crm.closeNeoConstructorModal();
        };

        const s = this.constructorState;
        const isEdit = Boolean(this.editEventId);
        const isPeloton = (s.eventType === 'peloton');
        
        // 1. ПРОВЕРКА ПРАВ
        const myRiderId = this.app.currentRider?.id;
        const myUserId = pb.authStore.model?.id || this.app.currentRider?.user_id;
        const roles = (this.app.usersMap && this.app.currentRider?.email) ? (this.app.usersMap[this.app.currentRider.email] || []) : [];
        const rStr = JSON.stringify(roles);
        const isGlobalAdmin = rStr.includes('superadmin') || rStr.includes('admin');
        const isCreator = Boolean(s.isCreator || (s.creatorId && (s.creatorId === myRiderId || s.creatorId === myUserId)));

        const isLegitPelotonAdmin = (s.myAdminPelotons || []).some(ap => ap.id === s.pelotonId);
        const isPelotonAdmin = isPeloton && (isGlobalAdmin || isLegitPelotonAdmin);
        
        const hasFullAccess = isPelotonAdmin;
        const canOpenReg = !isPeloton || isPelotonAdmin;

        // 🎯 ОПРЕДЕЛЕНИЕ ЭФФЕКТИВНОГО ФОРМАТА И ПОКРЫТИЯ ДЛЯ АКТИВНОЙ ДИСТАНЦИИ
        const activeDist = s.activeDistances[s.selectedDistIndex] || s.activeDistances[0];
        if (!activeDist.scoring) activeDist.scoring = this.createDefaultDistanceScoring();
        const sc = activeDist.scoring;

        const effectiveFormat = (activeDist.customFormat && activeDist.format) ? activeDist.format : s.format;
        const effectiveSurface = (activeDist.customFormat && activeDist.surface) ? activeDist.surface : (s.surface || 'road');
        const isTeamFormat = hasFullAccess && (effectiveFormat === 'ttt');

        const safeActiveName = (this.app && typeof this.app.escapeHTML === 'function') ? this.app.escapeHTML(activeDist.name || '') : (activeDist.name || '');
        const safeRaceName = (this.app && typeof this.app.escapeHTML === 'function') ? this.app.escapeHTML(s.name || '') : (s.name || '');

        let pelotonOptionsHtml = '<option value="" disabled>-- Выберите лигу --</option>';
        if (s.myPelotonsList && s.myPelotonsList.length > 0) {
            pelotonOptionsHtml += '<optgroup label="МОИ ПЕЛОТОНЫ">';
            s.myPelotonsList.forEach(p => {
                const isAdminOfThis = (s.myAdminPelotons || []).some(ap => ap.id === p.id);
                const tag = isAdminOfThis ? ' [Админ]' : '';
                const pSafeName = (this.app && typeof this.app.escapeHTML === 'function') ? this.app.escapeHTML(p.name) : p.name;
                const isSel = (s.pelotonId === p.id) ? 'selected' : '';
                pelotonOptionsHtml += '<option value="' + p.id + '" ' + isSel + '>' + pSafeName + tag + '</option>';
            });
            pelotonOptionsHtml += '</optgroup>';
        }
        if (s.otherPelotonsList && s.otherPelotonsList.length > 0) {
            pelotonOptionsHtml += '<optgroup label="ОСТАЛЬНЫЕ ЛИГИ">';
            s.otherPelotonsList.forEach(p => {
                const pSafeName = (this.app && typeof this.app.escapeHTML === 'function') ? this.app.escapeHTML(p.name) : p.name;
                const isSel = (s.pelotonId === p.id) ? 'selected' : '';
                pelotonOptionsHtml += '<option value="' + p.id + '" ' + isSel + '>' + pSafeName + '</option>';
            });
            pelotonOptionsHtml += '</optgroup>';
        }

        let judgesHtml = '<option value="">-- Без назначения судьи --</option>';
        if (s.judgesList && s.judgesList.length > 0) {
            s.judgesList.forEach(j => {
                const jn = j.name || j.username || 'Судья';
                const safeJn = (this.app && typeof this.app.escapeHTML === 'function') ? this.app.escapeHTML(jn) : jn;
                const isSel = (s.judgeId === j.id) ? 'selected' : '';
                judgesHtml += '<option value="' + j.id + '" ' + isSel + '>' + safeJn + '</option>';
            });
        }

        // 1. ВКЛАДКИ ДИСТАНЦИЙ
        let distButtonsHtml = '';
        s.activeDistances.forEach((d, idx) => {
            const isAct = (idx === s.selectedDistIndex) ? 'active' : '';
            const rawName = d.name ? d.name : ('Дист. ' + (idx + 1));
            const safeDName = (this.app && typeof this.app.escapeHTML === 'function') ? this.app.escapeHTML(rawName) : rawName;
            
            const dTime = d.time || s.time || '11:00';
            let distText = '';
            const isLeader = Number(d.laps) === 0;

            if (isLeader) {
                const mins = d.leader_minutes || d.dist || 30;
                const lapKm = d.lap_km || '';
                distText = lapKm ? ` (${dTime} • ${mins} мин • ${lapKm} км)` : ` (${dTime} • ${mins} мин)`;
            } else if (d.dist) {
                const totalKm = Number(d.dist);
                const laps = Number(d.laps) || 1;
                if (laps > 1) {
                    const lapLen = (totalKm / laps).toFixed(1).replace('.0', '');
                    distText = ` (${dTime} • ${totalKm} км • ${laps}к)`;
                } else {
                    distText = ` (${dTime} • ${totalKm} км)`;
                }
            } else {
                distText = ` (${dTime})`;
            }

            const customBadge = (d.customFormat && d.format) ? ` • ${d.format.toUpperCase()}` : '';
            const removeSpan = (s.activeDistances.length > 1) 
                ? '<span style="opacity:0.6; margin-left:4px;" onclick="event.stopPropagation(); window.app.crm.removeNeoDistance(' + idx + ');">&times;</span>' 
                : '';
            
            distButtonsHtml += '<button type="button" class="nc-pill-btn ' + isAct + '" style="display:inline-flex; align-items:center;" onclick="window.app.crm.selectNeoDistance(' + idx + ')">';
            distButtonsHtml += '<span id="ncDistPillText_' + idx + '">' + safeDName + distText + customBadge + '</span>' + removeSpan;
            distButtonsHtml += '</button>';
        });

        // БАЗОВЫЕ СПИСКИ ПОКРЫТИЙ И ФОРМАТОВ
        const surfaces = [
            { key: 'road', label: 'Шоссе' },
            { key: 'offroad', label: 'Грунт / МТБ' },
            { key: 'track', label: 'Трек' },
            { key: 'indoor', label: 'Индор / Кибер' }
        ];
        let surfaceButtonsHtml = '';
        surfaces.forEach(item => {
            const isAct = (s.surface === item.key) ? 'active' : '';
            surfaceButtonsHtml += '<button type="button" class="nc-pill-btn ' + isAct + '" onclick="window.app.crm.setNeoSurface(\'' + item.key + '\')">' + item.label + '</button>';
        });

        const formats = [
            { key: 'mass', label: 'Группа' },
            { key: 'itt', label: 'Разделка ITT' },
            { key: 'crit', label: 'Критериум' }
        ];
        if (hasFullAccess) {
            formats.push({ key: 'ttt', label: 'Команда / Эстафета' });
        }
        let formatButtonsHtml = '';
        formats.forEach(item => {
            const isAct = (s.format === item.key) ? 'active' : '';
            formatButtonsHtml += '<button type="button" class="nc-pill-btn ' + isAct + '" onclick="window.app.crm.setNeoFormat(\'' + item.key + '\')">' + item.label + '</button>';
        });

        // 🎯 ИНДИВИДУАЛЬНЫЙ БЛОК ВЫБОРА ФОРМАТА ДЛЯ АКТИВНОЙ ДИСТАНЦИИ
        const hasCustomFmt = Boolean(activeDist.customFormat);
        const distSurface = activeDist.surface || s.surface || 'road';
        const distFormat = activeDist.format || s.format || 'mass';

        let distSurfaceButtonsHtml = '';
        surfaces.forEach(item => {
            const isAct = (distSurface === item.key) ? 'active' : '';
            distSurfaceButtonsHtml += `<button type="button" class="nc-pill-btn ${isAct}" style="font-size:10px; height:28px; padding:0 8px;" onclick="window.app.crm.setNeoDistSurface('${item.key}')">${item.label}</button>`;
        });

        let distFormatButtonsHtml = '';
        formats.forEach(item => {
            const isAct = (distFormat === item.key) ? 'active' : '';
            distFormatButtonsHtml += `<button type="button" class="nc-pill-btn ${isAct}" style="font-size:10px; height:28px; padding:0 8px;" onclick="window.app.crm.setNeoDistFormat('${item.key}')">${item.label}</button>`;
        });

        const customFormatBlockHtml = `
            <div style="display:flex; flex-direction:column; gap:8px; padding:10px; border-radius:10px; background:var(--nc-bg-box); border:1px solid var(--nc-border);">
                <div style="display:flex; justify-content:space-between; align-items:center;">
                    <div style="display:flex; flex-direction:column; gap:2px;">
                        <span style="font-family:'Unbounded', sans-serif; font-size:10px; font-weight:800;">ФОРМАТ И ПОКРЫТИЕ ЗАЕЗДА</span>
                        <span style="font-size:9px; color:var(--nc-text-muted); font-family:'Roboto Mono';">
                            ${hasCustomFmt ? 'Индивидуальные настройки для этой дистанции' : 'Наследует общие параметры события'}
                        </span>
                    </div>
                    <button type="button" class="nc-pill-btn ${hasCustomFmt ? 'active' : ''}" style="height:26px; font-size:9.5px; padding:0 10px;" onclick="window.app.crm.toggleNeoDistCustomFormat()">
                        ${hasCustomFmt ? '✓ Настроен свой' : 'Как у события'}
                    </button>
                </div>
                ${hasCustomFmt ? `
                    <div style="display:flex; flex-direction:column; gap:6px; margin-top:4px; padding-top:8px; border-top:1px dashed var(--nc-border);">
                        <div style="display:flex; gap:4px; flex-wrap:wrap;">
                            ${distSurfaceButtonsHtml}
                        </div>
                        <div style="display:flex; gap:4px; flex-wrap:wrap; margin-top:2px;">
                            ${distFormatButtonsHtml}
                        </div>
                    </div>
                ` : ''}
            </div>
        `;

        // БАЗА ОБОРУДОВАНИЯ (АДАПТИРУЕТСЯ ПОД ПОКРЫТИЕ ДИСТАНЦИИ)
        const allGears = [
            { key: 'ROAD', label: 'Шоссе', surfaces: ['road', 'indoor'] },
            { key: 'TT', label: 'Разделка (TT)', surfaces: ['road', 'indoor'] },
            { key: 'GRAVEL', label: 'Грэвел', surfaces: ['offroad'] },
            { key: 'CX', label: 'Циклокросс (CX)', surfaces: ['offroad'] },
            { key: 'MTB', label: 'МТБ', surfaces: ['offroad', 'indoor'] },
            { key: 'FIX', label: 'Фикс (Fixed)', surfaces: ['track', 'road', 'offroad'] },
            { key: 'FAT', label: 'Фэтбайк', surfaces: ['offroad'] },
            { key: 'SS', label: 'Синглспид', surfaces: ['road', 'offroad'] },
            { key: 'EBIKE', label: 'Электро', surfaces: ['offroad', 'road'] }
        ];

        const isShowAllGears = Boolean(s.showAllGears);
        const curSurface = effectiveSurface;

        const visibleGears = allGears.filter(g => 
            isShowAllGears || (g.surfaces && g.surfaces.includes(curSurface)) || (sc.activeGears && sc.activeGears.includes(g.key))
        );

        if (!Array.isArray(sc.activeGears) || sc.activeGears.length === 0) {
            const fallbackGears = {
                road: ['ROAD'],
                offroad: ['GRAVEL', 'MTB'],
                track: ['FIX'],
                indoor: ['ROAD']
            };
            sc.activeGears = fallbackGears[curSurface] || ['ROAD'];
        }

        let gearButtonsHtml = '';
        visibleGears.forEach(item => {
            const isAct = (sc.activeGears && sc.activeGears.includes(item.key)) ? 'active' : '';
            gearButtonsHtml += '<button type="button" class="nc-pill-btn ' + isAct + '" onclick="window.app.crm.toggleNeoDistGearItem(\'' + item.key + '\')">' + item.label + '</button>';
        });

        if (!isShowAllGears) {
            gearButtonsHtml += '<button type="button" class="nc-pill-btn" style="border-style:dashed; opacity:0.65; font-size:9px; padding:0 8px;" onclick="window.app.crm.constructorState.showAllGears = true; window.app.crm.renderNeoConstructorModal();">+ Все типы</button>';
        } else {
            gearButtonsHtml += '<button type="button" class="nc-pill-btn" style="border-style:dashed; opacity:0.65; font-size:9px; padding:0 8px;" onclick="window.app.crm.constructorState.showAllGears = false; window.app.crm.renderNeoConstructorModal();">Свернуть</button>';
        }

        const activePersonalClass = (s.eventType === 'personal') ? 'active' : '';
        const activePelotonClass = (s.eventType === 'peloton') ? 'active' : '';
        const personalDisplay = (s.eventType === 'personal') ? 'flex' : 'none';
        const pelotonDisplay = (s.eventType === 'peloton') ? 'flex' : 'none';
        const isPublicChecked = s.isPublic ? 'checked' : '';
        const distPriceVal = (s.price !== undefined && s.price !== null) ? s.price : '';
        const gearChecked = sc.useGear ? 'checked' : '';
        const gearWrapDisplay = sc.useGear ? 'flex' : 'none';
        const headerTitle = isEdit ? 'Редактирование события' : 'Добавить в календарь';

        // ДАННЫЕ И РЕЖИМ ДИСТАНЦИИ
        const isLeaderMode = Number(activeDist.laps) === 0;
        const distNameVal = safeActiveName;
        const distTimeVal = activeDist.time || s.time || '11:00';
        const distDistVal = (activeDist.dist !== undefined && activeDist.dist !== null) ? activeDist.dist : '';
        const distLapsVal = (activeDist.laps !== undefined && activeDist.laps !== null) ? activeDist.laps : 1;
        const leaderMinsVal = activeDist.leader_minutes || (isLeaderMode ? activeDist.dist : 30) || 30;
        const lapKmVal = activeDist.lap_km || (isLeaderMode && activeDist.dist && activeDist.dist != leaderMinsVal ? activeDist.dist : '');

        const squadColHtml = isTeamFormat ? `
            <div>
                <span style="font-size:8.5px; font-family:Roboto Mono, monospace; font-weight:700; opacity:0.7;">В ЭКИПАЖЕ</span>
                <input type="number" class="nc-input" name="vilka_dist_squad" autocomplete="off" value="${activeDist.squad_max || 2}" min="2" max="10" placeholder="2" oninput="window.app.crm.updateActiveDistParam('squad_max', this.value)">
            </div>
        ` : '';

        const distGridCols = isTeamFormat 
            ? 'grid-template-columns: 1.1fr 0.85fr 0.9fr 0.7fr 0.85fr;' 
            : 'grid-template-columns: 1.2fr 0.9fr 1fr 0.8fr;';

        const distFieldsHtml = isLeaderMode ? `
            <div style="display:grid; ${isTeamFormat ? 'grid-template-columns: 1.1fr 0.85fr 0.95fr 0.8fr 0.8fr;' : 'grid-template-columns: 1.2fr 0.9fr 1fr 0.9fr;'} gap:8px;">
                <div>
                    <span style="font-size:8.5px; font-family:Roboto Mono, monospace; font-weight:700; opacity:0.7;">НАЗВАНИЕ</span>
                    <input type="text" class="nc-input" name="vilka_dist_label" autocomplete="off" value="${distNameVal}" placeholder="CX / Шорт-трек" oninput="window.app.crm.updateActiveDistParam('name', this.value)">
                </div>
                <div>
                    <span style="font-size:8.5px; font-family:Roboto Mono, monospace; font-weight:700; color:var(--primary, #ffc107);">СТАРТ</span>
                    <input type="time" class="nc-input" name="vilka_dist_time" autocomplete="off" value="${distTimeVal}" oninput="window.app.crm.updateActiveDistParam('time', this.value)">
                </div>
                <div>
                    <span style="font-size:8.5px; font-family:Roboto Mono, monospace; font-weight:700; color:var(--primary, #ffc107);">ЛИДЕР (МИН)</span>
                    <input type="number" class="nc-input" name="vilka_leader_minutes" autocomplete="off" value="${leaderMinsVal}" placeholder="30" oninput="window.app.crm.updateActiveDistParam('leader_minutes', this.value)">
                </div>
                <div>
                    <span style="font-size:8.5px; font-family:Roboto Mono, monospace; font-weight:700; opacity:0.7;">КРУГ (КМ)</span>
                    <input type="number" class="nc-input" name="vilka_lap_km" autocomplete="off" step="0.1" value="${lapKmVal}" placeholder="1.5" oninput="window.app.crm.updateActiveDistParam('lap_km', this.value)">
                </div>
                ${squadColHtml}
            </div>
        ` : `
            <div style="display:grid; ${distGridCols} gap:8px;">
                <div>
                    <span style="font-size:8.5px; font-family:Roboto Mono, monospace; font-weight:700; opacity:0.7;">НАЗВАНИЕ</span>
                    <input type="text" class="nc-input" name="vilka_dist_label" autocomplete="off" value="${distNameVal}" placeholder="Основная / PRO" oninput="window.app.crm.updateActiveDistParam('name', this.value)">
                </div>
                <div>
                    <span style="font-size:8.5px; font-family:Roboto Mono, monospace; font-weight:700; color:var(--primary, #ffc107);">СТАРТ</span>
                    <input type="time" class="nc-input" name="vilka_dist_time" autocomplete="off" value="${distTimeVal}" oninput="window.app.crm.updateActiveDistParam('time', this.value)">
                </div>
                <div>
                    <span style="font-size:8.5px; font-family:Roboto Mono, monospace; font-weight:700; opacity:0.7;">ДИСТАНЦИЯ (КМ)</span>
                    <input type="number" class="nc-input" name="vilka_dist_km" autocomplete="off" step="0.1" value="${distDistVal}" placeholder="Всего км" oninput="window.app.crm.updateActiveDistParam('dist', this.value)">
                </div>
                <div>
                    <span style="font-size:8.5px; font-family:Roboto Mono, monospace; font-weight:700; opacity:0.7;">КРУГОВ</span>
                    <input type="number" class="nc-input" name="vilka_dist_laps" autocomplete="off" min="1" value="${distLapsVal}" placeholder="1" oninput="window.app.crm.updateActiveDistParam('laps', this.value)">
                </div>
                ${squadColHtml}
            </div>
        `;

        const curDistTrack = activeDist.trackData?.summary;
        const gpxStatusHtml = curDistTrack 
            ? `<span style="font-family:'Roboto Mono', monospace; font-size:9.5px; color:var(--primary, #ffc107); font-weight:800;">
                   ✓ ${curDistTrack.distance} км • +${curDistTrack.gain}м / -${curDistTrack.loss}м • макс. ${curDistTrack.maxSlope}%
               </span>`
            : `<span style="font-family:'Roboto Mono', monospace; font-size:9px; opacity:0.5;">Файл .gpx не выбран</span>`;

        const gpxUploadBlockHtml = `
            <div style="display:flex; flex-direction:column; gap:6px; padding-top:8px; border-top:1px dashed var(--nc-border, #3f3f46);">
                <div style="display:flex; justify-content:space-between; align-items:center;">
                    <span style="font-family:'Unbounded', sans-serif; font-size:10px; font-weight:800;">3D ТРЕК И РЕЛЬЕФ (GPX)</span>
                    ${activeDist.trackData ? `
                        <button type="button" onclick="event.stopPropagation(); window.app.crm.removeNeoTrackData();" 
                                style="background:none; border:none; color:var(--nc-text-muted, #71717a); font-size:10px; cursor:pointer;" title="Удалить трек">
                            ✕ Удалить
                        </button>
                    ` : ''}
                </div>
                <div style="display:flex; align-items:center; gap:8px;">
                    <input type="file" id="ncGpxFileInput" accept=".gpx" style="display:none;" onchange="window.app.crm.handleGpxUpload(this)">
                    <button type="button" class="nc-pill-btn" style="flex:1; height:34px; font-size:10px; font-weight:800; display:flex; align-items:center; justify-content:center; gap:6px;" onclick="document.getElementById('ncGpxFileInput').click()">
                        <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"></path><polyline points="17 8 12 3 7 8"></polyline><line x1="12" y1="3" x2="12" y2="15"></line></svg>
                        <span>${activeDist.trackData ? 'ЗАМЕНИТЬ GPX ТРЕК' : 'ЗАГРУЗИТЬ GPX ТРЕК'}</span>
                    </button>
                </div>
                <div>${gpxStatusHtml}</div>
            </div>
        `;

        const dateTimeCols = hasFullAccess ? 'grid-template-columns: 1.2fr 1fr;' : 'grid-template-columns: 1fr;';
        const priceColHtml = hasFullAccess ? `
            <div>
                <span style="font-size:8.5px; font-family:Roboto Mono, monospace; font-weight:700; opacity:0.7;">ВЗНОС (W)</span>
                <input type="number" class="nc-input" id="ncRacePrice" name="vilka_event_fee" autocomplete="off" data-lpignore="true" value="${distPriceVal}" placeholder="0 = бесплатно" oninput="window.app.crm.constructorState.price = this.value; window.app.crm.updateNeoPreview();">
            </div>
        ` : '';

        // КАТЕГОРИИ (УЧИТЫВАЮТ ИНДИВИДУАЛЬНЫЙ ФОРМАТ)
        let categoriesBlockHtml = '';
        if (hasFullAccess) {
            if (isTeamFormat) {
                const teamAgeMode = sc.teamAgeMode || 'avg';
                const teamAgeSubBoxDisplay = sc.hasTeamAge ? 'flex' : 'none';
                const teamBands = sc.teamAgeBands?.[teamAgeMode] || (teamAgeMode === 'sum' ? ['до 70 лет', '70–99 лет', '100+ лет'] : ['до 35 лет', '35–49 лет', '50+ лет']);

                categoriesBlockHtml = `
                    <div style="display:flex; flex-direction:column; gap:6px; padding-top:6px; border-top:1px dashed var(--nc-border, #3f3f46);">
                        <div style="display:flex; justify-content:space-between; align-items:center;">
                            <span style="font-family:Unbounded, sans-serif; font-size:10px; font-weight:800;">Категории экипажей</span>
                            <span style="font-family:Roboto Mono, monospace; font-size:8.5px; opacity:0.7; font-weight:700;">КОМАНДНЫЙ ЗАЧЁТ</span>
                        </div>
                        <div style="display:grid; grid-template-columns: 1fr 1fr 1fr; gap:6px;">
                            <button type="button" class="nc-pill-btn ${sc.hasAbsolute ? 'active' : ''}" style="font-size:9.5px; padding:0 6px;" onclick="window.app.crm.toggleNeoScoringLayer('hasAbsolute')">
                                ${sc.hasAbsolute ? '✓ ' : ''}Абсолют
                            </button>
                            <button type="button" class="nc-pill-btn ${sc.hasTeamGenders ? 'active' : ''}" style="font-size:9.5px; padding:0 6px;" onclick="window.app.crm.toggleNeoScoringLayer('hasTeamGenders')">
                                ${sc.hasTeamGenders ? '✓ ' : ''}М / Ж / Микст
                            </button>
                            <button type="button" class="nc-pill-btn ${sc.hasTeamAge ? 'active' : ''}" style="font-size:9.5px; padding:0 6px;" onclick="window.app.crm.toggleNeoScoringLayer('hasTeamAge')">
                                ${sc.hasTeamAge ? '✓ ' : ''}Возраст
                            </button>
                        </div>

                        <div id="ncTeamAgeConfigBox" style="display:${teamAgeSubBoxDisplay}; border:1px solid var(--nc-border, #3f3f46); border-radius:8px; padding:10px; flex-direction:column; gap:8px; margin-top:4px;">
                            <div style="display:flex; justify-content:space-between; align-items:center;">
                                <span style="font-family:Roboto Mono, monospace; font-size:9px; font-weight:800;">ПРИНЦИП РАСЧЁТА ВОЗРАСТА</span>
                                <div style="display:flex; gap:4px;">
                                    <button type="button" class="nc-pill-btn ${teamAgeMode === 'avg' ? 'active' : ''}" style="font-size:9px; height:24px; padding:0 8px;" onclick="window.app.crm.setTeamAgeMode('avg')">Средний возраст</button>
                                    <button type="button" class="nc-pill-btn ${teamAgeMode === 'sum' ? 'active' : ''}" style="font-size:9px; height:24px; padding:0 8px;" onclick="window.app.crm.setTeamAgeMode('sum')">Сумма лет</button>
                                </div>
                            </div>
                            <div style="display:flex; gap:6px; flex-wrap:wrap;">
                                ${teamBands.map(b => `<span style="border:1px solid var(--nc-border, #3f3f46); border-radius:5px; padding:3px 7px; font-family:Roboto Mono, monospace; font-size:9.5px; font-weight:700;">${b}</span>`).join('')}
                            </div>
                        </div>
                    </div>
                `;
            } else {
                const ageBoxDisplay = sc.hasAge ? 'flex' : 'none';
                categoriesBlockHtml = `
                    <div style="display:flex; flex-direction:column; gap:6px; padding-top:6px; border-top:1px dashed var(--nc-border, #3f3f46);">
                        <span style="font-family:Unbounded, sans-serif; font-size:10px; font-weight:800;">Категории</span>
                        <div style="display:grid; grid-template-columns: 1fr 1fr; gap:6px;">
                            <button type="button" class="nc-pill-btn ${sc.hasAbsolute ? 'active' : ''}" style="font-size:10px;" onclick="window.app.crm.toggleNeoScoringLayer('hasAbsolute')">
                                ${sc.hasAbsolute ? '✓ ' : ''}Абсолют (Генерал)
                            </button>
                            <button type="button" class="nc-pill-btn ${sc.hasPro ? 'active' : ''}" style="font-size:10px;" onclick="window.app.crm.toggleNeoScoringLayer('hasPro')">
                                ${sc.hasPro ? '✓ ' : ''}Дивизион PRO
                            </button>
                            <button type="button" class="nc-pill-btn ${sc.hasAge ? 'active' : ''}" style="font-size:10px;" onclick="window.app.crm.toggleNeoScoringLayer('hasAge')">
                                ${sc.hasAge ? '✓ ' : ''}Возрастные группы
                            </button>
                            <button type="button" class="nc-pill-btn ${sc.hasClusters ? 'active' : ''}" style="font-size:10px;" onclick="window.app.crm.toggleNeoScoringLayer('hasClusters')">
                                ${sc.hasClusters ? '✓ ' : ''}Кластеры скорости A–D
                            </button>
                        </div>
                    </div>

                    <div id="ncAgeConfigBox" style="display:${ageBoxDisplay}; border:1px solid var(--nc-border, #3f3f46); border-radius:8px; padding:10px; flex-direction:column; gap:8px;">
                        <div style="display:flex; justify-content:space-between; align-items:center;">
                            <span style="font-family:Roboto Mono, monospace; font-size:9px; font-weight:800;">ВОЗРАСТНАЯ СЕТКА</span>
                            <span style="font-family:Roboto Mono, monospace; font-size:8px; opacity:0.7;">НА 31 ДЕКАБРЯ</span>
                        </div>
                        
                        <div style="display:flex; gap:4px; flex-wrap:wrap;">
                            <button type="button" class="nc-pill-btn ${sc.agePreset === 'gf10' ? 'active' : ''}" style="font-size:9.5px; height:26px; padding:0 8px;" onclick="window.app.crm.applyNeoAgePreset('gf10')">Gran Fondo 10л</button>
                            <button type="button" class="nc-pill-btn ${sc.agePreset === 'uci5' ? 'active' : ''}" style="font-size:9.5px; height:26px; padding:0 8px;" onclick="window.app.crm.applyNeoAgePreset('uci5')">Masters UCI 5л</button>
                            <button type="button" class="nc-pill-btn ${sc.agePreset === 'youth' ? 'active' : ''}" style="font-size:9.5px; height:26px; padding:0 8px;" onclick="window.app.crm.applyNeoAgePreset('youth')">Юноши U12-U18</button>
                            <button type="button" class="nc-pill-btn ${sc.agePreset === 'simple' ? 'active' : ''}" style="font-size:9.5px; height:26px; padding:0 8px;" onclick="window.app.crm.applyNeoAgePreset('simple')">18-39 / 40+</button>
                        </div>

                        <div style="display:flex; flex-direction:column; gap:6px; margin-top:2px;" id="ncAgeTagsStream"></div>
                    </div>
                `;
            }
        }

        // ОСОБЫЕ НОМИНАЦИИ
        let customCatsBlockHtml = '';
        if (hasFullAccess) {
            let customChipsHtml = '';
            (sc.customCategories || []).forEach((cName, cIdx) => {
                const safeCName = (this.app && typeof this.app.escapeHTML === 'function') ? this.app.escapeHTML(cName) : cName;
                customChipsHtml += '<span style="border:1px solid var(--nc-border, #3f3f46); border-radius:6px; padding:3px 8px; font-family:Roboto Mono, monospace; font-size:10px; font-weight:700; display:inline-flex; align-items:center; gap:6px;">' +
                    safeCName +
                    '<span style="cursor:pointer; opacity:0.6;" onclick="window.app.crm.removeNeoCustomCategory(' + cIdx + ')">&times;</span>' +
                '</span>';
            });

            customCatsBlockHtml = `
                <div style="display:flex; flex-direction:column; gap:6px; padding-top:6px; border-top:1px dashed var(--nc-border, #3f3f46);">
                    <span style="font-family:Unbounded, sans-serif; font-size:10px; font-weight:800;">Особые номинации</span>
                    <div style="display:flex; gap:6px; align-items:center;">
                        <input type="text" id="ncNewCustomCatInput" class="nc-input" style="height:32px; font-size:11.5px;" placeholder="Название (напр. Синглспид, Тандем, Электро)" onkeydown="if(event.key==='Enter'){event.preventDefault(); window.app.crm.addNeoCustomCategoryInline();}">
                        <button type="button" class="nc-pill-btn" style="height:32px; font-size:10px; padding:0 12px; white-space:nowrap;" onclick="window.app.crm.addNeoCustomCategoryInline()">+ Добавить</button>
                    </div>
                    <div style="display:flex; gap:6px; flex-wrap:wrap; align-items:center; min-height:22px; margin-top:2px;">
                        ${customChipsHtml || '<span style="font-size:10.5px; opacity:0.5;">Нет особых зачётов</span>'}
                    </div>
                </div>
            `;
        }

        // ПОДВАЛ
        let footerButtonsHtml = '';
        const currentEventStatus = s.status || 'Registration';

        if (isEdit) {
            if (currentEventStatus === 'Registration') {
                footerButtonsHtml = `
                    <button type="button" id="btnSubmitNeoSoon" class="nc-pill-btn" 
                            style="height:36px; padding:0 14px; font-family:Unbounded, sans-serif; font-size:9px; font-weight:800;" 
                            onclick="window.app.crm.submitNeoEvent('Скоро')">
                        ВЕРНУТЬ В АНОНС
                    </button>
                    <button type="button" id="btnSubmitNeoReg" class="nc-pill-btn active" 
                            style="height:36px; padding:0 18px; font-family:Unbounded, sans-serif; font-size:9.5px; font-weight:900; letter-spacing:0.3px;" 
                            onclick="window.app.crm.submitNeoEvent('Registration')">
                        СОХРАНИТЬ ИЗМЕНЕНИЯ
                    </button>
                `;
            } else if (currentEventStatus === 'Скоро') {
                footerButtonsHtml = `
                    <button type="button" id="btnSubmitNeoSoon" class="nc-pill-btn" 
                            style="height:36px; padding:0 14px; font-family:Unbounded, sans-serif; font-size:9px; font-weight:800;" 
                            onclick="window.app.crm.submitNeoEvent('Скоро')">
                        СОХРАНИТЬ АНОНС
                    </button>
                    <button type="button" id="btnSubmitNeoReg" class="nc-pill-btn active" 
                            style="height:36px; padding:0 18px; font-family:Unbounded, sans-serif; font-size:9.5px; font-weight:900; letter-spacing:0.3px;" 
                            onclick="window.app.crm.submitNeoEvent('Registration')">
                        ОТКРЫТЬ РЕГИСТРАЦИЮ
                    </button>
                `;
            } else {
                footerButtonsHtml = `
                    <button type="button" id="btnSubmitNeoReg" class="nc-pill-btn active" 
                            style="height:36px; padding:0 20px; font-family:Unbounded, sans-serif; font-size:9.5px; font-weight:900; letter-spacing:0.3px;" 
                            onclick="window.app.crm.submitNeoEvent('${currentEventStatus}')">
                        СОХРАНИТЬ ИЗМЕНЕНИЯ
                    </button>
                `;
            }
        } else {
            footerButtonsHtml = canOpenReg ? `
                <button type="button" id="btnSubmitNeoSoon" class="nc-pill-btn" 
                        style="height:36px; padding:0 16px; font-family:Unbounded, sans-serif; font-size:9.5px; font-weight:800;" 
                        onclick="window.app.crm.submitNeoEvent('Скоро')">
                    АНОНС СОБЫТИЯ
                </button>
                <button type="button" id="btnSubmitNeoReg" class="nc-pill-btn active" 
                        style="height:36px; padding:0 18px; font-family:Unbounded, sans-serif; font-size:9.5px; font-weight:900; letter-spacing:0.3px;" 
                        onclick="window.app.crm.submitNeoEvent('Registration')">
                    ОТКРЫТЬ РЕГИСТРАЦИЮ
                </button>
            ` : `
                <button type="button" id="btnSubmitNeoSoon" class="nc-pill-btn active" 
                        style="height:36px; padding:0 22px; font-family:Unbounded, sans-serif; font-size:9.5px; font-weight:900; letter-spacing:0.3px;" 
                        onclick="window.app.crm.submitNeoEvent('Скоро')">
                    ОПУБЛИКОВАТЬ АНОНС
                </button>
            `;
        }

        modal.innerHTML = `
            <div class="nc-window" onclick="event.stopPropagation()">
                <div class="nc-head">
                    <div>
                        <h2 style="font-family:Unbounded, sans-serif; font-size:15px; font-weight:900; margin:0; text-transform:uppercase; letter-spacing:-0.3px;">
                            ${headerTitle}
                        </h2>
                    </div>
                    <button type="button" onclick="window.app.crm.closeNeoConstructorModal()" style="background:transparent; border:none; font-size:20px; line-height:1; cursor:pointer; color:inherit; opacity:0.6;" onmouseover="this.style.opacity='1'" onmouseout="this.style.opacity='0.6'">&times;</button>
                </div>

                <div class="nc-body">
                    <div class="nc-left-pane">
                        
                        <!-- ВЫБОР ТИПА -->
                        <div class="nc-box">
                            <div style="display:grid; grid-template-columns:1fr 1fr; gap:6px;">
                                <button type="button" id="btnNeoTypePersonal" class="nc-pill-btn ${activePersonalClass}" onclick="window.app.crm.setNeoEventType('personal')">Заезд / Тренировка</button>
                                <button type="button" id="btnNeoTypePeloton" class="nc-pill-btn ${activePelotonClass}" onclick="window.app.crm.setNeoEventType('peloton')">Гонка пелотона</button>
                            </div>

                            <div id="ncPersonalOptsWrap" style="display:${personalDisplay}; align-items:center; gap:8px; padding-top:4px;">
                                <label style="display:flex; align-items:center; gap:8px; cursor:pointer; font-size:11.5px; font-weight:600;">
                                    <input type="checkbox" id="ncIsPublicCheck" ${isPublicChecked} onchange="window.app.crm.constructorState.isPublic = this.checked;" style="width:15px; height:15px;">
                                    <span>Публичный выезд (виден всем в календаре)</span>
                                </label>
                            </div>

                            <div id="ncPelotonOptsWrap" style="display:${pelotonDisplay}; flex-direction:column; gap:8px; padding-top:4px;">
                                <div>
                                    <span style="font-size:8.5px; font-family:Roboto Mono, monospace; font-weight:700; opacity:0.7;">ЛИГА / ПЕЛОТОН *</span>
                                    <select id="ncPelotonSelect" class="nc-input" onchange="window.app.crm.constructorState.pelotonId = this.value; window.app.crm.renderNeoConstructorModal();">
                                        ${pelotonOptionsHtml}
                                    </select>
                                </div>

                                ${hasFullAccess ? `
                                    <div>
                                        <span style="font-size:8.5px; font-family:Roboto Mono, monospace; font-weight:700; opacity:0.7;">ГЛАВНЫЙ СУДЬЯ</span>
                                        <select id="ncJudgeSelect" class="nc-input" onchange="window.app.crm.constructorState.judgeId = this.value;">
                                            ${judgesHtml}
                                        </select>
                                    </div>
                                ` : ''}
                            </div>
                        </div>

                        <!-- НАЗВАНИЕ, ДАТА СОБЫТИЯ И ВЗНОС -->
                        <div class="nc-box">
                            <input type="text" class="nc-input" id="ncRaceName" name="vilka_event_title" autocomplete="off" data-lpignore="true" value="${safeRaceName}" placeholder="Название заезда или тренировки" oninput="window.app.crm.constructorState.name = this.value; window.app.crm.updateNeoPreview();">
                            
                            <div style="display:grid; ${dateTimeCols} gap:8px;">
                                <div>
                                    <span style="font-size:8.5px; font-family:Roboto Mono, monospace; font-weight:700; opacity:0.7;">ДАТА СОБЫТИЯ</span>
                                    <input type="date" class="nc-input" id="ncRaceDate" name="vilka_event_date" autocomplete="off" value="${s.date}" onchange="window.app.crm.constructorState.date = this.value; window.app.crm.updateNeoPreview();">
                                </div>
                                ${priceColHtml}
                            </div>
                        </div>

                        <!-- ОБЩИЕ ПАРАМЕТРЫ СОБЫТИЯ (ПО УМОЛЧАНИЮ) -->
                        <div class="nc-box">
                            <span class="nc-box-title" style="margin-bottom:0;">Базовый регламент события</span>
                            <div style="display:flex; gap:6px; flex-wrap:wrap; margin-top:4px;" id="ncSurfaceRow">
                                ${surfaceButtonsHtml}
                            </div>
                            <div style="display:flex; gap:6px; flex-wrap:wrap; margin-top:4px;" id="ncFormatRow">
                                ${formatButtonsHtml}
                            </div>
                        </div>

                        <!-- ДИСТАНЦИИ -->
                        <div class="nc-box">
                            <span class="nc-box-title" style="margin-bottom:0;">Дистанции (${s.activeDistances.length})</span>

                            <div style="display:flex; gap:6px; flex-wrap:wrap; align-items:center; margin-top:8px;">
                                ${distButtonsHtml}
                                <button type="button" class="nc-pill-btn" style="height:32px; font-size:11px; padding:0 10px; border-style:dashed;" onclick="window.app.crm.addNeoDistance()">+ Дистанция</button>
                            </div>

                            <div class="nc-card-block" style="border:1px solid var(--nc-border, #3f3f46); border-radius:10px; padding:12px; display:flex; flex-direction:column; gap:10px; margin-top:10px;">
                                
                                <div style="display:flex; align-items:center; gap:6px; border-bottom:1px solid var(--nc-border, #3f3f46); padding-bottom:8px;">
                                    <span style="display:inline-block; width:6px; height:6px; border-radius:50%; background:currentColor;"></span>
                                    <span id="ncActiveDistCardHeader" style="font-family:Unbounded, sans-serif; font-size:10px; font-weight:900; text-transform:uppercase;">
                                        РЕГЛАМЕНТ: ${safeActiveName}
                                    </span>
                                </div>

                                <!-- ПЕРЕКЛЮЧАТЕЛЬ РЕЖИМА: КРУГИ ИЛИ ВРЕМЯ ЛИДЕРА -->
                                <div style="display:flex; gap:6px; align-items:center; margin-top:2px;">
                                    <button type="button" 
                                            class="nc-pill-btn ${!isLeaderMode ? 'active' : ''}" 
                                            style="height:26px; font-size:9.5px; padding:0 10px;" 
                                            onclick="window.app.crm.setDistFormatMode(false)">
                                        Фиксированные круги
                                    </button>
                                    <button type="button" 
                                            class="nc-pill-btn ${isLeaderMode ? 'active' : ''}" 
                                            style="height:26px; font-size:9.5px; padding:0 10px;" 
                                            onclick="window.app.crm.setDistFormatMode(true)">
                                        ⏱ По времени лидера
                                    </button>
                                </div>

                                <!-- ПОЛЯ ВВОДА ДИСТАНЦИИ -->
                                ${distFieldsHtml}

                                <!-- 🎯 БЛОК ИНДИВИДУАЛЬНОГО ФОРМАТА / ПОКРЫТИЯ ДИСТАНЦИИ -->
                                ${customFormatBlockHtml}

                                <!-- GPX ТРЕК И ВЫСОТНЫЙ ПРОФИЛЬ -->
                                ${gpxUploadBlockHtml}

                                <!-- КАТЕГОРИИ ДИСТАНЦИИ -->
                                ${categoriesBlockHtml}

                                <!-- ОБОРУДОВАНИЕ -->
                                <div style="display:flex; flex-direction:column; gap:6px; padding-top:6px; border-top:1px dashed var(--nc-border, #3f3f46);">
                                    <div style="display:flex; justify-content:space-between; align-items:center;">
                                        <span style="font-family:Unbounded, sans-serif; font-size:10px; font-weight:800;">Велосипеды</span>
                                        <input type="checkbox" id="ncGearToggle" ${gearChecked} onchange="window.app.crm.toggleNeoDistGear(this.checked)" style="width:16px; height:16px; cursor:pointer;">
                                    </div>
                                    <div id="ncGearPillsWrap" style="display:${gearWrapDisplay}; gap:6px; flex-wrap:wrap;">
                                        ${gearButtonsHtml}
                                    </div>
                                </div>

                                ${customCatsBlockHtml}

                            </div>
                        </div>

                    </div>

                    <!-- ПРАВАЯ КОЛОНКА (ПРЕВЬЮ) -->
                    <div class="nc-right-pane">
                        <div class="nc-card-block" style="display:flex; justify-content:space-between; align-items:center; border:1px solid var(--nc-border, #3f3f46); border-radius:14px; padding:12px 18px;">
                            <div>
                                <div style="font-family:Unbounded, sans-serif; font-size:13px; font-weight:900; text-transform:uppercase;" id="ncCardRaceTitle">
                                    ${safeRaceName || "Событие"}
                                </div>
                            </div>
                            <div style="display:flex; gap:16px; text-align:center;">
                                <div>
                                    <div style="font-family:Unbounded, sans-serif; font-size:8px; font-weight:800; opacity:0.7;">НОМИНАЦИИ</div>
                                    <div style="font-family:Roboto Mono, monospace; font-size:14px; font-weight:900;" id="ncStatCats">0</div>
                                </div>
                                <div>
                                    <div style="font-family:Unbounded, sans-serif; font-size:8px; font-weight:800; opacity:0.7;">МЕДАЛИ</div>
                                    <div style="font-family:Roboto Mono, monospace; font-size:14px; font-weight:900;" id="ncStatMedals">0</div>
                                </div>
                                <div>
                                    <div style="font-family:Unbounded, sans-serif; font-size:8px; font-weight:800; opacity:0.7;">ПОДИУМЫ</div>
                                    <div style="font-family:Roboto Mono, monospace; font-size:14px; font-weight:900;" id="ncStatCups">0</div>
                                </div>
                            </div>
                        </div>

                        <div id="ncOutputCategoriesStream" style="display:flex; flex-direction:column; gap:12px; overflow-y:auto;"></div>
                    </div>
                </div>

                <!-- ПОДВАЛ -->
                <div class="nc-foot" style="display:flex; justify-content:flex-end; align-items:center; gap:8px;">
                    ${footerButtonsHtml}
                </div>
            </div>
        `;

        if (!isTeamFormat && hasFullAccess) {
            this.renderNeoAgeChips();
        }
        this.updateNeoPreview();

        if (prevScroll > 0) {
            const newPane = modal.querySelector('.nc-left-pane');
            if (newPane) newPane.scrollTop = prevScroll;
        }
    }
// =========================================================================
    // 5. УПРАВЛЕНИЕ ДИСТАНЦИЯМИ И ИХ РЕГЛАМЕНТОМ
    // =========================================================================
setDistFormatMode(isLeader) {
        this.saveCurrentDistInputsFromDom();
        const curDist = this.constructorState.activeDistances[this.constructorState.selectedDistIndex];
        if (!curDist) return;

        if (isLeader) {
            curDist.prevLaps = curDist.laps > 0 ? curDist.laps : 1;
            curDist.laps = 0; // Флаг гонки по лидеру для базы и судейства
            if (!curDist.leader_minutes) curDist.leader_minutes = curDist.dist || 30;
        } else {
            curDist.laps = curDist.prevLaps || 1;
            if (curDist.lap_km && curDist.laps) {
                curDist.dist = (Number(curDist.lap_km) * Number(curDist.laps)).toFixed(1).replace('.0', '');
            }
        }
        this.renderNeoConstructorModal();
    }

   saveCurrentDistInputsFromDom() {
        const s = this.constructorState;
        if (!s || !s.activeDistances) return;
        const curDist = s.activeDistances[s.selectedDistIndex];
        if (!curDist) return;

        const dNameInp = document.querySelector('input[name="vilka_dist_label"]');
        if (dNameInp && dNameInp.value.trim()) curDist.name = dNameInp.value.trim();

        // ⏱️ Сохраняем индивидуальное время старта дистанции
        const dTimeInp = document.querySelector('input[name="vilka_dist_time"]');
        if (dTimeInp && dTimeInp.value) curDist.time = dTimeInp.value;

        const isLeader = Number(curDist.laps) === 0;

        if (isLeader) {
            const minsInp = document.querySelector('input[name="vilka_leader_minutes"]');
            const lapKmInp = document.querySelector('input[name="vilka_lap_km"]');
            if (minsInp) curDist.leader_minutes = minsInp.value === '' ? 30 : (Number(minsInp.value) || 30);
            if (lapKmInp) curDist.lap_km = lapKmInp.value === '' ? null : (Number(lapKmInp.value) || null);
            curDist.dist = curDist.lap_km || curDist.leader_minutes || 0;
            curDist.laps = 0;
        } else {
            const dDistInp = document.querySelector('input[name="vilka_dist_km"]');
            if (dDistInp) curDist.dist = dDistInp.value === '' ? '' : Number(dDistInp.value);
            const dLapsInp = document.querySelector('input[name="vilka_dist_laps"]');
            if (dLapsInp) curDist.laps = dLapsInp.value === '' ? 1 : Math.max(1, Number(dLapsInp.value));
        }

        // 🌟 Читаем размер экипажа универсально для любого формата
        const dSquadInp = document.querySelector('input[name="vilka_dist_squad"]');
        if (dSquadInp) curDist.squad_max = Number(dSquadInp.value) || 2;

        const gearToggle = document.getElementById('ncGearToggle');
        if (gearToggle && curDist.scoring) {
            curDist.scoring.useGear = gearToggle.checked;
        }
    }
	
    addNeoDistance() {
        this.saveCurrentDistInputsFromDom();
        const nextIdx = this.constructorState.activeDistances.length + 1;
        this.constructorState.activeDistances.push({
            id: 'd_' + Date.now().toString(36),
            name: 'Дист. ' + nextIdx,
            dist: "",
            laps: 1,
            time: this.constructorState.time || "11:00",
            customFormat: false, // 👈 Флаг: включен ли свой формат/покрытие для этой дистанции
            surface: null,
            format: null,
            scoring: this.createDefaultDistanceScoring()
        });
        this.constructorState.selectedDistIndex = this.constructorState.activeDistances.length - 1;
        this.renderNeoConstructorModal();
    }

    removeNeoDistance(idx) {
        if (this.constructorState.activeDistances.length <= 1) return;
        this.constructorState.activeDistances.splice(idx, 1);
        if (this.constructorState.selectedDistIndex >= this.constructorState.activeDistances.length) {
            this.constructorState.selectedDistIndex = this.constructorState.activeDistances.length - 1;
        } else if (this.constructorState.selectedDistIndex > idx) {
            this.constructorState.selectedDistIndex--;
        }
        this.renderNeoConstructorModal();
    }
    selectNeoDistance(idx) {
        this.saveCurrentDistInputsFromDom();
        this.constructorState.selectedDistIndex = idx;
        this.renderNeoConstructorModal();
    }
	
    updateActiveDistParam(field, val) {
        const idx = this.constructorState.selectedDistIndex;
        const d = this.constructorState.activeDistances[idx];
        if (!d) return;

        if (field === 'dist' || field === 'laps' || field === 'leader_minutes' || field === 'lap_km' || field === 'squad_max') {
            d[field] = val === '' ? '' : Number(val);
        } else {
            d[field] = val;
        }

        // 💡 Если меняется число кругов и загружен GPX-трек — перемножаем общую дистанцию!
        if (field === 'laps' && d.trackData?.summary?.distance && Number(d.laps) > 0) {
            const oneLapKm = Number(d.trackData.summary.distance);
            d.dist = parseFloat((oneLapKm * Number(d.laps)).toFixed(2));
            
            // Мгновенно обновляем значение в соседнем инпуте "ДИСТАНЦИЯ (КМ)":
            const distInp = document.querySelector('input[name="vilka_dist_km"]');
            if (distInp) distInp.value = d.dist;
        }

        const isLeader = Number(d.laps) === 0;
        if (isLeader) {
            d.dist = d.lap_km || d.leader_minutes || 0;
        }

        const safeName = d.name || ('Дист. ' + (idx + 1));
        
        let distText = '';
        if (isLeader) {
            const mins = d.leader_minutes || d.dist || 30;
            const lapKm = d.lap_km || '';
            distText = lapKm ? ` (${mins} мин лидер • круг ${lapKm} км)` : ` (${mins} мин лидер)`;
        } else if (d.dist) {
            const totalKm = Number(d.dist);
            const laps = Number(d.laps) || 1;
            if (laps > 1) {
                // Если есть GPX — берем точный круг из трека, иначе делим
                const lapLen = d.trackData?.summary?.distance 
                    ? Number(d.trackData.summary.distance).toFixed(1) 
                    : (totalKm / laps).toFixed(1).replace('.0', '');
                distText = ` (${totalKm} км • ${laps}к по ${lapLen} км)`;
            } else {
                distText = ` (${totalKm} км)`;
            }
        }

        const customBadge = (d.customFormat && d.format) ? ` • ${d.format.toUpperCase()}` : '';

        // 1. Обновляем текст на кнопке-вкладке дистанции
        const pillText = document.getElementById('ncDistPillText_' + idx);
        if (pillText) pillText.innerText = safeName + distText + customBadge;

        // 2. Обновляем заголовок карточки
        const cardHeader = document.getElementById('ncActiveDistCardHeader');
        if (cardHeader) cardHeader.innerText = 'РЕГЛАМЕНТ: ' + safeName.toUpperCase();

        this.updateNeoPreview();
    }
    toggleNeoScoringLayer(layerKey) {
        const d = this.constructorState.activeDistances[this.constructorState.selectedDistIndex];
        if (!d) return;
        if (!d.scoring) d.scoring = this.createDefaultDistanceScoring();
        
        // Свободное включение и выключение
        d.scoring[layerKey] = !d.scoring[layerKey];

        // 🌟 Если включили возраст и сетка еще пуста — сразу наполняем пресетом по умолчанию
        if (layerKey === 'hasAge' && d.scoring.hasAge && !d.scoring.ageBands) {
            this.applyNeoAgePreset(d.scoring.agePreset || 'gf10');
            return;
        }

        this.renderNeoConstructorModal();
    }

    toggleNeoDistGear(isChecked) {
        const d = this.constructorState.activeDistances[this.constructorState.selectedDistIndex];
        if (d && d.scoring) {
            d.scoring.useGear = isChecked;
            this.renderNeoConstructorModal();
        }
    }

    toggleNeoDistGearItem(gearKey) {
        const d = this.constructorState.activeDistances[this.constructorState.selectedDistIndex];
        if (!d || !d.scoring) return;

        let gears = d.scoring.activeGears || [];
        if (gears.includes(gearKey)) {
            gears = gears.filter(g => g !== gearKey);
        } else {
            gears.push(gearKey);
        }
        d.scoring.activeGears = gears.length > 0 ? gears : ['ROAD'];
        this.renderNeoConstructorModal();
    }

    applyNeoAgePreset(presetKey) {
        const d = this.constructorState.activeDistances[this.constructorState.selectedDistIndex];
        if (!d || !d.scoring) return;

        const presets = {
            gf10: { M: ['18-29', '30-39', '40-49', '50-59', '60+'], F: ['18-34', '35-49', '50+'] },
            uci5: { M: ['18-29', '30-34', '35-39', '40-44', '45-49', '50-54', '55-59', '60+'], F: ['18-29', '30-34', '35-39', '40-44', '45+'] },
            youth: { M: ['U12', 'U14', 'U16', 'U18', '18+'], F: ['U12', 'U14', 'U16', 'U18', '18+'] },
            simple: { M: ['18-39', '40+'], F: ['18-39', '40+'] }
        };

        if (presets[presetKey]) {
            d.scoring.agePreset = presetKey;
            d.scoring.ageBands = JSON.parse(JSON.stringify(presets[presetKey]));
            this.renderNeoConstructorModal();
        }
    }

    renderNeoAgeChips() {
        const stream = document.getElementById('ncAgeTagsStream');
        if (!stream) return;

        const d = this.constructorState.activeDistances[this.constructorState.selectedDistIndex];
        const bandsObj = d?.scoring?.ageBands || { M: [], F: [] };

        const renderLine = (gender, label) => {
            let tagsHtml = '';
            (bandsObj[gender] || []).forEach((b, idx) => {
                tagsHtml += '<span style="background:transparent; border:1px solid #cbd5e1; border-radius:5px; padding:2px 6px; font-family:\'Roboto Mono\', monospace; font-size:10px; font-weight:700; display:inline-flex; align-items:center; gap:4px;">' +
                    b +
                    '<span style="cursor:pointer; color:#94a3b8;" onclick="window.app.crm.removeNeoAgeBand(\'' + gender + '\', ' + idx + ')">&times;</span>' +
                '</span>';
            });

            // 👈 1. ВОТ ЭТО ДОБАВЛЯЕТСЯ: компактное поле ввода и кнопка "+"
            const addInputHtml = `
                <div style="display:inline-flex; align-items:center; gap:4px; margin-left:4px;">
                    <input type="text" id="ncNewAge_${gender}" placeholder="напр. 65+" 
                           style="width:72px; height:22px; font-size:9.5px; font-family:'Roboto Mono', monospace; padding:0 6px; border:1px dashed #cbd5e1; border-radius:4px; background:transparent; color:inherit; outline:none;"
                           onkeydown="if(event.key==='Enter'){event.preventDefault(); window.app.crm.addNeoAgeBand('${gender}');}">
                    <button type="button" class="nc-pill-btn" style="height:22px; padding:0 7px; font-size:11px; font-weight:900; line-height:1; display:flex; align-items:center; justify-content:center;" 
                            onclick="window.app.crm.addNeoAgeBand('${gender}')">+</button>
                </div>
            `;

            return '<div style="display:flex; align-items:center; gap:6px; flex-wrap:wrap; margin-bottom:6px;">' +
                '<span style="font-family:\'Unbounded\', sans-serif; font-size:9px; font-weight:900; width:20px; height:20px; border-radius:4px; background:#e2e8f0; display:flex; align-items:center; justify-content:center; color:#09090b; flex-shrink:0;">' + label + '</span>' +
                '<div style="display:flex; gap:4px; flex-wrap:wrap; align-items:center;">' + tagsHtml + addInputHtml + '</div>' +
            '</div>';
        };

        stream.innerHTML = renderLine('M', 'М') + renderLine('F', 'Ж');
    }

    // 👈 2. ВОТ ЭТОТ МЕТОД ДОБАВЛЯЕТСЯ СРАЗУ ПОД НИМ:
    addNeoAgeBand(gender) {
        const input = document.getElementById(`ncNewAge_${gender}`);
        const val = input ? input.value.trim().toUpperCase() : '';
        if (!val) return;

        const d = this.constructorState.activeDistances[this.constructorState.selectedDistIndex];
        if (!d || !d.scoring) return;
        if (!d.scoring.ageBands) d.scoring.ageBands = { M: [], F: [] };
        if (!d.scoring.ageBands[gender]) d.scoring.ageBands[gender] = [];

        // Добавляем, если такой группы еще нет в списке
        if (!d.scoring.ageBands[gender].includes(val)) {
            d.scoring.ageBands[gender].push(val);
            d.scoring.agePreset = 'custom'; // Снимаем активную подсветку со стандартных кнопок-пресетов
            this.renderNeoConstructorModal();
        }
    }

    removeNeoAgeBand(gender, idx) {
        const d = this.constructorState.activeDistances[this.constructorState.selectedDistIndex];
        if (d?.scoring?.ageBands?.[gender]) {
            d.scoring.ageBands[gender].splice(idx, 1);
            this.renderNeoConstructorModal();
        }
    }

    removeNeoCustomCategory(idx) {
        const d = this.constructorState.activeDistances[this.constructorState.selectedDistIndex];
        if (d?.scoring?.customCategories) {
            d.scoring.customCategories.splice(idx, 1);
            this.renderNeoConstructorModal();
        }
    }

    setNeoEventType(type) {
        if (!this.constructorState) return;
        this.constructorState.eventType = type;

        if (type === 'personal') {
            this.constructorState.pelotonId = "";
        } else if (!this.constructorState.pelotonId && (this.constructorState.myPelotonsList?.length > 0 || this.constructorState.otherPelotonsList?.length > 0)) {
            this.constructorState.pelotonId = this.constructorState.myPelotonsList?.[0]?.id || this.constructorState.otherPelotonsList?.[0]?.id || "";
        }

    // Подхватываем все уже введенные пользователем поля перед перерисовкой
    const nameInput = document.getElementById('ncRaceName');
    if (nameInput) this.constructorState.name = nameInput.value;
    const dateInput = document.getElementById('ncRaceDate');
    if (dateInput) this.constructorState.date = dateInput.value;
    const timeInput = document.getElementById('ncRaceTime');
    if (timeInput) this.constructorState.time = timeInput.value;
    const publicCheck = document.getElementById('ncIsPublicCheck');
    if (publicCheck) this.constructorState.isPublic = publicCheck.checked;

        // Полный пересчёт интерфейса: подвала, кнопок и прав доступа
        this.renderNeoConstructorModal();
    }

    setNeoSurface(surface) {
        if (!this.constructorState) return;
        const s = this.constructorState;
        s.surface = surface;
        s.showAllGears = false;

        // Дефолтные комплекты оборудования под выбранное покрытие
        const defaultGearsBySurface = {
            road: ['ROAD'],
            offroad: ['GRAVEL', 'MTB'],
            track: ['FIX'],
            indoor: ['ROAD']
        };

        const targetGears = defaultGearsBySurface[surface] || ['ROAD'];

        // Синхронизируем оборудование во всех дистанциях заезда
        (s.activeDistances || []).forEach(dist => {
            if (dist.scoring && !dist.customFormat) {
                dist.scoring.activeGears = [...targetGears];
            }
        });

        this.renderNeoConstructorModal();
    }

    setNeoFormat(fmt) {
        this.constructorState.format = fmt;
        this.renderNeoConstructorModal();
    }
	
	toggleNeoDistCustomFormat() {
        this.saveCurrentDistInputsFromDom();
        const d = this.constructorState.activeDistances[this.constructorState.selectedDistIndex];
        if (!d) return;
        d.customFormat = !d.customFormat;
        if (d.customFormat) {
            if (!d.surface) d.surface = this.constructorState.surface || 'road';
            if (!d.format) d.format = this.constructorState.format || 'mass';
        }
        this.renderNeoConstructorModal();
    }

    setNeoDistSurface(surface) {
    this.saveCurrentDistInputsFromDom();
    const d = this.constructorState.activeDistances[this.constructorState.selectedDistIndex];
    if (!d) return;
    d.surface = surface;

    // 💡 Автоматически предлагаем профильное оборудование под новое покрытие заезда:
    const defaultGears = {
        road: ['ROAD'],
        offroad: ['GRAVEL', 'MTB'],
        track: ['FIX'],
        indoor: ['ROAD']
    };
    if (d.scoring) {
        d.scoring.activeGears = [...(defaultGears[surface] || ['ROAD'])];
    }

    this.renderNeoConstructorModal();
}

    setNeoDistFormat(fmt) {
        this.saveCurrentDistInputsFromDom();
        const d = this.constructorState.activeDistances[this.constructorState.selectedDistIndex];
        if (!d) return;
        d.format = fmt;
        this.renderNeoConstructorModal();
    }

    // =========================================================================
    // 6. ПЕРЕСЧЁТ КАРТЫ ЗАЧЁТОВ (ДЛЯ АКТИВНОЙ ДИСТАНЦИИ)
    // =========================================================================
updateNeoPreview() {
        const stream = document.getElementById('ncOutputCategoriesStream');
        if (!stream) return;

        const s = this.constructorState;
        const activeDist = s.activeDistances[s.selectedDistIndex] || s.activeDistances[0];
        const sc = activeDist?.scoring || this.createDefaultDistanceScoring();

        // 🎯 Учитываем персональный формат и покрытие активной дистанции
        const effectiveFormat = (activeDist?.customFormat && activeDist?.format) ? activeDist.format : s.format;
        const effectiveSurface = (activeDist?.customFormat && activeDist?.surface) ? activeDist.surface : (s.surface || 'road');
        const isTeamFormat = (effectiveFormat === 'ttt');

        const titleEl = document.getElementById('ncCardRaceTitle');
        if (titleEl) titleEl.innerText = s.name || (s.eventType === 'personal' ? "Тренировочный выезд" : "Событие");

        const isPeloton = (s.eventType === 'peloton');
        const isGlobalAdmin = JSON.stringify(this.app.usersMap?.[this.app.currentRider?.email] || []).includes('admin');
        const isLegitPelotonAdmin = (s.myAdminPelotons || []).some(ap => ap.id === s.pelotonId);
        const isPelotonAdmin = isPeloton && (isGlobalAdmin || isLegitPelotonAdmin);
        const hasScoringCategories = isPeloton && isPelotonAdmin;

        const gearNames = {
            'ROAD': 'Шоссе',
            'TT': 'Разделка (TT)',
            'GRAVEL': 'Грэвел',
            'CX': 'Циклокросс',
            'MTB': 'МТБ',
            'FIX': 'Фикс',
            'FAT': 'Фэтбайк',
            'SS': 'Синглспид',
            'EBIKE': 'Электро'
        };

        const generated = [];
        const hasGears = Boolean(sc.useGear && Array.isArray(sc.activeGears) && sc.activeGears.length > 0);
        const gears = hasGears ? sc.activeGears : [''];

        gears.forEach(gear => {
            if (!hasScoringCategories) return;

            const gearTitle = gear ? (gearNames[gear] || gear).toUpperCase() : '';
            const gearPrefix = gear ? (gearTitle + ' • ') : '';
            const gearKey = gear ? (gear + '_') : '';
            const divPrefix = gear ? ('ДИВИЗИОН ' + gearTitle + ' • ') : '';

            // 1. КОМАНДНЫЕ КАТЕГОРИИ (TTT / Эстафета)
            if (isTeamFormat) {
                if (sc.hasAbsolute) {
                    generated.push({ 
                        division: divPrefix + 'ГЕНЕРАЛЬНАЯ КЛАССИФИКАЦИЯ ЭКИПАЖЕЙ', 
                        title: gearPrefix + 'АБСОЛЮТ (ЭКИПАЖИ)', 
                        key: gearKey + 'TEAM_ABS' 
                    });
                }

                const teamGenders = [
                    { key: 'M', label: 'МУЖЧИНЫ', div: 'МУЖСКИЕ ЭКИПАЖИ' },
                    { key: 'F', label: 'ЖЕНЩИНЫ', div: 'ЖЕНСКИЕ ЭКИПАЖИ' },
                    { key: 'MIX', label: 'МИКСТ', div: 'СМЕШАННЫЕ ЭКИПАЖИ (МИКСТ)' }
                ];

                const mode = sc.teamAgeMode || 'avg';
                const ageBands = sc.teamAgeBands?.[mode] || (mode === 'sum' 
                    ? ['до 70 лет', '70–99 лет', '100+ лет'] 
                    : ['до 35 лет', '35–49 лет', '50+ лет']);

                if (sc.hasTeamGenders && sc.hasTeamAge) {
                    teamGenders.forEach(tg => {
                        ageBands.forEach(band => {
                            generated.push({
                                division: divPrefix + tg.div,
                                title: `${gearPrefix}${tg.label} • ${band}`,
                                key: `${gearKey}TEAM_${tg.key}_${mode.toUpperCase()}_${band}`
                            });
                        });
                    });
                } else if (sc.hasTeamGenders) {
                    teamGenders.forEach(tg => {
                        generated.push({
                            division: divPrefix + 'СОСТАВ ЭКИПАЖЕЙ',
                            title: gearPrefix + tg.label,
                            key: `${gearKey}TEAM_${tg.key}`
                        });
                    });
                } else if (sc.hasTeamAge) {
                    const modeTitle = (mode === 'sum') ? 'СУММАРНЫЙ ВОЗРАСТ' : 'СРЕДНИЙ ВОЗРАСТ';
                    ageBands.forEach(band => {
                        generated.push({
                            division: divPrefix + 'ВОЗРАСТ ЭКИПАЖЕЙ (' + modeTitle + ')',
                            title: gearPrefix + band,
                            key: `${gearKey}TEAM_${mode.toUpperCase()}_${band}`
                        });
                    });
                }
            } 
            // 2. ИНДИВИДУАЛЬНЫЕ КАТЕГОРИИ
            else {
                if (sc.hasAbsolute) {
                    generated.push({ division: divPrefix + 'ГЕНЕРАЛЬНАЯ КЛАССИФИКАЦИЯ', title: '[М] ' + gearPrefix + 'АБСОЛЮТ', key: gearKey + 'M_ABS' });
                    generated.push({ division: divPrefix + 'ГЕНЕРАЛЬНАЯ КЛАССИФИКАЦИЯ', title: '[Ж] ' + gearPrefix + 'АБСОЛЮТ', key: gearKey + 'F_ABS' });
                }

                if (sc.hasPro) {
                    generated.push({ division: divPrefix + 'ЭЛИТА (PRO)', title: '[М] ' + gearPrefix + 'PRO • ELITE', key: gearKey + 'M_PRO', isPro: true });
                    generated.push({ division: divPrefix + 'ЭЛИТА (PRO)', title: '[Ж] ' + gearPrefix + 'PRO • ELITE', key: gearKey + 'F_PRO', isPro: true });
                }

                if (sc.hasClusters) {
                    ['A+', 'A', 'B', 'C', 'D'].forEach(cl => {
                        generated.push({ division: divPrefix + 'СКОРОСТНЫЕ КЛАСТЕРЫ (М)', title: '[М] ' + gearPrefix + 'Кластер ' + cl, key: gearKey + 'M_' + cl });
                        generated.push({ division: divPrefix + 'СКОРОСТНЫЕ КЛАСТЕРЫ (Ж)', title: '[Ж] ' + gearPrefix + 'Кластер ' + cl, key: gearKey + 'F_' + cl });
                    });
                }

                if (sc.hasAge) {
                    const mBands = Array.isArray(sc.ageBands) ? sc.ageBands : (sc.ageBands?.M || []);
                    const fBands = Array.isArray(sc.ageBands) ? sc.ageBands : (sc.ageBands?.F || []);

                    mBands.forEach(b => {
                        generated.push({ division: divPrefix + 'МУЖЧИНЫ (ВОЗРАСТ)', title: '[М] ' + gearPrefix + b, key: gearKey + 'M_' + b });
                    });
                    fBands.forEach(b => {
                        generated.push({ division: divPrefix + 'ЖЕНЩИНЫ (ВОЗРАСТ)', title: '[Ж] ' + gearPrefix + b, key: gearKey + 'F_' + b });
                    });
                }
            }

            if (sc.customCategories && sc.customCategories.length > 0) {
                sc.customCategories.forEach(cName => {
                    generated.push({ division: divPrefix + 'СПЕЦИАЛЬНЫЕ ЗАЧЁТЫ', title: gearPrefix + cName.toUpperCase(), key: gearKey + 'CUSTOM_' + cName.toUpperCase() });
                });
            }
        });

        const divs = {};
        generated.forEach(item => {
            if (!divs[item.division]) divs[item.division] = [];
            divs[item.division].push(item);
        });

        const statCats = document.getElementById('ncStatCats');
        const statMedals = document.getElementById('ncStatMedals');
        const statCups = document.getElementById('ncStatCups');

        if (statCats) statCats.innerText = generated.length;
        if (statMedals) statMedals.innerText = generated.length * 3;
        if (statCups) statCups.innerText = generated.length;

        if (generated.length === 0) {
            const emptyTitle = !isPeloton 
                ? "ТРЕНИРОВОЧНЫЙ ВЫЕЗД" 
                : (!isPelotonAdmin ? "АНОНС СОБЫТИЯ" : "КАТЕГОРИИ НЕ ВЫБРАНЫ");
            const emptySubtitle = !isPeloton 
                ? "Для совместных выездов и тренировок соревновательный регламент и награждение не формируются" 
                : (!isPelotonAdmin ? "Сетка категорий и судейство настраиваются организатором лиги" : "Отметьте нужные категории или тип оборудования в панели слева");

            stream.innerHTML = `
                <div style="padding: 40px 20px; text-align: center; color: var(--nc-text-muted); font-family: Unbounded, sans-serif; font-size: 11px; border: 1px dashed var(--nc-border); border-radius: 14px; background: var(--nc-bg-box);">
                    ${emptyTitle}
                    <div style="font-family: Roboto Mono, monospace; font-size: 10px; color: var(--nc-text-muted); margin-top: 6px; text-transform: none; opacity: 0.85;">
                        ${emptySubtitle}
                    </div>
                </div>
            `;
            return;
        }

        let fullStreamHtml = '';
        Object.keys(divs).forEach(divName => {
            let cardsHtml = '';
            divs[divName].forEach(cat => {
                const proClass = cat.isPro ? 'is-pro' : '';
                cardsHtml += '<div class="nc-category-card ' + proClass + '">';
                cardsHtml += '<span class="nc-category-title">' + cat.title + '</span>';
                cardsHtml += '</div>';
            });

            fullStreamHtml += '<div style="display:flex; flex-direction:column; gap:6px;">';
            fullStreamHtml += '<span style="font-family:Roboto Mono, monospace; font-size:9px; font-weight:800; color:var(--nc-text-muted); letter-spacing:0.5px; text-transform:uppercase;">' + divName + '</span>';
            fullStreamHtml += '<div style="display:grid; grid-template-columns: repeat(auto-fill, minmax(210px, 1fr)); gap:6px;">' + cardsHtml + '</div>';
            fullStreamHtml += '</div>';
        });

        stream.innerHTML = fullStreamHtml;
    }
	setTeamAgeMode(mode) {
        const d = this.constructorState.activeDistances[this.constructorState.selectedDistIndex];
        if (d && d.scoring) {
            d.scoring.teamAgeMode = mode;
            this.renderNeoConstructorModal();
        }
    }

    addNeoCustomCategoryInline() {
        const input = document.getElementById('ncNewCustomCatInput');
        const val = input ? input.value.trim() : '';
        if (!val) return;

        const d = this.constructorState.activeDistances[this.constructorState.selectedDistIndex];
        if (d && d.scoring) {
            if (!Array.isArray(d.scoring.customCategories)) d.scoring.customCategories = [];
            if (!d.scoring.customCategories.includes(val)) {
                d.scoring.customCategories.push(val);
            }
            this.renderNeoConstructorModal();
        }
    }

    // =========================================================================
    // 7. ПУБЛИКАЦИЯ С МУЛЬТИ-ДИСТАНЦИЯМИ И ИНДИВИДУАЛЬНЫМИ ЗАЧЁТАМИ
    // =========================================================================
async submitNeoEvent(targetStatus = 'Registration') {
        const initialRaceStatus = this.editEventId 
            ? ((this.dataCalendar?.find(r => r.id === this.editEventId)?.status) || this.constructorState?.status || null)
            : null;

        const s = this.constructorState;
        if (!s) return;

        const isPeloton = (s.eventType === 'peloton');

        const myRiderId = this.app.currentRider?.id;
        const myUserId = pb.authStore.model?.id || this.app.currentRider?.user_id;
        const roles = (this.app.usersMap && this.app.currentRider?.email) ? (this.app.usersMap[this.app.currentRider.email] || []) : [];
        const rStr = JSON.stringify(roles);
        const isGlobalAdmin = rStr.includes('superadmin') || rStr.includes('admin');

        const isCreator = Boolean(
            s.isCreator || 
            (s.creatorId && (s.creatorId === myRiderId || s.creatorId === myUserId)) ||
            (this.editEventId && (
                this.app?.racesMap?.[this.editEventId]?.creator_id === myRiderId || 
                this.app?.racesMap?.[this.editEventId]?.creator_id === myUserId ||
                this.dataCalendar?.find(r => r.id === this.editEventId)?.creator_id === myRiderId ||
                this.dataCalendar?.find(r => r.id === this.editEventId)?.creator_id === myUserId
            ))
        );

        const isLegitPelotonAdmin = (s.myAdminPelotons || []).some(ap => ap.id === s.pelotonId);
        const isPelotonAdmin = isPeloton && (isGlobalAdmin || isLegitPelotonAdmin);

        const canOpenReg = !isPeloton || isPelotonAdmin;
        if (!canOpenReg) targetStatus = 'Скоро';

        if (!isPelotonAdmin) {
            s.price = 0;
            s.judgeId = "";
        }

        s.status = targetStatus;
        const isSoon = (s.status === 'Скоро');

        const nameInput = document.getElementById('ncRaceName');
        if (nameInput) s.name = nameInput.value;
        const dateInput = document.getElementById('ncRaceDate');
        if (dateInput) s.date = dateInput.value;
        const priceInput = document.getElementById('ncRacePrice');
        if (priceInput && isPelotonAdmin) s.price = priceInput.value;
        const publicCheck = document.getElementById('ncIsPublicCheck');
        if (publicCheck && s.eventType === 'personal') s.isPublic = publicCheck.checked;

        if (typeof this.saveCurrentDistInputsFromDom === 'function') {
            this.saveCurrentDistInputsFromDom();
        }

        if (!s.time && s.activeDistances?.[0]?.time) {
            s.time = s.activeDistances[0].time;
        }

        if (!s.name || !s.name.trim() || !s.date) {
            return alert("Укажите название события и дату старта.");
        }

        if (isPeloton && !s.pelotonId) {
            return alert("Выберите лигу / пелотон из списка!");
        }

        const btnSoon = document.getElementById('btnSubmitNeoSoon');
        const btnReg = document.getElementById('btnSubmitNeoReg');
        if (btnSoon) {
            btnSoon.disabled = true;
            if (isSoon) btnSoon.innerText = this.editEventId ? "СОХРАНЕНИЕ..." : "ПУБЛИКАЦИЯ...";
        }
        if (btnReg) {
            btnReg.disabled = true;
            if (!isSoon) btnReg.innerText = this.editEventId ? "СОХРАНЕНИЕ..." : "ПУБЛИКАЦИЯ...";
        }

        const dispatchRegistrationPush = async (primaryRace, raceChat) => {
            try {
                const raceTitle = s.name.trim();
                const pId = isPeloton ? s.pelotonId : null;
                const targetRiderIds = new Set();

                if (pId) {
                    Object.values(this.app.ridersMap || {}).forEach(r => {
                        if (!r || r.id === myRiderId || r.email === 'bot@sotka.one') return;

                        let pinned = r.pinned_chats || [];
                        if (typeof pinned === 'string') { try { pinned = JSON.parse(pinned); } catch(e) { pinned = []; } }
                        if (Array.isArray(pinned) && primaryRace && (pinned.includes(primaryRace.id) || (raceChat && pinned.includes(raceChat.id)))) {
                            targetRiderIds.add(r.id);
                        }

                        let subs = r.subscriptions || {};
                        if (typeof subs === 'string') { try { subs = JSON.parse(subs); } catch(e) { subs = {}; } }
                        const pSubs = Array.isArray(subs.pelotons) ? subs.pelotons : [];
                        if (pSubs.includes(pId)) {
                            targetRiderIds.add(r.id);
                        }

                        if (r.team_id) {
                            const rTeams = Array.isArray(r.team_id) ? r.team_id : [r.team_id];
                            const inPeloton = rTeams.some(tId => {
                                const t = this.app.teamsMap?.[tId];
                                const tP = t && t.peloton_id ? (Array.isArray(t.peloton_id) ? t.peloton_id[0] : t.peloton_id) : null;
                                return tP === pId;
                            });
                            if (inPeloton) targetRiderIds.add(r.id);
                        }
                    });
                } else {
                    Object.values(this.app.ridersMap || {}).forEach(r => {
                        if (r && r.id !== myRiderId && r.email !== 'bot@sotka.one' && !r.email?.startsWith('guest_')) {
                            targetRiderIds.add(r.id);
                        }
                    });
                }

                const recipients = Array.from(targetRiderIds);
                if (typeof this.app.sendPushNotification === 'function') {
                    const pushTitle = `⚡ Регистрация открыта: ${raceTitle}`;
                    const pushText = `Подайте заявку и выберите зачетный класс в VILKA`;
                    const pushUrl = `https://vilka.sotka.one/?chat=${raceChat?.id || primaryRace?.id || ''}`;
                    this.app.sendPushNotification(pushTitle, pushText, recipients, pushUrl);
                }
            } catch (pushErr) {
                console.warn("Ошибка рассылки при открытии регистрации:", pushErr);
            }
        };

        try {
            if (!this.editEventId) {
                const targetDay = s.date.slice(0, 10);
                const cleanInputName = s.name.toLowerCase().trim().replace(/\[.*?\]/g, '').replace(/[^a-zа-яё0-9]/gi, '');

                const checkRaces = await pb.collection('races').getFullList({
                    filter: `date ~ "${targetDay}"`,
                    requestKey: null
                }).catch(() => []);

                const duplicateRace = checkRaces.find(r => {
                    const existingName = (r.name || '').toLowerCase().trim().replace(/\[.*?\]/g, '').replace(/[^a-zа-яё0-9]/gi, '');
                    if (!existingName || !cleanInputName) return false;
                    if (existingName === cleanInputName) return true;
                    return (cleanInputName.length >= 4 && existingName.length >= 4 && (existingName.includes(cleanInputName) || cleanInputName.includes(existingName)));
                });

                if (duplicateRace) {
                    const dupDateFormatted = new Date(duplicateRace.date).toLocaleDateString('ru-RU', { day: 'numeric', month: 'long', year: 'numeric' });
                    const wantSubscribe = confirm(
                        `Такое событие уже есть в календаре!\n\n` +
                        `«${duplicateRace.name}» (${dupDateFormatted}).\n\n` +
                        `Добавить его в ваш личный календарь вместо создания дубликата?`
                    );

                    if (wantSubscribe) {
                        try {
                            if (typeof this.app.togglePinChat === 'function') {
                                await this.app.togglePinChat(duplicateRace.id);
                            }
                        } catch (e) {}
                        this.closeNeoConstructorModal();
                        alert(`Событие «${duplicateRace.name}» добавлено в ваш личный календарь.`);
                        if (typeof this.loadData === 'function') this.loadData();
                        return;
                    } else {
                        alert("Создание дубликата отменено. Измените название или дату события.");
                        if (btnSoon) {
                            btnSoon.disabled = false;
                            btnSoon.innerText = canOpenReg ? "АНОНС СОБЫТИЯ" : "ОПУБЛИКОВАТЬ АНОНС";
                        }
                        if (btnReg) {
                            btnReg.disabled = false;
                            btnReg.innerText = "ОТКРЫТЬ РЕГИСТРАЦИЮ";
                        }
                        return;
                    }
                }
            }

            const finalPrice = (isPelotonAdmin && s.price !== "" && s.price !== null && !isNaN(Number(s.price))) ? Math.max(0, Number(s.price)) : 0;

            const baseData = {
                price: finalPrice,
                status: s.status,
                level: isPeloton ? 'peloton' : 'personal',
                peloton_id: isPeloton ? s.pelotonId : "",
                is_public: isPeloton ? true : Boolean(s.isPublic),
                verification_status: isPelotonAdmin ? 'verified' : 'training',
                judge_id: (isPelotonAdmin && s.judgeId) ? [s.judgeId] : []
            };

            if (!s.activeDistances || s.activeDistances.length === 0) {
                s.activeDistances = [{ id: 'd_1', name: 'Основная', dist: 0, laps: 1, time: s.time || "11:00", scoring: this.createDefaultDistanceScoring() }];
            }

            if (this.editEventId) {
                const isMulti = s.activeDistances.length > 1;
                const creatorId = pb.authStore.model?.id || this.app.currentRider?.user_id || this.app.currentRider?.id;

                const currentRace = (this.dataCalendar ? this.dataCalendar.find(r => r.id === this.editEventId) : null)
                                 || (this.app?.racesMap ? this.app.racesMap[this.editEventId] : null)
                                 || await pb.collection('races').getOne(this.editEventId, { requestKey: null });

                let existingSisters = typeof this.app?.getSisterRaces === 'function' 
                    ? this.app.getSisterRaces(currentRace) 
                    : [];

                if (existingSisters.length <= 1) {
                    const dayStr = currentRace.date ? String(currentRace.date).slice(0, 10) : '';
                    const baseName = currentRace.name.includes('[') ? currentRace.name.split('[')[0].trim().toLowerCase() : currentRace.name.trim().toLowerCase();
                    if (dayStr) {
                        try {
                            const dayRaces = await pb.collection('races').getFullList({
                                filter: `date ~ "${dayStr}"`,
                                requestKey: null
                            });
                            const matched = dayRaces.filter(r => {
                                const rBase = r.name.includes('[') ? r.name.split('[')[0].trim().toLowerCase() : r.name.trim().toLowerCase();
                                return rBase === baseName;
                            });
                            if (matched.length > existingSisters.length) existingSisters = matched;
                        } catch(e) {}
                    }
                }
                if (existingSisters.length === 0) existingSisters = [currentRace];

                const existingSisterIds = new Set(existingSisters.map(sr => sr.id));
                const keptSisterIds = new Set();
                const synchronizedRaces = [];

                for (let distObj of s.activeDistances) {
                    const dName = (distObj.name || 'Дистанция').trim();
                    const hasCustomDistName = dName && dName !== 'Основная' && dName !== s.name.trim();
                    const finalRaceName = (isMulti || hasCustomDistName) ? `${s.name.trim()} [${dName}]` : s.name.trim();

                    const isLeader = Number(distObj.laps) === 0;
                    const distKm = isLeader 
                        ? (Number(distObj.lap_km || distObj.dist) || 0) 
                        : (Number(distObj.dist) || 0);
                    const lapsCount = isLeader ? 0 : ((distObj.laps !== undefined && distObj.laps !== null && distObj.laps !== '' && !isNaN(Number(distObj.laps))) ? Number(distObj.laps) : 1);
                    const sc = distObj.scoring || this.createDefaultDistanceScoring();

                    const distStartTime = distObj.time || s.time || "11:00";
                    const formattedDistTime = distStartTime.length === 5 ? `${distStartTime}:00` : distStartTime;
                    let distIsoDate;
                    if (String(s.date).includes('T')) {
                        distIsoDate = new Date(s.date).toISOString();
                    } else {
                        distIsoDate = new Date(`${s.date}T${formattedDistTime}`).toISOString();
                    }

                    // 🎯 ОПРЕДЕЛЕНИЕ ИНДИВИДУАЛЬНОГО ФОРМАТА И ПОКРЫТИЯ ДЛЯ ЭТОЙ ДИСТАНЦИИ
                    const distSurface = (distObj.customFormat && distObj.surface) ? distObj.surface : (s.surface || 'road');
                    const rawDistFormat = (distObj.customFormat && distObj.format) ? distObj.format : (s.format || 'mass');
                    const distFormat = isPelotonAdmin ? rawDistFormat : (rawDistFormat === 'ttt' ? 'mass' : rawDistFormat);
                    const isTimeTrial = distFormat === 'itt' || distFormat === 'ttt' || distFormat === 'relay' || (finalRaceName || '').toUpperCase().includes('DTT');

                    const catLogicPayload = JSON.stringify({
                        has_absolute: isPelotonAdmin ? Boolean(sc.hasAbsolute) : false,
                        has_pro: isPelotonAdmin ? Boolean(sc.hasPro) : false,
                        has_age: isPelotonAdmin ? Boolean(sc.hasAge) : false,
                        age_bands: (isPelotonAdmin && sc.hasAge) ? sc.ageBands : null,
                        has_clusters: isPelotonAdmin ? Boolean(sc.hasClusters) : false,
                        has_team_genders: isPelotonAdmin ? Boolean(sc.hasTeamGenders) : false,
                        has_team_age: isPelotonAdmin ? Boolean(sc.hasTeamAge) : false,
                        team_age_mode: sc.teamAgeMode || 'avg',
                        use_gear: Boolean(sc.useGear),
                        active_gears: sc.useGear ? (Array.isArray(sc.activeGears) && sc.activeGears.length > 0 ? sc.activeGears : ['ROAD']) : [],
                        custom_categories: isPelotonAdmin ? (sc.customCategories || []) : [],
                        quorum: sc.quorum || 3,
                        is_leader: isLeader,
                        leader_minutes: isLeader ? (Number(distObj.leader_minutes) || 30) : null,
                        lap_km: isLeader ? (Number(distObj.lap_km) || null) : null,
                        track_data: distObj.trackData || null
                    });

                    const racePayload = {
                        ...baseData,
                        surface: distSurface,
                        format: distFormat,
                        date: distIsoDate,
                        name: finalRaceName,
                        distance: distKm,
                        laps: lapsCount,
                        squad_max: (isPelotonAdmin && distFormat === 'ttt') ? (Number(distObj.squad_max) || 2) : 1,
                        cat_logic: catLogicPayload
                    };

                    let savedRace = null;
                    if (distObj.id && existingSisterIds.has(distObj.id)) {
                        savedRace = await pb.collection('races').update(distObj.id, racePayload, { requestKey: null });
                        keptSisterIds.add(distObj.id);
                        synchronizedRaces.push(savedRace);
                    } else if (distObj.id === this.editEventId || (!distObj.id.startsWith('d_') && existingSisterIds.has(this.editEventId) && keptSisterIds.size === 0)) {
                        savedRace = await pb.collection('races').update(this.editEventId, racePayload, { requestKey: null });
                        keptSisterIds.add(this.editEventId);
                        distObj.id = this.editEventId;
                        synchronizedRaces.push(savedRace);
                    } else {
                        savedRace = await pb.collection('races').create({
                            ...racePayload,
                            creator_id: creatorId
                        }, { requestKey: null });
                        distObj.id = savedRace.id;
                        keptSisterIds.add(savedRace.id);
                        synchronizedRaces.push(savedRace);
                    }

                    // 🏁 Обновляем время старта участников ТОЛЬКО для групповых гонок
                    if (!isTimeTrial && savedRace?.id) {
                        try {
                            const rosters = await pb.collection('race_rosters').getFullList({
                                filter: `race_id="${savedRace.id}" && status!="canceled"`,
                                requestKey: null
                            });

                            await Promise.all(rosters.map(r => {
                                if (r.planned_start !== formattedDistTime) {
                                    return pb.collection('race_rosters').update(r.id, {
                                        planned_start: formattedDistTime
                                    }, { requestKey: null });
                                }
                                return Promise.resolve();
                            }));
                        } catch (syncRosterErr) {
                            console.warn("Ошибка синхронизации времени старта участников:", syncRosterErr);
                        }
                    }
                }

                for (let oldSister of existingSisters) {
                    if (!keptSisterIds.has(oldSister.id) && oldSister.id !== this.editEventId) {
                        try {
                            await pb.collection('races').delete(oldSister.id, { requestKey: null });
                            if (this.app?.racesMap) delete this.app.racesMap[oldSister.id];
                        } catch(e) {}
                    }
                }

                synchronizedRaces.forEach(r => {
                    if (this.app?.racesMap) this.app.racesMap[r.id] = r;
                    if (this.dataCalendar) {
                        const idx = this.dataCalendar.findIndex(x => x.id === r.id);
                        if (idx !== -1) Object.assign(this.dataCalendar[idx], r);
                        else this.dataCalendar.unshift(r);
                    }
                    if (this.app?.dataCalendar) {
                        const idx = this.app.dataCalendar.findIndex(x => x.id === r.id);
                        if (idx !== -1) Object.assign(this.app.dataCalendar[idx], r);
                        else this.app.dataCalendar.unshift(r);
                    }
                    if (this.app?.crm?.dataCalendar) {
                        const idx = this.app.crm.dataCalendar.findIndex(x => x.id === r.id);
                        if (idx !== -1) Object.assign(this.app.crm.dataCalendar[idx], r);
                        else this.app.crm.dataCalendar.unshift(r);
                    }
                });

                const primaryRace = synchronizedRaces[0] || currentRace;
                const raceChat = (this.app?.chats || []).find(c => c.race_id === this.editEventId || c.race_id === primaryRace.id);
                if (raceChat) {
                    const dObj = new Date(primaryRace.date || baseData.date);
                    const chatDate = dObj.toLocaleDateString('ru-RU', { day: 'numeric', month: 'long' });
                    const chatTime = dObj.toLocaleTimeString('ru-RU', { hour: '2-digit', minute: '2-digit' });
                    const chatName = `${s.name.toUpperCase()} ${chatDate} ${chatTime}`;

                    await pb.collection('chats').update(raceChat.id, {
                        name: chatName
                    }, { requestKey: null }).catch(() => {});

                    raceChat.name = chatName;
                }

                const wasSoon = (initialRaceStatus === 'Скоро');
                const isNowReg = (targetStatus === 'Registration');

                if (wasSoon && isNowReg) {
                    const bot = Object.values(this.app.ridersMap || {}).find(r => r.email === 'bot@sotka.one');
                    if (bot && raceChat) {
                        await pb.collection('messages').create({
                            chat_id: raceChat.id,
                            sender_id: bot.id,
                            text: `⚡ РЕГИСТРАЦИЯ ОТКРЫТА!\n\nСлоты доступны для бронирования и оплаты.\n\n[ACTION:REGISTER:${primaryRace.id}]`,
                            is_announcement: true
                        }, { requestKey: null }).catch(() => {});
                    }

                    await dispatchRegistrationPush(primaryRace, raceChat);
                }

                this.closeNeoConstructorModal();
                alert(`Событие «${s.name}» успешно обновлено (дистанций: ${synchronizedRaces.length}).`);

            } else {
                baseData.creator_id = pb.authStore.model?.id || this.app.currentRider?.user_id || this.app.currentRider?.id;

                const isMulti = s.activeDistances.length > 1;
                const createdRaces = [];

                for (let distObj of s.activeDistances) {
                    const dName = (distObj.name || 'Дистанция').trim();
                    const hasCustomDistName = dName && dName !== 'Основная' && dName !== s.name.trim();
                    const finalRaceName = (isMulti || hasCustomDistName) ? `${s.name.trim()} [${dName}]` : s.name.trim();

                    const isLeader = Number(distObj.laps) === 0;
                    const distKm = isLeader 
                        ? (Number(distObj.lap_km || distObj.dist) || 0) 
                        : (Number(distObj.dist) || 0);
                    const lapsCount = isLeader ? 0 : ((distObj.laps !== undefined && distObj.laps !== null && distObj.laps !== '' && !isNaN(Number(distObj.laps))) ? Number(distObj.laps) : 1);
                    const sc = distObj.scoring || this.createDefaultDistanceScoring();

                    const distStartTime = distObj.time || s.time || "11:00";
                    const formattedDistTime = distStartTime.length === 5 ? `${distStartTime}:00` : distStartTime;
                    let distIsoDate;
                    if (String(s.date).includes('T')) {
                        distIsoDate = new Date(s.date).toISOString();
                    } else {
                        distIsoDate = new Date(`${s.date}T${formattedDistTime}`).toISOString();
                    }

                    // 🎯 ОПРЕДЕЛЕНИЕ ИНДИВИДУАЛЬНОГО ФОРМАТА И ПОКРЫТИЯ ДЛЯ ЭТОЙ ДИСТАНЦИИ
                    const distSurface = (distObj.customFormat && distObj.surface) ? distObj.surface : (s.surface || 'road');
                    const rawDistFormat = (distObj.customFormat && distObj.format) ? distObj.format : (s.format || 'mass');
                    const distFormat = isPelotonAdmin ? rawDistFormat : (rawDistFormat === 'ttt' ? 'mass' : rawDistFormat);

                    const catLogicPayload = JSON.stringify({
                        has_absolute: isPelotonAdmin ? Boolean(sc.hasAbsolute) : false,
                        has_pro: isPelotonAdmin ? Boolean(sc.hasPro) : false,
                        has_age: isPelotonAdmin ? Boolean(sc.hasAge) : false,
                        age_bands: (isPelotonAdmin && sc.hasAge) ? sc.ageBands : null,
                        has_clusters: isPelotonAdmin ? Boolean(sc.hasClusters) : false,
                        has_team_genders: isPelotonAdmin ? Boolean(sc.hasTeamGenders) : false,
                        has_team_age: isPelotonAdmin ? Boolean(sc.hasTeamAge) : false,
                        team_age_mode: sc.teamAgeMode || 'avg',
                        use_gear: Boolean(sc.useGear),
                        active_gears: sc.useGear ? (Array.isArray(sc.activeGears) && sc.activeGears.length > 0 ? sc.activeGears : ['ROAD']) : [],
                        custom_categories: isPelotonAdmin ? (sc.customCategories || []) : [],
                        quorum: sc.quorum || 3,
                        is_leader: isLeader,
                        leader_minutes: isLeader ? (Number(distObj.leader_minutes) || 30) : null,
                        lap_km: isLeader ? (Number(distObj.lap_km) || null) : null,
                        track_data: distObj.trackData || null
                    });

                    const racePayload = {
                        ...baseData,
                        surface: distSurface,
                        format: distFormat,
                        date: distIsoDate,
                        name: finalRaceName,
                        distance: distKm,
                        laps: lapsCount,
                        squad_max: (isPelotonAdmin && distFormat === 'ttt') ? (Number(distObj.squad_max) || 2) : 1,
                        cat_logic: catLogicPayload
                    };

                    const newRace = await pb.collection('races').create(racePayload, { requestKey: null });
                    createdRaces.push(newRace);
                }

                const primaryRace = createdRaces[0];
                const dObj = new Date(primaryRace.date);
                const chatDate = dObj.toLocaleDateString('ru-RU', { day: 'numeric', month: 'long' });
                const chatTime = dObj.toLocaleTimeString('ru-RU', { hour: '2-digit', minute: '2-digit' });
                const isPrimaryTimeTrial = primaryRace.format === 'itt' || primaryRace.format === 'ttt' || primaryRace.format === 'relay' || (primaryRace.name || '').toUpperCase().includes('DTT');
                const timeLabel = isPrimaryTimeTrial ? 'Первый старт' : 'Старт';
                const chatName = `${s.name.trim().toUpperCase()} ${chatDate} ${chatTime}`;

                const cleanPanelData = {
                    text: "",
                    buttons: []
                };

                const newChat = await pb.collection('chats').create({
                    type: 'global',
                    name: chatName,
                    race_id: primaryRace.id,
                    peloton_id: isPeloton ? s.pelotonId : "",
                    participants: this.app.currentRider?.id ? [this.app.currentRider.id] : [],
                    panel_data: JSON.stringify(cleanPanelData)
                }, { requestKey: null });

                const bot = Object.values(this.app.ridersMap || {}).find(r => r.email === 'bot@sotka.one');
                if (bot) {
                    let noticeText = "";
                    if (isSoon) {
                        noticeText = `АНОНС СОБЫТИЯ\n\nСобытие внесено в календарь.\n${timeLabel}: ${chatDate} в ${chatTime}\n\nРегистрация откроется позже — сохраните гонку в личный календарь.`;
                    } else if (isPeloton) {
                        noticeText = `ОФИЦИАЛЬНЫЙ СТАРТ\n\nРегистрация открыта. Дистанций: ${createdRaces.length}. Регламент сформирован.\n${timeLabel}: ${chatDate} в ${chatTime}\n\n[ACTION:REGISTER:${primaryRace.id}]`;
                    } else {
                        noticeText = `ОТКРЫТЫЙ ВЫЕЗД\n\nСоздан заезд (${chatDate} в ${chatTime}). Добавляйтесь в участники!\n\n[ACTION:REGISTER:${primaryRace.id}]`;
                    }

                    await pb.collection('messages').create({
                        chat_id: newChat.id,
                        sender_id: bot.id,
                        text: noticeText,
                        is_announcement: true
                    }, { requestKey: null });
                }

                for (let cr of createdRaces) {
                    try {
                        if (typeof this.app.togglePinChat === 'function') {
                            await this.app.togglePinChat(cr.id);
                        }
                    } catch (pinErr) {}
                    if (this.app?.racesMap) this.app.racesMap[cr.id] = cr;
                    if (this.dataCalendar) this.dataCalendar.unshift(cr);
                    if (this.app?.dataCalendar) this.app.dataCalendar.unshift(cr);
                    if (this.app?.crm?.dataCalendar) this.app.crm.dataCalendar.unshift(cr);
                }

                if (targetStatus === 'Registration') {
                    await dispatchRegistrationPush(primaryRace, newChat);
                }

                this.closeNeoConstructorModal();
                alert(`Событие «${s.name}» успешно опубликовано (дистанций: ${createdRaces.length}).`);
            }

            if (typeof this.loadData === 'function') this.loadData();
            if (typeof this.app.loadChats === 'function') await this.app.loadChats();

        } catch (err) {
            console.error("Ошибка сохранения гонки:", err);
            alert("Ошибка сохранения: " + (err.message || "Сетевой сбой"));
        } finally {
            if (btnSoon) {
                btnSoon.disabled = false;
                btnSoon.innerText = canOpenReg 
                    ? (this.editEventId ? (s.status === 'Registration' ? "ВЕРНУТЬ В АНОНС" : "СОХРАНИТЬ АНОНС") : "АНОНС СОБЫТИЯ")
                    : (this.editEventId ? "СОХРАНИТЬ АНОНС" : "ОПУБЛИКОВАТЬ АНОНС");
            }
            if (btnReg) {
                btnReg.disabled = false;
                btnReg.innerText = this.editEventId 
                    ? (s.status === 'Registration' ? "СОХРАНИТЬ ИЗМЕНЕНИЯ" : "ОТКРЫТЬ РЕГИСТРАЦИЮ") 
                    : "ОТКРЫТЬ РЕГИСТРАЦИЮ";
            }
        }
    }
 // =========================================================================
    // 8. РЕДАКТИРОВАНИЕ СУЩЕСТВУЮЩЕГО СОБЫТИЯ
    // =========================================================================
async openEditEventModal(raceId) {
        let race = null;
        try {
            race = await pb.collection('races').getOne(raceId, { requestKey: null });
        } catch(e) {
            race = (this.dataCalendar ? this.dataCalendar.find(r => r.id === raceId) : null) 
                || (this.app?.racesMap ? this.app.racesMap[raceId] : null);
        }
        
        if (!race) {
            return alert("Не удалось найти событие для редактирования.");
        }

        const myRiderId = this.app.currentRider?.id;
        const myUserId = pb.authStore.model?.id || this.app.currentRider?.user_id;
        const roles = (this.app.usersMap && this.app.currentRider?.email) ? (this.app.usersMap[this.app.currentRider.email] || []) : []; 
        const rStr = JSON.stringify(roles); 
        const isAdmin = rStr.includes('superadmin') || rStr.includes('admin');
        const isJudge = rStr.includes('judge');
        const amISuper = rStr.includes('superadmin');
        const isCreator = Boolean(race.creator_id && (race.creator_id === myRiderId || race.creator_id === myUserId));

        if (!isAdmin && !isCreator) {
            return alert("Редактирование доступно только создателю события или администратору.");
        }

        this.editEventId = raceId;

        let defaultDate = new Date().toISOString().slice(0, 10);
        let defaultTime = "11:00";
        try {
            const rawDateVal = race.rawDate || race.date;
            if (rawDateVal) {
                const d = new Date(rawDateVal);
                const offset = d.getTimezoneOffset() * 60000;
                defaultDate = (new Date(d - offset)).toISOString().slice(0, 10);

                const hours = String(d.getHours()).padStart(2, '0');
                const mins = String(d.getMinutes()).padStart(2, '0');
                defaultTime = `${hours}:${mins}`;
            }
        } catch(e) {}

        const myTeams = Array.isArray(this.app.currentRider?.team_id) ? this.app.currentRider.team_id : (this.app.currentRider?.team_id ? [this.app.currentRider.team_id] : []);
        let subPelotonIds = [];
        let rawSubs = this.app.currentRider?.subscriptions;
        if (typeof rawSubs === 'string' && rawSubs.trim()) {
            try { rawSubs = JSON.parse(rawSubs); } catch(e) {}
        }
        if (rawSubs && typeof rawSubs === 'object') {
            subPelotonIds = Array.isArray(rawSubs.pelotons) ? rawSubs.pelotons : [];
        }

        const myAdminPelotons = [];
        const mySubscribedPelotons = [];
        const otherPelotonsList = [];

        Object.values(this.app.pelotonsMap || {}).forEach(p => {
            const adminIds = (Array.isArray(p.admin_id) ? p.admin_id : [p.admin_id]).map(a => (typeof a === 'object' && a !== null) ? a.id : String(a).trim());
            const isMyAdmin = adminIds.includes(myRiderId) || adminIds.includes(myUserId);
            const isTeamHome = myTeams.some(tId => {
                const t = this.app.teamsMap?.[tId];
                const pId = t && t.peloton_id ? (Array.isArray(t.peloton_id) ? t.peloton_id[0] : t.peloton_id) : null;
                return pId === p.id;
            });
            const isSubscribed = subPelotonIds.includes(p.id);

            if (isMyAdmin) {
                myAdminPelotons.push(p);
            } else if (isTeamHome || isSubscribed) {
                mySubscribedPelotons.push(p);
            } else if (!p.is_private || amISuper) {
                otherPelotonsList.push(p);
            }
        });

        const myPelotonsList = [...myAdminPelotons, ...mySubscribedPelotons];

        const cleanName = race.name ? (race.name.includes('[') ? race.name.split('[')[0].trim() : race.name.trim()) : "";
        const cleanDistName = race.name && race.name.includes('[') ? race.name.split('[')[1].replace(']', '').trim() : 'Основная';
        const isPelotonRace = (race.level === 'peloton');
        const dayStr = race.date ? String(race.date).slice(0, 10) : '';

        let sisters = [];
        if (dayStr) {
            try {
                const dayRaces = await pb.collection('races').getFullList({
                    filter: `date ~ "${dayStr}"`,
                    requestKey: null
                });
                sisters = dayRaces.filter(r => {
                    const rBase = r.name.includes('[') ? r.name.split('[')[0].trim().toLowerCase() : r.name.trim().toLowerCase();
                    return rBase === cleanName.toLowerCase();
                });
            } catch(e) {}
        }
        if (sisters.length === 0) {
            sisters = typeof this.app?.getSisterRaces === 'function' ? this.app.getSisterRaces(race) : [race];
        }
        if (sisters.length === 0) sisters = [race];

        const parseScoring = (catLogic, surface) => {
            if (typeof this.parseDistanceScoring === 'function') {
                return this.parseDistanceScoring(catLogic, surface);
            }
            const sc = this.createDefaultDistanceScoring ? this.createDefaultDistanceScoring() : {
                hasAbsolute: true,
                hasPro: false,
                hasAge: false,
                agePreset: 'gf10',
                ageBands: null,
                hasClusters: false,
                useGear: false,
                activeGears: ['ROAD'],
                customCategories: [],
                quorum: 3
            };

            const defaultGears = {
                road: ['ROAD'],
                offroad: ['GRAVEL', 'MTB'],
                track: ['FIX'],
                indoor: ['ROAD']
            };
            sc.activeGears = [...(defaultGears[surface || 'road'] || ['ROAD'])];

            if (!catLogic) return sc;

            try {
                const parsed = (typeof catLogic === 'string') ? JSON.parse(catLogic) : catLogic;
                if (parsed.has_absolute !== undefined) sc.hasAbsolute = Boolean(parsed.has_absolute);
                if (parsed.has_pro !== undefined) sc.hasPro = Boolean(parsed.has_pro);
                if (parsed.has_age !== undefined) sc.hasAge = Boolean(parsed.has_age);
                if (parsed.age_bands) sc.ageBands = parsed.age_bands;
                if (parsed.has_clusters !== undefined) sc.hasClusters = Boolean(parsed.has_clusters);
                if (parsed.has_team_genders !== undefined) sc.hasTeamGenders = Boolean(parsed.has_team_genders);
                if (parsed.has_team_age !== undefined) sc.hasTeamAge = Boolean(parsed.has_team_age);
                if (parsed.team_age_mode) sc.teamAgeMode = parsed.team_age_mode;
                if (parsed.use_gear !== undefined) sc.useGear = Boolean(parsed.use_gear);
                if (Array.isArray(parsed.active_gears) && parsed.active_gears.length > 0) {
                    sc.activeGears = [...parsed.active_gears];
                }
                if (Array.isArray(parsed.custom_categories)) sc.customCategories = [...parsed.custom_categories];
                if (parsed.quorum) sc.quorum = parsed.quorum;

                if (parsed.model) {
                    if (parsed.model === 'absolute') { sc.hasAbsolute = true; sc.hasAge = false; }
                    if (parsed.model === 'pure_age') { sc.hasAge = true; sc.hasAbsolute = false; }
                    if (parsed.model === 'sport_age') { sc.hasPro = true; sc.hasAge = true; }
                    if (parsed.model === 'clusters') { sc.hasClusters = true; sc.hasAbsolute = false; }
                }
            } catch(e) {}

            return sc;
        };

        const baseNormalizedSurface = (typeof resolveSurfaceAlias === 'function' ? resolveSurfaceAlias(race.surface) : null) || race.surface || 'road';
        const baseFormat = race.format || 'mass';

        // 🎯 Считываем индивидуальные format и surface для каждой дистанции
        const distList = sisters.map((sr, idx) => {
            const dName = sr.name.includes('[') 
                ? sr.name.split('[')[1].replace(']', '').trim() 
                : (idx === 0 ? cleanDistName : 'Дист. ' + (idx + 1));

            let cl = null;
            try {
                cl = typeof sr.cat_logic === 'string' ? JSON.parse(sr.cat_logic) : sr.cat_logic;
            } catch(e) {}

            const isLeader = Number(sr.laps) === 0 || Boolean(cl?.is_leader);

            let srTime = defaultTime;
            const srDateRaw = sr.rawDate || sr.date;
            if (srDateRaw) {
                const srd = new Date(srDateRaw);
                if (!isNaN(srd.getTime())) {
                    srTime = `${String(srd.getHours()).padStart(2, '0')}:${String(srd.getMinutes()).padStart(2, '0')}`;
                }
            }

            const distSurface = (typeof resolveSurfaceAlias === 'function' ? resolveSurfaceAlias(sr.surface) : null) || sr.surface || baseNormalizedSurface;
            const distFormat = sr.format || baseFormat;
            const hasCustomSetting = (distSurface !== baseNormalizedSurface) || (distFormat !== baseFormat);

            return {
                id: sr.id || 'd_' + idx,
                name: dName,
                time: srTime,
                customFormat: hasCustomSetting,
                surface: distSurface,
                format: distFormat,
                dist: (sr.distance !== undefined && sr.distance !== null) ? sr.distance : "",
                laps: isLeader ? 0 : ((sr.laps !== undefined && sr.laps !== null && sr.laps !== '') ? Number(sr.laps) : 1),
                squad_max: sr.squad_max || 2,
                leader_minutes: cl?.leader_minutes || (isLeader ? 30 : null),
                lap_km: cl?.lap_km || (isLeader ? sr.distance : null),
                scoring: parseScoring(sr.cat_logic, distSurface),
                trackData: cl?.track_data || null
            };
        });
        
        const targetDistIndex = Math.max(0, distList.findIndex(d => d.id === race.id));

        this.constructorState = {
            name: cleanName,
            date: defaultDate,
            time: defaultTime,
            status: race.status || 'Registration',
            eventType: isPelotonRace ? 'peloton' : 'personal',
            isPublic: race.is_public !== undefined ? Boolean(race.is_public) : true,
            pelotonId: Array.isArray(race.peloton_id) ? race.peloton_id[0] : (race.peloton_id || ""),
            myPelotonsList: myPelotonsList,
            myAdminPelotons: myAdminPelotons,
            otherPelotonsList: otherPelotonsList,
            isCreator: isCreator,
            creatorId: race.creator_id,
            judgeId: Array.isArray(race.judge_id) ? race.judge_id[0] : (race.judge_id || ""),
            judgesList: [],
            surface: baseNormalizedSurface,
            format: baseFormat,
            price: (race.price !== undefined && race.price !== null) ? race.price : "",
            activeDistances: distList,
            selectedDistIndex: targetDistIndex
        };

        if (isAdmin || isJudge) {
            pb.collection('users').getFullList({ filter: `role ~ "judge"`, requestKey: null }).then(judges => {
                this.constructorState.judgesList = judges;
                const judgeSelect = document.getElementById('ncJudgeSelect');
                if (judgeSelect) {
                    let jHtml = '<option value="">-- Без назначения судьи --</option>';
                    judges.forEach(j => {
                        const jn = j.name || j.username || 'Судья';
                        const safeJn = (this.app && typeof this.app.escapeHTML === 'function') ? this.app.escapeHTML(jn) : jn;
                        const isSel = (this.constructorState.judgeId === j.id) ? 'selected' : '';
                        jHtml += '<option value="' + j.id + '" ' + isSel + '>' + safeJn + '</option>';
                    });
                    judgeSelect.innerHTML = jHtml;
                }
            }).catch(() => {});
        }

        this.renderNeoConstructorModal();
    }
    // =========================================================================
    // 9. УДАЛЕНИЕ ЗАЕЗДА
    // =========================================================================
async deleteRace(raceId) {
        if (!raceId) return;

        const race = (this.dataCalendar ? this.dataCalendar.find(r => r.id === raceId) : null) 
                  || (this.app?.racesMap ? this.app.racesMap[raceId] : null)
                  || (this.app?.chats?.find(c => c.race_id === raceId || c.raceObj?.id === raceId)?.raceObj);

        const myRiderId = this.app.currentRider?.id;
        const myUserId = pb.authStore.model?.id || this.app.currentRider?.user_id;
        const roles = this.app.usersMap[this.app.currentRider?.email] || [];
        const rStr = JSON.stringify(roles);
        const isAdmin = rStr.includes('superadmin') || rStr.includes('admin');
        const isCreator = race && (race.creator_id === myRiderId || race.creator_id === myUserId);

        if (!isAdmin && !isCreator) {
            return alert("Удаление события доступно только его создателю или администратору.");
        }

        if (!confirm("Удалить это событие (включая все его дистанции) и связанный чат навсегда? Это действие нельзя отменить.")) return;

        try {
            // 1. Собираем ВСЕ сестринские дистанции события
            let sisterRaces = [];
            if (race) {
                sisterRaces = typeof this.app?.getSisterRaces === 'function' 
                    ? this.app.getSisterRaces(race) 
                    : [race];

                const dayStr = race.date ? String(race.date).slice(0, 10) : '';
                const baseName = race.name.includes('[') ? race.name.split('[')[0].trim().toLowerCase() : race.name.trim().toLowerCase();

                if (dayStr && navigator.onLine) {
                    try {
                        const dayRaces = await pb.collection('races').getFullList({
                            filter: `date ~ "${dayStr}"`,
                            requestKey: null
                        });
                        const matchedDb = dayRaces.filter(r => {
                            const rBase = r.name.includes('[') ? r.name.split('[')[0].trim().toLowerCase() : r.name.trim().toLowerCase();
                            return rBase === baseName;
                        });
                        matchedDb.forEach(mr => {
                            if (!sisterRaces.some(sr => sr.id === mr.id)) sisterRaces.push(mr);
                        });
                    } catch(dbErr) {}
                }
            }

            const idsToDelete = new Set(sisterRaces.map(sr => sr.id).filter(Boolean));
            idsToDelete.add(raceId);

            // 2. Удаляем ВСЕ дистанции из базы PocketBase
            for (let rId of idsToDelete) {
                try {
                    await pb.collection('races').delete(rId, { requestKey: null });
                } catch(err) {
                    console.warn(`Дистанция ${rId} уже удалена или недоступна:`, err);
                }
            }

            // 3. Удаляем все связанные чаты
            const chatsToDelete = (this.app.chats || []).filter(c => 
                idsToDelete.has(c.race_id) || 
                (c.raceObj && idsToDelete.has(c.raceObj.id)) ||
                idsToDelete.has(c.id)
            );

            for (let chat of chatsToDelete) {
                try {
                    await pb.collection('chats').delete(chat.id, { requestKey: null });
                } catch(chatErr) {}
            }

            if (this.app.chats) {
                this.app.chats = this.app.chats.filter(c => !chatsToDelete.some(dc => dc.id === c.id));
            }

            // 4. Очищаем память и кэши во всех модулях
            if (this.dataCalendar) {
                this.dataCalendar = this.dataCalendar.filter(r => !idsToDelete.has(r.id));
            }
            if (this.app?.dataCalendar) {
                this.app.dataCalendar = this.app.dataCalendar.filter(r => !idsToDelete.has(r.id));
            }
            if (this.app?.crm?.dataCalendar) {
                this.app.crm.dataCalendar = this.app.crm.dataCalendar.filter(r => !idsToDelete.has(r.id));
            }
            if (this.app?.racesMap) {
                idsToDelete.forEach(rId => delete this.app.racesMap[rId]);
            }

            // 5. Очищаем localStorage
            try {
                const cachedCore = localStorage.getItem('vilka_core_data');
                if (cachedCore) {
                    const data = JSON.parse(cachedCore);
                    if (Array.isArray(data.dataCalendar)) {
                        data.dataCalendar = data.dataCalendar.filter(r => !idsToDelete.has(r.id));
                        localStorage.setItem('vilka_core_data', JSON.stringify(data));
                    }
                }
                localStorage.setItem('vilka_chats_cache', JSON.stringify(this.app.chats || []));
            } catch(e) {}

            // 6. Сбрасываем правый экран, если открыта эта гонка
            if (this.app.activeChatId && (idsToDelete.has(this.app.activeChatId) || chatsToDelete.some(dc => dc.id === this.app.activeChatId))) {
                this.app.activeChatId = null;
                if (typeof this.app.closeChatMobile === 'function') {
                    this.app.closeChatMobile();
                }
            }

            // 7. Перерисовываем список
            const searchInput = document.getElementById('chatSearch');
            if (typeof this.app.renderChatList === 'function') {
                this.app.renderChatList(searchInput ? searchInput.value : "");
            }

            alert(`Событие и все его дистанции (${idsToDelete.size} шт.) успешно удалены.`);

        } catch(e) {
            console.error("Ошибка при удалении гонки:", e);
            alert("Ошибка при удалении гонки: " + (e.message || "Сетевая ошибка"));
        }
    }
// 🔥 1. УТВЕРЖДЕНИЕ СТАРТА КАК ОФИЦИАЛЬНОЙ ГОНКИ
    async approveRaceAsOfficial(raceId) {
        if (!confirm("Утвердить старт как официальную гонку Лиги? Результаты пойдут в глобальный кубковый рейтинг Сотки.")) return;

        try {
            await pb.collection('races').update(raceId, {
                verification_status: 'verified',
                level: 'peloton',
                is_public: true
            }, { requestKey: null });

            const raceChat = this.app.chats.find(c => c.race_id === raceId || c.raceObj?.id === raceId);
            const bot = Object.values(this.app.ridersMap).find(r => r.email === 'bot@sotka.one');
            if (raceChat && bot) {
                await pb.collection('messages').create({
                    chat_id: raceChat.id,
                    sender_id: bot.id,
                    text: `🏆 **СТАРТ ОФИЦИАЛЬНО УТВЕРЖДЕН ОРГКОМИТЕТОМ СОТКИ!**\n\nГонка включена в кубковый календарь. Финишные результаты пойдут в зачет глобального рейтинга и пересчет кластеров!`,
                    is_announcement: true
                }, { requestKey: null });
            }

            alert("✅ Гонка утверждена как официальный старт!");
            this.loadData();
        } catch(e) {
            alert("Ошибка утверждения: " + e.message);
        }
    }

    // 🔥 2. НАЗНАЧЕНИЕ ЗАЕЗДА ТРЕНИРОВКОЙ
    async setRaceAsTraining(raceId) {
        if (!confirm("Оставить заезд как тренировку? (Километры пойдут в накат, без начисления кубковых очков).")) return;

        try {
            await pb.collection('races').update(raceId, {
                verification_status: 'training',
                level: 'personal',
                is_public: true
            }, { requestKey: null });

            const raceChat = this.app.chats.find(c => c.race_id === raceId || c.raceObj?.id === raceId);
            const bot = Object.values(this.app.ridersMap).find(r => r.email === 'bot@sotka.one');
            if (raceChat && bot) {
                await pb.collection('messages').create({
                    chat_id: raceChat.id,
                    sender_id: bot.id,
                    text: `🚴‍♂️ **СТАТУС: СОВМЕСТНАЯ ТРЕНИРОВКА**\n\nЗаезд утвержден как тренировочный. Дистанция будет зачислена в накат сезона.`,
                    is_announcement: true
                }, { requestKey: null });
            }

            alert("✅ Статус заезда изменен на тренировку.");
            this.loadData();
        } catch(e) {
            alert("Ошибка изменения статуса: " + e.message);
        }
    }

// ==========================================
    // 🔥 ДИНАМИЧЕСКИЙ КАЛЬКУЛЯТОР КЛАСТЕРОВ (ОБНОВЛЕН)
    // ==========================================
    getClusterBySpeed(speed, gender = 'M', surface = 'road', rules = null) {
        speed = parseFloat(speed); if (!speed || speed <= 0) return 'O';
        const activeRules = rules || this.DEFAULT_RATING_RULES;
        const gKey = (gender === 'F' || gender === 'Ж') ? 'F' : 'M';
        
        let thresholds;
        // 🔥 Проверяем: это новый формат правил (прямые пороги) или старый (по покрытиям)?
        if (activeRules.thresholds && activeRules.thresholds[gKey]) {
            thresholds = activeRules.thresholds[gKey];
        } else {
            // Поддержка старого формата для обратной совместимости
            thresholds = activeRules?.speed_thresholds?.[surface]?.[gKey];
            if (!thresholds) thresholds = activeRules?.speed_thresholds?.['road']?.[gKey] || this.DEFAULT_RATING_RULES.speed_thresholds.road[gKey];
        }

        // Сортируем пороги от самого быстрого к медленному
        const sortedThresholds = Object.entries(thresholds).sort((a, b) => b[1] - a[1]);
        
        for (let [clusterName, minSpeed] of sortedThresholds) {
            if (speed >= minSpeed) return clusterName;
        }
        return 'E'; // Резервный кластер, если ехал медленнее всех порогов
    }
	
	// ==========================================
    // 🔥 УМНОЕ ФОРМАТИРОВАНИЕ НАЗВАНИЙ КОМАНД (ЧЕРЕЗ ЗАПЯТУЮ)
    // ==========================================
    getRiderTeamNames(rider, racePelotonId = null) {
        if (!rider || !rider.team_id) return 'ONE TEAM';
        
        const tIds = Array.isArray(rider.team_id) ? rider.team_id : [rider.team_id];
        if (tIds.length === 0) return 'ONE TEAM';
        
        const teams = tIds.map(id => this.app.teamsMap[id]).filter(Boolean);
        if (teams.length === 0) return 'ONE TEAM';

        // 🔥 Если передан пелотон гонки — ищем команду именно этой лиги
        if (racePelotonId) {
            const matchedTeam = teams.find(t => {
                const pIds = Array.isArray(t.peloton_id) ? t.peloton_id : (t.peloton_id ? [t.peloton_id] : []);
                return pIds.includes(racePelotonId);
            });
            if (matchedTeam) return matchedTeam.name;
        }

        // Если совпадения по пелотону нет — убираем ONE TEAM, если есть боевой клуб
        const combatTeams = teams.filter(t => !t.name.toUpperCase().includes('ONE TEAM'));
        return combatTeams.length > 0 ? combatTeams[0].name : teams[0].name;
    }
	
   // 🔥 ГЕНЕРАТОР КАТЕГОРИЙ (С УЧЕТОМ ПОКРЫТИЯ ГОНКИ)
getRaceCategory(rider, race) {
        if (!rider || !race) return '???';

        // 1. Проверяем, зашита ли в cat_logic новая JSON-матрица конструктора
        let matrix = null;
        if (race.cat_logic && typeof race.cat_logic === 'string' && race.cat_logic.trim().startsWith('{')) {
            try { matrix = JSON.parse(race.cat_logic); } catch(e) {}
        } else if (race.cat_logic && typeof race.cat_logic === 'object') {
            matrix = race.cat_logic;
        }

        const g = (rider.gender === 'F' || rider.gender === 'Ж') ? 'F' : 'M';
        const rusG = g === 'M' ? 'М' : 'Ж';

        // 2. Расчет возраста строго на год проведения гонки
        const dStr = race.rawDate || race.date;
        const dObj = dStr ? new Date(dStr) : new Date();
        const raceYear = isNaN(dObj.getFullYear()) ? new Date().getFullYear() : dObj.getFullYear();
        const birthYear = parseInt(rider.yob || rider.year_of_birth || 1990);
        const age = raceYear - birthYear;

        // =========================================================================
        // 🌟 ВЕТКА 1: НОВАЯ 3D-МАТРИЦА (РЕГЛАМЕНТ 2026)
        // =========================================================================
        if (matrix) {
            const parts = [];
            const gearLabels = {
                'ROAD': 'ШОССЕ', 'TT': 'TT', 'GRAVEL': 'ГРЭВЕЛ', 'GRVL': 'ГРЭВЕЛ',
                'CX': 'ЦИКЛОКРОСС', 'MTB': 'МТБ', 'FIX': 'ФИКС', 'FAT': 'ФЭТ',
                'SS': 'СИНГЛСПИД', 'EBIKE': 'ЭЛЕКТРО'
            };

            // 1. Тип велосипеда (с поддержкой сырых кодов и готовых строк)
            let rawGear = rider.gear;
            if (!rawGear) {
                const combinedStr = `${rider.final_cluster || ''} ${rider.base_cluster || ''} ${rider.group || ''}`.toUpperCase();
                for (const [code, label] of Object.entries(gearLabels)) {
                    const regex = new RegExp(`(^|[^a-zA-Zа-яА-Я0-9])(${code}|${label})([^a-zA-Zа-яА-Я0-9]|$)`, 'i');
                    if (regex.test(combinedStr)) {
                        rawGear = label;
                        break;
                    }
                }
            }

            if (matrix.use_gear && rawGear) {
                const gUpper = String(rawGear).toUpperCase().trim();
                parts.push(gearLabels[gUpper] || gUpper);
            }

            // 2. Командные форматы (TTT / Эстафета)
            if (matrix.has_team_genders || matrix.has_team_age || race.format === 'ttt' || race.format === 'relay') {
                let genders = rider.squad_genders || [];
                if (genders.length === 0) genders.push(String(rider.gender || 'M').toUpperCase().trim());
                const hasM = genders.some(x => x === 'M' || x === 'М');
                const hasF = genders.some(x => x === 'F' || x === 'Ж');
                let teamGenderLabel = (hasM && hasF) ? 'МИКСТ' : (hasF ? 'ЖЕНЩИНЫ' : 'МУЖЧИНЫ');
                
                if (matrix.has_team_genders && !matrix.has_team_age) {
                    return (parts.length ? parts.join(' • ') + ' • ' : '') + teamGenderLabel;
                }
                if (matrix.has_team_age) {
                    const mode = matrix.team_age_mode || 'avg';
                    const bands = matrix.team_age_bands?.[mode] || (mode === 'sum' ? ['до 70 лет', '70–99 лет', '100+ лет'] : ['до 35 лет', '35–49 лет', '50+ лет']);
                    const teamLabel = matrix.has_team_genders ? `${teamGenderLabel} • ${bands[0]}` : bands[0];
                    return (parts.length ? parts.join(' • ') + ' • ' : '') + teamLabel;
                }
                return (parts.length ? parts.join(' • ') + ' • ' : '') + teamGenderLabel;
            }

            // 3. Кластеры скорости Сотки (A+, A, B, C, D)
            if (matrix.has_clusters || matrix.model === 'clusters') {
                const surface = race.surface || 'road';
                const surfClusterKey = `cluster_${surface}`;
                const rawCl = rider[surfClusterKey] || rider.base_cluster || 'B';
                const cleanCl = String(rawCl).replace(/\[.*?\]\s*/g, '').trim() || 'B';
                parts.push('Кластер ' + cleanCl);
                return `[${rusG}] ` + parts.join(' • ');
            }

            // 4. Спортивный дивизион PRO (Элита)
            if ((matrix.has_pro || matrix.model === 'sport_age') && (rider.division === 'PRO' || rider.division === 'ELITE')) {
                parts.push('PRO • ELITE');
                return `[${rusG}] ` + parts.join(' • ');
            }

            // 5. Возрастная сетка из настроек гонки (только если включена!)
            if (matrix.has_age || matrix.model === 'pure_age' || matrix.model === 'sport_age') {
                const bands = (matrix.age_bands?.[g] || matrix.age_bands || ['18-29', '30-39', '40-49', '50-59', '60+']);
                let matchedBand = bands[0] || '18+';

                for (let b of bands) {
                    if (b.startsWith('U')) {
                        const limit = parseInt(b.replace('U', ''), 10);
                        if (age <= limit) { matchedBand = b; break; }
                    } else if (b.includes('-')) {
                        const [min, max] = b.split('-').map(Number);
                        if (age >= min && age <= max) { matchedBand = b; break; }
                    } else if (b.includes('+')) {
                        const min = parseInt(b.replace('+', ''), 10);
                        if (age >= min) { matchedBand = b; break; }
                    }
                }

                parts.push(matchedBand);
                return `[${rusG}] ` + parts.join(' • ');
            }

            // 6. Абсолютный зачёт (по умолчанию)
            if (matrix.has_absolute || matrix.model === 'absolute' || parts.length === 0) {
                parts.push('АБСОЛЮТ');
                return `[${rusG}] ` + parts.join(' • ');
            }

            return `[${rusG}] ` + parts.join(' • ');
        }

        // =========================================================================
        // 🛡️ ВЕТКА 2: ОБРАТНАЯ СОВМЕСТИМОСТЬ (СТАРЫЕ ГОНКИ)
        // =========================================================================
        let logic = race.cat_logic || 'clusters';
        if (logic === 'Кластеры') logic = 'clusters';
        if (logic === 'Возрастные') logic = 'age';
        if (logic === 'Абсолют') logic = 'absolute';
        if (logic === 'Смешанные') logic = 'mixed';
        if (logic === 'Командные' || logic === 'teams') logic = 'teams';

        const surface = race.surface || 'road';
        const surfClusterKey = `cluster_${surface}`;
        const rawCluster = rider[surfClusterKey] || rider.base_cluster || 'B';
        const cluster = String(rawCluster).replace(/\[.*?\]\s*/g, '').trim() || 'B';

        let ageIdx = ""; 
        let ageLabel = ""; 
        let isJunior = false; 
        let isVet = false;

        if (age < 18) {
            isJunior = true;
            if (age >= 16 && age <= 17) { ageIdx = "U18"; ageLabel = "16-17"; }
            else if (age >= 14 && age <= 15) { ageIdx = "U16"; ageLabel = "14-15"; }
            else if (age >= 12 && age <= 13) { ageIdx = "U14"; ageLabel = "12-13"; }
            else if (age >= 10 && age <= 11) { ageIdx = "U12"; ageLabel = "10-11"; }
            else { ageIdx = "U10"; ageLabel = "до 10"; }
        } else {
            if (age >= 18 && age <= 22) { ageIdx = "2"; ageLabel = "18-22"; }
            else if (age >= 23 && age <= 34) { ageIdx = "3"; ageLabel = "23-34"; }
            else if (age >= 35 && age <= 49) { ageIdx = "4"; ageLabel = "35-49"; }
            else if (age >= 50 && age <= 59) { ageIdx = "5"; ageLabel = "50-59"; if (g === 'F') isVet = true; } 
            else if (age >= 60 && age <= 69) { ageIdx = "6"; ageLabel = "60-69"; isVet = true; } 
            else if (age >= 70) { ageIdx = "7"; ageLabel = "70+"; isVet = true; }
        }

        if (logic === 'clusters') {
            if (isJunior) return `[${rusG}] ${ageIdx}`;
            return `[${rusG}] ${cluster}`;
        }
        if (logic === 'age') {
            if (isJunior) return `[${rusG}] ${ageIdx}`;
            return `[${rusG}] ${ageLabel}`;
        }
        if (logic === 'absolute') return 'АБСОЛЮТ';

        if (logic === 'teams') {
            let genders = rider.squad_genders || [];
            if (genders.length === 0) genders.push(String(rider.gender || 'M').toUpperCase().trim());
            const hasM = genders.some(x => x === 'M' || x === 'М');
            const hasF = genders.some(x => x === 'F' || x === 'Ж');
            if (hasM && hasF) return 'МИКСТ';
            if (hasF) return 'ЖЕНЩИНЫ';
            return 'МУЖЧИНЫ';
        }

        if (logic === 'mixed') {
            if (isJunior) return ageIdx + g;
            if (g === 'M') {
                if (isVet) return "VM" + ageIdx;
                if (cluster === 'A+') return "AM+";
                if (cluster === 'E') return "EM";
                return cluster + "M" + ageIdx;
            } else {
                if (isVet) return "VF" + ageIdx;
                if (cluster === 'A+') return "AF+";
                return cluster + "F" + ageIdx;
            }
        }

        return cluster;
    }
    // ==========================================
    // ИМПОРТ РЕЗУЛЬТАТОВ ИЗ CSV
    // ==========================================
triggerCsvImport(raceId) {
        // 🎯 1. Если выбрана конкретная дистанция (например, Спорт 23 км) — заявляем строго в неё
        let targetRaceId = raceId;
        if (this.liveService && this.liveService.liveDistanceFilter && this.liveService.liveDistanceFilter !== 'all') {
            targetRaceId = this.liveService.liveDistanceFilter;
        }

        let fileInput = document.getElementById('csvImportInput');
        if (!fileInput) {
            fileInput = document.createElement('input');
            fileInput.type = 'file';
            fileInput.id = 'csvImportInput';
            fileInput.accept = '.csv';
            fileInput.style.display = 'none';
            document.body.appendChild(fileInput);
        }
        fileInput.onchange = (e) => this.handleCsvFile(e, targetRaceId);
        fileInput.click();
    }

    async handleCsvFile(event, raceId) {
        const file = event.target.files[0];
        if (!file) return;

        // 🎯 2. Защита от null: выводим спиннер туда, где сейчас находится пользователь
        const liveTable = document.getElementById('liveBoardTable');
        const liveModal = document.getElementById('liveBoardModal');
        const contentArea = document.getElementById('crmContentArea');

        if (liveTable && liveModal && liveModal.style.display !== 'none') {
            liveTable.innerHTML = `
                <div style="display:flex; flex-direction:column; align-items:center; justify-content:center; padding:70px 20px; color:var(--text-muted); gap:12px;">
                    <span class="spinner" style="width:30px; height:30px; border-width:3px; display:inline-block; border-color:var(--primary) transparent transparent transparent;"></span>
                    <span style="font-family:'Unbounded', sans-serif; font-size:10px; font-weight:800; text-transform:uppercase; letter-spacing:0.5px;">
                        АНАЛИЗ CSV ПРОТОКОЛА...
                    </span>
                </div>
            `;
        } else if (contentArea) {
            contentArea.innerHTML = `
                <div style="display:flex; flex-direction:column; align-items:center; justify-content:center; height:100%;">
                    <div class="spinner" style="width:40px; height:40px; border-width:4px; display:inline-block; border-color: #a855f7 transparent transparent transparent;"></div>
                    <div style="margin-top:15px; font-family:'Unbounded'; font-size:12px; color:var(--text-main); font-weight:800; text-transform:uppercase;">
                        Анализ CSV протокола...
                    </div>
                </div>
            `;
        }

        const reader = new FileReader();
        reader.onload = async (e) => {
            const text = e.target.result;
            await this.processCsvData(text, raceId);
        };
        reader.readAsText(file); 
        event.target.value = ''; 
    }
    parseTimeToMs(timeStr) {
        if (!timeStr || timeStr === '-' || timeStr.toLowerCase().includes('dnf') || timeStr.toLowerCase().includes('dsq')) return 0;
        let parts = timeStr.split(':');
        if (parts.length === 3) {
            let h = parseInt(parts[0]) || 0;
            let m = parseInt(parts[1]) || 0;
            let sParts = parts[2].split(/[.,]/); 
            let s = parseInt(sParts[0]) || 0;
            let ms = sParts[1] ? parseInt(sParts[1].padEnd(3, '0').slice(0,3)) : 0;
            return (h * 3600000) + (m * 60000) + (s * 1000) + ms;
        } else if (parts.length === 2) {
            let m = parseInt(parts[0]) || 0;
            let sParts = parts[1].split(/[.,]/);
            let s = parseInt(sParts[0]) || 0;
            let ms = sParts[1] ? parseInt(sParts[1].padEnd(3, '0').slice(0,3)) : 0;
            return (m * 60000) + (s * 1000) + ms;
        }
        return 0;
    }

// ==========================================
    // 🔥 ГЛАВНЫЙ ИМПОРТЕР CSV И ВЫЧИСЛИТЕЛЬ ОЧКОВ
    // ==========================================
    async processCsvData(csvText, raceId) {
        try {
            const lines = csvText.split(/\r?\n/);
            if (lines.length < 2) return alert("Файл пуст или имеет неверный формат!");

            // 🔥 ШАГ 3.1: ЗАПРАШИВАЕМ ГОНКУ ВМЕСТЕ С ПРАВИЛОМ РЕЙТИНГА
            const currentRace = await pb.collection('races').getOne(raceId, { expand: 'peloton_id,rating_rule_id', requestKey: null });
            
            const regStatuses = ['registration', 'скоро', 'регистрация', 'draft', 'upcoming', 'open'];
            const isRegistrationPhase = regStatuses.includes((currentRace.status || '').toLowerCase());
            const raceDistance = currentRace.distance || 0;
            
            // 🔥 ШАГ 3.2: ИЗВЛЕКАЕМ АКТИВНЫЕ ПРАВИЛА
            let activeRule = null;
            let ruleType = currentRace.format === 'itt' ? 'ind' : 'mass'; // Базовый фолбэк
            
            if (currentRace.expand?.rating_rule_id) {
                const dbRule = currentRace.expand.rating_rule_id;
                ruleType = dbRule.type || ruleType; // берем тип (mass / ind) из базы
                try {
                    activeRule = typeof dbRule.config === 'string' ? JSON.parse(dbRule.config) : dbRule.config;
                } catch(e) { console.error("Ошибка парсинга JSON правила", e); }
            }

            // Если правило не привязано, используем старую логику (настройки пелотона или дефолт)
            if (!activeRule) {
                let pelotonObj = currentRace.expand?.peloton_id;
                if (Array.isArray(pelotonObj)) pelotonObj = pelotonObj[0]; 
                
                let pelotonRules = this.DEFAULT_RATING_RULES;
                if (pelotonObj && pelotonObj.rating_rules) {
                    try { pelotonRules = typeof pelotonObj.rating_rules === 'string' ? JSON.parse(pelotonObj.rating_rules) : pelotonObj.rating_rules; } catch(e) { }
                }
                activeRule = pelotonRules;
            }

            const isMassStart = (ruleType !== 'ind' && ruleType !== 'itt');

            // 🚴 ОПРЕДЕЛЯЕМ РЕГЛАМЕНТ ДИСТАНЦИИ И ТЕХНИКУ ПО УМОЛЧАНИЮ
            let cl = {};
            try {
                cl = typeof currentRace.cat_logic === 'string' ? JSON.parse(currentRace.cat_logic) : (currentRace.cat_logic || {});
            } catch(e) { cl = {}; }

            let defaultGear = null;
            if (cl.use_gear && Array.isArray(cl.active_gears) && cl.active_gears.length > 0) {
                defaultGear = cl.active_gears[0]; // Например: "ROAD", "GRAVEL", "MTB"
            }

            // ⏱️ ВРЕМЯ СТАРТА: для групповых гонок берем время из даты гонки, для разделок (ITT/TTT) — строго пусто
            const isTimeTrial = currentRace.format === 'itt' || currentRace.format === 'ttt' || currentRace.format === 'relay' || (currentRace.name || '').toUpperCase().includes('DTT');
            let autoPlannedStart = "";
            if (!isTimeTrial && currentRace.date) {
                const rDate = new Date(currentRace.date);
                if (!isNaN(rDate.getTime())) {
                    const hh = String(rDate.getHours()).padStart(2, '0');
                    const mm = String(rDate.getMinutes()).padStart(2, '0');
                    const ss = String(rDate.getSeconds()).padStart(2, '0');
                    autoPlannedStart = `${hh}:${mm}:${ss}`;
                }
            }

            const rosters = await pb.collection('race_rosters').getFullList({ filter: `race_id="${raceId}"`, expand: 'rider_id,rider_id.team_id', requestKey: null });
            const oneTeamObj = Object.values(this.app.teamsMap || {}).find(t => t.name && t.name.toUpperCase().includes('ONE TEAM'));
            const oneTeamId = oneTeamObj ? oneTeamObj.id : null;

            let liveBoard = []; let registeredCount = 0; let guestCount = 0;
            const separator = lines[0].includes(';') ? ';' : ',';

            // Карта распознавания техники из текста CSV
            const GEAR_ALIASES = {
                'ROAD': 'ROAD', 'ШОССЕ': 'ROAD',
                'TT': 'TT', 'ТТ': 'TT', 'РАЗДЕЛКА': 'TT',
                'GRAVEL': 'GRAVEL', 'GRVL': 'GRAVEL', 'ГРЭВЕЛ': 'GRAVEL', 'ГРАВИЙ': 'GRAVEL',
                'CX': 'CX', 'ЦИКЛОКРОСС': 'CX', 'ЦК': 'CX',
                'MTB': 'MTB', 'МТБ': 'MTB',
                'FIX': 'FIX', 'ФИКС': 'FIX',
                'FAT': 'FAT', 'ФЭТ': 'FAT',
                'SS': 'SS', 'СИНГЛСПИД': 'SS',
                'EBIKE': 'EBIKE', 'ЭЛЕКТРО': 'EBIKE'
            };

            // =========================================================
            // 🟢 РЕЖИМ 1: ПРЕДРЕГИСТРАЦИЯ (Заливка старт-листа до гонки)
            // =========================================================
            if (isRegistrationPhase) {
                for (let i = 1; i < lines.length; i++) {
                    let line = lines[i].trim(); if (!line) continue;
                    let cols = line.split(separator); 
                    
                    let bib = cols[1] ? cols[1].trim() : ''; 
                    let fullName = cols[2] ? cols[2].trim() : ''; 
                    let yob = cols[3] ? cols[3].trim() : '';
                    let category = cols[4] ? cols[4].trim() : ''; 
                    
                    if (!fullName) continue;

                    // 🛡️ Умная разбивка: в спорте обычно пишут "Фамилия Имя"
                    let nameParts = fullName.trim().split(/\s+/); 
                    const cap = (s) => s ? s.charAt(0).toUpperCase() + s.slice(1).toLowerCase() : '';
                    let lastName = cap(nameParts[0] || 'Неизвестно');
                    let firstName = nameParts.slice(1).map(cap).join(' ') || '';

                    // Умный поиск команды
                    let teamNameCsv = cols[5] ? cols[5].trim() : '';
                    let assignedTeamId = oneTeamId;

                    if (teamNameCsv) {
                        const matchedTeam = Object.values(this.app.teamsMap || {}).find(t => 
                            t.name && t.name.toLowerCase() === teamNameCsv.toLowerCase()
                        );
                        if (matchedTeam) assignedTeamId = matchedTeam.id;
                    }

                    // 🔍 Умное определение пола (по окончаниям ФИО + проверка пометок в колонке категории)
                    let guessedGender = 'M';
                    const ln = lastName.toLowerCase();
                    const fn = firstName.toLowerCase();
                    const catUpper = (category || '').toUpperCase();

                    if (catUpper.includes('[Ж]') || catUpper.includes('ЖЕН') || catUpper === 'F' || catUpper === 'Ж') {
                        guessedGender = 'F';
                    } else if (catUpper.includes('[М]') || catUpper.includes('МУЖ') || catUpper === 'M' || catUpper === 'М') {
                        guessedGender = 'M';
                    } else if (ln.endsWith('ва') || ln.endsWith('на') || ln.endsWith('ая') || ln.endsWith('ская') || ln.endsWith('ина') || ln.endsWith('ова') || ln.endsWith('ева')) {
                        guessedGender = 'F';
                    } else if ((fn.split(' ')[0].endsWith('а') || fn.split(' ')[0].endsWith('я')) && !['илья', 'никита', 'данила', 'савва', 'кузьма', 'фома', 'лука', 'миша', 'саша', 'коля', 'дима', 'леша'].includes(fn.split(' ')[0])) {
                        guessedGender = 'F';
                    }

                    let riderId = null;
                    let existingRider = Object.values(this.app.ridersMap || {}).find(r => 
                        (r.first_name + ' ' + r.last_name).toLowerCase() === (firstName + ' ' + lastName).toLowerCase() ||
                        (r.last_name + ' ' + r.first_name).toLowerCase() === (lastName + ' ' + firstName).toLowerCase()
                    );

                    let riderGender = guessedGender;
                    let riderYob = parseInt(yob) || 1990;
                    let riderCluster = '';

                    if (existingRider) {
                        riderId = existingRider.id;
                        riderGender = existingRider.gender ? String(existingRider.gender).toUpperCase().trim() : guessedGender;
                        riderYob = parseInt(existingRider.yob) || riderYob;
                        riderCluster = existingRider.base_cluster || '';
                    } else {
                        try {
                            const validClusters = ['A+', 'A', 'B', 'C', 'D'];
                            const assignedCluster = validClusters.includes((category || '').toUpperCase()) ? category.toUpperCase() : '';
                            riderCluster = assignedCluster;

                            const newRider = await pb.collection('riders').create({
                                first_name: firstName, 
                                last_name: lastName, 
                                yob: riderYob,
                                gender: riderGender, 
                                base_cluster: assignedCluster, 
                                team_id: assignedTeamId ? [assignedTeamId] : [], 
                                email: `rider_${Date.now()}_${Math.random().toString(36).substring(2,6)}@sotka.one`, 
                                rating: 0
                            }, { requestKey: null });

                            riderId = newRider.id;
                            if (this.app?.ridersMap) this.app.ridersMap[riderId] = newRider;
                            guestCount++;
                        } catch(e) { console.error("Ошибка автосоздания атлета", e); continue; }
                    }

                    // 🚴 Распознавание типа техники для строки:
                    let rowGear = null;
                    const textToScan = `${category} ${fullName} ${teamNameCsv}`.toUpperCase();
                    for (const [alias, gearVal] of Object.entries(GEAR_ALIASES)) {
                        const regex = new RegExp(`(^|[^a-zA-Zа-яА-Я0-9])(${alias})([^a-zA-Zа-яА-Я0-9]|$)`, 'i');
                        if (regex.test(textToScan)) {
                            rowGear = gearVal;
                            break;
                        }
                    }
                    if (!rowGear && cl.use_gear) {
                        rowGear = defaultGear; // Берем технику дистанции по умолчанию
                    }

                    // 🎯 РАСЧЕТ КАНОНИЧЕСКОЙ КАТЕГОРИИ (например: [М] ШОССЕ • 30-39)
                    let finalRosterCategory = category;
                    if (category && category.includes('[') && category.includes('•')) {
                        finalRosterCategory = category; // Если в CSV уже была вбита полная категория Вилки
                    } else if (typeof this.getRaceCategory === 'function') {
                        try {
                            const calculated = this.getRaceCategory({
                                gender: riderGender,
                                yob: riderYob,
                                base_cluster: riderCluster || 'B',
                                gear: rowGear,
                                final_cluster: category,
                                id: riderId
                            }, currentRace);
                            if (calculated && calculated !== '???') {
                                finalRosterCategory = calculated;
                            }
                        } catch (err) {
                            console.warn("Ошибка расчета категории:", err);
                        }
                    }

                    let alreadyInRoster = rosters.find(r => r.rider_id === riderId);
                    
                    if (!alreadyInRoster && riderId) {
                        await pb.collection('race_rosters').create({
                            race_id: raceId,
                            rider_id: riderId,
                            bib: bib,
                            final_cluster: finalRosterCategory, // 👈 Записываем полную категорию с велосипедом!
                            planned_start: autoPlannedStart,     // 👈 Время старта для масс-старта
                            status: 'registered'
                        }, { requestKey: null });
                        registeredCount++;
                    } else if (alreadyInRoster) {
                        const updatePayload = {};
                        if (bib && !alreadyInRoster.bib) updatePayload.bib = bib;
                        if (!alreadyInRoster.final_cluster || !alreadyInRoster.final_cluster.includes('[')) {
                            updatePayload.final_cluster = finalRosterCategory;
                        }
                        if (autoPlannedStart && !alreadyInRoster.planned_start) {
                            updatePayload.planned_start = autoPlannedStart;
                        }
                        if (Object.keys(updatePayload).length > 0) {
                            await pb.collection('race_rosters').update(alreadyInRoster.id, updatePayload, { requestKey: null });
                        }
                    }
                }

                alert(`✅ Старт-лист успешно загружен!\n\nДобавлено новых заявок: ${registeredCount}\nСоздано новых профилей: ${guestCount}\nКатегории и техника синхронизированы.`);

                // 🎯 Мгновенно перерисовываем открытый Live-борд
                if (this.liveService && (document.getElementById('liveBoardModal')?.style.display === 'flex' || this.liveService.expandedRaceId)) {
                    await this.liveService.openLiveBoard(this.liveService.expandedRaceId || raceId);
                } else if (typeof this.openRaceRoster === 'function') {
                    this.openRaceRoster(raceId, this.openedEventName, this.openedEventType);
                }
                return;
            }

            // =========================================================
            // 🔴 РЕЖИМ 2: ПОДВЕДЕНИЕ ИТОГОВ (Гонка в статусе LIVE)
            // =========================================================
            for (let i = 1; i < lines.length; i++) {
                let line = lines[i].trim(); if (!line) continue;
                let cols = line.split(separator); 
                
                let bib = cols[1] ? cols[1].trim() : ''; 
                let name = cols[2] ? cols[2].trim() : ''; 
                let yob = cols[3] ? cols[3].trim() : '';
                let category = cols[4] ? cols[4].trim() : ''; 
                let team = cols[5] ? cols[5].trim() : '';
                let laps = parseInt(cols[6]) || 0; 
                let timeStr = cols[7] ? cols[7].trim() : '';
                
                let timeMs = this.parseTimeToMs(timeStr);
                let speed = (raceDistance > 0 && timeMs > 0) ? (raceDistance / (timeMs / 3600000)).toFixed(2) : 0;

                let matchedRoster = rosters.find(r => r.bib === bib);
                if (!matchedRoster && name) {
                    let nameParts = name.trim().split(/\s+/);
                    let tryName1 = (nameParts.slice(1).join(' ') + ' ' + nameParts[0]).toLowerCase();
                    let tryName2 = (nameParts[0] + ' ' + nameParts.slice(1).join(' ')).toLowerCase();
                    matchedRoster = rosters.find(r => {
                        let dbName = (r.expand?.rider_id?.first_name + ' ' + r.expand?.rider_id?.last_name).toLowerCase();
                        return dbName === tryName1 || dbName === tryName2;
                    });
                }

                let earnedPoints = 0;
                let currentCluster = matchedRoster?.expand?.rider_id?.base_cluster || 'O';
                let newCluster = currentCluster; 
                let riderGender = matchedRoster?.expand?.rider_id?.gender || 'M';
                let position = i; 

                // 🔥 ШАГ 3.3: ПРИМЕНЕНИЕ ДИНАМИЧЕСКИХ ПРАВИЛ ПРИ РАСЧЕТЕ ОЧКОВ
                if (isMassStart) {
                    const clusterBanks = activeRule.banks || activeRule.mass_start_banks || this.DEFAULT_RATING_RULES.mass_start_banks;
                    const decay = activeRule.decay_factor || 0.85;

                    let baseBank = clusterBanks[currentCluster] || clusterBanks['B'] || 400;
                    earnedPoints = Math.max(1, Math.round(baseBank * Math.pow(decay, position - 1)));

                    if (position <= 3) {
                        const upgrades = { 'O':'D', 'D':'C', 'C':'B', 'B':'A', 'A':'A+' };
                        if (upgrades[currentCluster]) newCluster = upgrades[currentCluster];
                    }
                } else {
                    if (speed > 0) {
                        const multiplier = activeRule.multiplier || 1.0;
                        earnedPoints = Math.round(parseFloat(speed) * raceDistance * multiplier);
                        newCluster = this.getClusterBySpeed(speed, riderGender, currentRace.surface, activeRule);
                    }
                }

                // 🛡️ Защита от качелей: Кластер не может упасть, только вырасти
                const clusterRanks = { 'O':0, 'E':1, 'D':2, 'C':3, 'B':4, 'A':5, 'A+':6, 'V':7 };
                if (clusterRanks[newCluster] <= clusterRanks[currentCluster]) {
                    newCluster = currentCluster; 
                }
                
                // 🚴 Распознавание техники для результатов финиша
                let rowGear = null;
                const textToScan = `${category} ${name} ${team}`.toUpperCase();
                for (const [alias, gearVal] of Object.entries(GEAR_ALIASES)) {
                    const regex = new RegExp(`(^|[^a-zA-Zа-яА-Я0-9])(${alias})([^a-zA-Zа-яА-Я0-9]|$)`, 'i');
                    if (regex.test(textToScan)) {
                        rowGear = gearVal;
                        break;
                    }
                }
                if (!rowGear && cl.use_gear) {
                    rowGear = defaultGear;
                }

                let generatedCategory = this.getRaceCategory(
                    { gender: riderGender, yob: parseInt(yob) || 1990, base_cluster: newCluster, gear: rowGear, final_cluster: category },
                    currentRace
                );

                // Если в росторе уже была сохранена полная категория (например, [М] ШОССЕ • 30-39), не ломаем её сырым значением из финишного CSV
                let finalDisplayCluster = (matchedRoster?.final_cluster && matchedRoster.final_cluster.includes('['))
                    ? matchedRoster.final_cluster
                    : (generatedCategory || category);

                // Запись результатов
                if (matchedRoster) {
                    registeredCount++;
                    let status = (timeStr.toLowerCase().includes('dnf') || timeStr === '') ? 'dnf' : 'finished';
                    
                    await pb.collection('race_rosters').update(matchedRoster.id, { 
                        status: status, 
                        time_ms: timeMs, 
                        speed: Number(speed), 
                        earned_points: earnedPoints, 
                        final_cluster: finalDisplayCluster 
                    }, { requestKey: null });

                    if (status === 'finished') {
                        try {
                            const rData = matchedRoster.expand?.rider_id;
                            if (rData) {
                                let updatePayload = { rating: (rData.rating || 0) + earnedPoints, base_cluster: newCluster };
                                const surfKey = `rating_${currentRace.surface}`;
                                if (rData[surfKey] !== undefined) updatePayload[surfKey] = rData[surfKey] + earnedPoints;
                                await pb.collection('riders').update(rData.id, updatePayload, { requestKey: null });
                            }
                        } catch (err) {}
                    }

                    let finalTeamName = team;
                    if (!finalTeamName && matchedRoster.expand?.rider_id) {
                        finalTeamName = this.getRiderTeamNames(matchedRoster.expand.rider_id);
                    }
                    if (!finalTeamName) finalTeamName = 'Без команды';

                    liveBoard.push({ 
                        baseCluster: matchedRoster.expand?.rider_id?.base_cluster || 'B', 
                        bib: bib || matchedRoster.bib, 
                        category: finalDisplayCluster, 
                        lapTimes: timeMs > 0 ? [timeMs] : [], 
                        laps: laps, 
                        name: name || (matchedRoster.expand?.rider_id?.last_name + ' ' + matchedRoster.expand?.rider_id?.first_name), 
                        yob: yob || matchedRoster.expand?.rider_id?.yob || '', 
                        recCluster: newCluster, 
                        speed: speed.toString(), 
                        team: finalTeamName, 
                        timeStr: timeStr || status.toUpperCase(), 
                        points: earnedPoints 
                    });
                } else {
                    guestCount++;
                    liveBoard.push({ 
                        baseCluster: 'O', 
                        bib: bib, 
                        category: finalDisplayCluster, 
                        lapTimes: timeMs > 0 ? [timeMs] : [], 
                        laps: laps, 
                        name: name, 
                        yob: yob, 
                        recCluster: '-', 
                        speed: speed.toString(), 
                        team: team || 'Без команды', 
                        timeStr: timeStr, 
                        points: earnedPoints 
                    });
                }
            }

            await pb.collection('races').update(raceId, { status: 'Finished', live_board: liveBoard }, { requestKey: null });
            alert(`✅ Финишный протокол успешно загружен!\n\nОбновлено заявок: ${registeredCount}\nДобавлено гостей (без рейтинга): ${guestCount}\nГонка переведена в статус "Завершена". Очки и кластеры начислены по выбранным правилам.`);
            
            if (typeof window.app.openLiveBoard === 'function') window.app.openLiveBoard(raceId); else this.switchView('calendar');
            
        } catch(e) { 
            console.error(e);
            alert("❌ Ошибка при чтении CSV. Убедитесь, что формат правильный."); 
            this.openRaceRoster(raceId, this.openedEventName, this.openedEventType); 
        }
    }	
	// ==========================================
        // 🔥 УПРАВЛЕНИЕ БИБЛИОТЕКОЙ ПРАВИЛ (СУПЕРАДМИН)
        // ==========================================
        openRuleModal(id = null) {
            const m = document.getElementById('ruleEditModal');
            if (!m) return;
            
            if (id) {
                const r = this.dataRules.find(x => x.id === id);
                if (!r) return;
                document.getElementById('ruleModalTitle').innerText = 'РЕДАКТИРОВАНИЕ ПРАВИЛА';
                document.getElementById('ruleId').value = r.id;
                document.getElementById('ruleName').value = r.name;
                document.getElementById('ruleDesc').value = r.description || '';
                document.getElementById('ruleType').value = r.type;
                document.getElementById('ruleSurface').value = r.surface;
                document.getElementById('ruleConfig').value = r.config;
            } else {
                document.getElementById('ruleModalTitle').innerText = 'НОВОЕ ПРАВИЛО';
                document.getElementById('ruleId').value = '';
                document.getElementById('ruleName').value = '';
                document.getElementById('ruleDesc').value = '';
                document.getElementById('ruleType').value = 'mass';
                document.getElementById('ruleSurface').value = 'road';
                this.fillRuleTemplate();
            }
            m.style.display = 'flex';
        }

        fillRuleTemplate(confirmOverwrite = false) {
            const configEl = document.getElementById('ruleConfig');
            if (confirmOverwrite && configEl.value.trim() !== '') {
                if (!confirm("Заменить текущую конфигурацию стандартным шаблоном для выбранного типа?")) return;
            }
            
            const type = document.getElementById('ruleType').value;
            let tpl = '';
            if (type === 'mass') {
                tpl = `{\n  "banks": {\n    "A+": 1000,\n    "A": 800,\n    "B": 600,\n    "C": 400,\n    "D": 200,\n    "O": 200,\n    "V": 400\n  },\n  "decay_factor": 0.85\n}`;
            } else {
                tpl = `{\n  "multiplier": 1.0,\n  "thresholds": {\n    "M": {\n      "A+": 40.0,\n      "A": 37.0,\n      "B": 34.0,\n      "C": 30.0,\n      "D": 26.0\n    },\n    "F": {\n      "A+": 36.0,\n      "A": 33.0,\n      "B": 30.0,\n      "C": 26.0,\n      "D": 22.0\n    }\n  }\n}`;
            }
            configEl.value = tpl;
        }

        async saveRule() {
            const id = document.getElementById('ruleId').value;
            const name = document.getElementById('ruleName').value.trim();
            const desc = document.getElementById('ruleDesc').value.trim();
            const type = document.getElementById('ruleType').value;
            const surface = document.getElementById('ruleSurface').value;
            const config = document.getElementById('ruleConfig').value.trim();

            if (!name) return alert("Введите название правила!");
            if (!config) return alert("Конфигурация не может быть пустой!");

            // 🔥 Защита: проверяем валидность JSON перед сохранением!
            try {
                JSON.parse(config);
            } catch (e) {
                return alert("❌ Ошибка в формате JSON!\nУбедитесь, что нет лишних запятых, а все ключи в двойных кавычках.\n\n" + e.message);
            }

            const data = { name, description: desc, type, surface, config };

            try {
                if (id) {
                    await pb.collection('rating_rules').update(id, data, { requestKey: null });
                    alert("✅ Правило обновлено!");
                } else {
                    await pb.collection('rating_rules').create(data, { requestKey: null });
                    alert("✅ Правило создано!");
                }
                document.getElementById('ruleEditModal').style.display = 'none';
                this.loadData(); // Перезагружаем список
            } catch(e) {
                console.error(e);
                alert("Ошибка сохранения в базу.");
            }
        }

        async deleteRule(id) {
            if (!confirm("⚠️ Вы уверены, что хотите удалить это правило? Гонки, привязанные к нему, перейдут на стандартный (базовый) расчет.")) return;
            try {
                await pb.collection('rating_rules').delete(id, { requestKey: null });
                this.loadData();
            } catch(e) {
                alert("Ошибка удаления!");
            }
        }


// ==========================================
    // 📸 ГЕНЕРАТОР ФОТО-ПОСТЕРОВ ДЛЯ СОЦСЕТЕЙ
    // ==========================================
    async generateRacePoster(raceId, riderId = null) {
        // 🔥 ДЕЛАЕМ КАК ТЫ СКАЗАЛ: ПРОСТО И НАДЕЖНО БЕРЕМ ИЗ БАЗЫ
        let race;
        try {
            race = await pb.collection('races').getOne(raceId, { requestKey: null });
        } catch(e) {
            return alert("Гонка не найдена в базе данных.");
        }

        const input = document.createElement('input');
        input.type = 'file';
        input.accept = 'image/*';
        input.setAttribute('capture', 'environment'); 
        input.style.position = 'absolute';
        input.style.top = '-10000px';
        document.body.appendChild(input);

        input.onchange = async (e) => {
            const file = e.target.files[0];
            if (!file) { document.body.removeChild(input); return; }

            // ГЛОБАЛЬНЫЙ СПИННЕР
            const loaderId = 'posterGlobalLoader';
            let loaderEl = document.getElementById(loaderId);
            if (!loaderEl) {
                loaderEl = document.createElement('div');
                loaderEl.id = loaderId;
                loaderEl.className = 'modal-overlay';
                loaderEl.style.display = 'flex';
                loaderEl.style.zIndex = '9999999';
                loaderEl.innerHTML = `<div style="display:flex; flex-direction:column; align-items:center; justify-content:center;"><div class="spinner" style="width:50px; height:50px; border-width:4px; border-color: var(--primary) transparent transparent transparent;"></div><div style="margin-top:20px; font-family:'Unbounded'; font-size:14px; color:var(--primary); font-weight:800; text-shadow: 0 2px 10px rgba(0,0,0,0.5);">СОЗДАЕМ ИСТОРИЮ...</div></div>`;
                document.body.appendChild(loaderEl);
            } else {
                loaderEl.style.display = 'flex';
            }

            try {
                const imgUrl = URL.createObjectURL(file);
                const img = await this.loadImage(imgUrl);
                
                const canvas = document.createElement('canvas');
                canvas.width = 1080;
                canvas.height = 1920;
                const ctx = canvas.getContext('2d');

                // 4. Фон
                const scale = Math.max(canvas.width / img.width, canvas.height / img.height);
                const x = (canvas.width / 2) - (img.width / 2) * scale;
                const y = (canvas.height / 2) - (img.height / 2) * scale;
                ctx.drawImage(img, x, y, img.width * scale, img.height * scale);

                // 5. Градиент
                const gradient = ctx.createLinearGradient(0, canvas.height * 0.3, 0, canvas.height);
                gradient.addColorStop(0, 'rgba(0, 0, 0, 0)');
                gradient.addColorStop(0.5, 'rgba(0, 0, 0, 0.7)');
                gradient.addColorStop(1, 'rgba(0, 0, 0, 0.95)');
                ctx.fillStyle = gradient;
                ctx.fillRect(0, 0, canvas.width, canvas.height);

                const drawRoundRect = (ctx, x, y, w, h, r, fill, stroke) => {
                    ctx.beginPath(); ctx.moveTo(x + r, y); ctx.lineTo(x + w - r, y); ctx.quadraticCurveTo(x + w, y, x + w, y + r);
                    ctx.lineTo(x + w, y + h - r); ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h); ctx.lineTo(x + r, y + h);
                    ctx.quadraticCurveTo(x, y + h, x, y + h - r); ctx.lineTo(x, y + r); ctx.quadraticCurveTo(x, y, x + r, y); ctx.closePath();
                    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
                    if (stroke) { ctx.strokeStyle = stroke; ctx.stroke(); }
                };

                // 6. Бейджи
                const badgeY = canvas.height - 580;
                ctx.font = 'bold 30px "Unbounded", sans-serif';
                ctx.textBaseline = 'middle';
                
                let displayType = (race.type || 'ГОНКА').toUpperCase();
                if (race.type === 'ind') displayType = 'ITT';
                if (race.type === 'mass') displayType = 'МАСС-СТАРТ';

                const distText = (race.distance || 0) + ' КМ';
                
                const typeW = ctx.measureText(displayType).width + 60;
                const distW = ctx.measureText(distText).width + 60;

                ctx.lineWidth = 2;
                drawRoundRect(ctx, 80, badgeY, typeW, 60, 30, 'rgba(255,255,255,0.12)', 'rgba(255,255,255,0.3)');
                drawRoundRect(ctx, 80 + typeW + 20, badgeY, distW, 60, 30, 'rgba(255,255,255,0.12)', 'rgba(255,255,255,0.3)');
                
                ctx.fillStyle = '#FFC107';
                ctx.textAlign = 'center';
                ctx.fillText(displayType, 80 + typeW/2, badgeY + 32);
                ctx.fillText(distText, 80 + typeW + 20 + distW/2, badgeY + 32);

                // 7. Название и ДАТА
                ctx.textAlign = 'left';
                ctx.textBaseline = 'top';
                ctx.fillStyle = '#FFFFFF';
                ctx.font = 'bold 95px "Unbounded", sans-serif';
                ctx.fillText((race.name || 'СОРЕВНОВАНИЕ').toUpperCase(), 80, canvas.height - 500);

                // 🔥 ПРОСТАЯ И НАДЕЖНАЯ ДАТА НАПРЯМУЮ ИЗ БД
                let fullDateText = "ДАТА НЕ УКАЗАНА";
                if (race.date) {
                    const d = new Date(race.date);
                    if (!isNaN(d.getTime())) {
                        const day = d.getDate();
                        const month = d.toLocaleDateString('ru-RU', { month: 'long' });
                        const year = d.getFullYear();
                        fullDateText = `${day} ${month} ${year}`.toUpperCase();
                    } else {
                        // Фолбэк: если в базе лежит просто текст (например, "Скоро")
                        fullDateText = race.date.toUpperCase();
                    }
                }
                
                ctx.fillStyle = '#FFC107'; 
                ctx.font = 'bold 38px "Unbounded", sans-serif';
                ctx.fillText(fullDateText, 80, canvas.height - 380);

                // 8. Результаты
                let shareText = '';
                let roster = null;
                if (riderId) {
                    try { roster = await pb.collection('race_rosters').getFirstListItem(`race_id="${race.id}" && rider_id="${riderId}"`, { expand: 'rider_id', requestKey: null }); } catch (e) {}
                }

                if (roster && roster.status === 'finished') {
                    let timeStr = 'DNF';
                    if (roster.time_ms > 0) {
                        const h = Math.floor(roster.time_ms / 3600000);
                        const m = Math.floor((roster.time_ms % 3600000) / 60000).toString().padStart(2, '0');
                        const s = Math.floor((roster.time_ms % 60000) / 1000).toString().padStart(2, '0');
                        timeStr = h > 0 ? `${h}:${m}:${s}` : `${m}:${s}`;
                    }

                    const gridY = canvas.height - 280;
                    drawRoundRect(ctx, 80, gridY, 920, 160, 24, 'rgba(255,255,255,0.06)', 'rgba(255,255,255,0.2)');

                    ctx.strokeStyle = 'rgba(255,255,255,0.1)';
                    ctx.beginPath();
                    ctx.moveTo(80 + 920/3, gridY + 30); ctx.lineTo(80 + 920/3, gridY + 130);
                    ctx.moveTo(80 + 920*2/3, gridY + 30); ctx.lineTo(80 + 920*2/3, gridY + 130);
                    ctx.stroke();

                    ctx.fillStyle = '#8a8d9b';
                    ctx.font = 'bold 24px "Unbounded", sans-serif';
                    ctx.textAlign = 'center';
                    ctx.fillText('ВРЕМЯ', 80 + 920/6, gridY + 35);
                    ctx.fillText('ОЧКИ', 80 + 920/2, gridY + 35);
                    ctx.fillText('ГРУППА', 80 + 920*5/6, gridY + 35);

                    ctx.fillStyle = '#00e676';
                    ctx.font = 'bold 55px "Roboto Mono", monospace';
                    ctx.fillText(timeStr, 80 + 920/6, gridY + 85);
                    ctx.fillText('+' + (roster.earned_points || 0), 80 + 920/2, gridY + 85);
                    
                    ctx.fillStyle = '#FFFFFF';
                    ctx.fillText(roster.final_cluster || roster.expand?.rider_id?.base_cluster || 'O', 80 + 920*5/6, gridY + 85);

                    shareText = `Мой результат на ${race.name}: ${timeStr}. Протоколы в VILKA!`;
                } else {
                    ctx.fillStyle = '#FFFFFF';
                    ctx.font = 'bold 75px "Unbounded", sans-serif';
                    ctx.textAlign = 'left';
                    ctx.fillText('Я УЧАСТВУЮ! 🚀', 80, canvas.height - 240);
                    shareText = `Я в деле! Зарегистрировался на гонку ${race.name}. Жду на старте!`;
                }

                ctx.fillStyle = 'rgba(255,255,255,0.4)';
                ctx.font = 'bold 28px "Unbounded", sans-serif';
                ctx.textAlign = 'center';
                ctx.fillText('vilka.sotka.one', canvas.width/2, canvas.height - 60);

                const blob = await new Promise(resolve => canvas.toBlob(resolve, 'image/jpeg', 0.90));
                const posterFile = new File([blob], `story_${Date.now()}.jpg`, { type: "image/jpeg" });
                
                if (this.app && this.app.currentRider) {
                    try {
                        const formData = new FormData();
                        const fresh = await pb.collection('riders').getOne(this.app.currentRider.id, { requestKey: null });
                        const oldStories = fresh.stories || [];
                        
       
                 if (oldStories.length >= 10) {
                            formData.append('stories-', oldStories[0]);
                        }
                        formData.append('stories', posterFile);

                        const updated = await pb.collection('riders').update(this.app.currentRider.id, formData);

                        this.app.currentRider = updated;
                        this.app.ridersMap[updated.id] = updated;

                        await new Promise(resolve => setTimeout(resolve, 500));

                        if (typeof this.app.renderProfileHeader === 'function') this.app.renderProfileHeader();
                        if (typeof this.app.renderChatList === 'function') this.app.renderChatList(document.getElementById('chatSearch')?.value || "");

                    } catch (uploadErr) {
                        console.error("Ошибка загрузки в базу:", uploadErr);
                        alert("История создана, но не загрузилась в профиль (проверьте интернет).");
                    }
                }

                loaderEl.style.display = 'none';

                const dataUrl = canvas.toDataURL('image/jpeg', 0.90);
                this.app.showPosterPreviewModal(dataUrl, race, shareText);

            } catch (e) {
                console.error(e);
                alert("Ошибка генерации: " + e.message);
                loaderEl.style.display = 'none';
            }
            document.body.removeChild(input);
        };
        input.click();
    }

    loadImage(src) {
        return new Promise((resolve, reject) => {
            const img = new Image();
            img.onload = () => resolve(img);
            img.onerror = () => reject(new Error("Не удалось загрузить картинку"));
            img.src = src;
        });
    }


	// ==========================================
    // 🗂️ ВЫЗОВ ШТОРКИ СОЗДАНИЯ ИСТОРИЙ (ПРЯМОЙ ЗАПРОС В БД)
    // ==========================================
    async openStoryCreatorMenu() {
        const modal = document.getElementById('storyCreatorModal');
        const listEl = document.getElementById('storyCreatorList');
        
        if (!modal || !listEl || !this.app.currentRider) return;

        // Показываем спиннер загрузки
        listEl.innerHTML = `<div style="text-align:center; padding:40px;"><span class="spinner" style="width:30px; height:30px; border-width:3px; display:inline-block; border-color: var(--primary) transparent transparent transparent;"></span></div>`;
        modal.style.display = 'flex';

        try {
            const myRegs = await pb.collection('race_rosters').getFullList({
                filter: `rider_id="${this.app.currentRider.id}" && status != "canceled"`,
                expand: 'race_id',
                requestKey: null
            });

            let myRaces = myRegs.map(reg => {
                let race = reg.expand?.race_id;
                if (race) {
                    race.myRosterStatus = reg.status; 
                    
                    // 🔥 1. ВОЗВРАЩАЕМ ГОД: Ручной парсинг даты из PocketBase (100% защита от ошибок iOS)
                    let fDate = "Дата не указана";
                    if (race.date && race.date.length >= 10) {
                        const [y, m, d] = race.date.substring(0, 10).split('-');
                        const months = ['января', 'февраля', 'марта', 'апреля', 'мая', 'июня', 'июля', 'августа', 'сентября', 'октября', 'ноября', 'декабря'];
                        const mIndex = parseInt(m, 10) - 1;
                        if (mIndex >= 0 && mIndex <= 11) {
                            fDate = `${parseInt(d, 10)} ${months[mIndex]} ${y}`; // Теперь год на месте!
                        }
                    }
                    race.formattedDate = fDate;

                    // 🔥 2. БЕРЕМ ФОРМАТ ИЗ НОВОГО СЛОВАРЯ
race.displayType = this.RACE_FORMATS[race.format] || 'ГОНКА';

                    return race;
                }
                return null;
            }).filter(Boolean);

            if (myRaces.length === 0) {
                listEl.innerHTML = `
                    <div style="text-align:center; padding:40px 20px; background:var(--bg-body); border-radius:16px; border:1px dashed var(--border);">
                        <div style="font-size:30px; margin-bottom:10px;">🚷</div>
                        <div style="color:var(--text-main); font-family:'Unbounded'; font-size:12px; margin-bottom:5px;">ВЫ ПОКА НЕ В ДЕЛЕ</div>
                        <div style="color:var(--text-muted); font-size:11px;">Заявитесь на любую гонку в календаре, чтобы создавать постеры.</div>
                    </div>`;
                return;
            }

            myRaces.sort((a, b) => new Date(b.date) - new Date(a.date));

            let html = '';
            myRaces.forEach(r => {
                const isFinished = (r.status === 'Finished' || r.myRosterStatus === 'finished');
                const statusBadge = isFinished 
                    ? `<span style="background:rgba(0,230,118,0.1); color:var(--success); border:1px solid rgba(0,230,118,0.3); padding:4px 8px; border-radius:6px; font-size:9px; font-weight:bold; font-family:'Unbounded';">🏁 РЕЗУЛЬТАТ</span>` 
                    : `<span style="background:rgba(255,193,7,0.1); color:var(--primary); border:1px solid rgba(255,193,7,0.3); padding:4px 8px; border-radius:6px; font-size:9px; font-weight:bold; font-family:'Unbounded';">🚀 ЖДУ СТАРТА</span>`;

                html += `
                <div onclick="document.getElementById('storyCreatorModal').style.display='none'; window.app.crm.generateRacePoster('${r.id}', '${this.app.currentRider.id}');" 
                     style="display:flex; justify-content:space-between; align-items:center; background:var(--bg-body); border:1px solid var(--border); padding:16px; border-radius:16px; cursor:pointer; transition:0.2s; margin-bottom:10px;" 
                     onmouseover="this.style.borderColor='var(--primary)'; this.style.transform='translateY(-2px)';" 
                     onmouseout="this.style.borderColor='var(--border)'; this.style.transform='translateY(0)';">
                    
                    <div style="display:flex; flex-direction:column; gap:6px;">
                        <b style="color:var(--text-main); font-family:'Unbounded'; font-size:13px; text-transform:uppercase;">${r.name}</b>
                        <div style="display:flex; gap:8px; align-items:center;">
                            <span style="color:var(--text-muted); font-size:10px; font-family:'Roboto Mono'; background:var(--bg-surface-hover); padding:2px 6px; border-radius:4px;">${r.formattedDate}</span>
                            <span style="color:var(--text-muted); font-size:10px; font-family:'Roboto Mono'; background:var(--bg-surface-hover); padding:2px 6px; border-radius:4px;">${r.displayType}</span>
                        </div>
                    </div>
                    <div>${statusBadge}</div>
                </div>`;
            });
            listEl.innerHTML = html;

        } catch (e) {
            console.error("Ошибка загрузки заявок для шторки:", e);
            listEl.innerHTML = `<div style="text-align:center; color:var(--danger); padding:20px; font-size:12px;">Ошибка загрузки данных.</div>`;
        }
    }

    
	
	// ==========================================
    // 🎞️ ПРОСМОТРЩИК ИСТОРИЙ (STORY VIEWER)
    // ==========================================
    async openStoryViewer(riderId) {
        const modal = document.getElementById('storyViewerModal');
        if (!modal) return;

        try {
            // Запрашиваем актуальные данные гонщика
            const rider = await pb.collection('riders').getOne(riderId, { requestKey: null });
            
            if (!rider.stories || rider.stories.length === 0) {
                // Если историй нет (например, удалил)
                if (rider.id === this.app.currentRider?.id) {
                    this.openStoryCreatorMenu();
                } else {
                    alert("У этого пользователя больше нет историй.");
                }
                return;
            }

            // Настраиваем состояние плеера
            this.currentStoryRider = rider;
            this.currentStoryIndex = 0;
            this.storyTimer = null;

            // Заполняем шапку
            document.getElementById('storyViewerName').innerText = `${rider.first_name} ${rider.last_name}`;
            document.getElementById('storyViewerAvatar').innerText = (rider.first_name[0] || '') + (rider.last_name[0] || '');

            modal.style.display = 'flex';
            this.renderStoryFrame();

        } catch (e) {
            console.error("Ошибка загрузки историй", e);
            alert("Не удалось загрузить истории.");
        }
    }

    renderStoryFrame() {
        const rider = this.currentStoryRider;
        if (!rider || !rider.stories) return this.closeStoryViewer();

        const stories = rider.stories;
        const index = this.currentStoryIndex;

        // Рисуем полоски прогресса
        const progressContainer = document.getElementById('storyProgressBarContainer');
        let barsHtml = '';
        for (let i = 0; i < stories.length; i++) {
            let bg = 'rgba(255,255,255,0.3)'; // Будущие (полупрозрачные)
            if (i < index) bg = '#fff'; // Просмотренные (белые)
            
            barsHtml += `
            <div style="flex: 1; height: 3px; background: ${bg}; border-radius: 3px; overflow: hidden; position: relative;">
                ${i === index ? '<div id="activeStoryProgress" style="position:absolute; top:0; left:0; height:100%; width:0%; background:#fff;"></div>' : ''}
            </div>`;
        }
        progressContainer.innerHTML = barsHtml;

        // Загружаем картинку
        const imgEl = document.getElementById('storyViewerImage');
        imgEl.src = pb.files.getURL(rider, stories[index]);

        // 🔥 ПОКАЗЫВАЕМ ИЛИ ПРЯЧЕМ КНОПКИ УПРАВЛЕНИЯ
        const controls = document.getElementById('myStoryControls');
        if (controls) {
            controls.style.display = (rider.id === this.app.currentRider?.id) ? 'flex' : 'none';
        }

        // Запускаем анимацию и таймер (5 секунд на историю)
        this.startStoryTimer();
    }

    // ==========================================
    // 🗑️ УДАЛЕНИЕ ИСТОРИИ ИЗ POCKETBASE
    // ==========================================
    async deleteCurrentStory() {
        if (!this.currentStoryRider) return;
        if (!confirm("Удалить эту историю? Это действие нельзя отменить.")) return;

        // Останавливаем таймер, чтобы история не перелистнулась во время удаления
        if (this.storyTimer) clearInterval(this.storyTimer);

        const filename = this.currentStoryRider.stories[this.currentStoryIndex];
        const controls = document.getElementById('myStoryControls');
        if (controls) controls.style.opacity = '0.5';

        try {
            const formData = new FormData();
            // 🔥 В PocketBase удаление файла из массива делается добавлением минуса к имени поля
            formData.append('stories-', filename);
            
            const updated = await pb.collection('riders').update(this.currentStoryRider.id, formData);
            
            // Обновляем память приложения
            this.app.currentRider = updated;
            this.app.ridersMap[updated.id] = updated;
            this.currentStoryRider = updated;

            // Перерисовываем интерфейс (убираем кольцо, если историй 0)
            if (typeof this.app.renderProfileHeader === 'function') this.app.renderProfileHeader();
            if (typeof this.app.renderChatList === 'function') this.app.renderChatList(document.getElementById('chatSearch')?.value || "");

            // Проверяем, остались ли еще истории
            if (!updated.stories || updated.stories.length === 0) {
                this.closeStoryViewer(); // Закрываем вьювер, если удалили последнюю
            } else {
                // Если мы удалили последнюю в массиве, сдвигаем индекс назад
                if (this.currentStoryIndex >= updated.stories.length) {
                    this.currentStoryIndex = updated.stories.length - 1;
                }
                if (controls) controls.style.opacity = '1';
                this.renderStoryFrame(); // Перерисовываем соседнюю историю
            }
        } catch (e) {
            console.error("Ошибка удаления:", e);
            alert("Не удалось удалить историю.");
            if (controls) controls.style.opacity = '1';
            this.startStoryTimer(); // Если ошибка - запускаем таймер обратно
        }
    }

    startStoryTimer() {
        if (this.storyTimer) clearInterval(this.storyTimer);
        
        let progress = 0;
        const progressBar = document.getElementById('activeStoryProgress');
        
        this.storyTimer = setInterval(() => {
            progress += 2; // Шаг прогресса (100% за 5000мс = 5 сек)
            if (progressBar) progressBar.style.width = `${progress}%`;

            if (progress >= 100) {
                this.nextStory();
            }
        }, 100); // Обновляем каждые 100мс
    }

    nextStory() {
        if (!this.currentStoryRider) return;
        this.currentStoryIndex++;
        
        if (this.currentStoryIndex >= this.currentStoryRider.stories.length) {
            this.closeStoryViewer(); // Если истории закончились - закрываем
        } else {
            this.renderStoryFrame();
        }
    }

    prevStory() {
        if (!this.currentStoryRider) return;
        this.currentStoryIndex--;
        
        if (this.currentStoryIndex < 0) {
            this.currentStoryIndex = 0;
            this.renderStoryFrame(); // Просто перезапускаем первую
        } else {
            this.renderStoryFrame();
        }
    }

    closeStoryViewer() {
        if (this.storyTimer) clearInterval(this.storyTimer);
        document.getElementById('storyViewerModal').style.display = 'none';
        this.currentStoryRider = null;
    }
	
	// =========================================================================
    // 🏆 СВОДНЫЙ ПРОТОКОЛ КУБКА: СТРОГИЙ МОНОХРОМ + КЛАСТЕРЫ + U + V (М / Ж)
    // =========================================================================
	closeCupStandings() {
        const modal = document.getElementById('cupStandingsModal');
        if (modal) modal.style.display = 'none';

        // На смартфоне гарантированно прячем чат и показываем список гонок
        if (window.innerWidth <= 768) {
            const sidebar = document.querySelector('.sidebar') || document.getElementById('sidebar');
            const mainChat = document.getElementById('mainChatArea') || document.querySelector('.chat-area');
            const backBtn = document.querySelector('.back-btn');

            document.body.classList.remove('mobile-chat-open');

            if (mainChat) {
                mainChat.classList.remove('mobile-open');
                mainChat.style.setProperty('display', 'none', 'important');
            }
            if (sidebar) {
                sidebar.style.removeProperty('display');
                sidebar.style.setProperty('display', 'flex', 'important');
            }
            if (backBtn) {
                backBtn.style.setProperty('display', 'none', 'important');
            }

            if (this.app) {
                this.app.activeChatId = null;
            }
        }
    }
async openCupStandings(cupId) {
        // 1. Быстро освобождаем правый экран от календаря месяца
        const calView = document.getElementById('monthCalendarViewContainer');
        if (calView) calView.remove();
        if (this.app && typeof this.app.closeMonthCalendarView === 'function') {
            this.app.closeMonthCalendarView(true);
        }

        const mainArea = document.getElementById('mainChatArea') || document.querySelector('.chat-area');
        let modal = document.getElementById('cupStandingsModal');
        const isDesktop = window.innerWidth > 768;

        if (!modal) {
            modal = document.createElement('div');
            modal.id = 'cupStandingsModal';
            modal.className = 'modal-overlay';
            if (isDesktop && mainArea) {
                mainArea.appendChild(modal);
            } else {
                document.body.appendChild(modal);
            }
        } else {
            if (isDesktop && mainArea && modal.parentElement !== mainArea) {
                mainArea.appendChild(modal);
            } else if (!isDesktop && modal.parentElement !== document.body) {
                document.body.appendChild(modal);
            }
        }

        const esc = (str) => {
            if (!str) return '';
            if (this.app && typeof this.app.escapeHTML === 'function') return this.app.escapeHTML(str);
            return String(str).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
        };

        if (isDesktop && mainArea) {
            mainArea.style.position = 'relative';
            mainArea.style.display = 'flex';
            modal.style.cssText = `
                position: absolute !important; inset: 0 !important; width: 100% !important; height: 100% !important;
                background: var(--bg-body, #0d0f12) !important; z-index: 1000 !important;
                display: flex !important; flex-direction: column !important; align-items: stretch !important;
                justify-content: stretch !important; padding: 0 !important; box-sizing: border-box !important;
                overflow: hidden !important;
            `;
        } else {
            modal.style.cssText = `
                position: fixed !important; inset: 0 !important; width: 100vw !important; height: 100vh !important;
                height: 100dvh !important; background: var(--bg-body, #0d0f12) !important;
                z-index: 10000050 !important; display: flex !important; align-items: stretch !important;
                justify-content: stretch !important; padding: 0 !important; box-sizing: border-box !important;
                overflow: hidden !important;
            `;
        }

        // ⚡ МГНОВЕННЫЙ КЭШ: если кубок уже считался в этой сессии, открываем моментально за 0 мс!
        const cacheKey = typeof cupId === 'object' && cupId !== null ? (cupId.id || cupId.name) : String(cupId);
        if (this._cupMemoryCache && this._cupMemoryCache[cacheKey]) {
            const cached = this._cupMemoryCache[cacheKey];
            this.currentCupInfo = cached.info;
            this.currentCupStandings = [...cached.standings];
            this.cupSortState = { field: 'points', dir: 'desc' };
            this.cupFilterType = 'all';
            this.cupFilterGender = 'all';
            modal.style.display = 'flex';
            this.renderCupStandingsModalHTML(modal, cached.info.name, cached.info.stagesCount, cached.standings, false);
            return;
        }

        modal.innerHTML = `
            <div style="display:flex; flex-direction:column; align-items:center; justify-content:center; width:100%; height:100%; color:var(--text-muted); gap:14px;">
                <span class="spinner" style="width:28px; height:28px; border-width:2.5px; display:inline-block; border-color:var(--text-main) transparent transparent transparent;"></span>
                <span style="font-family:'Unbounded', sans-serif; font-size:10px; font-weight:800; text-transform:uppercase; letter-spacing:0.8px; color:var(--text-main);">
                    СИНХРОНИЗАЦИЯ ТЕЛЕМЕТРИИ КУБКА...
                </span>
            </div>
        `;
        modal.style.display = 'flex';

        try {
            let targetCupId = cupId;
            let cup = null;

            if (typeof targetCupId === 'object' && targetCupId !== null) {
                if (targetCupId.name) {
                    cup = targetCupId;
                    targetCupId = cup.id;
                } else if (Array.isArray(targetCupId)) {
                    targetCupId = targetCupId[0];
                } else {
                    targetCupId = targetCupId.id;
                }
            }

            // Быстрый поиск без падающих 404 запросов
            if (!cup && targetCupId) {
                const isPbId = /^[a-z0-9]{15}$/i.test(String(targetCupId));
                if (isPbId) {
                    try {
                        cup = await pb.collection('cups').getOne(targetCupId, { requestKey: null });
                    } catch (e) {}
                }

                if (!cup) {
                    const clean = String(targetCupId).replace(/^#/, '').toLowerCase().trim();
                    const cupsList = await pb.collection('cups').getFullList({ requestKey: null });
                    cup = cupsList.find(c => (c.name || '').toLowerCase() === clean || (c.slug || '').toLowerCase() === clean || c.id === clean);
                    if (cup) targetCupId = cup.id;
                }
            }

            if (!cup) {
                throw new Error("Кубок не найден в базе данных");
            }

            let allowedPelotons = [];
            if (cup.peloton_id) {
                let rawP = Array.isArray(cup.peloton_id) ? cup.peloton_id : [cup.peloton_id];
                allowedPelotons = rawP.map(p => (typeof p === 'object' && p !== null) ? p.id : String(p)).filter(Boolean);
            }

            // Берем гонки прямо из оперативной памяти
            const allRaces = (this.dataCalendar && this.dataCalendar.length > 0)
                ? this.dataCalendar
                : ((this.app?.dataCalendar && this.app.dataCalendar.length > 0)
                    ? this.app.dataCalendar
                    : await pb.collection('races').getFullList({ sort: 'date', requestKey: null }));

            const cupRaces = allRaces.filter(r => {
                if (!r.cup_id && !r.cupId) return false;
                let cId = r.cupId || (Array.isArray(r.cup_id) ? r.cup_id[0] : (typeof r.cup_id === 'object' && r.cup_id !== null ? r.cup_id.id : r.cup_id));
                return String(cId) === String(targetCupId);
            });

            const finishedRaces = cupRaces.filter(r => r.status && (
                r.status.toLowerCase() === 'finished' || 
                r.status.toLowerCase() === 'завершена'
            ));

            const cupTitle = cup.name ? cup.name.toUpperCase() : 'КУБОК';
            this.currentCupInfo = { id: cup.id, name: cupTitle, stagesCount: finishedRaces.length, totalRaces: cupRaces.length };

            if (finishedRaces.length === 0) {
                this.renderCupStandingsModalHTML(modal, cupTitle, 0, [], true);
                return;
            }

            const raceIds = finishedRaces.map(r => r.id);
            const raceFilterStr = raceIds.map(id => `race_id = "${id}"`).join(' || ');

            // 🚀 ГЛАВНОЕ УСКОРЕНИЕ: УБРАН ТЯЖЕЛЫЙ expand!
            // Запрашиваем чистую плоскую таблицу за 40 мс:
            const rosters = await pb.collection('race_rosters').getFullList({
                filter: `(${raceFilterStr}) && (status = "finished" || status = "Finished" || earned_points > 0)`,
                fields: 'id,race_id,rider_id,earned_points,speed,status,bib',
                requestKey: null
            });

            const standingsMap = {};
            const currentYear = new Date().getFullYear();
            const ridersMapRef = this.app?.ridersMap || {};
            const teamsMapRef = this.app?.teamsMap || {};

            rosters.forEach(r => {
                // Мгновенно подтягиваем спортсмена из памяти ПК:
                const rider = ridersMapRef[r.rider_id];
                if (!rider) return;

                if (allowedPelotons.length > 0) {
                    let riderTeams = [];
                    if (rider.team_id) {
                        const tIds = Array.isArray(rider.team_id) ? rider.team_id : [rider.team_id];
                        riderTeams = tIds.map(id => teamsMapRef[id]).filter(Boolean);
                    }

                    let primaryPelotons = [];
                    riderTeams.forEach(tObj => {
                        if (tObj && tObj.peloton_id) {
                            let pel = tObj.peloton_id;
                            let homeP = Array.isArray(pel) ? pel[0] : pel;
                            if (typeof homeP === 'object' && homeP !== null) homeP = homeP.id;
                            if (homeP) primaryPelotons.push(String(homeP));
                        }
                    });

                    if (rider.peloton_id) {
                        let pel = rider.peloton_id;
                        let homeP = Array.isArray(pel) ? pel[0] : pel;
                        if (typeof homeP === 'object' && homeP !== null) homeP = homeP.id;
                        if (homeP) primaryPelotons.push(String(homeP));
                    }

                    if (primaryPelotons.length > 0 && !primaryPelotons.some(pId => allowedPelotons.includes(pId))) {
                        return;
                    }
                }

                const riderId = rider.id;
                let points = parseInt(r.earned_points) || 0;
                let speed = parseFloat(r.speed) || 0;

                if ((!points || speed === 0) && r.race_id) {
                    const raceObj = finishedRaces.find(race => race.id === r.race_id);
                    if (raceObj && raceObj.live_board) {
                        let lb = typeof raceObj.live_board === 'string' ? JSON.parse(raceObj.live_board) : raceObj.live_board;
                        if (Array.isArray(lb)) {
                            let match = lb.find(b => (r.bib && String(b.bib) === String(r.bib)) || (rider.last_name && b.name && b.name.toLowerCase().includes(rider.last_name.toLowerCase())));
                            if (match) {
                                if (!points && match.points) points = parseInt(match.points) || 0;
                                if (speed === 0 && match.speed) speed = parseFloat(match.speed) || 0;
                            }
                        }
                    }
                }

                if (!standingsMap[riderId]) {
                    let teamName = 'ONE TEAM';
                    try {
                        teamName = typeof this.getRiderTeamNames === 'function' ? this.getRiderTeamNames(rider) : (rider.team || 'ONE TEAM');
                    } catch (e) {
                        teamName = rider.team || 'ONE TEAM';
                    }

                    const yob = parseInt(rider.yob) || 0;
                    const age = yob > 0 ? (currentYear - yob) : 0;
                    const baseCl = (rider.base_cluster || 'B').toUpperCase().trim();
                    const rawGender = String(rider.gender || 'M').toUpperCase().trim();
                    const isFemale = (rawGender === 'F' || rawGender === 'Ж');
                    const normalizedGender = isFemale ? 'F' : 'M';
                    const gPrefix = isFemale ? '[Ж]' : '[М]';

                    let groupType = 'cluster';
                    let categoryDisplay = '';
                    let isJunior = false;
                    let isVeteran = false;

                    if (baseCl === 'U' || (age > 0 && age < 18)) {
                        isJunior = true;
                        groupType = 'u';
                        let uSub = 'U18';
                        if (age <= 14 && age > 0) uSub = 'U14';
                        else if (age <= 16 && age > 0) uSub = 'U16';
                        categoryDisplay = `${gPrefix} ${uSub}`;
                    } else if (isFemale) {
                        if (age >= 50 || baseCl === 'V') {
                            isVeteran = true;
                            groupType = 'v';
                            categoryDisplay = `[Ж] V50+`;
                        } else {
                            groupType = 'cluster';
                            categoryDisplay = `[Ж] ${baseCl}`;
                        }
                    } else {
                        if (age >= 70) {
                            isVeteran = true;
                            groupType = 'v';
                            categoryDisplay = `[М] V70+`;
                        } else if (age >= 60 || (baseCl === 'V' && age >= 60)) {
                            isVeteran = true;
                            groupType = 'v';
                            categoryDisplay = `[М] V60+`;
                        } else {
                            groupType = 'cluster';
                            categoryDisplay = `[М] ${baseCl}`;
                        }
                    }

                    const getCatWeight = (catStr) => {
                        if (catStr.includes('A+')) return 10;
                        if (catStr.includes('A')) return 20;
                        if (catStr.includes('B')) return 30;
                        if (catStr.includes('C')) return 40;
                        if (catStr.includes('D')) return 50;
                        if (catStr.includes('E') || catStr.includes('O')) return 60;
                        if (catStr.includes('V50')) return 110;
                        if (catStr.includes('V60')) return 120;
                        if (catStr.includes('V70')) return 130;
                        if (catStr.includes('U18')) return 210;
                        if (catStr.includes('U16')) return 220;
                        if (catStr.includes('U14')) return 230;
                        return 999;
                    };

                    standingsMap[riderId] = {
                        id: riderId,
                        name: `${rider.first_name || ''} ${rider.last_name || ''}`.trim() || 'Гонщик',
                        gender: normalizedGender,
                        groupType: groupType,
                        category: categoryDisplay,
                        catSortRank: (isFemale ? 1000 : 0) + getCatWeight(categoryDisplay),
                        isJunior: isJunior,
                        isVeteran: isVeteran,
                        age: age,
                        yob: yob,
                        team: teamName,
                        totalPoints: 0,
                        stagesCount: 0,
                        maxSpeed: 0
                    };
                }

                standingsMap[riderId].totalPoints += points;
                standingsMap[riderId].stagesCount += 1;
                if (speed > standingsMap[riderId].maxSpeed) {
                    standingsMap[riderId].maxSpeed = speed;
                }
            });

            let standingsArr = Object.values(standingsMap);
            standingsArr.sort((a, b) => b.totalPoints - a.totalPoints);

            // Сохраняем в кэш сессии
            if (!this._cupMemoryCache) this._cupMemoryCache = {};
            this._cupMemoryCache[cacheKey] = {
                info: this.currentCupInfo,
                standings: standingsArr
            };

            this.currentCupStandings = standingsArr;
            this.cupSortState = { field: 'points', dir: 'desc' };
            this.cupFilterType = 'all';
            this.cupFilterGender = 'all';

            this.renderCupStandingsModalHTML(modal, cupTitle, finishedRaces.length, standingsArr, false);

        } catch (e) {
            console.error("Ошибка при подсчете кубка:", e);
            modal.innerHTML = `
                <div style="display:flex; flex-direction:column; align-items:center; justify-content:center; width:100%; height:100%; color:var(--text-main); font-family:'Unbounded', sans-serif; gap:12px;">
                    <div style="font-size:12px; font-weight:900; letter-spacing:0.5px;">ОШИБКА ПОДСЧЕТА КУБКА</div>
                    <div style="font-family:'Roboto Mono', monospace; font-size:11px; color:var(--text-muted);">${esc(e.message || '')}</div>
                    <button type="button" class="cup-mono-btn" style="margin-top:14px; background:var(--text-main); color:var(--bg-body);" onclick="window.app.closeCupStandings()">ЗАКРЫТЬ</button>
                </div>
            `;
        }
    }
    // 🎨 ЧИСТАЯ МОНОХРОМНАЯ ВЁРСТКА СО СТРОГИМИ SVG (БЕЗ ЭМОДЗИ)
    renderCupStandingsModalHTML(modal, cupTitle, stagesCount, standingsArr, isEmpty = false) {
        const esc = (str) => {
            if (!str) return '';
            if (this.app && typeof this.app.escapeHTML === 'function') {
                return this.app.escapeHTML(str);
            }
            return String(str).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#039;');
        };

        const svgTrophy = `<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M6 9H4.5a2.5 2.5 0 0 1 0-5H6"></path><path d="M18 9h1.5a2.5 2.5 0 0 0 0-5H18"></path><path d="M4 22h16"></path><path d="M10 14.66V17c0 .55-.47.98-.97 1.21C7.85 18.75 7 20.24 7 22"></path><path d="M14 14.66V17c0 .55.47.98.97 1.21C16.15 18.75 17 20.24 17 22"></path><path d="M18 2H6v7a6 6 0 0 0 12 0V2Z"></path></svg>`;
        const svgClose = `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg>`;
        const svgDownload = `<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"></path><polyline points="7 10 12 15 17 10"></polyline><line x1="12" y1="15" x2="12" y2="3"></line></svg>`;
        const svgSearch = `<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><circle cx="11" cy="11" r="8"></circle><line x1="21" y1="21" x2="16.65" y2="16.65"></line></svg>`;
        const svgStar = `<svg width="10" height="10" viewBox="0 0 24 24" fill="currentColor"><polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2"/></svg>`;
        const svgLightning = `<svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polygon points="13 2 3 14 12 14 11 22 21 10 12 10 13 2"></polygon></svg>`;
        const svgJunior = `<svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><polyline points="12 6 12 12 14 14"></polyline></svg>`;
        const svgVeteran = `<svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"></path></svg>`;
        const svgLayers = `<svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polygon points="12 2 2 7 12 12 22 7 12 2"></polygon><polyline points="2 17 12 22 22 17"></polyline><polyline points="2 12 12 17 22 12"></polyline></svg>`;

        if (!document.getElementById('cup-monochrome-styles')) {
            const style = document.createElement('style');
            style.id = 'cup-monochrome-styles';
            style.innerHTML = `
                .cup-mono-container {
                    display: flex; flex-direction: column; 
                    width: 100% !important; max-width: 100% !important; height: 100% !important;
                    background: var(--bg-body, #0d0f12); color: var(--text-main, #f4f4f5);
                    font-family: 'Manrope', -apple-system, sans-serif; box-sizing: border-box; overflow: hidden;
                }
                .cup-mono-header {
                    display: flex; align-items: center; justify-content: space-between;
                    padding: 12px 18px; border-bottom: 1px solid var(--border, #27272a);
                    background: var(--bg-surface, #14161b); flex-shrink: 0; gap: 10px;
                    box-sizing: border-box; width: 100%;
                }
                .cup-mono-subbar {
                    display: flex; align-items: center; justify-content: space-between; gap: 10px;
                    padding: 8px 18px; border-bottom: 1px solid var(--border, #27272a);
                    background: var(--bg-body, #0d0f12); flex-shrink: 0; flex-wrap: wrap;
                    box-sizing: border-box; width: 100%;
                }
                .cup-mono-filter-group {
                    display: inline-flex; align-items: center; background: var(--bg-surface, #14161b);
                    border: 1px solid var(--border, #27272a); border-radius: 8px; padding: 2px; gap: 2px;
                }
                .cup-mono-pill {
                    height: 26px; padding: 0 8px; border-radius: 6px; border: none;
                    background: transparent; color: var(--text-muted, #71717a);
                    font-family: 'Unbounded', sans-serif; font-size: 8.5px; font-weight: 800; letter-spacing: 0.3px;
                    cursor: pointer; display: inline-flex; align-items: center; gap: 4px; transition: all 0.15s ease;
                    white-space: nowrap; user-select: none;
                }
                .cup-mono-pill:hover {
                    color: var(--text-main, #f4f4f5);
                }
                .cup-mono-pill.active {
                    background: var(--text-main, #f4f4f5) !important; color: var(--bg-body, #0d0f12) !important;
                }
                .cup-mono-icon-btn {
                    width: 30px; height: 30px; border-radius: 8px; border: 1px solid var(--border, #27272a);
                    background: var(--bg-surface, #14161b); color: var(--text-muted, #71717a);
                    display: inline-flex; align-items: center; justify-content: center; cursor: pointer;
                    transition: all 0.15s ease; flex-shrink: 0;
                }
                .cup-mono-icon-btn:hover {
                    color: var(--text-main, #f4f4f5); border-color: var(--text-main, #f4f4f5);
                }
                .cup-mono-table-wrap {
                    flex: 1; overflow-y: auto; overflow-x: auto; width: 100%; box-sizing: border-box;
                }
                .cup-mono-table {
                    width: 100%; min-width: 640px; border-collapse: collapse; text-align: left;
                }
                .cup-mono-th {
                    position: sticky; top: 0; background: var(--bg-surface, #14161b); z-index: 5;
                    border-bottom: 1px solid var(--border, #27272a); padding: 10px 8px;
                    font-family: 'Unbounded', sans-serif; font-size: 8.5px; font-weight: 800;
                    color: var(--text-muted, #71717a); letter-spacing: 0.5px; text-transform: uppercase;
                    cursor: pointer; user-select: none; white-space: nowrap;
                }
                .cup-mono-th:hover {
                    color: var(--text-main, #f4f4f5);
                }
                .cup-mono-tr {
                    border-bottom: 1px solid var(--border, #27272a); transition: background 0.1s ease;
                    cursor: pointer;
                }
                .cup-mono-tr:hover {
                    background: var(--bg-surface-hover, rgba(255,255,255,0.03));
                }
                .cup-mono-tr.is-me {
                    background: rgba(255, 193, 7, 0.05);
                }
                .cup-mono-td {
                    padding: 8px; vertical-align: middle; box-sizing: border-box;
                }
                .cup-rank-chip {
                    display: inline-flex; align-items: center; justify-content: center; gap: 4px;
                    font-family: 'Roboto Mono', monospace; font-size: 11px; font-weight: 800;
                    min-width: 26px; height: 22px; padding: 0 5px; border-radius: 6px;
                    background: var(--bg-surface, #14161b); border: 1px solid var(--border, #27272a);
                    color: var(--text-muted, #71717a);
                }
                .cup-rank-chip.rank-1 {
                    background: var(--text-main, #f4f4f5); color: var(--bg-body, #0d0f12);
                    border-color: var(--text-main, #f4f4f5); font-weight: 900;
                }
                .cup-rank-chip.rank-2 {
                    background: transparent; color: var(--text-main, #f4f4f5);
                    border-color: var(--text-main, #f4f4f5);
                }
                .cup-rank-chip.rank-3 {
                    background: transparent; color: var(--text-main, #f4f4f5);
                    border-color: rgba(255,255,255,0.3);
                }
                .cup-cat-tag {
                    display: inline-flex; align-items: center; justify-content: center;
                    font-family: 'Roboto Mono', monospace; font-size: 9.5px; font-weight: 800;
                    padding: 2px 6px; border-radius: 5px; background: var(--bg-surface, #14161b);
                    border: 1px solid var(--border, #27272a); color: var(--text-main, #f4f4f5);
                }
            `;
            document.head.appendChild(style);
        }

        let bodyContent = '';

        if (isEmpty || standingsArr.length === 0) {
            bodyContent = `
                <div style="display:flex; flex-direction:column; align-items:center; justify-content:center; flex:1; color:var(--text-muted); font-family:'Unbounded', sans-serif; font-size:11px; letter-spacing:0.4px;">
                    ${stagesCount === 0 ? 'НЕТ ЗАВЕРШЕННЫХ ЭТАПОВ ДЛЯ ПОДСЧЕТА РЕЙТИНГА' : 'В ЗАЧЕТЕ КУБКА НЕТ УЧАСТНИКОВ ПО ТЕКУЩИМ ФИЛЬТРАМ'}
                </div>
            `;
        } else {
            const myRiderId = this.app?.currentRider?.id;
            let rank = 1;
            let prevPoints = -1;

            let rowsHtml = standingsArr.map((s, index) => {
                if (s.totalPoints !== prevPoints && index !== 0) {
                    rank = index + 1;
                }
                prevPoints = s.totalPoints;

                let rankChip = `<div class="cup-rank-chip">${rank}</div>`;
                if (rank === 1) rankChip = `<div class="cup-rank-chip rank-1">${svgStar} 1</div>`;
                else if (rank === 2) rankChip = `<div class="cup-rank-chip rank-2">2</div>`;
                else if (rank === 3) rankChip = `<div class="cup-rank-chip rank-3">3</div>`;

                const isMe = (myRiderId && s.id === myRiderId);
                const searchStr = esc(`${s.name} ${s.category} ${s.team} ${s.gender}`.toLowerCase());
                const speedStr = s.maxSpeed > 0 ? `${s.maxSpeed.toFixed(2)}` : '—';

                return `
                    <tr class="cup-mono-tr cup-standing-row ${isMe ? 'is-me' : ''}" 
                        data-search="${searchStr}" 
                        data-grouptype="${s.groupType}"
                        data-gender="${s.gender}"
                        onclick="window.app.closeCupStandings(); window.app.openProfile('${s.id}')">
                        
                        <td class="cup-mono-td" style="text-align: center; width: 45px;">
                            <div class="row-rank-slot">${rankChip}</div>
                        </td>

                        <td class="cup-mono-td">
                            <div style="display:flex; align-items:center; gap:6px;">
                                <span style="font-family:'Unbounded', sans-serif; font-size:11.5px; font-weight:800; color:var(--text-main); letter-spacing:-0.2px;">${esc(s.name)}</span>
                                ${isMe ? '<span style="font-family:Roboto Mono, monospace; font-size:8px; font-weight:800; padding:1px 4px; border-radius:4px; background:var(--text-main); color:var(--bg-body);">YOU</span>' : ''}
                            </div>
                        </td>

                        <td class="cup-mono-td" style="text-align: center; width: 85px;">
                            <span class="cup-cat-tag">
                                ${esc(s.category)}
                            </span>
                        </td>

                        <td class="cup-mono-td">
                            <span style="font-size:11px; color:var(--text-muted); font-weight:600;">${esc(s.team)}</span>
                        </td>

                        <td class="cup-mono-td" style="text-align: center; width: 110px;">
                            <span style="font-family:Roboto Mono, monospace; font-size:12px; font-weight:800; color:var(--text-main);">${speedStr}</span>
                            ${s.maxSpeed > 0 ? '<span style="font-family:Roboto Mono, monospace; font-size:8.5px; color:var(--text-muted); margin-left:2px;">КМ/Ч</span>' : ''}
                        </td>

                        <td class="cup-mono-td" style="text-align: center; width: 70px;">
                            <span style="font-family:Roboto Mono, monospace; font-size:11px; font-weight:700; color:var(--text-muted);">${s.stagesCount} / ${stagesCount}</span>
                        </td>

                        <td class="cup-mono-td" style="text-align: right; width: 105px; padding-right: 14px;">
                            <span style="font-family:Roboto Mono, monospace; font-size:13.5px; font-weight:900; color:var(--text-main);">${s.totalPoints.toLocaleString('ru-RU')}</span>
                            <span style="font-family:Roboto Mono, monospace; font-size:8.5px; font-weight:700; color:var(--text-muted); margin-left:1px;">PTS</span>
                        </td>
                    </tr>
                `;
            }).join('');

            const getSortIcon = (field) => {
                if (this.cupSortState?.field !== field) {
                    return `<svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" opacity="0.3" style="vertical-align:middle; margin-left:3px;"><polyline points="8 9 12 5 16 9"></polyline><polyline points="16 15 12 19 8 15"></polyline></svg>`;
                }
                return this.cupSortState.dir === 'desc'
                    ? `<svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" style="vertical-align:middle; margin-left:3px;"><polyline points="6 9 12 15 18 9"></polyline></svg>`
                    : `<svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" style="vertical-align:middle; margin-left:3px;"><polyline points="18 15 12 9 6 15"></polyline></svg>`;
            };

            bodyContent = `
                <div class="cup-mono-table-wrap">
                    <table class="cup-mono-table">
                        <thead>
                            <tr>
                                <th class="cup-mono-th" style="width: 45px; text-align: center;" onclick="window.app.crm.sortCupStandings('rank')">РАНГ ${getSortIcon('rank')}</th>
                                <th class="cup-mono-th" onclick="window.app.crm.sortCupStandings('name')">АТЛЕТ ${getSortIcon('name')}</th>
                                <th class="cup-mono-th" style="width: 85px; text-align: center;" onclick="window.app.crm.sortCupStandings('category')">КАТЕГОРИЯ ${getSortIcon('category')}</th>
                                <th class="cup-mono-th" onclick="window.app.crm.sortCupStandings('team')">КОМАНДА ${getSortIcon('team')}</th>
                                <th class="cup-mono-th" style="width: 110px; text-align: center;" onclick="window.app.crm.sortCupStandings('speed')">СКОРОСТЬ ${getSortIcon('speed')}</th>
                                <th class="cup-mono-th" style="width: 70px; text-align: center;" onclick="window.app.crm.sortCupStandings('stages')">ЭТАПЫ ${getSortIcon('stages')}</th>
                                <th class="cup-mono-th" style="width: 105px; text-align: right; padding-right: 14px;" onclick="window.app.crm.sortCupStandings('points')">БАЛЛЫ ${getSortIcon('points')}</th>
                            </tr>
                        </thead>
                        <tbody id="cupStandingsTbody">
                            ${rowsHtml}
                        </tbody>
                    </table>
                </div>
            `;
        }

        const activeType = this.cupFilterType || 'all';
        const activeGender = this.cupFilterGender || 'all';

        modal.innerHTML = `
            <div class="cup-mono-container" style="width: 100% !important; max-width: 100% !important; height: 100% !important;">
                
                <!-- Верхняя монохромная панель -->
                <div class="cup-mono-header">
                    <div style="display:flex; align-items:center; gap:10px; min-width:0;">
                        <div class="cup-mono-icon-btn" style="color:var(--text-main); cursor:default;">
                            ${svgTrophy}
                        </div>
                        <div style="min-width:0;">
                            <div style="font-family:'Unbounded', sans-serif; font-size:13px; font-weight:900; letter-spacing:0.3px; text-transform:uppercase; line-height:1.2; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">
                                ${esc(cupTitle)}
                            </div>
                            <div style="font-family:'Roboto Mono', monospace; font-size:9.5px; font-weight:700; color:var(--text-muted); margin-top:2px;">
                                ЭТАПОВ: ${stagesCount} • В ЗАЧЁТЕ: ${standingsArr.length} АТЛЕТОВ
                            </div>
                        </div>
                    </div>

                    <div style="display:flex; align-items:center; gap:8px; flex-shrink:0;">
                        ${standingsArr.length > 0 ? `
                            <button type="button" onclick="window.app.crm.exportCupData()" 
                                    style="height: 30px; padding: 0 12px; border-radius: 8px; border: 1px solid var(--border, #27272a); background: var(--bg-surface, #14161b); color: var(--text-main, #f4f4f5); font-family: 'Unbounded', sans-serif; font-size: 9px; font-weight: 800; letter-spacing: 0.3px; cursor: pointer; display: inline-flex; align-items: center; gap: 5px; box-sizing: border-box; transition: 0.15s ease;"
                                    onmouseover="this.style.borderColor='var(--text-main, #fff)'; this.style.background='var(--bg-surface-hover, #222)';"
                                    onmouseout="this.style.borderColor='var(--border, #27272a)'; this.style.background='var(--bg-surface, #14161b)';">
                                <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round">
                                    <path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"></path>
                                    <polyline points="7 10 12 15 17 10"></polyline>
                                    <line x1="12" y1="15" x2="12" y2="3"></line>
                                </svg>
                                <span>СКАЧАТЬ</span>
                            </button>
                        ` : ''}
                        <button type="button" onclick="window.app.closeCupStandings()" 
        style="width: 30px; height: 30px; border-radius: 8px; border: 1px solid var(--border, #27272a); background: var(--bg-surface, #14161b); color: var(--text-muted, #71717a); cursor: pointer; display: inline-flex; align-items: center; justify-content: center; padding: 0; box-sizing: border-box; transition: 0.15s ease;"
        onmouseover="this.style.color='var(--text-main, #fff)'; this.style.borderColor='var(--text-main, #fff)';"
        onmouseout="this.style.color='var(--text-muted, #71717a)'; this.style.borderColor='var(--border, #27272a)';">
    <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">
        <line x1="18" y1="6" x2="6" y2="18"></line>
        <line x1="6" y1="6" x2="18" y2="18"></line>
    </svg>
</button>
                    </div>
                </div>

                <!-- Строка независимых фильтров: [ТИП ЗАЧЁТА] + [ПОЛ] + [ПОИСК] -->
                <div class="cup-mono-subbar">
                    <div style="display:flex; gap:6px; overflow-x:auto; scrollbar-width:none; align-items:center;">
                        
                        <!-- Блок 1: Тип зачёта (Кластеры / Юность / Ветераны) -->
                        <div class="cup-mono-filter-group">
                            <button type="button" class="cup-mono-pill ${activeType === 'all' ? 'active' : ''}" onclick="window.app.crm.setCupTypeFilter('all')">
                                ${svgLayers}
                                <span>ВСЕ</span>
                            </button>
                            <button type="button" class="cup-mono-pill ${activeType === 'cluster' ? 'active' : ''}" onclick="window.app.crm.setCupTypeFilter('cluster')">
                                ${svgLightning}
                                <span>КЛАСТЕРЫ</span>
                            </button>
                            <button type="button" class="cup-mono-pill ${activeType === 'u' ? 'active' : ''}" onclick="window.app.crm.setCupTypeFilter('u')">
                                ${svgJunior}
                                <span>ЮНОСТЬ U</span>
                            </button>
                            <button type="button" class="cup-mono-pill ${activeType === 'v' ? 'active' : ''}" onclick="window.app.crm.setCupTypeFilter('v')">
                                ${svgVeteran}
                                <span>ВЕТЕРАНЫ V</span>
                            </button>
                        </div>

                        <!-- Блок 2: Разделение по полу (М / Ж) -->
                        <div class="cup-mono-filter-group">
                            <button type="button" class="cup-mono-pill ${activeGender === 'all' ? 'active' : ''}" onclick="window.app.crm.setCupGenderFilter('all')">
                                <span>М + Ж</span>
                            </button>
                            <button type="button" class="cup-mono-pill ${activeGender === 'M' ? 'active' : ''}" onclick="window.app.crm.setCupGenderFilter('M')">
                                <span>[М]</span>
                            </button>
                            <button type="button" class="cup-mono-pill ${activeGender === 'F' ? 'active' : ''}" onclick="window.app.crm.setCupGenderFilter('F')">
                                <span>[Ж]</span>
                            </button>
                        </div>

                    </div>

                    <!-- Поиск -->
                    <div style="position:relative; width:220px; max-width:100%;">
                        <span style="position:absolute; left:10px; top:50%; transform:translateY(-50%); color:var(--text-muted); display:flex; align-items:center; pointer-events:none;">
                            ${svgSearch}
                        </span>
                        <input type="text" id="cupStandingsSearchInput" 
                               placeholder="ПОИСК АТЛЕТА..." 
                               style="width:100%; height:30px; border-radius:8px; background:var(--bg-surface, #14161b); border:1px solid var(--border, #27272a); color:var(--text-main); padding:0 10px 0 28px; font-family:'Roboto Mono', monospace; font-size:10px; outline:none; box-sizing:border-box;"
                               oninput="window.app.crm.applyCupDomFilter()">
                    </div>
                </div>

                <!-- Таблица результатов -->
                <div id="cupStandingsContent" style="flex:1; min-height:0; display:flex; flex-direction:column;">
                    ${bodyContent}
                </div>

            </div>
        `;
    }

    // 🔀 СОРТИРОВКА: ПРИ КЛИКЕ НА "КАТЕГОРИЯ" ГРУППИРУЕТ ПО РАНГУ ГРУППЫ И БАЛЛАМ
    sortCupStandings(field) {
        if (!this.currentCupStandings) return;

        let dir = 'desc';
        if (this.cupSortState?.field === field) {
            dir = this.cupSortState.dir === 'desc' ? 'asc' : 'desc';
        }
        this.cupSortState = { field, dir };

        this.currentCupStandings.sort((a, b) => {
            if (field === 'points' || field === 'rank') {
                return dir === 'desc' ? (b.totalPoints - a.totalPoints) : (a.totalPoints - b.totalPoints);
            } else if (field === 'speed') {
                return dir === 'desc' ? (b.maxSpeed - a.maxSpeed) : (a.maxSpeed - b.maxSpeed);
            } else if (field === 'stages') {
                return dir === 'desc' ? (b.stagesCount - a.stagesCount) : (a.stagesCount - b.stagesCount);
            } else if (field === 'name') {
                return dir === 'asc' ? a.name.localeCompare(b.name) : b.name.localeCompare(a.name);
            } else if (field === 'team') {
                return dir === 'asc' ? a.team.localeCompare(b.team) : b.team.localeCompare(a.team);
            } else if (field === 'category') {
                if (a.catSortRank !== b.catSortRank) {
                    return dir === 'asc' ? (a.catSortRank - b.catSortRank) : (b.catSortRank - a.catSortRank);
                }
                return b.totalPoints - a.totalPoints;
            }
            return 0;
        });

        const modal = document.getElementById('cupStandingsModal');
        this.renderCupStandingsModalHTML(modal, this.currentCupInfo?.name || 'КУБОК', this.currentCupInfo?.stagesCount || 0, this.currentCupStandings, false);
        this.applyCupDomFilter();
    }

    // 🔘 ПЕРЕКЛЮЧАТЕЛЬ ТИПА ЗАЧЁТА
    setCupTypeFilter(typeKey) {
        this.cupFilterType = typeKey;
        const modal = document.getElementById('cupStandingsModal');
        if (modal) {
            this.renderCupStandingsModalHTML(modal, this.currentCupInfo?.name || 'КУБОК', this.currentCupInfo?.stagesCount || 0, this.currentCupStandings, false);
            this.applyCupDomFilter();
        }
    }

    // 🔘 ПЕРЕКЛЮЧАТЕЛЬ ПОЛА (М / Ж)
    setCupGenderFilter(genderKey) {
        this.cupFilterGender = genderKey;
        const modal = document.getElementById('cupStandingsModal');
        if (modal) {
            this.renderCupStandingsModalHTML(modal, this.currentCupInfo?.name || 'КУБОК', this.currentCupInfo?.stagesCount || 0, this.currentCupStandings, false);
            this.applyCupDomFilter();
        }
    }

    // ⚡ МГНОВЕННАЯ ФИЛЬТРАЦИЯ С ПЕРЕСЧЁТОМ МЕСТ (1, 2, 3...)
    applyCupDomFilter() {
        const typeKey = this.cupFilterType || 'all';
        const genderKey = this.cupFilterGender || 'all';
        const searchInput = document.getElementById('cupStandingsSearchInput');
        const q = (searchInput?.value || '').toLowerCase().trim();

        const rows = Array.from(document.querySelectorAll('.cup-standing-row'));
        const svgStar = `<svg width="10" height="10" viewBox="0 0 24 24" fill="currentColor"><polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2"/></svg>`;

        let visibleRank = 1;

        rows.forEach(r => {
            const gType = r.getAttribute('data-grouptype') || 'cluster';
            const gender = r.getAttribute('data-gender') || 'M';
            const text = r.getAttribute('data-search') || '';

            const passType = (typeKey === 'all') || (gType === typeKey);
            const passGender = (genderKey === 'all') || (gender === genderKey);
            const passSearch = !q || text.includes(q);

            const isVisible = passType && passGender && passSearch;
            r.style.display = isVisible ? '' : 'none';

            if (isVisible) {
                const rankSlot = r.querySelector('.row-rank-slot');
                if (rankSlot) {
                    if (visibleRank === 1) rankSlot.innerHTML = `<div class="cup-rank-chip rank-1">${svgStar} 1</div>`;
                    else if (visibleRank === 2) rankSlot.innerHTML = `<div class="cup-rank-chip rank-2">2</div>`;
                    else if (visibleRank === 3) rankSlot.innerHTML = `<div class="cup-rank-chip rank-3">3</div>`;
                    else rankSlot.innerHTML = `<div class="cup-rank-chip">${visibleRank}</div>`;
                }
                visibleRank++;
            }
        });
    }

 // 🔍 БЫСТРЫЙ ПОИСК В ПРОТОКОЛЕ КУБКА
    filterCupStandings(query) {
        const q = (query || '').toLowerCase().trim();
        const rows = document.querySelectorAll('.cup-standing-row');
        rows.forEach(r => {
            const text = r.getAttribute('data-search') || '';
            r.style.display = (!q || text.includes(q)) ? '' : 'none';
        });
    }

    // 🎯 СБОР ДАННЫХ ДЛЯ ЭКСПОРТА С УЧЕТОМ АКТИВНОГО ПОИСКА
    getCupExportPayload() {
        const cupInfo = this.currentCupInfo || {};
        const cupName = cupInfo.name || "КУБОК";
        const stagesCount = cupInfo.stagesCount || 0;

        const typeKey = this.cupFilterType || 'all';
        const genderKey = this.cupFilterGender || 'all';
        const searchInput = document.getElementById('cupStandingsSearchInput');
        const q = (searchInput?.value || '').toLowerCase().trim();

        // Фильтруем ровно тех атлетов, которые сейчас видны в таблице
        let list = (this.currentCupStandings || []).filter(s => {
            const passType = (typeKey === 'all') || (s.groupType === typeKey);
            const passGender = (genderKey === 'all') || (s.gender === genderKey);
            const text = `${s.name} ${s.category} ${s.team} ${s.gender}`.toLowerCase();
            const passSearch = !q || text.includes(q);
            return passType && passGender && passSearch;
        });

        let filterSubtitle = 'ОБЩИЙ ЗАЧЕТ';
        if (typeKey === 'cluster') filterSubtitle = 'СКОРОСТНЫЕ КЛАСТЕРЫ';
        else if (typeKey === 'u') filterSubtitle = 'ЮНОСТЬ U';
        else if (typeKey === 'v') filterSubtitle = 'ВЕТЕРАНЫ V';

        if (genderKey === 'M') filterSubtitle += ' • МУЖЧИНЫ';
        else if (genderKey === 'F') filterSubtitle += ' • ЖЕНЩИНЫ';

        return {
            cupName,
            stagesCount,
            subtitle: filterSubtitle,
            totalCount: list.length,
            standings: list
        };
    }
    // 📥 1. ВЫЗОВ МОДАЛЬНОГО ОКНА ВЫБОРА ФОРМАТА ЭКСПОРТА КУБКА (CSV / HTML / ПЕЧАТЬ)
    exportCupData() {
        const payload = this.getCupExportPayload();
        if (!payload.standings.length) {
            alert("Нет данных для экспорта по текущим фильтрам");
            return;
        }

        const existingModal = document.getElementById('cupExportMenuModal');
        if (existingModal) existingModal.remove();

        const modal = document.createElement('div');
        modal.id = 'cupExportMenuModal';
        modal.style.cssText = 'position:fixed !important; inset:0 !important; background:rgba(0,0,0,0.75) !important; z-index:10000070 !important; display:flex !important; align-items:center !important; justify-content:center !important; backdrop-filter:blur(8px) !important; padding:16px !important; box-sizing:border-box !important;';
        modal.onclick = (e) => { if (e.target.id === 'cupExportMenuModal') modal.remove(); };

        const esc = (str) => {
            if (!str) return '';
            if (this.app && typeof this.app.escapeHTML === 'function') return this.app.escapeHTML(str);
            return String(str).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
        };

        const svgTable = `<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"></path><polyline points="14 2 14 8 20 8"></polyline><line x1="16" y1="13" x2="8" y2="13"></line><line x1="16" y1="17" x2="8" y2="17"></line></svg>`;
        const svgCode = `<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="16 18 22 12 16 6"></polyline><polyline points="8 6 2 12 8 18"></polyline></svg>`;
        const svgPrint = `<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 6 2 18 2 18 9"></polyline><path d="M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2"></path><rect x="6" y="14" width="12" height="8"></rect></svg>`;

        modal.innerHTML = `
            <div style="background:var(--bg-surface, #14161b); border:1px solid var(--border, #27272a); border-radius:18px; padding:22px 20px; width:100%; max-width:340px; box-shadow:0 20px 50px rgba(0,0,0,0.6); text-align:center; box-sizing:border-box;" onclick="event.stopPropagation()">
                <div style="font-family:'Unbounded', sans-serif; font-size:12px; font-weight:900; color:var(--text-main, #f4f4f5); margin-bottom:4px; letter-spacing:0.5px; text-transform:uppercase;">
                    ПРОТОКОЛ КУБКА
                </div>
                <div style="font-family:'Roboto Mono', monospace; font-size:10px; font-weight:800; color:var(--primary, #ffc107); margin-bottom:4px;">
                    ${esc(payload.cupName)} • ${payload.stagesCount} ЭТАПОВ
                </div>
                <div style="font-family:'Roboto Mono', monospace; font-size:9.5px; color:var(--text-muted, #71717a); margin-bottom:16px;">
                    ${esc(payload.subtitle)} (${payload.totalCount} АТЛ.)
                </div>
                
                <div style="display:flex; flex-direction:column; gap:8px;">
                    <button type="button" onclick="window.app.crm.downloadCupFormatSelected('csv')" 
                            style="background:var(--bg-body, #0d0f12); color:var(--text-main, #f4f4f5); border:1px solid var(--border, #27272a); padding:11px 14px; border-radius:10px; font-family:'Unbounded', sans-serif; font-size:9.5px; font-weight:800; cursor:pointer; display:flex; align-items:center; gap:10px; transition:0.15s ease;"
                            onmouseover="this.style.borderColor='var(--text-main, #fff)';"
                            onmouseout="this.style.borderColor='var(--border, #27272a)';">
                        <span style="display:flex; align-items:center; color:var(--text-muted);">${svgTable}</span>
                        <span>Таблица CSV (Excel)</span>
                    </button>

                    <button type="button" onclick="window.app.crm.downloadCupFormatSelected('html')" 
                            style="background:var(--bg-body, #0d0f12); color:var(--text-main, #f4f4f5); border:1px solid var(--border, #27272a); padding:11px 14px; border-radius:10px; font-family:'Unbounded', sans-serif; font-size:9.5px; font-weight:800; cursor:pointer; display:flex; align-items:center; gap:10px; transition:0.15s ease;"
                            onmouseover="this.style.borderColor='var(--text-main, #fff)';"
                            onmouseout="this.style.borderColor='var(--border, #27272a)';">
                        <span style="display:flex; align-items:center; color:var(--text-muted);">${svgCode}</span>
                        <span>Веб-протокол (.HTML)</span>
                    </button>

                    <button type="button" onclick="window.app.crm.downloadCupFormatSelected('print')" 
                            style="background:var(--bg-body, #0d0f12); color:var(--text-main, #f4f4f5); border:1px solid var(--border, #27272a); padding:11px 14px; border-radius:10px; font-family:'Unbounded', sans-serif; font-size:9.5px; font-weight:800; cursor:pointer; display:flex; align-items:center; gap:10px; transition:0.15s ease;"
                            onmouseover="this.style.borderColor='var(--text-main, #fff)';"
                            onmouseout="this.style.borderColor='var(--border, #27272a)';">
                        <span style="display:flex; align-items:center; color:var(--text-muted);">${svgPrint}</span>
                        <span>Печать / В PDF</span>
                    </button>
                </div>
                
                <button type="button" onclick="document.getElementById('cupExportMenuModal').remove()" 
                        style="margin-top:16px; background:none; border:none; color:var(--text-muted, #71717a); font-family:'Unbounded', sans-serif; font-size:9.5px; font-weight:800; cursor:pointer; transition:0.15s ease;"
                        onmouseover="this.style.color='var(--text-main, #ffffff)';"
                        onmouseout="this.style.color='var(--text-muted, #71717a)';">
                    ОТМЕНА
                </button>
            </div>
        `;
        document.body.appendChild(modal);
    }
    // Сохранение совместимости со старыми вызовами
    exportCupStandingsCsv() {
        this.exportCupData();
    }

    // 🎯 2. МАРШРУТИЗАЦИЯ ФОРМАТА
    downloadCupFormatSelected(format) {
        const modal = document.getElementById('cupExportMenuModal');
        if (modal) modal.remove();

        const payload = this.getCupExportPayload();
        if (!payload.standings.length) {
            alert("Нет данных для экспорта");
            return;
        }

        if (format === 'csv') {
            this.executeCupCsvExport(payload);
        } else if (format === 'html') {
            this.executeCupHtmlExport(payload, false);
        } else if (format === 'print') {
            this.executeCupHtmlExport(payload, true);
        }
    }

    // 📊 3. ВЫГРУЗКА В CSV (UTF-8 BOM ДЛЯ EXCEL)
executeCupCsvExport(payload) {
        const data = payload || this.getCupExportPayload();
        const list = data.standings || [];
        const cupName = (data.cupName || "КУБОК").replace(/[^a-zA-Zа-яА-Я0-9_-]/g, '_');
        const stagesCount = data.stagesCount || 0;

        let csvContent = "\uFEFFМесто;Спортсмен;Категория;Команда;Лучшая средняя (км/ч);Этапы;Очки (PTS)\n";

        list.forEach((s, idx) => {
            const rank = idx + 1; // Место пересчитывается внутри текущей выборки
            const name = (s.name || '').replace(/;/g, ' ').replace(/"/g, '""');
            const cat = (s.category || '').replace(/;/g, ' ');
            const team = (s.team || '').replace(/;/g, ' ');
            const speed = s.maxSpeed > 0 ? s.maxSpeed.toFixed(2) : '-';
            const stages = `${s.stagesCount} / ${stagesCount}`;
            const points = s.totalPoints || 0;

            csvContent += `${rank};${name};${cat};${team};${speed};${stages};${points}\n`;
        });

        const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
        const link = document.createElement("a");
        link.href = URL.createObjectURL(blob);
        const dateStr = new Date().toISOString().slice(0, 10);

        link.download = `Кубок_${cupName}_${dateStr}.csv`;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        URL.revokeObjectURL(link.href);
    }
// 🌐 4. ВЕБ-ПРОТОКОЛ HTML И ПЕЧАТЬ В PDF (БЕЗ ЭМОДЗИ, ЧИСТЫЙ СТИЛЬ)
    executeCupHtmlExport(payload, isPrintMode) {
        const now = new Date();
        const dateStr = now.toLocaleDateString('ru-RU');
        const timeStr = now.toLocaleTimeString('ru-RU', { hour: '2-digit', minute: '2-digit' });

        const esc = (str) => {
            if (!str) return '';
            if (this.app && typeof this.app.escapeHTML === 'function') return this.app.escapeHTML(str);
            return String(str).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
        };

        let rank = 1;
        let prevPoints = -1;

        let rowsHtml = payload.standings.map((s, idx) => {
            if (s.totalPoints !== prevPoints && idx !== 0) rank = idx + 1;
            prevPoints = s.totalPoints;

            const isTop1 = (rank === 1);
            const rankStyle = isTop1 
                ? 'font-weight:900; background:rgba(255,193,7,0.25); border:1px solid #ffc107; padding:2px 6px; border-radius:4px;' 
                : 'font-weight:800;';

            const speed = s.maxSpeed > 0 ? `${s.maxSpeed.toFixed(2)} км/ч` : '—';
            const cat = s.category || s.baseCluster || '—';

            return `
                <tr>
                    <td style="text-align:center; font-family:monospace; font-size:13px;"><span style="${rankStyle}">${rank}</span></td>
                    <td><b>${esc(s.name)}</b></td>
                    <td style="text-align:center;"><span class="badge">${esc(cat)}</span></td>
                    <td>${esc(s.team)}</td>
                    <td style="text-align:center; font-family:monospace; font-weight:700;">${speed}</td>
                    <td style="text-align:center; font-family:monospace; font-weight:700;">${s.stagesCount} / ${payload.stagesCount}</td>
                    <td style="text-align:right; font-family:monospace; font-weight:900; font-size:13px;">${s.totalPoints.toLocaleString('ru-RU')} pts</td>
                </tr>
            `;
        }).join('');

        const htmlContent = `<!DOCTYPE html>
<html lang="ru">
<head>
    <meta charset="UTF-8">
    <title>${esc(payload.cupName)} — Сводный протокол кубка</title>
    <style>
        body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; background: #f4f4f5; color: #111827; margin: 0; padding: 24px; }
        .sheet { max-width: 960px; margin: 0 auto; background: #ffffff; padding: 32px; border-radius: 16px; border: 1px solid #e4e4e7; box-shadow: 0 4px 20px rgba(0,0,0,0.04); }
        .header { display: flex; justify-content: space-between; align-items: flex-start; border-bottom: 2px solid #ffc107; padding-bottom: 16px; margin-bottom: 20px; }
        .event-title { font-size: 20px; font-weight: 900; text-transform: uppercase; margin: 0; letter-spacing: -0.3px; }
        .doc-title { font-size: 12px; color: #71717a; font-weight: 800; margin-top: 4px; text-transform: uppercase; letter-spacing: 0.5px; }
        .meta { font-size: 11px; color: #a1a1aa; margin-top: 6px; font-family: monospace; }
        .btn-print { background: #ffc107; color: #000; border: none; padding: 8px 16px; border-radius: 8px; font-weight: 800; font-size: 11px; cursor: pointer; text-transform: uppercase; }
        table { width: 100%; border-collapse: collapse; font-size: 12px; margin-top: 14px; }
        th { background: #fafafa; color: #71717a; font-weight: 800; text-transform: uppercase; font-size: 9.5px; padding: 10px; border-bottom: 1.5px solid #e4e4e7; letter-spacing: 0.5px; }
        td { padding: 10px; border-bottom: 1px solid #f4f4f5; vertical-align: middle; }
        tr:nth-child(even) { background: #fdfdfd; }
        .badge { background: #e4e4e7; padding: 2px 6px; border-radius: 4px; font-weight: 700; font-size: 10px; font-family: monospace; }
        .footer { margin-top: 26px; display: flex; justify-content: space-between; font-size: 11px; color: #a1a1aa; border-top: 1px solid #e4e4e7; padding-top: 12px; font-family: monospace; }
        @media print {
            body { background: #fff; padding: 0; }
            .sheet { border: none; box-shadow: none; padding: 0; width: 100%; max-width: 100%; }
            .btn-print { display: none; }
            tr { page-break-inside: avoid; }
        }
    </style>
</head>
<body>
    <div class="sheet">
        <div class="header">
            <div>
                <h1 class="event-title">${esc(payload.cupName)}</h1>
                <div class="doc-title">СВОДНЫЙ КУБКОВЫЙ ЗАЧЕТ • ${payload.stagesCount} ЭТАПОВ</div>
                <div class="meta">Дата фиксации: ${dateStr} | Время: ${timeStr}</div>
            </div>
            <button class="btn-print" onclick="window.print()">Печать / PDF</button>
        </div>

        <table>
            <thead>
                <tr>
                    <th style="text-align:center; width:55px;">РАНГ</th>
                    <th style="text-align:left;">СПОРТСМЕН</th>
                    <th style="text-align:center; width:90px;">КАТЕГОРИЯ</th>
                    <th style="text-align:left;">КОМАНДА</th>
                    <th style="text-align:center; width:120px;">ЛУЧШАЯ СКОРОСТЬ</th>
                    <th style="text-align:center; width:80px;">ЭТАПЫ</th>
                    <th style="text-align:right; width:100px;">БАЛЛЫ</th>
                </tr>
            </thead>
            <tbody>
                ${rowsHtml}
            </tbody>
        </table>

        <div class="footer">
            <div>vilka.sotka.one</div>
            <div>Всего участников в зачете: ${payload.totalCount}</div>
        </div>
    </div>
    ${isPrintMode ? '<script>window.onload = () => { setTimeout(() => window.print(), 250); };<\/script>' : ''}
</body>
</html>`;

        if (isPrintMode) {
            const printWindow = window.open('', '_blank');
            if (printWindow) {
                printWindow.document.write(htmlContent);
                printWindow.document.close();
            } else {
                alert("Разрешите всплывающие окна в браузере для печати протокола");
            }
        } else {
            const blob = new Blob([htmlContent], { type: 'text/html;charset=utf-8;' });
            const link = document.createElement("a");
            const fileDate = `${dateStr.replace(/\./g, '-')}_${timeStr.replace(/:/g, '-')}`;
            link.href = URL.createObjectURL(blob);
            link.download = `CUP_PROTOCOL_${fileDate}.html`;
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);
        }
    }

	
}

class TeamManagerService {
    constructor(app) {
        this.app = app;
    }

    // 1. Создание новой команды
    async createTeam() { 
        const input = document.getElementById('newTeamInput'); 
        const n = input.value.trim(); 
        if (!n) return; 
        try { 
            const pelotonId = this.app.currentPelotonFilter === 'all' ? "" : this.app.currentPelotonFilter;
            const newTeam = await pb.collection('teams').create({ name: n, points: 0, peloton_id: pelotonId }, { requestKey: null }); 
            
            document.getElementById('createTeamModal').style.display = 'none'; 
            input.value = ''; 
            
            // Обновляем карту команд в памяти
            const allTeams = await pb.collection('teams').getFullList({ sort: 'name', requestKey: null });
            this.app.teamsMap = {}; 
            allTeams.forEach(t => { this.app.teamsMap[t.id] = t; });
            
            this.app.crm.adminSwitchTeam(newTeam.id); 
            alert("✅ Команда успешно создана!");
        } catch (e) { alert("❌ Ошибка создания. Проверьте права доступа."); } 
    }

    // 2. Назначение капитана
    async assignCaptain() { 
        const email = document.getElementById('capEmailInput').value.trim(); 
        if(!email) return; 
        try { 
            const newCap = Object.values(this.app.ridersMap).find(r => r.email && r.email.toLowerCase() === email.toLowerCase());
            if (!newCap) return alert("❌ Гонщик с таким Email не найден в базе данных.");
            
            // 🔥 ФИКС: Умное извлечение активной команды
            const myTeams = Array.isArray(this.app.currentRider?.team_id) ? this.app.currentRider.team_id : (this.app.currentRider?.team_id ? [this.app.currentRider.team_id] : []);
            const targetTeamId = this.app.crm.viewedTeamId || (myTeams.length > 0 ? myTeams.find(id => this.app.teamsMap[id]?.peloton_id === this.app.currentPelotonFilter) || myTeams[0] : null);
            
            if (!targetTeamId) return alert("❌ Не удалось определить команду.");

            // Снимаем права со старых капитанов этой команды
            const teamRiders = Object.values(this.app.ridersMap).filter(r => {
                const rTeams = Array.isArray(r.team_id) ? r.team_id : (r.team_id ? [r.team_id] : []);
                return rTeams.includes(targetTeamId);
            });

            for (let oldCap of teamRiders) {
                if (oldCap.roles && oldCap.roles.includes('captain') && oldCap.id !== newCap.id) {
                    let newRoles = oldCap.roles.filter(r => r !== 'captain');
                    await pb.collection('riders').update(oldCap.id, { roles: newRoles }, { requestKey: null });
                }
            }

            // Выдаем права новому капитану и добавляем его в команду (если его там нет)
            let newCapRoles = newCap.roles || [];
            if (!Array.isArray(newCapRoles)) newCapRoles = [newCapRoles];
            if (!newCapRoles.includes('captain')) newCapRoles.push('captain');
            
            let newCapTeams = Array.isArray(newCap.team_id) ? [...newCap.team_id] : (newCap.team_id ? [newCap.team_id] : []);
            if (!newCapTeams.includes(targetTeamId)) newCapTeams.push(targetTeamId);
            
            await pb.collection('riders').update(newCap.id, { team_id: newCapTeams, roles: newCapRoles }, { requestKey: null }); 
            
            alert(`✅ Пользователь успешно назначен капитаном!`); 
            document.getElementById('captainModal').style.display = 'none'; 
            window.location.reload(true); 
        } catch(e) { 
            console.error(e); 
            alert("❌ Ошибка при назначении капитана."); 
        } 
    }

    // 3. Удаление команды
    async deleteTeam() { 
        // 🔥 ФИКС: Умное извлечение активной команды
        const myTeams = Array.isArray(this.app.currentRider?.team_id) ? this.app.currentRider.team_id : (this.app.currentRider?.team_id ? [this.app.currentRider.team_id] : []);
        const targetTeamId = this.app.crm.viewedTeamId || (myTeams.length > 0 ? myTeams.find(id => this.app.teamsMap[id]?.peloton_id === this.app.currentPelotonFilter) || myTeams[0] : null);
        
        const tName = this.app.teamsMap[targetTeamId]?.name || "Эту команду";
        if (!targetTeamId || !confirm(`⚠️ ВНИМАНИЕ! Удалить команду "${tName}" навсегда?`)) return; 
        
        try { 
            await pb.collection('teams').delete(targetTeamId, { requestKey: null }); 
            const allTeams = await pb.collection('teams').getFullList({ sort: 'name', requestKey: null });
            this.app.teamsMap = {}; 
            allTeams.forEach(t => { this.app.teamsMap[t.id] = t; });
            
            this.app.crm.viewedTeamId = null; 
            this.app.crm.switchView('team'); 
        } catch(e) { alert("❌ Ошибка удаления."); } 
    }

    // 4. Переименование команды
    async renameTeam(teamId, currentName) {
        const roles = this.app.usersMap[this.app.currentRider?.email] || [];
        const rStr = JSON.stringify(roles);
        const isAdmin = rStr.includes('admin') || rStr.includes('superadmin');
        
        // 🔥 ФИКС: Проверка капитанства через массив
        const myTeams = Array.isArray(this.app.currentRider?.team_id) ? this.app.currentRider.team_id : (this.app.currentRider?.team_id ? [this.app.currentRider.team_id] : []);
        const isCaptain = rStr.includes('captain') && myTeams.includes(teamId);
        
        if (!isAdmin && !isCaptain) return alert("❌ Только капитан или администратор может менять название команды!");

        const newName = prompt("Введите новое название команды:", currentName);
        if (!newName || newName.trim() === "" || newName === currentName) return;
        
        try {
            await pb.collection('teams').update(teamId, { name: newName.trim() }, { requestKey: null });
            const teamChats = this.app.chats.filter(c => c.team_id === teamId && (c.type === 'team_channel' || c.type === 'team'));
            for (let chat of teamChats) {
                await pb.collection('chats').update(chat.id, { name: newName.trim() }, { requestKey: null });
            }
            alert("✅ Название команды и канала успешно изменено!");
            location.reload(); 
        } catch(e) {
            console.error(e);
            alert("❌ Ошибка при переименовании.");
        }
    }

    // 5. Исключение гонщика
    async removePlayer(riderId) { 
        if(!confirm("Исключить спортсмена из команды и вернуть в свободные агенты?")) return; 
        const oneTeam = Object.values(this.app.teamsMap).find(t => t.name && t.name.toUpperCase().includes('ONE TEAM'));
        const oneTeamId = oneTeam ? oneTeam.id : null;
        if(!oneTeamId) return alert("❌ Не найдена системная база ONE TEAM"); 
        
        // 🔥 ФИКС: Узнаем, из какой команды мы его кикаем
        const myTeams = Array.isArray(this.app.currentRider?.team_id) ? this.app.currentRider.team_id : (this.app.currentRider?.team_id ? [this.app.currentRider.team_id] : []);
        const targetTeamId = this.app.crm.viewedTeamId || (myTeams.length > 0 ? myTeams.find(id => this.app.teamsMap[id]?.peloton_id === this.app.currentPelotonFilter) || myTeams[0] : null);

        if (!targetTeamId) return alert("❌ Не удалось определить команду для исключения.");

        try { 
            const rider = this.app.ridersMap[riderId];
            if (!rider) return;
            
            // Удаляем только текущую открытую команду
            let currentTeams = Array.isArray(rider.team_id) ? [...rider.team_id] : (rider.team_id ? [rider.team_id] : []);
            currentTeams = currentTeams.filter(id => id !== targetTeamId);
            
            // Если выгнали отовсюду - даем статус Свободного Агента (ONE TEAM)
            if (currentTeams.length === 0) currentTeams.push(oneTeamId);

            await pb.collection('riders').update(riderId, { team_id: currentTeams, transfer_request: "" }, { requestKey: null }); 
            this.app.crm.loadData(); 
        } catch(e) { alert("❌ Ошибка удаления"); } 
    }
}  

class RaceTrack3DViewer {
    constructor(canvasContainer, trackData) {
        this.container = canvasContainer;
        this.trackData = trackData;
        this.scene = null;
        this.camera = null;
        this.renderer = null;
        this.controls = null;
        this.animId = null;
        this.curve = null;
        this.runner = null;
        this.runnerLight = null;
        this.init();
    }

    async ensureThreeJs() {
        if (typeof THREE !== 'undefined' && THREE.OrbitControls) return true;
        return new Promise((resolve) => {
            const s1 = document.createElement('script');
            s1.src = 'https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js';
            s1.onload = () => {
                const s2 = document.createElement('script');
                s2.src = 'https://cdn.jsdelivr.net/npm/three@0.128.0/examples/js/controls/OrbitControls.js';
                s2.onload = () => resolve(true);
                document.head.appendChild(s2);
            };
            document.head.appendChild(s1);
        });
    }

    async init() {
        await this.ensureThreeJs();
        if (!this.container) return;
        this.container.innerHTML = '';

        const width = this.container.clientWidth || 700;
        const height = this.container.clientHeight || 400;

        this.scene = new THREE.Scene();
        this.scene.background = new THREE.Color(0x0a0b0e);

        this.camera = new THREE.PerspectiveCamera(40, width / height, 0.1, 1000);
        this.camera.position.set(0, 85, 8);
        this.camera.lookAt(0, 0, 0);

        this.renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true, powerPreference: 'high-performance' });
        this.renderer.setSize(width, height);
        this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
        this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
        this.renderer.toneMappingExposure = 1.0;
        this.container.appendChild(this.renderer.domElement);

        this.controls = new THREE.OrbitControls(this.camera, this.renderer.domElement);
        this.controls.enableDamping = true;
        this.controls.dampingFactor = 0.05;
        this.controls.maxPolarAngle = Math.PI / 2 - 0.05;
        this.controls.minDistance = 15;
        this.controls.maxDistance = 220;

        const ambLight = new THREE.AmbientLight(0xffffff, 0.35);
        this.scene.add(ambLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1.2);
        dirLight.position.set(50, 90, 50);
        this.scene.add(dirLight);

        const fillLight = new THREE.DirectionalLight(0xffc107, 0.35);
        fillLight.position.set(-50, -30, -50);
        this.scene.add(fillLight);

        this.buildTrack();

        // 🔄 Анимационный цикл с бегущим шариком
        const animate = () => {
            this.animId = requestAnimationFrame(animate);
            this.controls.update();

            if (this.curve && this.runner) {
                const now = performance.now();
                // Полный цикл проезда от старта до финиша за ~8 секунд
                const t = (now * 0.00012) % 1;
                const point = this.curve.getPointAt(t);
                this.runner.position.copy(point);
                if (this.runnerLight) {
                    this.runnerLight.position.copy(point);
                }
            }

            this.renderer.render(this.scene, this.camera);
        };
        animate();
    }

  buildTrack() {
        const pts = this.trackData.points;
        if (!pts || pts.length < 2) return;

        let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
        let minEle = Infinity, maxEle = -Infinity;

        pts.forEach(p => {
            minX = Math.min(minX, p.lon); maxX = Math.max(maxX, p.lon);
            minY = Math.min(minY, p.lat); maxY = Math.max(maxY, p.lat);
            minEle = Math.min(minEle, p.ele); maxEle = Math.max(maxEle, p.ele);
        });

        const centerX = (minX + maxX) / 2;
        const centerY = (minY + maxY) / 2;
        const scaleGeo = 60 / (Math.max(maxX - minX, maxY - minY) || 0.01);
        const eleDiff = maxEle - minEle;
        
        // 1 градус широты ≈ 111 320 метров. Переводим гео-масштаб в метры:
        const unitsPerMeter = scaleGeo / 111320;
        
        // Преувеличение рельефа в 2.8 раза (достаточно, чтобы видеть холмы, но без диких пиков)
        let eleScale = unitsPerMeter * 2.8;

        // Ограничитель: максимальный подъем рельефа над сеткой не превысит 4 единиц
        if (eleDiff * eleScale > 4.5) {
            eleScale = 4.5 / eleDiff;
        }

        const vec3Points = pts.map(p => {
            const x = (p.lon - centerX) * scaleGeo * Math.cos(centerY * Math.PI / 180);
            const z = -(p.lat - centerY) * scaleGeo;
            const y = eleDiff > 0 ? (p.ele - minEle) * eleScale : 0;
            return new THREE.Vector3(x, y, z);
        });

        this.curve = new THREE.CatmullRomCurve3(vec3Points);

        // 1. Геометрия трубы трека
        const tubeGeo = new THREE.TubeGeometry(
            this.curve, 
            Math.max(pts.length * 3, 250), 
            0.18, 
            12, 
            false
        );

        const getColorForSlope = (slope) => {
            if (slope > 12) return new THREE.Color(0xef4444);
            if (slope > 7)  return new THREE.Color(0xf59e0b);
            if (slope > 3)  return new THREE.Color(0xffc107);
            if (slope < -4) return new THREE.Color(0x06b6d4);
            return new THREE.Color(0xe4e4e7);
        };

        const colors = [];
        const count = tubeGeo.attributes.position.count;
        for (let i = 0; i < count; i++) {
            const ptIdx = Math.min(pts.length - 1, Math.floor((i / count) * pts.length));
            const c = getColorForSlope(pts[ptIdx].slope);
            colors.push(c.r, c.g, c.b);
        }
        tubeGeo.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));

        const tubeMat = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.35, metalness: 0.2 });
        this.scene.add(new THREE.Mesh(tubeGeo, tubeMat));

        // 2. Сетка подложки
        const gridHelper = new THREE.GridHelper(80, 20, 0x27272a, 0x14161b);
        gridHelper.position.y = -0.2;
        this.scene.add(gridHelper);

        // -------------------------------------------------------------
        // 🏁 3. МАРКЕРЫ СТАРТА И ФИНИША НА АККУРАТНЫХ ПИНАХ-МАЯКАХ
        // -------------------------------------------------------------
        const startPos = this.curve.getPointAt(0);
        const endPos = this.curve.getPointAt(1);
        const isLoopCourse = startPos.distanceTo(endPos) < 1.5;

        // Вспомогательная функция создания парящего пина со шпилькой
        const createPin3D = (pos, colorHex, isLoop = false) => {
            const group = new THREE.Group();

            // Тонкая полупрозрачная ножка-шпилька (высота 1.1 ед.)
            const stemGeo = new THREE.CylinderGeometry(0.03, 0.03, 1.1, 8);
            const stemMat = new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.65 });
            const stem = new THREE.Mesh(stemGeo, stemMat);
            stem.position.set(0, 0.55, 0);
            group.add(stem);

            // Парящая верхушка (не пересекается с полотном дороги)
            const headGeo = new THREE.SphereGeometry(0.35, 16, 16);
            const headMat = new THREE.MeshStandardMaterial({
                color: colorHex,
                emissive: colorHex,
                emissiveIntensity: 0.7,
                roughness: 0.2
            });
            const head = new THREE.Mesh(headGeo, headMat);
            head.position.set(0, 1.1, 0);
            group.add(head);

            group.position.copy(pos);
            return group;
        };

        if (isLoopCourse) {
            // КОЛЬЦО: Ставим один чистый маркер старта/финиша изумрудного цвета
            this.scene.add(createPin3D(startPos, 0x10b981, true));
        } else {
            // ЛИНЕЙНАЯ ТРАССА: Зеленый старт и красный финиш
            this.scene.add(createPin3D(startPos, 0x10b981, false));
            this.scene.add(createPin3D(endPos, 0xef4444, false));
        }

        // 🟡 4. БЕГУЩИЙ ОГОНЁК (аккуратный размер 0.26 вместо 0.62)
        const runnerMat = new THREE.MeshStandardMaterial({
            color: 0xffffff,
            emissive: 0xffc107,
            emissiveIntensity: 1.8,
            roughness: 0.1
        });
        this.runner = new THREE.Mesh(new THREE.SphereGeometry(0.26, 16, 16), runnerMat);
        this.runner.position.copy(startPos);
        this.scene.add(this.runner);

        this.runnerLight = new THREE.PointLight(0xffc107, 1.8, 10);
        this.runnerLight.position.copy(startPos);
        this.scene.add(this.runnerLight);
    }
    destroy() {
        if (this.animId) cancelAnimationFrame(this.animId);
        if (this.renderer?.domElement?.parentNode) {
            this.renderer.domElement.parentNode.removeChild(this.renderer.domElement);
        }
    }
}
