		// 🔥 ЭКСТРЕННАЯ АПТЕЧКА: Полный сброс приложения при зависании
    hardResetApp() {
        console.log("Выполняется жесткий сброс кэша...");
        
        // Сохраняем авторизацию и настройки
        const authData = localStorage.getItem('pocketbase_auth');
        const guestId = localStorage.getItem('vilka_guest_id');
        const theme = localStorage.getItem('sotka_theme');
        
        // Очищаем локальное хранилище данных
        localStorage.clear();
        sessionStorage.clear();
        
        // Восстанавливаем авторизацию
        if (authData) localStorage.setItem('pocketbase_auth', authData);
        if (guestId) localStorage.setItem('vilka_guest_id', guestId);
        if (theme) localStorage.setItem('sotka_theme', theme);
        
        if ('serviceWorker' in navigator) {
            navigator.serviceWorker.getRegistrations().then(registrations => {
                for (let r of registrations) r.unregister();
            });
        }
        
        window.location.reload(true);
    }
	
	// ==========================================
        // 🚀 СИСТЕМА PWA-ОБНОВЛЕНИЯ (LIKE PERO)
        // ==========================================
        initPwaUpdateCheck() {
    if (!('serviceWorker' in navigator)) return;

    let refreshing = false;
    navigator.serviceWorker.addEventListener('controllerchange', () => {
        if (!refreshing) {
            refreshing = true;
            window.location.reload();
        }
    });

    navigator.serviceWorker.ready.then(registration => {
        // 🔥 Проверяем наличие обновлений СРАЗУ при запуске приложения:
        registration.update().catch(() => {});

        if (registration.waiting) {
            this.showUpdateBanner(registration.waiting);
            return;
        }

        registration.addEventListener('updatefound', () => {
            const newWorker = registration.installing;
            if (!newWorker) return;

            newWorker.addEventListener('statechange', () => {
                if (newWorker.state === 'installed' && navigator.serviceWorker.controller) {
                    this.showUpdateBanner(newWorker);
                }
            });
        });

        setInterval(() => {
            registration.update().catch(() => {});
        }, 15 * 60 * 1000);

        document.addEventListener('visibilitychange', () => {
            if (document.visibilityState === 'visible') {
                registration.update().catch(() => {});
            }
        });
    });
}

