        const pinnedBar = document.getElementById('pinnedMessageBar');
        if (pinnedBar) pinnedBar.style.display = 'none';

        const staticInfoBanner = document.getElementById('staticInfoBanner');
        if (staticInfoBanner) staticInfoBanner.style.display = 'none';

        // 1. Единая геометрия шапки (65px, отступы 12px 20px, чистый фон)
