            this.activeChatId = realChatId; 
            this.activeRaceId = activeRaceId;
            this.expandedRaceId = activeRaceId;

            // 💾 2. СОХРАНЯЕМ ТЕКУЩИЙ ПОИСКОВЫЙ ЗАПРОС
            const searchInput = document.getElementById('chatSearch');
            const currentSearch = searchInput ? searchInput.value.trim() : '';

            this.unreadCounts[realChatId] = 0;
