            this.openChatMobile();
            
            // Подсвечиваем активный чат / дистанцию в списке слева
            document.querySelectorAll('.chat-item').forEach(el => el.classList.remove('active')); 
            const activeItem = document.getElementById(`chat-item-${activeRaceId}`) || document.getElementById(`chat-item-${realChatId}`); 
            if (activeItem) activeItem.classList.add('active');
            
            const emptyMsg = document.getElementById('emptyChatMsg'); 
            if (emptyMsg) emptyMsg.style.display = 'none';
            document.getElementById('chatHeader').style.display = 'flex'; 

            // 3. ПОДГОТОВКА ДАННЫХ ДЛЯ ШАПКИ
            let chatName = targetRace ? targetRace.name : (this.getChatName(chat) || "Чат"); 
            const nameEl = document.getElementById('activeChatName');
