                    // 🔒 Защита от мерцания: если кнопка уже содержит нужный текст и иконку — не перерисовываем её!
const targetStateKey = `${svgType}_${text}`;
if (b.dataset.renderedState === targetStateKey && !b.innerHTML.includes('spinner')) {
    return;
}
b.dataset.renderedState = targetStateKey;
b.innerHTML = `${svgIcon} <span>${text}</span>`;

