// ==========================================
// 👑 DRAFT TREASURY HUB: ЛОГИКА СУПЕРАДМИНА
// ==========================================

let treasuryRawData = null;
let currentTreasuryTab = 'wallets';
let targetAdjustUser = null;

// Автопроверка роли суперадмина для отображения кнопки
window.checkSuperadminTreasuryEntry = function() {
    let roles = [];
    try {
        const model = pb?.authStore?.model;
        roles = model?.role || [];
        if (!Array.isArray(roles) && roles) roles = [roles];
    } catch(e) {}

    const isSuper = roles.includes('superadmin');
    const btn = document.getElementById('btn-open-treasury');
    if (btn) {
        btn.style.display = isSuper ? 'inline-flex' : 'none';
    }
};

window.openDraftTreasury = async function() {
    const modal = document.getElementById('draftTreasuryModal');
    if (!modal) return;
    modal.style.display = 'flex';
    await window.fetchTreasuryData();
};

window.closeDraftTreasury = function() {
    const modal = document.getElementById('draftTreasuryModal');
    if (modal) modal.style.display = 'none';
};

window.switchTreasuryTab = function(tab) {
    currentTreasuryTab = tab;
    ['wallets', 'debts', 'audit'].forEach(t => {
        const btn = document.getElementById(`tab-btn-${t}`);
        const content = document.getElementById(`treasury-tab-${t}`);
        if (btn) btn.classList.toggle('active', t === tab);
        if (content) content.style.display = (t === tab) ? 'flex' : 'none';
    });
};

window.fetchTreasuryData = async function() {
    if (!pb || !pb.authStore || !pb.authStore.isValid) return;

    try {
        const res = await pb.send('/api/draft/admin/treasury-overview', { method: 'GET' });
        treasuryRawData = res;

        const kpi = res.kpi || {};
        const elTotal = document.getElementById('kpi-total-val');
        const elSub = document.getElementById('kpi-real-bonus-sub');
        const elRev = document.getElementById('kpi-revenue-val');
        const elDebt = document.getElementById('kpi-debt-val');
        const elDebtSub = document.getElementById('kpi-debt-sub');
        const elTabTitle = document.getElementById('treasury-debt-tab-title');

        if (elTotal) elTotal.innerText = `${kpi.total_circulation?.toLocaleString('ru-RU') || 0} W`;
        if (elSub) elSub.innerText = `Real: ${kpi.total_real || 0} • Bonus: ${kpi.total_bonus || 0}`;
        if (elRev) elRev.innerText = `+${kpi.timing_revenue?.toLocaleString('ru-RU') || 0} W`;
        if (elDebt) elDebt.innerText = `-${kpi.total_debt?.toLocaleString('ru-RU') || 0} W`;
        if (elDebtSub) elDebtSub.innerText = `${kpi.debt_wallets_count || 0} должников`;
        if (elTabTitle) elTabTitle.innerText = `ЗАДОЛЖЕННОСТИ (${kpi.debt_wallets_count || 0})`;

        renderTreasuryWallets(res.wallets || []);
        renderTreasuryDebts(res.wallets?.filter(w => w.is_debt) || []);
        renderTreasuryAudit(res.audit_log || []);
    } catch (err) {
        console.error('Ошибка казначейства:', err);
        alert('Не удалось загрузить данные: ' + (err.message || 'Ошибка связи'));
    }
};

function renderTreasuryWallets(list) {
    const container = document.getElementById('treasury-wallets-list');
    if (!container) return;
    if (!list || list.length === 0) {
        container.innerHTML = '<div style="text-align:center; padding:30px; font-size:10px; color:var(--text-muted); font-family:\'Unbounded\';">Кошельков не найдено</div>';
        return;
    }

    let html = '';
    list.forEach(w => {
        const realStr = w.real >= 0 ? `${w.real.toLocaleString('ru-RU')} W` : `-${Math.abs(w.real).toLocaleString('ru-RU')} W`;
        const realColor = w.real < 0 ? 'var(--danger)' : 'var(--text-main)';
        const safeName = (w.user_name || '').replace(/'/g, "\\'");

        html += `
          <div class="treasury-card ${w.is_debt ? 'is-debt' : ''}" 
               style="cursor: pointer;"
               onclick="openWalletHistoryModal('${w.user_id}', '${safeName}')"
               title="Нажмите для просмотра полной истории операций">
            <div style="min-width:0; flex:1;">
              <div class="treasury-card-name">${w.user_name}</div>
              <div class="treasury-card-meta">${w.user_email}</div>
            </div>
            
            <div style="text-align:right;">
              <div class="treasury-card-balance" style="color: ${realColor};">${realStr}</div>
              <div class="treasury-card-subbalance">Bonus: ${w.bonus} W</div>
            </div>

            <button type="button" class="treasury-badge-action" onclick="event.stopPropagation(); openAdjustModal('${w.user_id}', '${safeName}')" title="Корректировка баланса">
              <span>± W</span>
            </button>
          </div>
        `;
    });
    container.innerHTML = html;
}

// Открытие и загрузка выписки конкретного спортсмена
window.openWalletHistoryModal = async function(userId, fallbackName) {
    const modal = document.getElementById('treasuryWalletHistoryModal');
    const nameEl = document.getElementById('history-modal-user-name');
    const metaEl = document.getElementById('history-modal-user-meta');
    const listEl = document.getElementById('history-modal-tx-list');

    if (nameEl) nameEl.innerText = fallbackName || 'Загрузка...';
    if (metaEl) metaEl.innerText = 'Запрашиваем операции...';
    if (listEl) {
        listEl.innerHTML = `<div style="text-align:center; padding:30px;"><span class="spinner" style="width:24px; height:24px; border-width:2px; display:inline-block; border-color:var(--primary) transparent transparent transparent;"></span></div>`;
    }
    if (modal) modal.style.display = 'flex';

    try {
        const res = await pb.send(`/api/draft/admin/wallet-history?user_id=${userId}`, { method: 'GET' });
        
        if (nameEl) nameEl.innerText = res.user?.name || fallbackName;
        if (metaEl) metaEl.innerText = `${res.user?.email || ''} • Всего операций: ${res.transactions?.length || 0}`;

        if (!res.transactions || res.transactions.length === 0) {
            listEl.innerHTML = `<div style="text-align:center; padding:30px; font-size:10px; color:var(--text-muted); font-family:'Unbounded';">История транзакций пуста</div>`;
            return;
        }

        let html = '';
        res.transactions.forEach(tx => {
            const isOut = tx.is_outgoing;
            const status = (tx.status || 'success').toLowerCase();
            const isPending = status === 'pending';
            const isFailed = status === 'failed' || status === 'canceled';

            let sign = isOut ? '−' : '+';
            let color = isOut ? 'var(--text-main)' : 'var(--success, #10b981)';
            let statusBadge = '';
            let opacity = '1';

            if (isPending) {
                sign = '';
                color = 'var(--text-muted)';
                opacity = '0.65';
                statusBadge = '<span style="font-family:\'Unbounded\'; font-size:7.5px; padding:1px 5px; border-radius:4px; background:rgba(255,193,7,0.15); color:var(--primary); border:1px solid rgba(255,193,7,0.3); margin-left:6px; text-transform:uppercase;">НЕ ОПЛАЧЕН</span>';
            } else if (isFailed) {
                sign = '';
                color = 'var(--danger)';
                opacity = '0.5';
                statusBadge = '<span style="font-family:\'Unbounded\'; font-size:7.5px; padding:1px 5px; border-radius:4px; background:rgba(239,68,68,0.15); color:var(--danger); border:1px solid rgba(239,68,68,0.3); margin-left:6px; text-transform:uppercase;">ОТМЕНЕН</span>';
            }

            const dateStr = tx.created ? new Date(tx.created).toLocaleString('ru-RU', { day:'2-digit', month:'2-digit', year:'2-digit', hour:'2-digit', minute:'2-digit' }) : '—';
            const counterpart = isOut ? `Кому: ${tx.receiver_name}` : `От кого: ${tx.sender_name}`;

            html += `
              <div class="treasury-card" style="padding: 8px 12px; cursor: default; opacity: ${opacity};">
                <div style="min-width:0; flex:1;">
                  <div style="display:flex; align-items:center; gap:6px; flex-wrap:wrap;">
                    <span style="font-family:'Unbounded'; font-size:7.5px; padding:1px 5px; border-radius:4px; background:var(--bg-body); border:1px solid var(--border); text-transform:uppercase;">${tx.type}</span>
                    <span style="font-size:11px; font-weight:700; color:var(--text-main); white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">
                      ${tx.description || tx.type}
                    </span>
                    ${statusBadge}
                  </div>
                  <div style="font-size:9.5px; font-family:'Roboto Mono'; color:var(--text-muted); margin-top:2px;">
                    ${dateStr} • ${counterpart}
                  </div>
                </div>
                <div style="font-family:'Roboto Mono'; font-weight:900; font-size:13px; color:${color}; flex-shrink:0;">
                  ${sign}${tx.amount.toLocaleString('ru-RU')} W
                </div>
              </div>
            `;
        });
        listEl.innerHTML = html;

    } catch (err) {
        if (listEl) {
            listEl.innerHTML = `<div style="text-align:center; padding:30px; font-size:11px; color:var(--danger);">Ошибка загрузки: ${err.message || 'Сбой сети'}</div>`;
        }
    }
};
window.closeWalletHistoryModal = function() {
    const modal = document.getElementById('treasuryWalletHistoryModal');
    if (modal) modal.style.display = 'none';
};
function renderTreasuryDebts(debts) {
    const container = document.getElementById('treasury-debts-list');
    if (!container) return;
    if (!debts || debts.length === 0) {
        container.innerHTML = '<div style="text-align:center; padding:30px; font-size:10px; color:var(--text-muted); font-family:\'Unbounded\';">Все счета в плюсе. Должников нет.</div>';
        return;
    }

    let html = '';
    debts.forEach(w => {
        const safeName = (w.user_name || '').replace(/'/g, "\\'");
        html += `
          <div class="treasury-card is-debt">
            <div style="min-width:0; flex:1;">
              <div class="treasury-card-name" style="color:var(--danger);">${w.user_name}</div>
              <div class="treasury-card-meta">${w.user_email}</div>
            </div>
            
            <div style="text-align:right;">
              <div class="treasury-card-balance" style="color:var(--danger); font-size:14px;">-${Math.abs(w.real)} W</div>
              <div class="treasury-card-subbalance">Овердрафт за судейство</div>
            </div>

            <button type="button" class="treasury-badge-action" style="border-color:rgba(239,68,68,0.3); color:var(--danger);" onclick="openAdjustModal('${w.user_id}', '${safeName}')">
              <span>ПОГАСИТЬ</span>
            </button>
          </div>
        `;
    });
    container.innerHTML = html;
}

function renderTreasuryAudit(txList) {
    const container = document.getElementById('treasury-audit-list');
    if (!container) return;
    if (!txList || txList.length === 0) {
        container.innerHTML = '<div style="text-align:center; padding:30px; font-size:10px; color:var(--text-muted); font-family:\'Unbounded\';">История пуста</div>';
        return;
    }

    let html = '';
    txList.forEach(tx => {
        const dateStr = tx.created ? new Date(tx.created).toLocaleString('ru-RU', { day:'2-digit', month:'2-digit', hour:'2-digit', minute:'2-digit' }) : '—';
        html += `
          <div class="treasury-card" style="padding:6px 10px;">
            <div style="min-width:0; flex:1;">
              <div style="display:flex; align-items:center; gap:6px;">
                <span style="font-family:'Unbounded'; font-size:7.5px; padding:1px 5px; border-radius:4px; background:var(--bg-body); border:1px solid var(--border);">${tx.type}</span>
                <span style="font-size:10.5px; font-weight:700; color:var(--text-main); white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">
                  ${tx.description || tx.type}
                </span>
              </div>
              <div style="font-size:9px; font-family:'Roboto Mono'; color:var(--text-muted); margin-top:2px;">
                ${dateStr} • ${tx.sender_name} → ${tx.receiver_name}
              </div>
            </div>
            <div style="font-family:'Roboto Mono'; font-weight:800; font-size:12px; color:var(--text-main); flex-shrink:0;">
              ${tx.amount} W
            </div>
          </div>
        `;
    });
    container.innerHTML = html;
}

window.filterTreasuryWallets = function(query) {
    if (!treasuryRawData || !treasuryRawData.wallets) return;
    const q = (query || '').trim().toLowerCase();
    if (!q) {
        renderTreasuryWallets(treasuryRawData.wallets);
        return;
    }
    const filtered = treasuryRawData.wallets.filter(w => 
        (w.user_name || '').toLowerCase().includes(q) || 
        (w.user_email || '').toLowerCase().includes(q) || 
        (w.user_id || '').toLowerCase().includes(q)
    );
    renderTreasuryWallets(filtered);
};

window.openAdjustModal = function(userId, userName) {
    targetAdjustUser = userId;
    const nameEl = document.getElementById('adjust-user-name');
    const amtEl = document.getElementById('adjust-amount-input');
    const rsnEl = document.getElementById('adjust-reason-input');
    const bktEl = document.getElementById('adjust-bucket-select');
    const modal = document.getElementById('treasuryAdjustModal');

    if (nameEl) nameEl.innerText = userName;
    if (amtEl) amtEl.value = '';
    if (rsnEl) rsnEl.value = '';
    if (bktEl) bktEl.value = 'real';
    if (modal) modal.style.display = 'flex';
    setTimeout(() => amtEl?.focus(), 50);
};

window.closeAdjustModal = function() {
    targetAdjustUser = null;
    const modal = document.getElementById('treasuryAdjustModal');
    if (modal) modal.style.display = 'none';
};

window.submitBalanceAdjustment = async function() {
    if (!targetAdjustUser) return;
    const amount = parseInt(document.getElementById('adjust-amount-input')?.value, 10);
    const bucket = document.getElementById('adjust-bucket-select')?.value || 'real';
    const reason = document.getElementById('adjust-reason-input')?.value.trim();

    if (isNaN(amount) || amount === 0) {
        alert('Введите корректную сумму (не 0)');
        return;
    }
    if (!reason) {
        alert('Укажите причину корректировки для аудита');
        return;
    }

    const btn = document.getElementById('btn-save-adjustment');
    if (btn) { btn.innerText = 'ПРОВОДКА...'; btn.disabled = true; }

    try {
        await pb.send('/api/draft/admin/adjust-balance', {
            method: 'POST',
            body: {
                user_id: targetAdjustUser,
                amount: amount,
                bucket: bucket,
                reason: reason
            }
        });

        alert(`✓ Успешно: ${amount > 0 ? '+' : ''}${amount} W`);
        window.closeAdjustModal();
        await window.fetchTreasuryData();
    } catch (err) {
        alert('Ошибка проводки: ' + (err.message || 'Сбой сервера'));
    } finally {
        if (btn) { btn.innerText = 'ПРИМЕНИТЬ'; btn.disabled = false; }
    }
};

    // --- ГЛОБАЛЬНЫЙ ЗАПУСК ---
window.sotkaAuth = new SotkaAuthManager();
window.app = new MessengerApp();

    document.addEventListener('DOMContentLoaded', () => {
        window.app.init();
    });
    
    const appManifest = {
        "name": "VILKA RADIO", "short_name": "VILKA", "start_url": window.location.href.split('?')[0], "display": "standalone", "background_color": "#18181b", "theme_color": "#ffc107",
        "icons": [
            { "src": "https://cdn-icons-png.flaticon.com/512/2972/2972185.png", "sizes": "192x192", "type": "image/png" },
            { "src": "https://cdn-icons-png.flaticon.com/512/2972/2972185.png", "sizes": "512x512", "type": "image/png" }
        ]
    };
    const manifestBlob = new Blob([JSON.stringify(appManifest)], { type: 'application/json' });
    const manifestUrl = URL.createObjectURL(manifestBlob);
    document.head.insertAdjacentHTML('beforeend', `<link rel="manifest" href="${manifestUrl}">`);
    document.head.insertAdjacentHTML('beforeend', `<meta name="theme-color" content="#ffc107">`);
    document.head.insertAdjacentHTML('beforeend', `<meta name="apple-mobile-web-app-capable" content="yes">`);
    document.head.insertAdjacentHTML('beforeend', `<meta name="apple-mobile-web-app-status-bar-style" content="black-translucent">`);
    document.head.insertAdjacentHTML('beforeend', `<link rel="apple-touch-icon" href="https://cdn-icons-png.flaticon.com/512/2972/2972185.png">`); 

    let deferredPrompt;
    window.addEventListener('beforeinstallprompt', (e) => { e.preventDefault(); deferredPrompt = e; });

    window.installPWA = async () => {
        const userAgent = navigator.userAgent || navigator.vendor || window.opera;
        const isIOS = /iPad|iPhone|iPod/.test(userAgent) && !window.MSStream;
        const isAndroid = /android/i.test(userAgent);
        
        const modal = document.getElementById('installGuideModal');
        const content = document.getElementById('installGuideContent');

        if (deferredPrompt) {
            deferredPrompt.prompt();
            const { outcome } = await deferredPrompt.userChoice;
            if (outcome === 'accepted') {
                const btn = document.getElementById('installAppHeaderBtn');
                if(btn) btn.style.display = 'none';
            }
            deferredPrompt = null;
            return;
        } 
        
        let guideHtml = '';
        if (isIOS) {
            guideHtml = `
                <div style="background: var(--bg-body); padding: 15px; border-radius: 12px; border: 1px solid var(--border);">
                    <div style="display:flex; align-items:center; gap: 15px; margin-bottom: 20px;">
                        <div style="background: #fff; color: #007aff; padding: 10px; border-radius: 8px; flex-shrink:0;"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 12v8a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-8"></path><polyline points="16 6 12 2 8 6"></polyline><line x1="12" y1="2" x2="12" y2="15"></line></svg></div>
                        <span><b>Шаг 1:</b> В браузере Safari нажмите кнопку <b>«Поделиться»</b> (внизу по центру).</span>
                    </div>
                    <div style="display:flex; align-items:center; gap: 15px;">
                        <div style="background: #fff; color: #000; padding: 10px; border-radius: 8px; flex-shrink:0;"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="3" width="18" height="18" rx="4" ry="4"></rect><line x1="12" y1="8" x2="12" y2="16"></line><line x1="8" y1="12" x2="16" y2="12"></line></svg></div>
                        <span><b>Шаг 2:</b> В появившемся меню прокрутите вниз и выберите <b>«На экран Домой»</b>.</span>
                    </div>
                </div>`;
        } else if (isAndroid) {
             guideHtml = `
                <div style="background: var(--bg-body); padding: 15px; border-radius: 12px; border: 1px solid var(--border);">
                    <div style="display:flex; align-items:center; gap: 15px; margin-bottom: 20px;">
                        <div style="background: #fff; color: #333; padding: 10px; border-radius: 8px; flex-shrink:0;"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><circle cx="12" cy="5" r="1.5"></circle><circle cx="12" cy="12" r="1.5"></circle><circle cx="12" cy="19" r="1.5"></circle></svg></div>
                        <span><b>Шаг 1:</b> Откройте меню браузера (нажмите на <b>три точки ⋮</b> в правом верхнем углу).</span>
                    </div>
                    <div style="display:flex; align-items:center; gap: 15px;">
                        <div style="background: #fff; color: #000; padding: 10px; border-radius: 8px; flex-shrink:0;"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="3" width="18" height="18" rx="2" ry="2"></rect><line x1="12" y1="8" x2="12" y2="16"></line><line x1="8" y1="12" x2="16" y2="12"></line></svg></div>
                        <span><b>Шаг 2:</b> Найдите и нажмите пункт <b>«Добавить на главный экран»</b> или <b>«Установить приложение»</b>.</span>
                    </div>
                </div>`;
        } else {
             guideHtml = `
                <div style="background: var(--bg-body); padding: 15px; border-radius: 12px; border: 1px solid var(--border);">
                    <div style="display:flex; align-items:center; gap: 15px; margin-bottom: 20px;">
                        <div style="background: #fff; color: #333; padding: 10px; border-radius: 8px; flex-shrink:0;"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><circle cx="12" cy="5" r="1.5"></circle><circle cx="12" cy="12" r="1.5"></circle><circle cx="12" cy="19" r="1.5"></circle></svg></div>
                        <span><b>Шаг 1:</b> Откройте меню браузера Chrome (<b>три точки ⋮</b> в правом верхнем углу).</span>
                    </div>
                    <div style="display:flex; align-items:center; gap: 15px;">
                        <div style="background: #fff; color: #000; padding: 10px; border-radius: 8px; flex-shrink:0;"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"></path><polyline points="7 10 12 15 17 10"></polyline><line x1="12" y1="15" x2="12" y2="3"></line></svg></div>
                        <span><b>Шаг 2:</b> Выберите пункт <b>«Сохранить и поделиться»</b> ➔ <b>«Установить страницу как приложение»</b>.</span>
                    </div>
                </div>`;
        }
        
        if (content && modal) {
            content.innerHTML = guideHtml;
            modal.style.display = 'flex';
        }
    };

    window.addEventListener('DOMContentLoaded', () => {
        if (window.matchMedia('(display-mode: standalone)').matches || window.navigator.standalone === true) {
            const btn = document.getElementById('installAppHeaderBtn');
            if(btn) btn.style.display = 'none';
        }
    });

   // ==========================================
    // 🔥 PULL-TO-REFRESH (СВАЙП ВНИЗ ДЛЯ ПЕРЕЗАГРУЗКИ)
    // ==========================================
    function initPullToRefresh() {
        let touchStartY = 0;
        let isPulling = false;

        const ptrIndicator = document.createElement('div');
        ptrIndicator.innerHTML = '<div style="background: var(--bg-surface); padding: 10px 20px; border-radius: 20px; box-shadow: 0 5px 15px rgba(0,0,0,0.3); display: flex; align-items: center; gap: 10px; border: 1px solid var(--primary);"><span class="spinner" style="width: 14px; height: 14px; border-width: 2px; border-color: var(--primary) transparent transparent transparent;"></span> <span style="font-size: 12px; font-family:\'Unbounded\'; font-weight:800; color: var(--text-main);">ОБНОВЛЕНИЕ...</span></div>';
        ptrIndicator.style.cssText = 'position: fixed; top: -60px; left: 0; width: 100%; display: flex; justify-content: center; z-index: 999999; transition: top 0.2s ease-out; pointer-events: none;';
        document.body.appendChild(ptrIndicator);

        document.addEventListener('touchstart', (e) => {
            // 1. Находим ближайший скролл-контейнер под пальцем
            const scrollContainer = e.target.closest('#chatList, #messagesContainer, .p-table-container, .modal-box, #crmContentArea');
            
            // 2. Если мы внутри длинного списка (протокола) и он прокручен вниз хотя бы чуть-чуть
            // то Pull-to-Refresh ЗАПРЕЩЕН.
            if (scrollContainer && scrollContainer.scrollTop > 5) {
                isPulling = false;
                return;
            }
            
            // 3. Если мы не в контейнере или контейнер в самом верху (scrollTop === 0)
            touchStartY = e.touches[0].clientY;
            isPulling = true;
        }, { passive: true });

        document.addEventListener('touchmove', (e) => {
            if (!isPulling) return;
            
            const currentY = e.touches[0].clientY;
            const pullDistance = currentY - touchStartY;

            // Если палец движется ВВЕРХ (обычный скролл вниз) — сразу выключаем логику пулла
            if (pullDistance < 0) {
                isPulling = false;
                return;
            }

            // Визуальный индикатор появляется только если потянули вниз реально ощутимо
            if (pullDistance > 50 && pullDistance < 200) {
                ptrIndicator.style.top = '30px';
            }
        }, { passive: true });

        document.addEventListener('touchend', (e) => {
            if (!isPulling) return;
            const pullDistance = e.changedTouches[0].clientY - touchStartY;
            
            // Порог срабатывания увеличил до 120px, чтобы исключить случайные дергания
            if (pullDistance > 120) {
                if(typeof showVilkaSplash === 'function') showVilkaSplash();
                setTimeout(() => window.location.reload(true), 300);
            } else {
                ptrIndicator.style.top = '-60px';
            }
            isPulling = false;
        }, { passive: true });
    }
	
    // ==========================================
    // 🔥 SWIPE-TO-CLOSE (СВАЙП ВПРАВО ДЛЯ ЗАКРЫТИЯ ЧАТА)
    // ==========================================
    function initSwipeGestures() {
        let touchStartX = 0; 
        let touchStartY = 0;
        
        document.addEventListener('touchstart', (e) => { 
            touchStartX = e.touches[0].clientX; 
            touchStartY = e.touches[0].clientY; 
        }, { passive: true });
        
        document.addEventListener('touchend', (e) => {
            const chatArea = document.getElementById('mainChatArea');
            // Если мы на мобилке и чат открыт
            if (chatArea && chatArea.classList.contains('mobile-open')) {
                const diffX = e.changedTouches[0].clientX - touchStartX; 
                const diffY = Math.abs(e.changedTouches[0].clientY - touchStartY);
                
                // Если жест был явным горизонтальным свайпом вправо (X > 80, а по Y сдвиг минимальный)
                if (diffX > 80 && diffY < 50) {
                    if (window.app && typeof window.app.closeChatMobile === 'function') {
                        window.app.closeChatMobile();
                    }
                }
            }
        }, { passive: true });
    }

    // ==========================================
    // 🔥 МОНИТОР ИНТЕРНЕТА
    // ==========================================
    function initConnectionMonitor() {
        const offlineBanner = document.createElement('div');
        offlineBanner.id = 'vilka-offline-banner';
        offlineBanner.innerHTML = `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="1" y1="1" x2="23" y2="23"></line><path d="M16.72 11.06A10.94 10.94 0 0 1 19 12.55"></path><path d="M5 12.55a10.94 10.94 0 0 1 5.17-2.39"></path><path d="M10.71 5.05A16 16 0 0 1 22.58 9"></path><path d="M1.42 9a15.91 15.91 0 0 1 4.7-2.88"></path><path d="M8.53 16.11a6 6 0 0 1 6.95 0"></path><line x1="12" y1="20" x2="12.01" y2="20"></line></svg> НЕТ ПОДКЛЮЧЕНИЯ К СЕРВЕРУ`;
        offlineBanner.style.cssText = 'position:fixed; top:0; left:0; width:100%; background:var(--danger); color:#fff; font-family:"Unbounded"; font-size:10px; font-weight:800; text-align:center; padding:6px; z-index:9999999; transform:translateY(-100%); transition:transform 0.3s; display:flex; justify-content:center; align-items:center; gap:8px;';
        document.body.appendChild(offlineBanner);

        let isOffline = false;
        async function runCheck() {
            let serverAlive = false;
            if (navigator.onLine) { try { serverAlive = (await fetch('https://vilka.sotka.one/api/health', { method: 'GET', cache: 'no-store' })).ok; } catch (e) {} }
            
            if (!serverAlive && !isOffline) {
                isOffline = true; offlineBanner.style.transform = 'translateY(0)';
                const sendBtn = document.getElementById('sendBtnIcon'); if(sendBtn) { sendBtn.style.opacity = '0.5'; sendBtn.style.pointerEvents = 'none'; }
            } else if (serverAlive && isOffline) {
                isOffline = false; offlineBanner.style.transform = 'translateY(-100%)';
                const sendBtn = document.getElementById('sendBtnIcon'); if(sendBtn) { sendBtn.style.opacity = '1'; sendBtn.style.pointerEvents = 'auto'; }
                if(window.app) window.app.softRefreshMessages();
            }
        }
        setInterval(runCheck, 5000);
        window.addEventListener('offline', runCheck); window.addEventListener('online', runCheck);
    }
	
	document.addEventListener('click', (e) => {
    const menuEl = document.getElementById('chatDropdownMenu');
    const menuBtn = document.getElementById('chatMenuBtn');
    if (menuEl && menuEl.classList.contains('show')) {
        if (!menuEl.contains(e.target) && !menuBtn?.contains(e.target)) {
            menuEl.classList.remove('show');
        }
    }
});
	
	// ==========================================
    // 🔥 ГЛОБАЛЬНЫЙ ЗАПУСК СИСТЕМНЫХ ФУНКЦИЙ
    // ==========================================
    document.addEventListener('DOMContentLoaded', () => {
        // initPullToRefresh();
        initSwipeGestures();
        initConnectionMonitor();

        // 👇 НОВЫЙ КОД: Перехват системного свайпа "Назад" от края экрана
        setTimeout(() => {
            if (window.app) {
                history.replaceState({ page: 'main' }, "", window.location.pathname);

                const originalOpenChat = window.app.openChat;
                window.app.openChat = function(chatId) {
                    // 🔥 Добавляем #chat в историю ТОЛЬКО на смартфонах!
                    if (window.innerWidth <= 768) {
                        history.pushState({ chatOpen: true }, "", "#chat");
                    }
                    if (originalOpenChat) originalOpenChat.apply(this, arguments);
                };

                const originalStartDirect = window.app.startDirectChat;
                window.app.startDirectChat = function(userId) {
                    if (window.innerWidth <= 768) {
                        history.pushState({ chatOpen: true }, "", "#chat");
                    }
                    if (originalStartDirect) originalStartDirect.apply(this, arguments);
                };

                // Слушаем системный жест "Назад" (кнопка телефона или свайп от края)
                window.addEventListener('popstate', (e) => {
                    const chatArea = document.getElementById('mainChatArea');
                    // Если мы нажали назад, хэш "#chat" пропал, а чат на экране всё еще открыт
                    if (window.location.hash !== '#chat' && chatArea && chatArea.classList.contains('mobile-open')) {
                        // Просто закрываем шторку, никуда не переходя!
                        if (typeof window.app.closeChatMobile === 'function') {
                            window.app.closeChatMobile();
                        }
                    }
                });
                
                // Перехватываем закрытие чата крестиком (чтобы тоже откатывать историю)
                const originalCloseChat = window.app.closeChatMobile;
                window.app.closeChatMobile = function() {
                    if (window.location.hash === '#chat') {
                        history.back(); // Это триггернет popstate и закроет чат чисто
                    } else {
                        if (originalCloseChat) originalCloseChat.apply(this, arguments);
                    }
                };
            }
        }, 1000); // Ждем секунду, пока window.app инициализируется
    });